(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("diogenes-lives-4-e", [{"sp": "HDR", "t": "Βιβλίον Η"}, {"sp": "HDR", "t": "ΠΥΘΑΓΟΡΑΣ"}, {"sp": "N", "t": "Ἐπειδὴ δὲ τὴν Ἰωνικὴν φιλοσοφίαν τὴν ἀπὸ Θαλοῦ καὶ τοὺς ἐν ταύτῃ διαγενομένους ἄνδρας ἀξιολόγους διεληλύθαμεν, φέρε καὶ περὶ τῆς Ἰταλικῆς διαλάβωμεν, ἧς ἦρξε Πυθαγόρας Μνησάρχου δακτυλιογλύφου, ὥς φησιν Ἕρμιππος, Σάμιος ἤ, ὡς Ἀριστόξενος, Τυρρηνὸς ἀπὸ μιᾶς τῶν νήσων ἃς ἔσχον Ἀθηναῖοι Τυρρηνοὺς ἐκβαλόντες. ἔνιοι δ’ υἱὸν μὲν εἶναι Μαρμάκου τοῦ Ἱππάσου τοῦ Εὐθύφρονος τοῦ Κλεωνύμου φυγάδος ἐκ Φλιοῦντος, οἰκεῖν δ’ ἐν Σάμῳ τὸν Μάρμακον, ὅθεν Σάμιον τὸν Πυθαγόραν λέγεσθαι· συστῆναι δ’ εἰς Λέσβον ἐλθόντα Φερεκύδῃ ὑπὸ Ζωίλου τοῦ θείου. καὶ τρία ποτήρια κατασκευασάμενος ἀργυρᾶ δῶρον ἀπήνεγκεν ἑκάστῳ τῶν ἱερέων εἰς Αἴγυπτον. ἔσχε δ’ ἀδελφούς, πρεσβύτερον μὲν Εὔνομον, μέσον δὲ Τυρρηνόν· καὶ δοῦλον Ζάμολξιν, ᾧ Γέται θύουσι, Κρόνον νομίζοντες, ὥς φησιν Ἡρόδοτος.", "st": "8.1"}, {"sp": "N", "t": "οὗτος ἤκουσε μέν, καθὰ προείρηται, Φερεκύδου τοῦ Συρίου· μετὰ δὲ τὴν ἐκείνου τελευτὴν ἧκεν εἰς Σάμον καὶ ἤκουσεν Ἑρμοδάμαντος τοῦ ἀπογόνου Κρεωφύλου, ἤδη πρεσβυτέρου.", "st": "8.1b"}, {"sp": "N", "t": "νέος δ’ ὢν καὶ φιλομαθὴς ἀπεδήμησε τῆς πατρίδος καὶ πάσας ἐμυήθη τάς θ’ Ἑλληνικὰς καὶ βαρβαρικὰς τελετάς. ἐγένετ’ οὖν ἐν Αἰγύπτῳ, ὁπηνίκα καὶ Πολυκράτης αὐτὸν Ἀμάσιδι συνέστησε δι’ ἐπιστολῆς· καὶ ἐξέμαθε τὴν φωνὴν αὐτῶν, καθά φησιν Ἀντιφῶν ἐν τῷ Περὶ τῶν ἐν ἀρετῇ πρωτευσάντων, καὶ παρὰ Χαλδαίοις ἐγένετο καὶ Μάγοις.", "st": "8.3"}, {"sp": "N", "t": "εἶτ’ ἐν Κρήτῃ σὺν Ἐπιμενίδῃ κατῆλθεν εἰς τὸ Ἰδαῖον ἄντρον, ἀλλὰ καὶ ἐν Αἰγύπτῳ εἰς τὰ ἄδυτα· καὶ τὰ περὶ θεῶν ἐν ἀπορρήτοις ἔμαθεν. εἶτ’ ἐπανῆλθεν εἰς Σάμον, καὶ εὑρὼν τὴν πατρίδα τυραννουμένην ὑπὸ Πολυκράτους, ἀπῆρεν εἰς Κρότωνα τῆς Ἰταλίας· κἀκεῖ νόμους θεὶς τοῖς Ἰταλιώταις ἐδοξάσθη σὺν τοῖς μαθηταῖς, οἳ πρὸς τοὺς τριακοσίους ὄντες ᾠκονόμουν ἄριστα τὰ πολιτικά, ὥστε σχεδὸν ἀριστοκρατίαν εἶναι τὴν πολιτείαν.", "st": "8.3b"}, {"sp": "N", "t": "Τοῦτόν φησιν Ἡρακλείδης ὁ Ποντικὸς περὶ αὑτοῦ τάδε λέγειν, ὡς εἴη ποτὲ γεγονὼς Αἰθαλίδης καὶ Ἑρμοῦ υἱὸς νομισθείη· τὸν δὲ Ἑρμῆν εἰπεῖν αὐτῷ ἑλέσθαι ὅ τι ἂν βούληται πλὴν ἀθανασίας. αἰτήσασθαι οὖν ζῶντα καὶ τελευτῶντα μνήμην ἔχειν τῶν συμβαινόντων. ἐν μὲν οὖν τῇ ζωῇ πάντων διαμνημονεῦσαι· ἐπεὶ δὲ ἀποθάνοι, τηρῆσαι τὴν αὐτὴν μνήμην. χρόνῳ δ’ ὕστερον εἰς Εὔφορβον ἐλθεῖν καὶ ὑπὸ Μενέλεω τρωθῆναι. ὁ δ’ Εὔφορβος ἔλεγεν ὡς Αἰθαλίδης ποτὲ γεγόνοι καὶ ὅτι παρ’ Ἑρμοῦ τὸ δῶρον λάβοι καὶ τὴν τῆς ψυχῆς περιπόλησιν, ὡς περιεπολήθη καὶ εἰς ὅσα φυτὰ καὶ ζῷα παρεγένετο καὶ ὅσα ἡ ψυχὴ ἐν Ἅιδῃ ἔπαθε καὶ αἱ λοιπαὶ τίνα ὑπομένουσιν.", "st": "8.4"}, {"sp": "N", "t": "ἐπειδὴ δὲ Εὔφορβος ἀποθάνοι, μεταβῆναι τὴν ψυχὴν αὐτοῦ εἰς Ἑρμότιμον, ὃς καὶ αὐτὸς πίστιν θέλων δοῦναι εἶτ’ ἀνῆλθεν εἰς Βραγχίδας καὶ εἰσελθὼν εἰς τὸ τοῦ Ἀπόλλωνος ἱερὸν ἐπέδειξεν ἣν Μενέλαος ἀνέθηκεν ἀσπίδα, (ἔφη γὰρ αὐτόν, ὅτ’ ἀπέπλει ἐκ Τροίας, ἀναθεῖναι τῷ Ἀπόλλωνι τὴν ἀσπίδα,) διασεσηπυῖαν ἤδη, μόνον δὲ διαμένον τὸ ἐλεφάντινον πρόσωπον. ἐπειδὴ δ’ Ἑρμότιμος ἀπέθανε, γενέσθαι Πύρρον τὸν Δήλιον ἁλιέα· καὶ πάντα πάλιν μνημονεύειν, πῶς πρόσθεν Αἰθαλίδης, εἶτ’ Εὔφορβος, εἶτα Ἑρμότιμος, εἶτα Πύρρος γένοιτο. ἐπειδὴ δὲ Πύρρος ἀπέθανε, γενέσθαι Πυθαγόραν καὶ πάντων τῶν εἰρημένων μεμνῆσθαι.", "st": "8.5"}, {"sp": "N", "t": "Ἔνιοι μὲν οὖν Πυθαγόραν μηδὲ ἓν καταλιπεῖν σύγγραμμά φασιν παίζοντες. Ἡράκλειτος γοῦν ὁ φυσικὸς μονονουχὶ κέκραγε καί φησι· Πυθαγόρης Μνησάρχου ἱστορίην ἤσκησεν ἀνθρώπων μάλιστα πάντων καὶ ἐκλεξάμενος ταύτας τὰς συγγραφὰς ἐποιήσατο ἑαυτοῦ σοφίην, πολυμαθείην, κακοτεχνίην. οὕτω δ’ εἶπεν, ἐπειδήπερ ἐναρχόμενος ὁ Πυθαγόρας τοῦ Φυσικοῦ συγγράμματος λέγει ὧδε· οὐ μὰ τὸν ἀέρα, τὸν ἀναπνέω, οὐ μὰ τὸ ὕδωρ, τὸ πίνω, οὔ κοτ’ οἴσω ψόγον περὶ τοῦ λόγου τοῦδε.", "st": "8.6"}, {"sp": "N", "t": "γέγραπται δὲ τῷ Πυθαγόρᾳ συγγράμματα τρία, Παιδευτικόν, Πολιτικόν, Φυσικόν· τὸ δὲ φερόμενον ὡς Πυθαγόρου Λύσιδός ἐστι τοῦ Ταραντίνου Πυθαγορικοῦ, φυγόντος εἰς Θήβας καὶ Ἐπαμεινώνδα καθηγησαμένου. φησὶ δ’ Ἡρακλείδης ὁ τοῦ Σαραπίωνος ἐν τῇ Σωτίωνος ἐπιτομῇ γεγραφέναι αὐτὸν καὶ Περὶ τοῦ ὅλου ἐν ἔπεσιν, δεύτερον τὸν Ἱερὸν λόγον, οὗ ἡ ἀρχή·<br>ὦ νέοι, ἀλλὰ σέβεσθε μεθ’ ἡσυχίης τάδε πάντα·", "st": "8.7"}, {"sp": "N", "t": "τρίτον Περὶ ψυχῆς, τέταρτον Περὶ εὐσεβείας, πέμπτον Ἡλοθαλῆ τὸν Ἐπιχάρμου τοῦ Κῴου πατέρα, ἕκτον Κρότωνα καὶ ἄλλους. τὸν δὲ Μυστικὸν λόγον Ἱππάσου φησὶν εἶναι, γεγραμμένον ἐπὶ διαβολῇ Πυθαγόρου, πολλοὺς δὲ καὶ ὑπὸ Ἄστωνος τοῦ Κροτωνιάτου γραφέντας ἀνατεθῆναι Πυθαγόρᾳ.", "st": "8.7b"}, {"sp": "N", "t": "φησὶ δὲ καὶ Ἀριστόξενος τὰ πλεῖστα τῶν ἠθικῶν δογμάτων λαβεῖν τὸν Πυθαγόραν παρὰ Θεμιστοκλείας τῆς ἐν Δελφοῖς. Ἴων δὲ ὁ Χῖος ἐν τοῖς Τριαγμοῖς φησιν αὐτὸν ἔνια ποιήσαντα ἀνενεγκεῖν εἰς Ὀρφέα. αὐτοῦ λέγουσι καὶ τοὺς Σκοπιάδας, οὗ ἡ ἀρχή, Μὴ * * ἀνααίδευ μηδενί.", "st": "8.8"}, {"sp": "N", "t": "Σωσικράτης δ’ ἐν Διαδοχαῖς φησιν αὐτὸν ἐρωτηθέντα ὑπὸ Λέοντος τοῦ Φλιασίων τυράννου τίς εἴη, φιλόσοφος, εἰπεῖν. καὶ τὸν βίον ἐοικέναι πανηγύρει· ὡς οὖν εἰς ταύτην οἱ μὲν ἀγωνιούμενοι, οἱ δὲ κατ’ ἐμπορίαν, οἱ δέ γε βέλτιστοι ἔρχονται θεαταί, οὕτως ἐν τῷ βίῳ οἱ μὲν ἀνδραποδώδεις, ἔφη, φύονται δόξης καὶ πλεονεξίας θηραταί, οἱ δὲ φιλόσοφοι τῆς ἀληθείας. καὶ τάδε μὲν ὧδε. Ἐν δὲ τοῖς τρισὶ συγγράμμασι τοῖς προειρημένοις φέρεται Πυθαγόρου τάδε καθολικῶς.", "st": "8.9"}, {"sp": "N", "t": "οὐκ ἐᾷ εὔχεσθαι ὑπὲρ ἑαυτῶν διὰ τὸ μὴ εἰδέναι τὸ συμφέρον. τὴν μέθην ἓν ἀνθ’ ἑνὸς βλάβην καλεῖ καὶ πλησμονὴν πᾶσαν ἀποδοκιμάζει, λέγων μὴ παραβαίνειν μήτε τῶν ποτῶν μήτε τῶν σιτίων μηδένα τὴν συμμετρίαν. καὶ περὶ ἀφροδισίων δέ φησιν οὕτως· Ἀφροδίσια χειμῶνος ποιέεσθαι, μὴ θέρεος· φθινοπώρου δὲ καὶ ἦρος κουφότερα, βαρέα δὲ πᾶσαν ὥρην καὶ ἐς ὑγιείην οὐκ ἀγαθά. ἀλλὰ καί ποτ’ ἐρωτηθέντα πότε δεῖ πλησιάζειν εἰπεῖν· ὅταν βούλῃ γενέσθαι σωυτοῦ ἀσθενέστερος.", "st": "8.9b"}, {"sp": "N", "t": "Διαιρεῖται δὲ καὶ τὸν τοῦ ἀνθρώπου βίον οὕτως· Παῖς εἴκοσι ἔτεα, νεηνίσκος εἴκοσι, νεηνίης εἴκοσι, γέρων εἴκοσι. αἱ δὲ ἡλικίαι πρὸς τὰς ὥρας ὧδε σύμμετροι· παῖς ἔαρ, νεηνίσκος θέρος, νεηνίης φθινόπωρον, γέρων χειμών. ἔστι δ’ αὐτῷ ὁ μὲν νεηνίσκος μειράκιον, ὁ δὲ νεηνίης ἀνήρ.", "st": "8.10"}, {"sp": "N", "t": "εἶπέ τε πρῶτος, ὥς φησι Τίμαιος, κοινὰ τὰ φίλων εἶναι καὶ φιλίαν ἰσότητα. καὶ αὐτοῦ οἱ μαθηταὶ κατετίθεντο τὰς οὐσίας εἰς ἕν [ποιούμενοι]. πενταετίαν θ’ ἡσύχαζον, μόνον τῶν λόγων κατακούοντες καὶ οὐδέπω Πυθαγόραν ὁρῶντες εἰς ὃ δοκιμασθεῖεν· τοὐντεῦθεν δ’ ἐγίνοντο τῆς οἰκίας αὐτοῦ καὶ τῆς ὄψεως μετεῖχον. ἀπείχοντο δὲ καὶ σοροῦ κυπαρισσίνης διὰ τὸ τὸ τοῦ Διὸς σκῆπτρον ἐντεῦθεν πεποιῆσθαι, ὥς φησιν Ἕρμιππος ἐν δευτέρῳ Περὶ Πυθαγόρου.", "st": "8.10b"}, {"sp": "N", "t": "Καὶ γὰρ καὶ σεμνοπρεπέστατος λέγεται γενέσθαι καὶ οἱ μαθηταὶ δόξαν εἶχον περὶ αὐτοῦ ὡς εἴη Ἀπόλλων ἐξ Ὑπερβορέων ἀφιγμένος. λόγος δέ ποτ’ αὐτοῦ παραγυμνωθέντος τὸν μηρὸν ὀφθῆναι χρυσοῦν· καὶ ὅτι Νέσσος ὁ ποταμὸς διαβαίνοντα αὐτὸν προσαγορεύσαι πολὺς ἦν ὁ φάσκων.", "st": "8.11"}, {"sp": "N", "t": "Τίμαιός τέ φησιν ἐν δεκάτῃ Ἱστοριῶν λέγειν αὐτὸν τὰς συνοικούσας ἀνδράσι θεῶν ἔχειν ὀνόματα, Κόρας, Νύμφας, εἶτα Μητέρας καλουμένας.", "st": "8.11b"}, {"sp": "N", "t": "τοῦτον καὶ γεωμετρίαν ἐπὶ πέρας ἀγαγεῖν, Μοίριδος πρώτου εὑρόντος τὰς ἀρχὰς τῶν στοιχείων αὐτῆς, ὥς φησιν Ἀντικλείδης ἐν δευτέρῳ Περὶ Ἀλεξάνδρου. μάλιστα δὲ σχολάσαι τὸν Πυθαγόραν περὶ τὸ ἀριθμητικὸν εἶδος αὐτῆς· τόν τε κανόνα τὸν ἐκ μιᾶς χορδῆς εὑρεῖν. οὐκ ἠμέλησε δ’ οὐδ’ ἰατρικῆς. φησὶ δ’ Ἀπολλόδωρος ὁ λογιστικὸς ἑκατόμβην θῦσαι αὐτόν, εὑρόντα ὅτι τοῦ ὀρθογωνίου τριγώνου ἡ ὑποτείνουσα πλευρὰ ἴσον δύναται ταῖς περιεχούσαις. καὶ ἔστιν ἐπίγραμμα οὕτως ἔχον·<br>ἡνίκα Πυθαγόρης τὸ περικλεὲς εὕρετο γράμμα, κεῖν’ ἐφ’ ὅτῳ κλεινὴν ἤγαγε βουθυσίην.", "st": "8.12"}, {"sp": "N", "t": "Λέγεται δὲ καὶ πρῶτος κρέασιν ἀσκῆσαι ἀθλητάς, καὶ πρῶτόν γ’ Εὐρυμένην, καθά φησι Φαβωρῖνος ἐν τρίτῳ τῶν Ἀπομνημονευμάτων, τῶν πρότερον ἰσχάσι ξηραῖς καὶ τυροῖς ὑγροῖς, ἀλλὰ καὶ πυροῖς σωμασκούντων αὐτούς, καθάπερ ὁ αὐτὸς Φαβωρῖνος ἐν ὀγδόῃ Παντοδαπῆς ἱστορίας φησίν. οἱ δὲ Πυθαγόραν ἀλείπτην τινὰ τοῦτον σιτίσαι τὸν τρόπον, μὴ τοῦτον. τοῦτον γὰρ καὶ τὸ φονεύειν ἀπαγορεύειν, μὴ ὅτι γεύεσθαι τῶν ζῴων κοινὸν δίκαιον ἡμῖν ἐχόντων ψυχῆς. καὶ τόδε μὲν ἦν τὸ πρόσχημα· τὸ δ’ ἀληθὲς τῶν ἐμψύχων ἀπηγόρευεν ἅπτεσθαι συνασκῶν καὶ συνεθίζων εἰς εὐκολίαν βίου τοὺς ἀνθρώπους, ὥστε εὐπορίστους αὐτοῖς εἶναι τὰς τροφάς, ἄπυρα προσφερομένοις καὶ λιτὸν ὕδωρ πίνουσιν· ἐντεῦθεν γὰρ καὶ σώματος ὑγίειαν καὶ ψυχῆς ὀξύτητα περιγίνεσθαι.", "st": "8.13"}, {"sp": "N", "t": "ἀμέλει καὶ βωμὸν προσκυνῆσαι μόνον ἐν Δήλῳ τὸν Ἀπόλλωνος τοῦ γενέτορος, ὅς ἐστιν ὄπισθεν τοῦ Κερατίνου, διὰ τὸ πυροὺς καὶ κριθὰς καὶ πόπανα μόνα τίθεσθαι ἐπ’ αὐτοῦ ἄνευ πυρός, ἱερεῖον δὲ μηδέν, ὥς φησιν Ἀριστοτέλης ἐν Δηλίων πολιτείᾳ. Πρῶτόν τέ φασι τοῦτον ἀποφῆναι τὴν ψυχὴν κύκολον ἀνάγκης ἀμείβουσαν ἄλλοτ’ ἄλλοις ἐνδεῖσθαι ζῴοις·", "st": "8.14"}, {"sp": "N", "t": "καὶ πρῶτον εἰς τοὺς Ἕλληνας μέτρα καὶ σταθμὰ εἰσηγήσασθαι, καθά φησιν Ἀριστόξενος ὁ μουσικός·", "st": "8.14b"}, {"sp": "N", "t": "πρῶτόν τε Ἕσπερον καὶ Φωσφόρον τὸν αὐτὸν εἰπεῖν, ὥς φησι Παρμενίδης.", "st": "8.14c"}, {"sp": "N", "t": "οὕτω δ’ ἐθαυμάσθη ὥστ’ ἔλεγον τοὺς γνωρίμους αὐτοῦ μάντιας θεῶ φωνᾶς, ἀλλὰ καὶ αὐτὸς ἐν τῇ γραφῇ φησι δι’ ἑπτὰ καὶ διηκοσίων ἐτέων ἐξ ἀΐδεω παραγεγενῆσθαι ἐς ἀνθρώπους. τοιγὰρ καὶ προσεκαρτέρουν αὐτῷ καὶ τῶν λόγων ἕνεκα προσῄεσαν καὶ Λευκανοὶ καὶ Πευκέτιοι Μεσσάπιοί τε καὶ Ῥωμαῖοι. Μέχρι δὲ Φιλολάου οὐκ ἦν τι γνῶναι Πυθαγόρειον δόγμα· οὗτος δὲ μόνος ἐξήνεγκε τὰ διαβόητα τρία βιβλία, ἃ Πλάτων ἐπέστειλεν ἑκατὸν μνῶν ὠνηθῆναι. τῶν θ’ ἑξακοσίων οὐκ ἐλάττους ἐπὶ τὴν νυκτερινὴν ἀκρόασιν ἀπήντων αὐτοῦ· καὶ εἴ τινες ἀξιωθεῖεν αὐτὸν θεάσασθαι, ἔγραφον πρὸς τοὺς οἰκείους ὡς μεγάλου τινὸς τετυχηκότες.", "st": "8.15"}, {"sp": "N", "t": "Μεταποντῖνοί γε μὴν τὴν μὲν οἰκίαν αὐτοῦ Δήμητρος ἱερὸν ἐκάλουν, τὸν στενωπὸν δὲ μουσεῖον, ὥς φησι Φαβωρῖνος ἐν Παντοδαπαῖς ἱστορίαις·", "st": "8.15b"}, {"sp": "N", "t": "ἔλεγόν τε καὶ οἱ ἄλλοι Πυθαγόρειοι μὴ εἶναι πρὸς πάντας πάντα ῥητά, ὥς φησιν Ἀριστόξενος ἐν δεκάτῃ Παιδευτικῶν νόμων· ἔνθα καὶ Ξενόφιλον τὸν Πυθαγορικόν, ἐρωτηθέντα πῶς ἂν μάλιστα τὸν υἱὸν παιδεύσειεν, εἰπεῖν, εἰ πόλεως εὐνομουμένης γενηθείη.", "st": "8.16"}, {"sp": "N", "t": "ἄλλους τε πολλοὺς κατὰ τὴν Ἰταλίαν ἀπεργάσασθαι καλούς τε κἀγαθοὺς ἄνδρας, ἀτὰρ καὶ Ζάλευκον καὶ Χαρώνδαν τοὺς νομοθέτας·", "st": "8.16b"}, {"sp": "N", "t": "ἱκανός τε γὰρ ἦν φιλίας ἐργάτης τά τ’ ἄλλα καὶ εἴ τινα πύθοιτο τῶν συμβόλων αὐτοῦ κεκοινωνηκότα, εὐθύς τε προσηταιρίζετο καὶ φίλον κατεσκεύαζεν.", "st": "8.16c"}, {"sp": "N", "t": "Ἦν δ’ αὐτῷ τὰ σύμβολα τάδε· πῦρ μαχαίρᾳ μὴ σκαλεύειν, ζυγὸν μὴ ὑπερβαίνειν, ἐπὶ χοίνικος μὴ καθίζειν, καρδίην μὴ ἐσθίειν, φορτίον μὴ συγκαθαιρεῖν, ουνεπιτιθέναι δέ, τὰ στρώματα ἀεὶ συνδεδεμένα ἔχειν, ἐν δακτυλίῳ εἰκόνα θεοῦ μὴ περιφέρειν, χύτρας ἴχνος συγχεῖν ἐν τῇ τέφρᾳ, δᾳδίῳ θᾶκον μὴ ὀμόργνυσθαι, πρὸς ἥλιον τετραμμένον μὴ ὀμίχειν, τὰς λεωφόρους μὴ βαδίζειν, μὴ ῥᾳδίως δεξιὰν ἐμβάλλειν, ὁμωροφίους χελιδόνας μὴ ἔχειν, γαμψώνυχα μὴ τρέφειν, ἀπονυχίσμασι καὶ κουραῖς μὴ ἐπουρεῖν μηδὲ ἐφίστασθαι, ὀξεῖαν μάχαιραν ἀποστρέφειν, ἀποδημοῦντα ἐπὶ τοῖς ὅροις ἀνεπιστρεπτεῖν. Ἤθελε δ’ αὐτῷ τὸ μὲν πῦρ μαχαίρᾳ μὴ σκαλεύειν δυναστῶν ὀργὴν καὶ οἰδοῦντα θυμὸν μὴ κινεῖν. τὸ δὲ ζυγὸν μὴ ὑπερβαίνειν, τουτέστι τὸ ἴσον καὶ δίκαιον μὴ ὑπερβαίνειν. ἐπί τε χοίνικος μὴ καθίζειν ἐν ἴσῳ τοῦ ἐνεστῶτος φροντίδα ποιεῖσθαι καὶ τοῦ μέλλοντος· ἡ γὰρ χοῖνιξ ἡμερησία τροφή. διὰ δὲ τοῦ καρδίαν μὴ ἐσθίειν ἐδήλου μὴ τὴν ψυχὴν ἀνίαις καὶ λύπαις κατατήκειν. διὰ δὲ τοῦ εἰς ἀποδημίαν βαδίζοντα μὴ ἐπιστρέφεσθαι παρῄνει τοῖς ἀπαλλαττομένοις τοῦ βίου μὴ ἐπιθυμητικῶς ἔχειν τοῦ ζῆν μηδ’ ὑπὸ τῶν ἐνταῦθα ἡδονῶν ἐπάγεσθαι. καὶ τὰ ἄλλα πρὸς ταῦτα λοιπόν ἐστιν ἐκλαμβάνειν, ἵνα μὴ παρέλκωμεν.", "st": "8.17"}, {"sp": "N", "t": "Παντὸς δὲ μᾶλλον ἀπηγόρευε μήτ’ ἐρυθῖνον ἐσθίειν μήτε μελάνουρον, καρδίας τ’ ἀπέχεσθαι καὶ κυάμων· Ἀριστοτέλης δέ φησι καὶ μήτρας καὶ τρίγλης ἐνίοτε. αὐτὸν δ’ ἀρκεῖσθαι μέλιτι μόνῳ φασί τινες ἢ κηρίῳ ἢ ἄρτῳ, οἴνου δὲ μεθ’ ἡμέραν μὴ γεύεσθαι· ὄψῳ τε τὰ πολλὰ λαχάνοις ἑφθοῖς τε καὶ ὠμοῖς, τοῖς δὲ θαλαττίοις σπανίως. στολὴ δ’ αὐτῷ λευκή, καθαρά, καὶ στρώματα λευκὰ ἐξ ἐρίων· τὰ γὰρ λινᾶ οὔπω εἰς ἐκείνους ἀφῖκτο τοὺς τόπους. οὐδέποτ’ ἐγνώσθη οὔτε διαχωρῶν οὔτε ἀφροδισιάζων οὔτε μεθυσθείς. ἀπείχετο καὶ γέλωτος καὶ πάσης ἀρεσκείας οἷον σκωμμάτων καὶ διηγημάτων φορτικῶν. ὀργιζόμενός τ’ οὔτε οἰκέτην ἐκόλαζεν οὔτ’ ἐλεύθερον οὐδένα. ἐκάλει δὲ τὸ νουθετεῖν πεδαρτᾶν.", "st": "8.19"}, {"sp": "N", "t": "μαντικῇ τ’ ἐχρῆτο τῇ διὰ τῶν κλῃδόνων τε καὶ οἰωνῶν, ἥκιστα δὲ τῇ διὰ τῶν ἐμπύρων, ἔξω τῆς διὰ λιβάνου. θυσίαις τε ἐχρῆτο ἀψύχοις, οἱ δέ φασιν, ὅτι ἀλέκτορσι μόνον καὶ ἐρίφοις γαλαθηνοῖς καὶ τοῖς λεγομένοις ἁπαλίαις, ἥκιστα δὲ ἄρνασιν. ὅ γε μὴν Ἀριστόξενος πάντα μὲν τἄλλα συγχωρεῖν αὐτὸν ἐσθίειν ἔμψυχα, μόνον δ’ ἀπέχεσθαι βοὸς ἀροτῆρος καὶ κριοῦ.", "st": "8.19b"}, {"sp": "N", "t": "Ὁ δ’ αὐτός φησιν, ὡς προείρηται, καὶ τὰ δόγματα λαβεῖν αὐτὸν παρὰ τῆς ἐν Δελφοῖς Θεμιστοκλείας. φησὶ δ’ Ἱερώνυμος κατελθόντα αὐτὸν εἰς ᾅδου τὴν μὲν Ἡσιόδου ψυχὴν ἰδεῖν πρὸς κίονι χαλκῷ δεδεμένην καὶ τρίζουσαν, τὴν δ’ Ὁμήρου κρεμαμένην ἀπὸ δένδρου καὶ ὄφεις περὶ αὐτὴν ἀνθ’ ὧν εἶπον περὶ θεῶν, κολαζομένους δὲ καὶ τοὺς μὴ θέλοντας συνεῖναι ταῖς ἑαυτῶν γυναιξί· καὶ δὴ καὶ διὰ τοῦτο τιμηθῆναι ὑπὸ τῶν ἐν Κρότωνι.", "st": "8.21"}, {"sp": "N", "t": "φησὶ δ’ Ἀρίστιππος ὁ Κυρηναῖος ἐν τῷ Περὶ φυσιολόγων Πυθαγόραν αὐτὸν ὀνομασθῆναι ὅτι τὴν ἀλήθειαν ἠγόρευεν οὐχ ἧττον τοῦ Πυθίου.", "st": "8.21b"}, {"sp": "N", "t": "Λέγεται παρεγγυᾶν αὐτὸν ἑκάστοτε τοῖς μαθηταῖς τάδε λέγειν εἰς τὸν οἶκον εἰσιοῦσι,<br>πῆ παρέβην; τί δ’ ἔρεξα; τί μοι δέον οὐκ ἐτελέσθη;", "st": "8.22"}, {"sp": "N", "t": "σφάγιά τε θεοῖς προσφέρειν κωλύειν, μόνον δὲ τὸν ἀναίμακτον βωμὸν προσκυνεῖν. μηδ’ ὀμνύναι θεούς· ἀσκεῖν γὰρ αὑτὸν δεῖν ἀξιόπιστον παρέχειν. τούς τε πρεσβυτέρους τιμᾶν, τὸ προηγούμενον τῷ χρόνῳ τιμιώτερον ἡγουμένους· ὡς ἐν κόσμῳ μὲν ἀνατολὴν δύσεως, ἐν βίῳ δ’ ἀρχὴν τελευτῆς, ἐν ζωῇ δὲ γένεσιν φθορᾶς.", "st": "8.22b"}, {"sp": "N", "t": "καὶ θεοὺς μὲν δαιμόνων προτιμᾶν, ἥρωας δ’ ἀνθρώπων, ἀνθρώπων δὲ μάλιστα τοὺς γονέας. ἀλλήλοις θ’ ὁμιλεῖν, ὡς τοὺς μὲν φίλους ἐχθροὺς μὴ ποιῆσαι, τοὺς δ’ ἐχθροὺς φίλους ἐργάσασθαι. ἴδιόν τε μηδὲν ἡγεῖσθαι. νόμῳ βοηθεῖν, ἀνομίᾳ πολεμεῖν· φυτὸν ἥμερον μήτε φθίνειν μήτε σίνεσθαι, ἀλλὰ μηδὲ ζῷον ὃ μὴ βλάπτει ἀνθρώπους. αἰδῶ καὶ εὐλάβειαν εἶναι μήτε γέλωτι κατέχεσθαι μήτε σκυθρωπάζειν. φεύγειν σαρκῶν πλεονασμόν, ὁδοιπορίης ἄνεσιν καὶ ἐπίτασιν ποιεῖσθαι, μνήμην ἀσκεῖν, ἐν ὀργῇ μήτε τι λέγειν μήτε πράσσειν, μαντικὴν πᾶσαν τιμᾶν, ᾠδαῖς χρῆσθαι πρὸς λύραν ὕμνῳ τε θεῶν καὶ ἀνδρῶν ἀγαθῶν εὔλογον χάριν ἔχειν.", "st": "8.23"}, {"sp": "N", "t": "τῶν δὲ κυάμων ἀπέχεσθαι διὰ τὸ πνευματώδεις ὄντας μάλιστα μετέχειν τοῦ ψυχικοῦ· καὶ ἄλλως κοσμιωτέρας ἀπεργάζεσθαι τὰς γαστέρας, μὴ παραληφθέντας. καὶ διὰ τοῦτο καὶ τὰς καθ’ ὕπνους φαντασίας λείας καὶ ἀταράχους ἀποτελεῖν. Φησὶ δ’ ὁ Ἀλέξανδρος ἐν Ταῖς τῶν φιλοσόφων διαδοχαῖς καὶ ταῦτα εὑρηκέναι ἐν Πυθαγορικοῖς ὑπομνήμασιν.", "st": "8.23b"}, {"sp": "N", "t": "ἀρχὴν μὲν ἁπάντων μονάδα· ἐκ δὲ τῆς μονάδος ἀόριστον δυάδα ὡς ἂν ὕλην τῇ μονάδι αἰτίῳ ὄντι ὑποστῆναι· ἐκ δὲ τῆς μονάδος καὶ τῆς ἀορίστου δυάδος τοὺς ἀριθμούς· ἐκ δὲ τῶν ἀριθμῶν τὰ σημεῖα· ἐκ δὲ τούτων τὰς γραμμάς, ἐξ ὧν τὰ ἐπίπεδα σχήματα· ἐκ δὲ τῶν ἐπιπέδων τὰ στερεὰ σχήματα· ἐκ δὲ τούτων τὰ αἰσθητὰ σώματα, ὧν καὶ τὰ στοιχεῖα εἶναι τέτταρα, πῦρ, ὕδωρ, γῆν, ἀέρα· μεταβάλλειν δὲ καὶ τρέπεσθαι δι’ ὅλων, καὶ γίνεσθαι ἐξ αὐτῶν κόσμον ἔμψυχον, νοερόν, σφαιροειδῆ, μέσην περιέχοντα τὴν γῆν καὶ αὐτὴν σφαιροειδῆ καὶ περιοικουμένην. εἶναι δὲ καὶ ἀντίποδας καὶ τὰ ἡμῖν κάτω ἐκείνοις ἄνω.", "st": "8.25"}, {"sp": "N", "t": "ἰσόμοιρά τ’ εἶναι ἐν τῷ κόσμῳ φῶς καὶ σκότος, καὶ θερμὸν καὶ ψυχρόν, καὶ ξηρὸν καὶ ὑγρόν· ὧν κατ’ ἐπικράτειαν θερμοῦ μὲν θέρος γίνεσθαι, ψυχροῦ δὲ χειμῶνα, ξηροῦ δ’ ἔαρ, καὶ ὑγροῦ φθινόπωρον. ἐὰν δὲ ἰσομοιρῇ, τὰ κάλλιστα εἶναι τοῦ ἔτους, οὗ τὸ μὲν θάλλον ἔαρ ὑγιεινόν, τὸ δὲ φθίνον φθινόπωρον νοσερόν. ἀλλὰ καὶ τῆς ἡμέρας θάλλειν μὲν τὴν ἕω, φθίνειν δὲ τὴν ἑσπέραν· ὅθεν καὶ νοσερωτέραν εἶναι. τόν τε περὶ τὴν γῆν ἀέρα ἄσειστον καὶ νοσερὸν καὶ τὰ ἐν αὐτῷ πάντα θνητά·", "st": "8.25b"}, {"sp": "N", "t": "τὸν δὲ ἀνωτάτω ἀεικίνητόν τ’ εἶναι καὶ καθαρὸν καὶ ὑγιᾶ καὶ πάντα τὰ ἐν αὐτῷ ἀθάνατα καὶ διὰ τοῦτο θεῖα. ἥλιόν τε καὶ σελήνην καὶ τοὺς ἄλλους ἀστέρας εἶναι θεούς· ἐπικρατεῖν γὰρ τὸ θερμὸν ἐν αὐτοῖς, ὅπερ ἐστὶ ζωῆς αἴτιον. τήν τε σελήνην λάμπεσθαι ὑφ’ ἡλίου. καὶ ἀνθρώποις εἶναι πρὸς θεοὺς συγγένειαν, κατὰ τὸ μετέχειν ἄνθρωπον θερμοῦ· διὸ καὶ προνοεῖσθαι τὸν θεὸν ἡμῶν. εἱμαρμένην τε τῶν ὅλων καὶ κατὰ μέρος αἰτίαν εἶναι τῆς διοικήσεως. διήκειν τ’ ἀπὸ τοῦ ἡλίου ἀκτῖνα διὰ τοῦ αἰθέρος τοῦ τε ψυχροῦ καὶ παχέος. καλοῦσι δὲ τὸν μὲν ἀέρα ψυχρὸν αἰθέρα, τὴν δὲ θάλασσαν καὶ τὸ ὑγρὸν παχὺν αἰθέρα. ταύτην δὲ τὴν ἀκτῖνα καὶ εἰς τὰ βένθη δύεσθαι καὶ διὰ τοῦτο ζωοποιεῖν πάντα. καὶ ζῆν μὲν πάνθ’ ὅσα μετέχει τοῦ θερμοῦ· διὸ καὶ τὰ φυτὰ ζῷα εἶναι· ψυχὴν μέντοι μὴ ἔχειν πάντα. εἶναι δὲ τὴν ψυχὴν ἀπόσπασμα αἰθέρος καὶ τοῦ θερμοῦ καὶ τοῦ ψυχροῦ, τῷ συμμετέχειν ψυχροῦ αἰθέρος. διαφέρειν τε ψυχὴν ζωῆς· ἀθάνατόν τ’ εἶναι αὐτήν, ἐπειδήπερ καὶ τὸ ἀφ’ οὗ ἀπέσπασται ἀθάνατόν ἐστι.", "st": "8.27"}, {"sp": "N", "t": "τὰ δὲ ζῷα γεννᾶσθαι ἐξ ἀλλήλων ἀπὸ σπερμάτων, τὴν δ’ ἐκ γῆς γένεσιν ἀδύνατον ὑφίστασθαι. τὸ δὲ σπέρμα εἶναι σταγόνα ἐγκεφάλου περιέχουσαν ἐν ἑαυτῇ θερμὸν ἀτμόν· ταύτην δὲ προσφερομένην τῇ μήτρᾳ ἀπὸ μὲν τοῦ ἐγκεφάλου ἰχῶρα καὶ ὑγρὸν καὶ αἷμα προΐεσθαι, ἐξ ὧν σάρκας τε καὶ νεῦρα καὶ ὀστᾶ καὶ τρίχας καὶ τὸ ὅλον συνίστασθαι σῶμα· ἀπὸ δὲ τοῦ ἀτμοῦ ψυχὴν καὶ αἴσθησιν. μορφοῦσθαι δὲ τὸ μὲν πρῶτον παγὲν ἐν ἡμέραις τεσσαράκοντα, κατὰ δὲ τοὺς τῆς ἁρμονίας λόγους ἐν ἑπτὰ ἢ ἐννέα ἢ δέκα τὸ πλεῖστον μησὶ τελεωθὲν ἀποκυΐσκεσθαι τὸ βρέφος· ἔχειν δ’ ἐν αὑτῷ πάντας τοὺς λόγους τῆς ζωῆς, ὧν εἰρομένων συνέχεσθαι κατὰ τοὺς τῆς ἁρμονίας λόγους, ἑκάστων ἐν τεταγμένοις καιροῖς ἐπιγινομένων.", "st": "8.29"}, {"sp": "N", "t": "τήν τ’ αἴσθησιν κοινῶς καὶ κατ’ εἶδος τὴν ὅρασιν ἀτμόν τιν’ εἶναι ἄγαν θερμόν. καὶ διὰ τοῦτο λέγεται δι’ ἀέρος ὁρᾶν καὶ δι’ ὕδατος· ἀντερείδεσθαι γὰρ τὸ θερμὸν ἀπὸ τοῦ ψυχροῦ. ἐπεί τοι εἰ ψυχρὸς ἦν ὁ ἐν τοῖς ὄμμασιν ἀτμός, διειστήκει ἂν πρὸς τὸν ὅμοιον ἀέρα· νῦν δὲ * * ἔστιν ἐν οἷς ἡλίου πύλας καλεῖ τοὺς ὀφθαλμούς. τὰ δ’ αὐτὰ καὶ περὶ τῆς ἀκοῆς καὶ τῶν λοιπῶν αἰσθήσεων δογματίζει.", "st": "8.29b"}, {"sp": "N", "t": "Τὴν δ’ ἀνθρώπου ψυχὴν διαιρεῖσθαι τριχῆ, εἴς τε νοῦν καὶ φρένας καὶ θυμόν. νοῦν μὲν οὖν καὶ θυμὸν εἶναι καὶ ἐν τοῖς ἄλλοις ζῴοις, φρένας δὲ μόνον ἐν ἀνθρώπῳ. εἶναι δὲ τὴν ἀρχὴν τῆς ψυχῆς ἀπὸ καρδίας μέχρις ἐγκεφάλου· καὶ τὸ μὲν ἐν τῇ καρδίᾳ μέρος αὐτῆς ὑπάρχειν θυμόν, φρένας δὲ καὶ νοῦν τὰ ἐν τῷ ἐγκεφάλῳ·", "st": "8.30"}, {"sp": "N", "t": "σταγόνας δ’ εἶναι ἀπὸ τούτων τὰς αἰσθήσεις. καὶ τὸ μὲν φρόνιμον ἀθάνατον, τὰ δὲ λοιπὰ θνητά. τρέφεσθαί τε τὴν ψυχὴν ἀπὸ τοῦ αἵματος· τοὺς δὲ λόγους ψυχῆς ἀνέμους εἶναι. ἀόρατόν τ’ εἶναι αὐτὴν καὶ τοὺς λόγους, ἐπεὶ καὶ ὁ αἰθὴρ ἀόρατος. δεσμά τ’ εἶναι τῆς ψυχῆς τὰς φλέβας καὶ τὰς ἀρτηρίας καὶ τὰ νεῦρα· ὅταν δ’ ἰσχύῃ καὶ καθ’ αὑτὴν γενομένη ἠρεμῇ, δεσμὰ γίνεσθαι αὐτῆς τοὺς λόγους καὶ τὰ ἔργα. ἐκριφθεῖσαν δ’ αὐτὴν ἐπὶ γῆς πλάζεσθαι ἐν τῷ ἀέρι ὁμοίαν τῷ σώματι. τὸν δ’ Ἑρμῆν ταμίαν εἶναι τῶν ψυχῶν καὶ διὰ τοῦτο πομπαῖον λέγεσθαι καὶ πυλαῖον καὶ χθόνιον, ἐπειδήπερ οὗτος εἰσπέμπει ἀπὸ τῶν σωμάτων τὰς ψυχὰς ἀπό τε γῆς καὶ ἐκ θαλάττης· καὶ ἄγεσθαι τὰς μὲν καθαρὰς ἐπὶ τὸν ὕψιστον, τὰς δ’ ἀκαθάρτους μήτ’ ἐκείναις πελάζειν μήτ’ ἀλλήλαις, δεῖσθαι δ’ ἐν ἀρρήκτοις δεσμοῖς ὑπ’ Ἐρινύων. εἶναί τε πάντα τὸν ἀέρα ψυχῶν ἔμπλεων· καὶ ταύτας δαίμονάς τε καὶ ἥρωας ὀνομάζεσθαι· καὶ ὑπὸ τούτων πέμπεσθαι ἀνθρώποις τούς τ’ ὀνείρους καὶ τὰ σημεῖα νόσου τε καὶ ὑγιείας, καὶ οὐ μόνον ἀνθρώποις, ἀλλὰ καὶ προβάτοις καὶ τοῖς ἄλλοις κτήνεσιν· εἴς τε τούτους γίνεσθαι τούς τε καθαρμοὺς καὶ ἀποτροπιασμοὺς μαντικήν τε πᾶσαν καὶ κληδόνας καὶ τὰ ὅμοια.", "st": "8.31"}, {"sp": "N", "t": "μέγιστον δέ φησιν εἶναι τῶν ἐν ἀνθρώποις τὸ τὴν ψυχὴν πεῖσαι ἐπὶ τὸ ἀγαθὸν ἢ ἐπὶ τὸ κακόν. εὐδαιμονεῖν τ’ ἀνθρώπους ὅταν ἀγαθὴ ψυχὴ προσγένηται, μηδέποτε δ’ ἠρεμεῖν μηδὲ τὸν αὐτὸν * * ῥόον κρατεῖν. Ὅρκιόν τ’ εἶναι τὸ δίκαιον καὶ διὰ τοῦτο Δία ὅρκιον λέγεσθαι. τήν τ’ ἀρετὴν ἁρμονίαν εἶναι καὶ τὴν ὑγίειαν καὶ τὸ ἀγαθὸν ἅπαν καὶ τὸν θεόν· διὸ καὶ καθ’ ἁρμονίαν συνεστάναι τὰ ὅλα. φιλίαν τ’ εἶναι ἐναρμόνιον ἰσότητα.", "st": "8.33"}, {"sp": "N", "t": "τιμὰς θεοῖς δεῖν νομίζειν καὶ ἥρωσι μὴ τὰς ἴσας, ἀλλὰ θεοῖς ἀεὶ μετ’ εὐφημίας λευχειμονοῦντας καὶ ἁγνεύοντας, ἥρωσι δ’ ἀπὸ μέσου ἡμέρας. τὴν δ’ ἁγνείαν εἶναι διὰ καθαρμῶν καὶ λουτρῶν καὶ περιρραντηρίων καὶ διὰ τοῦ καθαρεύειν ἀπό τε κήδους καὶ λεχοῦς καὶ μιάσματος παντὸς καὶ ἀπέχεσθαι βρωτῶν θνησειδίων τε κρεῶν καὶ τριγλῶν καὶ μελανούρων καὶ ᾠῶν καὶ τῶν ᾠοτόκων ζῴων καὶ κυάμων καὶ τῶν ἄλλων ὧν παρακελεύονται καὶ οἱ τὰς τελετὰς ἐν τοῖς ἱεροῖς ἐπιτελοῦντες.", "st": "8.33b"}, {"sp": "N", "t": "φησὶ δ’ Ἀριστοτέλης ἐν τῷ Περὶ τῶν Πυθαγορείων παραγγέλλειν αὐτὸν ἀπέχεσθαι τῶν κυάμων ἤτοι ὅτι αἰδοίοις εἰσὶν ὅμοιοι ἢ ὅτι ᾍδου πύλαις. * * ἀγόνατον γὰρ μόνον· ἢ ὅτι φθείρει ἢ ὅτι τῇ τοῦ ὅλου φύσει ὅμοιον ἢ ὅτι ὀλιγαρχικόν· κληροῦνται γοῦν αὐτοῖς. τὰ δὲ πεσόντα μὴ ἀναιρεῖσθαι, ὑπὲρ τοῦ ἐθίζεσθαι μὴ ἀκολάστως ἐσθίειν ἢ ὅτι ἐπὶ τελευτῇ τινος·", "st": "8.34"}, {"sp": "N", "t": "καὶ Ἀριστοφάνης δὲ τῶν ἡρώων φησὶν εἶναι τὰ πίπτοντα, λέγων ἐν τοῖς Ἥρωσι,<br>μηδὲ γεύεσθ’ ἅττ’ ἂν ἐντὸς τῆς τραπέζης καταπέσῃ·", "st": "8.34b"}, {"sp": "N", "t": "Ἀλεκτρυόνος μὴ ἅπτεσθαι λευκοῦ, ὅτι ἱερὸς τοῦ Μηνὸς καὶ ἱκέτης· τὸ δ’ ἦν τῶν ἀγαθῶν· τῷ τε Μηνὶ ἱερός· σημαίνει γὰρ τὰς ὥρας. καὶ τὸ μὲν λευκὸν τῆς τἀγαθοῦ φύσεως, τὸ δὲ μέλαν τοῦ κακοῦ.", "st": "8.34c"}, {"sp": "N", "t": "τῶν ἰχθύων μὴ ἅπτεσθαι, ὅσοι ἱεροί· μὴ γὰρ δεῖν τὰ αὐτὰ τετάχθαι θεοῖς καὶ ἀνθρώποις, ὥσπερ οὐδ’ ἐλευθέροις καὶ δούλοις. ἄρτον μὴ καταγνύειν, ὅτι ἐπὶ ἕνα οἱ πάλαι τῶν φίλων ἐφοίτων, καθάπερ ἔτι καὶ νῦν οἱ βάρβαροι· μηδὲ διαιρεῖν, ὃς συνάγει αὐτούς· οἱ δέ, πρὸς τὴν ἐν ᾅδου κρίσιν· οἱ δ’ εἰς πόλεμον δειλίαν ποιεῖν· οἱ δέ, ἐπεὶ ἀπὸ τούτου ἄρχεται τὸ ὅλον.", "st": "8.35"}, {"sp": "N", "t": "Καὶ τῶν σχημάτων τὸ κάλλιστον σφαῖραν εἶναι τῶν στερεῶν, τῶν δ’ ἐπιπέδων κύκλον. γῆρας καὶ πᾶν τὸ μειούμενον ὅμοιον· καὶ αὔξην καὶ νεότητα ταὐτόν. ὑγίειαν τὴν τοῦ εἴδους διαμονήν, νόσον τὴν τούτου φθοράν. περὶ τῶν ἁλῶν, ὅτι δεῖ παρατίθεσθαι πρὸς ὑπόμνησιν τοῦ δικαίου· οἱ γὰρ ἅλες πᾶν σῴζουσιν ὅ τι ἂν παραλάβωσι καὶ γεγόνασιν ἐκ τῶν καθαρωτάτων ἡλίου καὶ θαλάσσης.", "st": "8.35b"}, {"sp": "N", "t": "Καὶ ταῦτα μέν φησιν ὁ Ἀλέξανδρος ἐν τοῖς Πυθαγορικοῖς ὑπομνήμασιν εὑρηκέναι, καὶ τὰ ἐκείνων ἐχόμενα ὁ Ἀριστοτέλης.", "st": "8.36"}, {"sp": "N", "t": "Τὴν δὲ σεμνοπρέπειαν τοῦ Πυθαγόρου καὶ Τίμων ἐν τοῖς Σίλλοις δάκνων αὐτὸν ὅμως οὐ παρέλιπεν, εἰπὼν οὕτω·<br>Πυθαγόρην τε γόητας ἀποκλίναντ’ ἐπὶ δόξας θήρῃ ἐπ’ ἀνθρώπων, σεμνηγορίης ὀαριστήν.", "st": "8.36b"}, {"sp": "N", "t": "περὶ δὲ τοῦ ἄλλοτ’ ἄλλον αὐτὸν γεγενῆσθαι Ξενοφάνης ἐν ἐλεγείᾳ προσμαρτυρεῖ, ἧς ἀρχή,<br>νῦν αὖτ’ ἄλλον ἔπειμι λόγον, δείξω δὲ κέλευθον.", "st": "8.36c"}, {"sp": "N", "t": "ὃ δὲ περὶ αὐτοῦ φησιν, οὕτως ἔχει·<br>καί ποτέ μιν στυφελιζομένου σκύλακος παριόντα φασὶν ἐποικτῖραι καὶ τόδε φάσθαι ἔπος· παῦσαι μηδὲ ῥάπιζ’, ἐπεὶ ἦ φίλου ἀνέρος ἐστὶ ψυχή, τὴν ἔγνων φθεγξαμένης ἀΐων.", "st": "8.36d"}, {"sp": "N", "t": "Καὶ ταῦτα μὲν ὁ Ξενοφάνης. ἔσκωψε δ’ αὐτὸν Κρατῖνος μὲν ἐν Πυθαγοριζούσῃ· ἀλλὰ καὶ ἐν Ταραντίνοις φησὶν οὕτως·<br>ἔθος ἐστὶν αὐτοῖς, ἄν τιν’ ἰδιώτην ποθὲν λάβωσιν εἰσελθόντα, διαπειρώμενον τῆς τῶν λόγων ῥώμης ταράττειν καὶ κυκᾶν τοῖς ἀντιθέτοις, τοῖς πέρασι, τοῖς παρισώμασιν, τοῖς ἀποπλάνοις, τοῖς μεγέθεσιν νουβυστικῶς.", "st": "8.37"}, {"sp": "N", "t": "Μνησίμαχος δ’ Ἀλκμαίωνι·<br>ὡς Πυθαγοριστὶ θύομεν τῷ Λοξίᾳ, ἔμψυχον οὐδὲν ἐσθίοντες παντελῶς. Ἀριστοφῶν Πυθαγοριστῇ·<br>ἔφη καταβὰς ἐς τὴν δίαιταν τῶν κάτω ἰδεῖν ἑκάστους, διαφέρειν δὲ πάμπολυ τοὺς Πυθαγοριστὰς τῶν νεκρῶν· μόνοισι γὰρ τούτοισι τὸν Πλούτωνα συσσιτεῖν ἔφη δι’ εὐσέβειαν. β. δυσχερῆ θεὸν λέγεις, εἰ τοῖς ῥύπου μεστοῖσιν ἥδεται ξυνών.<br>ἔτι ἐν τῷ αὐτῷ·<br>ἐσθίουσί τε λάχανά τε καὶ πίνουσιν ἐπὶ τούτοις ὕδωρ· φθεῖρας δὲ καὶ τρίβωνα τήν τ’ ἀλουσίαν οὐδεὶς ἂν ὑπομείνειε τῶν ἑτέρων 〈νεκρῶν〉.", "st": "8.38"}, {"sp": "N", "t": "Ἐτελεύτα δ’ ὁ Πυθαγόρας τοῦτον τὸν τρόπον. συνεδρεύοντος μετὰ τῶν συνήθων ἐν τῇ Μίλωνος οἰκίᾳ [τούτου], ὑπό τινος τῶν μὴ παραδοχῆς ἀξιωθέντων διὰ φθόνον ὑποπρησθῆναι τὴν οἰκίαν συνέβη· τινὲς δ’ αὐτοὺς τοὺς Κροτωνιάτας τοῦτο πρᾶξαι, τυραννίδος ἐπίθεσιν εὐλαβουμένους. τὸν δὴ Πυθαγόραν καταληφθῆναι διεξιόντα· καὶ πρός τινι χωρίῳ γενόμενος πλήρει κυάμων, ἵνα [αὐτόθι] ἔστη, εἰπὼν ἁλῶναι ἂν μᾶλλον ἢ πατῆσαι [ἀναιρεθῆναι δὲ κρεῖττον ἢ λαλῆσαι]· καὶ ὧδε πρὸς τῶν διωκόντων ἀποσφαγῆναι. οὕτω δὲ καὶ τοὺς πλείους τῶν ἑταίρων αὐτοῦ διαφθαρῆναι, ὄντας πρὸς τοὺς τετταράκοντα· διαφυγεῖν δ’ ὀλίγους, ὧν ἦν καὶ Ἄρχιππος ὁ Ταραντῖνος καὶ Λῦσις ὁ προειρημένος.", "st": "8.39"}, {"sp": "N", "t": "Φησὶ δὲ Δικαίαρχος τὸν Πυθαγόραν ἀποθανεῖν καταφυγόντα εἰς τὸ ἐν Μεταποντίῳ ἱερὸν τῶν Μουσῶν, τετταράκοντ’ ἡμέρας ἀσιτήσαντα. Ἡρακλείδης δέ φησιν ἐν τῇ τῶν Σατύρου βίων ἐπιτομῇ μετὰ τὸ θάψαι Φερεκύδην ἐν Δήλῳ ἐπανελθεῖν εἰς Ἰταλίαν καὶ * * πανδαισίαν εὑρόντα Κύλωνος τοῦ Κροτωνιάτου εἰς Μεταπόντιον ὑπεξελθεῖν κἀκεῖ τὸν βίον καταστρέψαι ἀσιτίᾳ, μὴ βουλόμενον περαιτέρω ζῆν. Ἕρμιππος δέ φησι, πολεμούντων Ἀκραγαντίνων καὶ Συρακοσίων, ἐξελθεῖν τὸν Πυθαγόραν μετὰ τῶν συνήθων καὶ προστῆναι τῶν Ἀκραγαντίνων· τροπῆς δὲ γενομένης περικάμπτοντα αὐτὸν τὴν τῶν κυάμων χώραν ὑπὸ τῶν Συρακοσίων ἀναιρεθῆναι· τούς τε λοιπούς, ὄντας πρὸς τοὺς πέντε καὶ τριάκοντα, ἐν Τάραντι κατακαυθῆναι, θέλοντας ἀντιπολιτεύεσθαι τοῖς προεστῶσι.", "st": "8.40"}, {"sp": "N", "t": "Καὶ ἄλλο τι περὶ Πυθαγόρου φησὶν ὁ Ἕρμιππος. [λέγει γὰρ] ὡς γενόμενος ἐν Ἰταλίᾳ κατὰ γῆς οἰκίσκον ποιήσαι καὶ τῇ μητρὶ ἐντείλαιτο τὰ γινόμενα εἰς δέλτον γράφειν σημειουμένην καὶ τὸν χρόνον, ἔπειτα καθιέναι αὐτῷ ἔστ’ ἂν ἀνέλθῃ. τοῦτο ποιῆσαι τὴν μητέρα. τὸν δὲ Πυθαγόραν μετὰ χρόνον ἀνελθεῖν ἰσχνὸν καὶ κατεσκελετευμένον· εἰσελθόντα τ’ εἰς τὴν ἐκκλησίαν φάσκειν ὡς ἀφῖκται ἐξ ᾅδου· καὶ δὴ καὶ ἀνεγίνωσκεν αὐτοῖς τὰ συμβεβηκότα. οἱ δὲ σαινόμενοι τοῖς λεγομένοις ἐδάκρυόν τε καὶ ᾤμωζον καὶ ἐπίστευον εἶναι τὸν Πυθαγόραν θεῖόν τινα, ὥστε καὶ τὰς γυναῖκας αὐτῷ παραδοῦναι, ὡς καὶ μαθησομένας τι τῶν αὐτοῦ· ἃς καὶ Πυθαγορικὰς κληθῆναι. καὶ ταῦτα μὲν ὁ Ἕρμιππος.", "st": "8.41"}, {"sp": "N", "t": "Ἦν δὲ τῷ Πυθαγόρᾳ καὶ γυνή, Θεανὼ ὄνομα, Βροντίνου τοῦ Κροτωνιάτου θυγάτηρ· οἱ δέ, γυναῖκα μὲν εἶναι Βροντίνου, μαθήτριαν δὲ Πυθαγόρου. ἦν αὐτῷ καὶ θυγάτηρ Δαμώ, ὥς φησι Λῦσις ἐν ἐπιστολῇ τῇ πρὸς Ἵππασον, περὶ Πυθαγόρου λέγων οὕτως· λέγοντι δὲ πολλοὶ τὺ καὶ δαμοσίᾳ φιλοσοφέν, ὅπερ ἀπαξίωσε Πυθαγόρας, ὅς γέ τοι Δαμοῖ τᾷ ἑαυτοῦ θυγατρὶ παρακαταθέμενος τὰ ὑπομνάματα ἐπέσκαψε μηδενὶ τῶν ἐκτὸς τᾶς οἰκίας παραδιδόμεν. ἁ δὲ δυναμένα πολλῶν χραμάτων ἀποδίδοσθαι τὼς λόγως οὐκ ἐβουλάθη· πενίαν δὲ καὶ τὰς τῶ πατρὸς ἐπισκάψιας ἐνόμιζε χρυσῶ τιμιωτέρας ἦμεν, καὶ ταῦτα γυνά.", "st": "8.42"}, {"sp": "N", "t": "Ἦν καὶ Τηλαύγης υἱὸς αὐτοῖς, ὃς καὶ διεδέξατο τὸν πατέρα καὶ κατά τινας Ἐμπεδοκλέους καθηγήσατο· Ἱππόβοτός γέ τοί φησι λέγειν Ἐμπεδοκλέα,<br>Τήλαυγες, κλυτὲ κοῦρε Θεανοῦς Πυθαγόρεώ τε.", "st": "8.43"}, {"sp": "N", "t": "σύγγραμμα δὲ [φέρεται] τοῦ Τηλαύγους οὐδέν, τῆς δὲ μητρὸς αὐτοῦ Θεανοῦς τινα. ἀλλὰ καί φασιν αὐτὴν ἐρωτηθεῖσαν ποσταία γυνὴ ἀπ’ ἀνδρὸς καθαρεύει, φάναι, ἀπὸ μὲν τοῦ ἰδίου παραχρῆμα, ἀπὸ δὲ τοῦ ἀλλοτρίου οὐδέποτε. τῇ δὲ πρὸς τὸν ἴδιον ἄνδρα μελλούσῃ πορεύεσθαι παρῄνει ἅμα τοῖς ἐνδύμασι καὶ τὴν αἰσχύνην ἀποτίθεσθαι, ἀνισταμένην τε πάλιν ἅμ’ αὐτοῖσιν ἀναλαμβάνειν. ἐρωτηθεῖσα, ποῖα; ἔφη, ταῦτα δι’ ἃ γυνὴ κέκλημαι.", "st": "8.43b"}, {"sp": "N", "t": "Ὁ δ’ οὖν Πυθαγόρας, ὡς μὲν Ἡρακλείδης φησὶν ὁ τοῦ Σαραπίωνος, ὀγδοηκοντούτης ἐτελεύτα, κατὰ τὴν ἰδίαν ὑπογραφὴν τῶν ἡλικιῶν· ὡς δ’ οἱ πλείους, ἔτη βιοὺς ἐνενήκοντα. καὶ ἡμῶν ἐστιν εἰς αὐτὸν πεπαιγμένα οὕτως ἔχοντα·<br>οὐ μόνος ἐμψύχων ἄπεχες χέρας, ἀλλὰ καὶ ἡμεῖς· τίς γὰρ ὃς ἐμψύχων ἥψατο, Πυθαγόρα; ἀλλ’ ὅταν ἑψηθῇ τι καὶ ὀπτηθῇ καὶ ἁλισθῇ, δὴ τότε καὶ ψυχὴν οὐκ ἔχον ἐσθίομεν.", "st": "8.44"}, {"sp": "N", "t": "ἄλλο·<br>ἦν ἄρα Πυθαγόρης τοῖος σοφός, ὥστε μὲν αὐτὸς μὴ ψαύειν κρειῶν καὶ λέγεν ὡς ἄδικον, σιτίζειν δ’ ἄλλους. ἄγαμαι σοφόν· αὐτὸς ἔφα μὲν οὐκ ἀδικεῖν, ἄλλους δ’ αὐτὸς ἔτευχ’ ἀδικεῖν. καὶ ἄλλο·<br>τὰς φρένας ἢν ἐθέλῃς τὰς Πυθαγόραο νοῆσαι, ἀσπίδος Εὐφόρβου βλέψον ἐς ὀμφάλιον. φησὶ γὰρ οὗτος, Ἐγὼν ἦν πρόβροτος· ὃς δ’ ὅτε οὐκ ἦν, φάσκων ὥς τις ἔην, οὔτις ἔην ὅτ’ ἔην.<br>καὶ ἄλλο, ὡς ἐτελεύτα·<br>αἲ, αἴ, Πυθαγόρης τί τόσον κυάμους ἐσεβάσθη; καὶ θάνε φοιτηταῖς ἄμμιγα τοῖς ἰδίοις. χωρίον ἦν κυάμων· ἵνα μὴ τούτους δὲ πατήσῃ, ἐξ Ἀκραγαντίνων κάτθαν’ ἐνὶ τριόδῳ.", "st": "8.45"}, {"sp": "N", "t": "Ἤκμαζε δὲ καὶ κατὰ τὴν ἑξηκοστὴν Ὀλυμπιάδα, καὶ αὐτοῦ τὸ σύστημα διέμενε μέχρι γενεῶν ἐννέα ἢ καὶ δέκα· τελευταῖοι γὰρ ἐγένοντο τῶν Πυθαγορείων, οὓς καὶ Ἀριστόξενος εἶδε, Ξενόφιλός τε ὁ Χαλκιδεὺς ἀπὸ Θρᾴκης καὶ Φάντων ὁ Φλιάσιος καὶ Ἐχεκράτης καὶ Διοκλῆς καὶ Πολύμναστος, Φλιάσιοι καὶ αὐτοί. ἦσαν δ’ ἀκροαταὶ Φιλολάου καὶ Εὐρύτου τῶν Ταραντίνων.", "st": "8.46"}, {"sp": "N", "t": "Γεγόνασι δὲ Πυθαγόραι τέτταρες περὶ τοὺς αὐτοὺς χρόνους, οὐ πολὺ ἀπ’ ἀλλήλων ἀπέχοντες· εἷς μὲν Κροτωνιάτης, τυραννικὸς ἄνθρωπος· ἕτερος Φλιάσιος, σωμασκητής, [ἀλείπτης, ὥς φασί τινες]· τρίτος Ζακύνθιος· τέταρτος αὐτὸς οὗτος, οὗ φασιν εἶναι τἀπόρρητα τῆς φιλοσοφίας· [αὐτῶν διδάσκαλος·] ἐφ’ οὗ καὶ τὸ Αὐτὸς ἔφα παροιμιακὸν εἰς τὸν βίον ἦλθεν. οἱ δὲ καὶ ἄλλον ἀνδριαντοποιὸν Ῥηγῖνον γεγονέναι φασὶ Πυθαγόραν, πρῶτον δοκοῦντα ῥυθμοῦ καὶ συμμετρίας ἐστοχάσθαι· καὶ ἄλλον ἀνδριαντοποιὸν Σάμιον· καὶ ἕτερον ῥήτορα μοχθηρόν· καὶ ἰατρὸν ἄλλον, τὰ περὶ κήλης γεγραφότα καί τινα περὶ Ὁμήρου συντεταγμένον· καὶ ἕτερον Δωρικὰ πεπραγματευμένον, ὡς Διονύσιος ἱστορεῖ.", "st": "8.47"}, {"sp": "N", "t": "Ἐρατοσθένης δέ φησι, καθὸ καὶ Φαβωρῖνος ἐν τῇ ὀγδόῃ Παντοδαπῆς ἱστορίας παρατίθεται, τοῦτον εἶναι τὸν πρῶτον ἐντέχνως πυκτεύσαντα ἐπὶ τῆς ὀγδόης καὶ τετταρακοστῆς Ὀλυμπιάδος, κομήτην καὶ ἁλουργίδα φοροῦντα· ἐκκριθέντα τ’ ἐκ τῶν παίδων καὶ χλευασθέντα αὐτίκα προσβῆναι τοὺς ἄνδρας καὶ νικῆσαι. δηλοῦν δὲ τοῦτο καὶ τοὐπίγραμμα ὅπερ ἐποίησε Θεαίτητος·<br>Πυθαγόρην τινά, Πυθαγόρην, ὦ ξεῖνε, κομήτην, ᾀδόμενον πύκτην εἰ κατέχεις Σάμιον, Πυθαγόρης ἐγώ εἰμι· τὰ δ’ ἔργα μου εἴ τιν’ ἔροιο Ἠλείων, φήσεις αὐτὸν ἄπιστα λέγειν.", "st": "8.48"}, {"sp": "N", "t": "Τοῦτον ὁ Φαβωρῖνός φησιν ὅροις χρήσασθαι διὰ τῆς μαθηματικῆς ὕλης, ἐπὶ πλέον δὲ Σωκράτην καὶ τοὺς ἐκείνῳ πλησιάσαντας, καὶ μετὰ ταῦτ’ Ἀριστοτέλην καὶ τοὺς στωικούς.", "st": "8.48b"}, {"sp": "N", "t": "Ἀλλὰ μὴν καὶ τὸν οὐρανὸν πρῶτον ὀνομάσαι κόσμον καὶ τὴν γῆν στρογγύλην· ὡς δὲ Θεόφραστος, Παρμενίδην· ὡς δὲ Ζήνων, Ἡσίοδον. τούτῳ φασὶν ἀντιπαρατάσσεσθαι Κύλωνα καθάπερ Ἀντίλοχον Σωκράτει. Ἐπὶ δὲ τοῦ ἀθλητοῦ Πυθαγόρου καὶ τοῦτ’ ἐλέγετο τὸ ἐπίγραμμα·<br>οὗτος πυκτεύσων ἐς Ὀλύμπια παισὶν ἄνηβος ἤλυθε Πυθαγόρης ὁ Κράτεω Σάμιος.", "st": "8.49"}, {"sp": "N", "t": "ὁ δὲ φιλόσοφος καὶ ὧδε ἐπέστειλε·", "st": "8.49b"}, {"sp": "N", "t": "Πυθαγόρης Ἀναξιμένει. “Καὶ σύ, ὦ λῷστε, εἰ μηδὲν ἀμείνων ἦς Πυθαγόρεω γενεήν τε καὶ κλέος, μεταναστὰς ἂν οἴχεο ἐκ Μιλήτου· νῦν δὲ κατερύκει σε ἡ πατρόθεν εὔκλεια, καὶ ἐμὲ δὲ ἂν κατείρυκεν Ἀναξιμένει ἐοικότα. εἰ δὲ ὑμεῖς οἱ ὀνήιστοι τὰς πόλιας ἐκλείψετε, ἀπὸ μὲν αὐτέων ὁ κόσμος αἱρεθήσεται, ἐπικινδυνότερα δ’ αὐτῇσι τὰ ἐκ Μήδων. οὔτε δὲ αἰεὶ καλὸν αἰθερολογέειν μελεδωνόν τε εἶναι τῇ πατρίδι κάλλιον. καὶ ἐγὼ δὲ οὐ πάντα περὶ τοὺς ἐμεωυτοῦ μύθους, ἀλλὰ καὶ ἐν πολέμοις οὓς διαφέρουσιν ἐς ἀλλήλους Ἰταλιῶται.", "st": "8.50"}, {"sp": "N", "t": "Ἐπειδὴ δὲ περὶ Πυθαγόρου διεληλύθαμεν, ῥητέον περὶ τῶν ἐλλογίμων Πυθαγορικῶν· μεθ’ οὓς περὶ τῶν σποράδην κατά τινας φερομένων· ἔπειθ’ οὕτως ἐξάψομεν τὴν διαδοχὴν τῶν ἀξίων λόγου ἕως Ἐπικούρου καθὰ καὶ προειρήκαμεν.", "st": "8.50b"}, {"sp": "N", "t": "περὶ μὲν οὖν Θεανοῦς καὶ Τηλαύγους διειλέγμεθα· λεκτέον δὲ νῦν περὶ Ἐμπεδοκλέους πρῶτον· κατὰ γάρ τινας Πυθαγόρου διήκουσεν.", "st": "8.50c"}, {"sp": "HDR", "t": "ΕΜΠΕΔΟΚΛΗΣ"}, {"sp": "N", "t": "Ἐμπεδοκλῆς, ὥς φησιν Ἱππόβοτος, Μέτωνος ἦν υἱὸς τοῦ Ἐμπεδοκλέους, Ἀκραγαντῖνος. τὸ δ’ αὐτὸ καὶ Τίμαιος ἐν τῇ πεντεκαιδεκάτῃ τῶν Ἱστοριῶν 〈λέγει προσιστορῶν〉 ἐπίσημον ἄνδρα γεγονέναι τὸν Ἐμπεδοκλέα τὸν πάππον τοῦ ποιητοῦ. ἀλλὰ καὶ Ἕρμιππος τὰ αὐτὰ τούτῳ φησίν. ὁμοίως καὶ Ἡρακλείδης ἐν τῷ Περὶ νόσων, ὅτι λαμπρᾶς ἦν οἰκίας ἱπποτροφηκότος τοῦ πάππου. λέγει δὲ καὶ Ἐρατοσθένης ἐν τοῖς Ὀλυμπιονίκαις τὴν πρώτην καὶ ἑβδομηκοστὴν Ὀλυμπιάδα νενικηκέναι τὸν τοῦ Μέτωνος πατέρα, μάρτυρι χρώμενος Ἀριστοτέλει.", "st": "8.51"}, {"sp": "N", "t": "Ἀπολλόδωρος δ’ ὁ γραμματικὸς ἐν τοῖς Χρονικοῖς φησιν ὡς<br>ἦν μὲν Μέτωνος υἱός, εἰς δὲ Θουρίους αὐτὸν νεωστὶ παντελῶς ἐκτισμένους 〈ὁ〉 Γλαῦκος ἐλθεῖν φησιν.<br>εἶθ’ ὑποβάς·<br>οἱ δ’ ἱστοροῦντες, ὡς πεφευγὼς οἴκοθεν εἰς τὰς Συρακούσας μετ’ ἐκείνων ἐπολέμει πρὸς Ἀθηνάους ἐμοί 〈γε〉 τελέως ἀγνοεῖν δοκοῦσιν· ἢ γὰρ οὐκέτ’ ἦν ἢ παντελῶς ὑπεργεγηρακώς, ὅπερ οὐχὶ φαίνεται.<br>Ἀριστοτέλης γὰρ αὐτόν, ἔτι τε Ἡρακλείδης, ἑξήκοντα ἐτῶν φησὶ τετελευτηκέναι.", "st": "8.52"}, {"sp": "N", "t": "ὁ δὲ 〈τὴν〉 μίαν καὶ ἑβδομηκοστὴν Ὀλυμπιάδα νενικηκὼς<br>κέλητι τούτου πάππος ἦν ὁμώνυμος,<br>ὥσθ’ ἅμα καὶ τὸν χρόνον ὑπὸ τοῦ Ἀπολλοδώρου σημαίνεσθαι.", "st": "8.52b"}, {"sp": "N", "t": "Σάτυρος δ’ ἐν τοῖς Βίοις φησὶν ὅτι Ἐμπεδοκλῆς υἱὸς μὲν ἦν Ἐξαινέτου, κατέλιπε δὲ καὶ αὐτὸς υἱὸν Ἐξαίνετον· ἐπί τε τῆς αὐτῆς Ὀλυμπιάδος τὸν μὲν ἵππῳ κέλητι νενικηκέναι, τὸν δ’ υἱὸν αὐτοῦ πάλῃ ἤ, ὡς Ἡρακλείδης ἐν τῇ Ἐπιτομῇ, δρόμῳ. ἐγὼ δ’ εὗρον ἐν τοῖς Ὑπομνήμασι Φαβωρίνου ὅτι καὶ βοῦν ἔθυσε τοῖς θεωροῖς ὁ Ἐμπεδοκλῆς ἐκ μέλιτος καὶ ἀλφίτων, καὶ ἀδελφὸν ἔσχε Καλλικρατίδην.", "st": "8.53"}, {"sp": "N", "t": "Τηλαύγης δ’ ὁ Πυθαγόρου παῖς ἐν τῇ πρὸς Φιλόλαον ἐπιστολῇ φησι τὸν Ἐμπεδοκλέα Ἀρχινόμου εἶναι υἱόν. Ὅτι δ’ ἦν Ἀκραγαντῖνος ἐκ Σικελίας, αὐτὸς ἐναρχόμενος τῶν Καθαρμῶν φησιν·<br>ὦ φίλοι οἳ μέγα ἄστυ κατὰ ξανθοῦ Ἀκράγαντος ναίετ’ ἀν’ ἄκρα πόλεος.", "st": "8.54"}, {"sp": "N", "t": "καὶ τὰ μὲν περὶ τοῦ γένους αὐτοῦ τάδε.", "st": "8.54b"}, {"sp": "N", "t": "Ἀκοῦσαι δ’ αὐτὸν Πυθαγόρου Τίμαιος διὰ τῆς ἐνάτης ἱστορεῖ, λέγων ὅτι καταγνωσθεὶς ἐπὶ λογοκλοπίᾳ τότε, καθὰ καὶ Πλάτων, τῶν λόγων ἐκωλύθη μετέχειν. μεμνῆσθαι δὲ καὶ αὐτὸν Πυθαγόρου λέγοντα·<br>ἦν δέ τις ἐν κείνοισιν ἀνὴρ περιώσια εἰδώς, ὃς δὴ μήκιστον πραπίδων ἐκτήσατο πλοῦτον.", "st": "8.54c"}, {"sp": "N", "t": "οἱ δὲ τοῦτο εἰς Παρμενίδην αὐτὸν λέγειν ἀναφέροντα.", "st": "8.54d"}, {"sp": "N", "t": "Φησὶ δὲ Νεάνθης ὅτι μέχρι Φιλολάου καὶ Ἐμπεδοκλέους ἐκοινώνουν οἱ Πυθαγορικοὶ τῶν λόγων. ἐπεὶ δ’ αὐτὸς διὰ τῆς ποιήσεως ἐδημοσίωσεν αὐτά, νόμον ἔθεντο μηδενὶ μεταδώσειν ἐποποιῷ. τὸ δ’ αὐτὸ καὶ Πλάτωνα παθεῖν φησι· καὶ γὰρ τοῦτον κωλυθῆναι. τίνος μέντοι γε αὐτῶν ἤκουσεν ὁ Ἐμπεδοκλῆς, οὐκ εἶπε· τὴν γὰρ περιφερομένην ὡς Τηλαύγους ἐπιστολὴν ὅτι τε μετέσχεν Ἱππάσου καὶ Βροντίνου, μὴ εἶναι ἀξιόπιστον. Ὁ δὲ Θεόφραστος Παρμενίδου φησὶ ζηλωτὴν αὐτὸν γενέσθαι καὶ μιμητὴν ἐν τοῖς ποιήμασι· καὶ γὰρ ἐκεῖνον ἐν ἔπεσι τὸν Περὶ φύσεως ἐξενεγκεῖν λόγον.", "st": "8.55"}, {"sp": "N", "t": "Ἕρμιππος δὲ οὐ Παρμενίδου, Ξενοφάνους δὲ γεγονέναι ζηλωτήν, ᾧ καὶ συνδιατρῖψαι καὶ μιμήσασθαι τὴν ἐποποιίαν· ὕστερον δὲ τοῖς Πυθαγορικοῖς ἐντυχεῖν. Ἀλκιδάμας δ’ ἐν τῷ Φυσικῷ φησι κατὰ τοὺς αὐτοὺς χρόνους Ζήνωνα καὶ Ἐμπεδοκλέα ἀκοῦσαι Παρμενίδου, εἶθ’ ὕστερον ἀποχωρῆσαι, καὶ τὸν μὲν Ζήνωνα κατ’ ἰδίαν φιλοσοφῆσαι, τὸν δὲ Ἀναξαγόρου διακοῦσαι καὶ Πυθαγόρου· καὶ τοῦ μὲν τὴν σεμνότητα ζηλῶσαι τοῦ τε βίου καὶ τοῦ σχήματος, τοῦ δὲ τὴν φυσιολογίαν.", "st": "8.56"}, {"sp": "N", "t": "Ἀριστοτέλης δ’ ἐν τῷ Σοφιστῇ φησι πρῶτον Ἐμπεδοκλέα ῥητορικὴν εὑρεῖν, Ζήνωνα δὲ διαλεκτικήν. ἐν δὲ τῷ Περὶ ποιητῶν φησιν ὅτι καὶ Ὁμηρικὸς ὁ Ἐμπεδοκλῆς καὶ δεινὸς περὶ τὴν φράσιν γέγονεν, μεταφορητικός τε ὢν καὶ τοῖς ἄλλοις τοῖς περὶ ποιητικὴν ἐπιτεύγμασι χρώμενος· καὶ διότι γράψαντος αὐτοῦ καὶ ἄλλα ποιήματα τήν τε τοῦ Ξέρξου διάβασιν καὶ προοίμιον εἰς Ἀπόλλωνα, ταῦθ’ ὕστερον κατέκαυσεν ἀδελφή τις αὐτοῦ (ἢ θυγάτηρ, ὥς φησιν Ἱερώνυμος), τὸ μὲν προοίμιον ἄκουσα, τὰ δὲ Περσικὰ βουληθεῖσα διὰ τὸ ἀτελείωτα εἶναι. καθόλου δέ φησι καὶ τραγῳδίας αὐτὸν γράψαι καὶ πολιτικούς·", "st": "8.57"}, {"sp": "N", "t": "Ἡρακλείδης δ’ ὁ τοῦ Σαραπίωνος ἑτέρου φησὶν εἶναι τὰς τραγῳδίας. Ἱερώνυμος δὲ τρισὶ καὶ τετταράκοντά φησιν ἐντετυχηκέναι, Νεάνθης δὲ νέον ὄντα γεγραφέναι τὰς τραγῳδίας καὶ αὐτῶν ἑπτὰ ἐντετυχηκέναι. Φησὶ δὲ Σάτυρος ἐν τοῖς Βίοις ὅτι καὶ ἰατρὸς ἦν καὶ ῥήτωρ ἄριστος. Γοργίαν γοῦν τὸν Λεοντῖνον αὐτοῦ γενέσθαι μαθητήν, ἄνδρα ὑπερέχοντα ἐν ῥητορικῇ καὶ Τέχνην ἀπολελοιπότα· ὅν φησιν Ἀπολλόδωρος ἐν Χρονικοῖς ἐννέα πρὸς τοῖς ἑκατὸν ἔτη βιῶναι.", "st": "8.57b"}, {"sp": "N", "t": "τοῦτόν φησιν ὁ Σάτυρος λέγειν ὡς αὐτὸς παρείη τῷ Ἐμπεδοκλεῖ γοητεύοντι. ἀλλὰ καὶ αὐτὸν διὰ τῶν ποιημάτων ἐπαγγέλλεσθαι τοῦτό τε καὶ ἄλλα πλείω, δι’ ὧν φησι· φάρμακα δ’ ὅσσα γεγᾶσι κακῶν καὶ γήραος ἄλκαρ πεύσῃ, ἐπεὶ μούνῳ σοὶ ἐγὼ κρανέω τάδε πάντα. παύσεις δ’ ἀκαμάτων ἀνέμων μένος, οἵ τ’ ἐπὶ γαῖαν ὀρνύμενοι πνοιαῖσι καταφθινύθουσιν ἄρουραν· καὶ πάλιν, ἢν ἐθέλῃσθα, παλίντιτα πνεύματ’ ἐπάξεις· θήσεις δ’ ἐξ ὄμβροιο κελαινοῦ καίριον αὐχμὸν ἀνθρώποις, θήσεις δὲ καὶ ἐξ αὐχμοῖο θερείου ῥεύματα δενδρεόθρεπτα, τά τ’ αἰθέρι ναιήσονται, ἄξεις δ’ ἐξ Ἀΐδαο καταφθιμένου μένος ἀνδρός.", "st": "8.59"}, {"sp": "N", "t": "Φησὶ δὲ καὶ Τίμαιος ἐν τῇ ὀκτωκαιδεκάτῃ κατὰ πολλοὺς τρόπους τεθαυμάσθαι τὸν ἄνδρα. καὶ γὰρ ἐτησίων ποτὲ σφοδρῶς πνευσάντων ὡς τοὺς καρποὺς λυμῆναι, κελεύσας ὄνους ἐκδαρῆναι καὶ ἀσκοὺς ποιῆσαι περὶ τοὺς λόφους καὶ τὰς ἀκρωρείας διέτεινε πρὸς τὸ συλλαβεῖν τὸ πνεῦμα· λήξαντος δὲ κωλυσανέμαν κληθῆναι. Ἡρακλείδης τε ἐν τῷ Περὶ νόσων φησὶ καὶ Παυσανίᾳ ὑφηγήσασθαι αὐτὸν τὰ περὶ τὴν ἄπνουν. ἦν δ’ ὁ Παυσανίας, ὥς φησιν Ἀρίστιππος καὶ Σάτυρος, ἐρώμενος αὐτοῦ, ᾧ δὴ καὶ τὰ Περὶ φύσεως προσπεφώνηκεν οὕτως· Παυσανίη, σὺ δὲ κλῦθι, δαΐφρονος Ἀγχίτου υἰέ.", "st": "8.60"}, {"sp": "N", "t": "ἀλλὰ καὶ ἐπίγραμμα εἰς αὐτὸν ἐποίησε·<br>Παυσανίην ἰητρὸν ἐπώνυμον Ἀγχίτου υἱὸν φῶτ’ Ἀσκληπιάδην πατρὶς ἔθρεψε Γέλα, ὃς πολλοὺς μογεροῖσι μαραινομένους καμάτοισι φῶτας ἀπέστρεψεν Φερσεφόνης ἀδύτων.", "st": "8.60b"}, {"sp": "N", "t": "τὴν γοῦν ἄπνουν ὁ Ἡρακλείδης φησὶ τοιοῦτόν τι εἶναι, ὡς τριάκοντα ἡμέρας συντηρεῖν ἄπνουν καὶ ἄσφυκτον τὸ σῶμα· ὅθεν καὶ εἶπεν αὐτὸν καὶ ἰητρὸν καὶ μάντιν, λαμβάνων ἅμα καὶ ἀπὸ τούτων τῶν στίχων· ὦ φίλοι, οἳ μέγα ἄστυ κατὰ ξανθοῦ Ἀκράγαντος ναίετ’ ἀν’ ἄκρα πόλεος, ἀγαθῶν μελεδήμονες ἔργων, χαίρετ’· ἐγὼ δ’ ὑμῖν θεὸς ἄμβροτος, οὐκέτι θνητὸς πωλεῦμαι μετὰ πᾶσι τετιμένος, ὥσπερ ἔοικα, ταινίαις τε περίστεπτος στέφεσίν τε θαλείοις· τοῖσιν ἅμ’ 〈εὖτ’〉 ἂν ἵκωμαι ἐς ἄστεα τηλεθάοντα, ἀνδράσιν ἠδὲ γυναιξί, σεβίζομαι· οἱ δ’ ἅμ’ ἕπονται μυρίοι, ἐξερέοντες ὅπῃ πρὸς κέρδος ἀταρπός· οἱ μὲν μαντοσυνέων κεχρημένοι, οἱ δ’ ἐπὶ νούσων παντοίων ἐπύθοντο κλύειν εὐηκέα βάξιν.", "st": "8.62"}, {"sp": "N", "t": "Μέγαν δὲ τὸν Ἀκράγαντα εἰπεῖν φησιν ἐπεὶ μυριάδες αὐτὸν κατῴκουν ὀγδοήκοντα· ὅθεν τὸν Ἐμπεδοκλέα εἰπεῖν, τρυφώντων αὐτῶν, Ἀκραγαντῖνοι τρυφῶσι μὲν ὡς αὔριον ἀποθανούμενοι, οἰκίας δὲ κατασκευάζονται ὡς πάντα τὸν χρόνον βιωσόμενοι.", "st": "8.63"}, {"sp": "N", "t": "Αὐτοὺς δὲ τούτους τοὺς Καθαρμοὺς [ἐν] Ὀλυμπίασι ῥαψῳδῆσαι λέγεται Κλεομένη τὸν ῥαψῳδόν, ὡς καὶ Φαβωρῖνος ἐν Ἀπομνημονεύμασι.", "st": "8.63b"}, {"sp": "N", "t": "φησὶ δ’ αὐτὸν καὶ Ἀριστοτέλης ἐλεύθερον γεγονέναι καὶ πάσης ἀρχῆς ἀλλότριον, εἴ γε τὴν βασιλείαν αὐτῷ διδομένην παρῃτήσατο, καθάπερ Ξάνθος ἐν τοῖς περὶ αὐτοῦ λέγει, τὴν λιτότητα δηλονότι πλέον ἀγαπήσας. τὰ δ’ αὐτὰ καὶ Τίμαιος εἴρηκε, τὴν αἰτίαν ἅμα παρατιθέμενος τοῦ δημοτικὸν εἶναι τὸν ἄνδρα. φησὶ γὰρ ὅτι κληθεὶς ὑπό τινος τῶν ἀρχόντων 〈ὡς〉 προβαίνοντος τοῦ δείπνου τὸ ποτὸν οὐκ εἰσεφέρετο, τῶν ἄλλων ἡσυχαζόντων, μισοπονήρως διατεθεὶς ἐκέλευσεν εἰσφέρειν· ὁ δὲ κεκληκὼς ἀναμένειν ἔφη τὸν τῆς βουλῆς ὑπηρέτην. ὡς δὲ παρεγένετο, ἐγενήθη συμποσίαρχος, τοῦ κεκληκότος δηλονότι καταστήσαντος, ὃς ὑπεγράφετο τυραννίδος ἀρχήν· ἐκέλευσε γὰρ ἢ πίνειν ἢ καταχεῖσθαι τῆς κεφαλῆς. τότε μὲν οὖν ὁ Ἐμπεδοκλῆς ἡσύχασε· τῇ δ’ ὑστεραίᾳ εἰσαγαγὼν εἰς δικαστήριον ἀπέκτεινε καταδικάσας ἀμφοτέρους, τόν τε κλήτορα καὶ τὸν συμποσίαρχον.", "st": "8.64"}, {"sp": "N", "t": "ἀρχὴ μὲν οὖν αὐτῷ τῆς πολιτείας ἥδε. Πάλιν δ’ Ἄκρωνος τοῦ ἰατροῦ τόπον αἰτοῦντος παρὰ τῆς βουλῆς εἰς κατασκευὴν πατρῴου μνήματος διὰ τὴν ἐν τοῖς ἰατροῖς ἀκρότητα παρελθὼν ὁ Ἐμπεδοκλῆς ἐκώλυσε, τά τ’ ἄλλα περὶ ἰσότητος διαλεχθεὶς καί τι καὶ τοιοῦτον ἐρωτήσας· τί δ’ ἐπιγράψομεν ἐλεγεῖον; ἢ τοῦτο;<br>ἄκρον ἰατρὸν Ἄκρων’ Ἀκραγαντῖνον πατρὸς Ἄκρου κρύπτει κρημνὸς ἄκρος πατρίδος ἀκροτάτης.", "st": "8.65"}, {"sp": "N", "t": "τινὲς δὲ τὸν δεύτερον στίχον οὕτω προφέρονται,<br>ἀκροτάτης κορυφῆς τύμβος ἄκρος κατέχει.<br>τοῦτό τινες Σιμωνίδου φασὶν εἶναι.", "st": "8.65b"}, {"sp": "N", "t": "Ὕστερον δ’ ὁ Ἐμπεδοκλῆς καὶ τὸ τῶν χιλίων ἄθροισμα κατέλυσε συνεστὸς ἐπὶ ἔτη τρία, ὥστε οὐ μόνον ἦν τῶν πλουσίων, ἀλλὰ καὶ τῶν τὰ δημοτικὰ φρονούντων. ὅ γέ τοι Τίμαιος ἐν τῇ ια’ καὶ ιβ’, πολλάκις γὰρ αὐτοῦ μνημονεύει, φησὶν ἐναντίαν ἐσχηκέναι γνώμην αὐτὸν τῇ πολιτείᾳ φαίνεσθαι· 〈ἔστιν〉 ὅπου δ’ ἀλαζόνα καὶ φίλαυτον ἐν τῇ ποιήσει [ἴδοι τις ἄν]· φησὶ γοῦν,<br>χαίρετ’· ἐγὼ δ’ ὑμῖν θεὸς ἄμβροτος, οὐκέτι θνητὸς πωλεῦμαι,", "st": "8.66"}, {"sp": "N", "t": "καὶ τὰ ἑξῆς. καθ’ ὃν δὲ χρόνον ἐπεδήμει Ὀλυμπίασιν, ἐπιστροφῆς ἠξιοῦτο πλείονος, ὥστε μηδενὸς ἑτέρου μνείαν γίνεσθαι ἐν ταῖς ὁμιλίαις τοσαύτην ὅσην Ἐμπεδοκλέους.", "st": "8.66b"}, {"sp": "N", "t": "Ὕστερον μέντοι τοῦ Ἀκράγαντος οἰκ〈τ〉ιζομένου, ἀντέστησαν αὐτοῦ τῇ καθόδῳ οἱ τῶν ἐχθρῶν ἀπόγονοι· διόπερ εἰς Πελοπόννησον ἀποχωρήσας ἐτελεύτησεν. οὐ παρῆκε δ’ οὐδὲ τοῦτον ὁ Τίμων, ἀλλ’ ὧδ’ αὐτοῦ καθάπτεται λέγων·<br>καὶ Ἐμπεδοκλῆς ἀγοραίων ληκητὴς ἐπέων· ὅσα δ’ ἔσθενε, τόσσα διεῖλεν, ἀρχῶν ὃς διέθηκ’ ἀρχὰς ἐπιδευέας ἄλλων.", "st": "8.67"}, {"sp": "N", "t": "Περὶ δὲ τοῦ θανάτου διάφορός ἐστιν αὐτοῦ λόγος.", "st": "8.67b"}, {"sp": "N", "t": "Ἡρακλείδης μὲν γὰρ τὰ περὶ τῆς ἄπνου διηγησάμενος, ὡς ἐδοξάσθη Ἐμπεδοκλῆς ἀποστείλας τὴν νεκρὰν ἄνθρωπον ζῶσαν, φησὶν ὅτι θυσίαν συνετέλει πρὸς τῷ Πεισιάνακτος ἀγρῷ. συνεκέκληντο δὲ τῶν φίλων τινές, ἐν οἷς καὶ Παυσανίας. εἶτα μετὰ τὴν εὐωχίαν οἱ μὲν ἄλλοι χωρισθέντες ἀνεπαύοντο, οἱ μὲν ὑπὸ τοῖς δένδροις ὡς ἀγροῦ παρακειμένου, οἱ δ’ ὅπῃ βούλοιντο, αὐτὸς δ’ ἔμεινεν ἐπὶ τοῦ τόπου ἐφ’ οὗπερ κατεκέκλιτο. ὡς δ’ ἡμέρας γενηθείσης ἐξανέστησαν, οὐχ ηὑρέθη μόνος. ζητουμένου δὲ καὶ τῶν οἰκετῶν ἀνακρινομένων καὶ φασκόντων μὴ εἰδέναι, εἷς τις ἔφη μέσων νυκτῶν φωνῆς ὑπερμεγέθους ἀκοῦσαι προσκαλουμένης Ἐμπεδοκλέα, εἶτ’ ἐξαναστὰς ἑωρακέναι φῶς οὐράνιον καὶ λαμπάδων φέγγος, ἄλλο δὲ μηδέν· τῶν δ’ ἐπὶ τῷ γενομένῳ ἐκπλαγέντων, καταβὰς ὁ Παυσανίας ἔπεμψέ τινας ζητήσοντας. ὕστερον δὲ ἐκώλυε πολυπραγμονεῖν, φάσκων εὐχῆς ἄξια συμβεβηκέναι καὶ θύειν αὐτῷ δεῖν καθαπερεὶ γεγονότι θεῷ.", "st": "8.68"}, {"sp": "N", "t": "Ἕρμιππος δέ φησι Πάνθειάν τινα Ἀκραγαντίνην ἀπηλπισμένην ὑπὸ τῶν ἰατρῶν θεραπεῦσαι αὐτὸν καὶ διὰ τοῦτο τὴν θυσίαν ἐπιτελεῖν· τοὺς δὲ κληθέντας εἶναι πρὸς τοὺς ὀγδοήκοντα. Ἱππόβοτος δέ φησιν ἐξαναστάντα αὐτὸν ὡδευκέναι ὡς ἐπὶ τὴν Αἴτνην, εἶτα παραγενόμενον ἐπὶ τοὺς κρατῆρας τοῦ πυρὸς ἐναλέσθαι καὶ ἀφανισθῆναι, βουλόμενον τὴν περὶ αὑτοῦ φήμην βεβαιῶσαι ὅτι γεγόνοι θεός, ὕστερον δὲ γνωσθῆναι, ἀναρριπισθείσης αὐτοῦ μιᾶς τῶν κρηπίδων· χαλκᾶς γὰρ εἴθιστο ὑποδεῖσθαι. πρὸς τοῦθ’ ὁ Παυσανίας ἀντέλεγε.", "st": "8.69"}, {"sp": "N", "t": "Διόδωρος δ’ ὁ Ἐφέσιος περὶ Ἀναξιμάνδρου γράφων φησὶν ὅτι τοῦτον ἐζηλώκει, τραγικὸν ἀσκῶν τῦφον καὶ σεμνὴν ἀναλαβὼν ἐσθῆτα. τοῖς Σελινουντίοις ἐμπεσόντος λοιμοῦ διὰ τὰς ἀπὸ τοῦ παρακειμένου ποταμοῦ δυσωδίας, ὥστε καὶ αὐτοὺς φθείρεσθαι καὶ τὰς γυναῖκας δυστοκεῖν, ἐπινοῆσαι τὸν Ἐμπεδοκλέα καὶ δύο τινὰς ποταμοὺς τῶν σύνεγγυς ἐπαγαγεῖν ἰδίαις δαπάναις· καὶ καταμίξαντα γλυκῆναι τὰ ῥεύματα. οὕτω δὴ λήξαντος τοῦ λοιμοῦ καὶ τῶν Σελινουντίων εὐωχουμένων ποτὲ παρὰ τῷ ποταμῷ, ἐπιφανῆναι τὸν Ἐμπεδοκλέα· τοὺς δ’ ἐξαναστάντας προσκυνεῖν καὶ προσεύχεσθαι καθαπερεὶ θεῷ. ταύτην οὖν θέλοντα βεβαιῶσαι τὴν διάληψιν εἰς τὸ πῦρ ἐναλέσθαι.", "st": "8.70"}, {"sp": "N", "t": "τούτοις δ’ ἐναντιοῦται Τίμαιος, ῥητῶς λέγων ὡς ἐξεχώρησεν εἰς Πελοπόννησον καὶ τὸ σύνολον οὐκ ἐπανῆλθεν· ὅθεν αὐτοῦ καὶ τὴν τελευτὴν ἄδηλον εἶναι. πρὸς δὲ τὸν Ἡρακλείδην καὶ ἐξ ὀνόματος ποιεῖται τὴν ἀντίρρησιν ἐν τῇ ιδ’· Συρακόσιόν τε γὰρ εἶναι τὸν Πεισιάνακτα καὶ ἀγρὸν οὐκ ἔχειν ἐν Ἀκράγαντι· Παυσανίαν τε μνημεῖον 〈ἂν〉 πεποιηκέναι τοῦ φίλου, τοιούτου διαδοθέντος λόγου, ἢ ἀγαλμάτιόν τι ἢ σηκὸν οἷα θεοῦ· καὶ γὰρ πλούσιον εἶναι. πῶς οὖν, φησὶν, εἰς τοὺς κρατῆρας ἥλατο ὧν 〈ὡς〉 σύνεγγυς ὄντων οὐδὲ μνείαν ποτὲ ἐπεποίητο; τετελεύτηκεν οὖν ἐν Πελοποννήσῳ. οὐδὲν δὲ παράδοξον τάφον αὐτοῦ μὴ φαίνεσθαι· μηδὲ γὰρ ἄλλων πολλῶν. τοιαῦτά τινα εἰπὼν ὁ Τίμαιος ἐπιφέρει· ἀλλὰ διὰ παντός ἐστιν Ἡρακλείδης τοιοῦτος παραδοξολόγος, καὶ ἐκ τῆς σελήνης πεπτωκέναι ἄνθρωπον λέγων.", "st": "8.71"}, {"sp": "N", "t": "Ἱππόβοτος δέ φησιν ὅτι ἀνδριὰς ἐγκεκαλυμμένος Ἐμπεδοκλέους ἔκειτο πρότερον μὲν ἐν Ἀκράγαντι, ὕστερον δὲ πρὸ τοῦ Ῥωμαίων βουλευτηρίου ἀκάλυφος δηλονότι μεταθέντων αὐτὸν ἐκεῖ Ῥωμαίων· γραπταὶ μὲν γὰρ εἰκόνες καὶ νῦν περιφέρονται.", "st": "8.71b"}, {"sp": "N", "t": "Νεάνθης δ’ ὁ Κυζικηνὸς ὁ καὶ περὶ τῶν Πυθαγορικῶν εἰπών φησι Μέτωνος τελευτήσαντος τυραννίδος ἀρχὴν ὑποφύεσθαι· εἶτα τὸν Ἐμπεδοκλέα πεῖσαι τοὺς Ἀκραγαντίνους παύσασθαι μὲν τῶν στάσεων, ἰσότητα δὲ πολιτικὴν ἀσκεῖν. Ἔτι τε πολλὰς τῶν πολιτίδων ἀπροίκους ὑπαρχούσας αὐτὸν προικίσαι διὰ τὸν παρόντα πλοῦτον· διὸ δὴ πορφύραν τε ἀναλαβεῖν αὐτὸν καὶ στρόφιον ἐπιθέσθαι χρυσοῦν, ὡς Φαβωρῖνος ἐν Ἀπομνημονεύμασιν· ἔτι τ’ ἐμβάδας χαλκᾶς καὶ στέμμα Δελφικόν. κόμη τε ἦν αὐτῷ βαθεῖα καὶ παῖδες ἀκόλουθοι· καὶ αὐτὸς ἀεὶ σκυθρωπὸς ἐφ’ ἑνὸς σχήματος ἦν. τοιοῦτος δὴ προῄει, τῶν πολιτῶν ἐντυχόντων καὶ τοῦτ’ ἀξιωσάντων οἱονεὶ βασιλείας τινὸς παράσημον. ὕστερον δὲ διά τινα πανήγυριν πορευόμενον ἐπ’ ἀμάξης ὡς εἰς Μεσσήνην πεσεῖν καὶ τὸν μηρὸν κλάσαι· νοσήσαντα δ’ ἐκ τούτου τελευτῆσαι ἐτῶν ἑπτὰ καὶ ἑβδομήκοντα. εἶναι δ’ αὐτοῦ καὶ τάφον ἐν Μεγάροις.", "st": "8.73"}, {"sp": "N", "t": "Περὶ δὲ τῶν ἐτῶν Ἀριστοτέλης διαφέρεται· φησὶ γὰρ ἐκεῖνος ἑξήκοντ’ ἐτῶν αὐτὸν τελευτῆσαι· οἱ δὲ ἐννέα καὶ ἑκατόν. ἤκμαζε δὲ κατὰ τὴν τετάρτην καὶ ὀγδοηκοστὴν Ὀλυμπιάδα. Δημήτριος δ’ ὁ Τροιζήνιος ἐν τῷ Κατὰ σοφιστῶν βιβλίῳ φησὶν αὐτὸν καθ’ Ὅμηρον<br>ἁψάμενον βρόχον αἰπὺν ἀφ’ ὑψηλοῖο κρανείης αὐχέν’ ἀποκρεμάσαι, ψυχὴν δ’ Ἄϊδόσδε κατελθεῖν.", "st": "8.74"}, {"sp": "N", "t": "Ἐν δὲ τῷ προειρημένῳ Τηλαύγους ἐπιστολίῳ λέγεται αὐτὸν εἰς θάλατταν ὑπὸ γήρως ὀλισθόντα τελευτῆσαι.", "st": "8.74b"}, {"sp": "N", "t": "καὶ ταῦτα μὲν περὶ τοῦ θανάτου καὶ τοσαῦτα.", "st": "8.74c"}, {"sp": "N", "t": "Φέρεται δὲ καὶ ἡμῶν εἰς αὐτὸν ἐν τῇ Παμμέτρῳ σκωπτικὸν μέν, τοῦτον δ’ ἔχον τὸν τρόπον· καὶ σύ ποτ’, Ἐμπεδόκλεις, διερῇ φλογὶ σῶμα καθήρας πῦρ ἀπὸ κρητήρων ἔκπιες ἀθανάτων· οὐκ ἐρέω δ’ ὅτι σαυτὸν ἑκὼν βάλες ἐς ῥόον Αἴτνης, ἀλλὰ λαθεῖν ἐθέλων ἔμπεσες οὐκ ἐθέλων.", "st": "8.75"}, {"sp": "N", "t": "καὶ ἄλλο·<br>ναὶ μὴν Ἐμπεδοκλῆα θανεῖν λόγος ὥς ποτ’ ἀμάξης ἔκπεσε καὶ μηρὸν κλάσσατο δεξιτερόν· εἰ δὲ πυρὸς κρητῆρας ἐσήλατο καὶ πίε τὸ ζῆν, πῶς ἂν ἔτ’ ἐν Μεγάροις δείκνυτο τοῦδε τάφος;", "st": "8.75b"}, {"sp": "N", "t": "Ἐδόκει δ’ αὐτῷ τάδε· στοιχεῖα μὲν εἶναι τέτταρα, πῦρ, ὕδωρ, γῆν, ἀέρα· Φιλίαν θ’ ᾗ συγκρίνεται καὶ Νεῖκος ᾧ διακρίνεται. φησὶ δ’ οὕτω·<br>Ζεὺς ἀργὴς Ἥρη τε φερέσβιος ἠδ’ Ἀϊδωνεὺς Νῆστίς θ’, ἣ δακρύοις τέγγει κρούνωμα βρότειον·", "st": "8.76"}, {"sp": "N", "t": "Δία μὲν τὸ πῦρ λέγων, Ἥρην δὲ τὴν γῆν, Ἀϊδωνέα δὲ τὸν ἀέρα, Νῆστιν δὲ τὸ ὕδωρ. Καὶ ταῦτα, φησίν, ἀλλάττοντα διαμπερὲς οὐδαμὰ λήγει, ὡς ἂν ἀϊδίου τῆς τοιαύτης διακοσμήσεως οὔσης· ἐπιφέρει γοῦν·<br>ἄλλοτε μὲν Φιλότητι συνερχόμεν’ εἰς ἓν ἅπαντα, ἄλλοτε δ’ αὖ δίχ’ ἕκαστα φορεύμενα Νείκεος ἔχθει.", "st": "8.76b"}, {"sp": "N", "t": "Καὶ τὸν μὲν ἥλιόν φησι πυρὸς ἄθροισμα μέγα καὶ τῆς σελήνης μείζω· τὴν δὲ σελήνην δισκοειδῆ, αὐτὸν δὲ τὸν οὐρανὸν κρυσταλλοειδῆ. καὶ τὴν ψυχὴν παντοῖα εἴδη ζῴων καὶ φυτῶν ἐνδύεσθαι· φησὶ γοῦν·<br>ἤδη γάρ ποτ’ ἐγὼ γενόμην κοῦρός τε κόρη τε θάμνος τ’ οἰωνός τε καὶ ἔξαλος ἔμπυρος ἰχθύς.", "st": "8.77"}, {"sp": "N", "t": "Τὰ μὲν οὖν Περὶ φύσεως αὐτῷ καὶ οἱ Καθαρμοὶ εἰς ἔπη τείνουσι πεντακισχίλια, ὁ δὲ Ἰατρικὸς λόγος εἰς ἔπη ἑξακόσια. περὶ δὲ τῶν τραγῳδιῶν προειρήκαμεν.", "st": "8.77b"}, {"sp": "HDR", "t": "ΕΠΙΧΑΡΜΟΣ"}, {"sp": "N", "t": "Ἐπίχαρμος Ἡλοθαλοῦς Κῷος. καὶ οὗτος ἤκουσε Πυθαγόρου. τριμηνιαῖος δ’ ὑπάρχων ἀπηνέχθη τῆς Σικελίας εἰς Μέγαρα, ἐντεῦθεν δ’ εἰς Συρακούσας, ὥς φησι καὶ αὐτὸς ἐν τοῖς συγγράμμασιν. καὶ αὐτῷ ἐπὶ τοῦ ἀνδριάντος ἐπιγέγραπται τόδε·<br>εἴ τι παραλλάσσει φαέθων μέγας ἅλιος ἄστρων καὶ πόντος ποταμῶν μείζον’ ἔχει δύναμιν, φαμὶ τοσοῦτον ἐγὼ σοφίᾳ προέχειν Ἐπίχαρμον, ὃν πατρὶς ἐστεφάνωσ’ ἅδε Συρακοσίων.", "st": "8.78"}, {"sp": "N", "t": "οὗτος ὑπομνήματα καταλέλοιπεν ἐν οἷς φυσιολογεῖ, γνωμολογεῖ, ἰατρολογεῖ· καὶ παραστιχίδα γε ἐν τοῖς πλείστοις τῶν ὑπομνημάτων πεποίηκεν, οἷς διασαφεῖ ὅτι ἑαυτοῦ ἐστι τὰ συγγράμματα.", "st": "8.78b"}, {"sp": "N", "t": "βιοὺς δ’ ἔτη ἐνενήκοντα κατέστρεψεν.", "st": "8.78c"}, {"sp": "HDR", "t": "ΑΡΧΥΤΑΣ"}, {"sp": "N", "t": "Ἀρχύτας Μνησαγόρου Ταραντῖνος, ὡς δὲ Ἀριστόξενος, Ἑστιαίου, Πυθαγορικὸς καὶ αὐτός.", "st": "8.79"}, {"sp": "N", "t": "οὗτός ἐστιν ὁ Πλάτωνα ῥυσάμενος δι’ ἐπιστολῆς παρὰ Διονυσίου μέλλοντ’ ἀναιρεῖσθαι.", "st": "8.79b"}, {"sp": "N", "t": "ἐθαυμάζετο δὲ καὶ παρὰ τοῖς πολλοῖς ἐπὶ πάσῃ ἀρετῇ· καὶ δὴ ἑπτάκις τῶν πολιτῶν ἐστρατήγησε, τῶν ἄλλων μὴ πλέον ἐνιαυτοῦ στρατηγούντων διὰ τὸ κωλύειν τὸν νόμον.", "st": "8.79c"}, {"sp": "N", "t": "πρὸς τοῦτον καὶ Πλάτων γέγραφεν ἐπιστολὰς δύο, ἐπειδήπερ αὐτῷ πρότερος ἐγεγράφει τοῦτον τὸν τρόπον·", "st": "8.79d"}, {"sp": "N", "t": "“Ἀρχύτας Πλάτωνι ὑγιαίνειν.", "st": "8.79e"}, {"sp": "N", "t": "“Καλῶς ποιέεις ὅτι ἀποπέφευγας ἐκ τᾶς ἀρρωστίας· ταῦτα γὰρ αὐτός τυ ἐπέσταλκας καὶ τοὶ περὶ Λαμίσκον ἀπάγγελον. περὶ δὲ τῶν ὑπομνημάτων ἐπεμελήθημες καὶ ἀνήλθομες ὡς Λευκανὼς καὶ ἐνετύχομες τοῖς Ὀκκέλω ἐκγόνοις. τὰ μὲν ὦν Περὶ νόμω καὶ Βασιληίας καὶ Ὁσιότατος καὶ τᾶς τῶ παντὸς γενέσιος αὐτοί τ’ ἔχομες καὶ τὶν ἀπεστάλκαμες· τὰ δὲ λοιπὰ οὔτοι νῦν γα δύναται εὑρεθῆμεν, αἰ δέ κα εὑρεθῇ, ἥξει τοι.", "st": "8.80"}, {"sp": "N", "t": "Ὧδε μὲν ὁ Ἀρχύτας· ὁ δὲ Πλάτων ἀντεπιστέλλει τοῦτον τὸν τρόπον· “Πλάτων Ἀρχύτᾳ εὖ πράττειν.", "st": "8.80b"}, {"sp": "N", "t": "“Τὰ μὲν παρὰ σοῦ ἐλθόντα ὑπομνήματα θαυμαστῶς ἄσμενοί τε ἐλάβομεν καὶ τοῦ γράψαντος αὐτὰ ἠγάσθημεν ὡς ἔνι μάλιστα, καὶ ἔδοξεν ἡμῖν ἁνὴρ ἄξιος ἐκείνων τῶν παλαιῶν προγόνων. λέγονται γὰρ δὴ οἱ ἄνδρες οὗτοι Μυραῖοι εἶναι· οὗτοι δ’ ἦσαν τῶν ἐπὶ Λαομέδοντος ἐξαναστάντων Τρώων ἄνδρες ἀγαθοί, ὡς ὁ παραδεδομένος μῦθος δηλοῖ. τὰ δὲ παρ’ ἐμοῦ ὑπομνήματα, περὶ ὧν ἐπέστειλας, ἱκανῶς μὲν οὔπω ἔχει· ὡς δέ ποτε τυγχάνει ἔχοντα ἀπέσταλκά σοι. περὶ δὲ τῆς φυλακῆς ἀμφότεροι συμφωνοῦμεν, ὥστε οὐδὲν δεῖ παρακελεύεσθαι. ἔρρωσο.", "st": "8.81"}, {"sp": "N", "t": "Καὶ ὧδε μὲν πρὸς ἀλλήλους αὐτοῖς ἔχουσιν αἱ ἐπιστολαί.", "st": "8.81b"}, {"sp": "N", "t": "Γεγόνασι δ’ Ἀρχύται τέτταρες· πρῶτος αὐτὸς οὗτος, δεύτερος Μυτιληναῖος μουσικός, τρίτος Περὶ γεωργίας συγγεγραφώς, τέταρτος ἐπιγραμματοποιός.", "st": "8.82"}, {"sp": "N", "t": "ἔνιοι καὶ πέμπτον ἀρχιτέκτονά φασιν, οὗ φέρεται βιβλίον Περὶ μηχανῆς, ἀρχὴν ἔχον ταύτην, τάδε παρὰ Τεύκρου Καρχηδονίου διήκουσα.", "st": "8.82b"}, {"sp": "N", "t": "περὶ δὲ τοῦ μουσικοῦ φέρεται καὶ τόδε, ὡς ὀνειδιζόμενος ἐπὶ τῷ μὴ ἐξακούεσθαι εἴποι, τὸ γὰρ ὄργανον ὑπὲρ ἐμοῦ διαγωνιζόμενον λαλεῖ.", "st": "8.82c"}, {"sp": "N", "t": "Τὸν δὲ Πυθαγορικὸν Ἀριστόξενός φησι μηδέποτε στρατηγοῦντα ἡττηθῆναι· φθονούμενον δ’ ἅπαξ ἐκχωρῆσαι τῆς στρατηγίας καὶ τοὺς αὐτίκα ληφθῆναι.", "st": "8.82d"}, {"sp": "N", "t": "Οὗτος πρῶτος τὰ μηχανικὰ ταῖς μαθηματικαῖς προσχρησάμενος ἀρχαῖς μεθώδευσε καὶ πρῶτος κίνησιν ὀργανικὴν διαγράμματι γεωμετρικῷ προσήγαγε, διὰ τῆς τομῆς τοῦ ἡμικυλίνδρου δύο μέσας ἀνὰ λόγον λαβεῖν ζητῶν εἰς τὸν τοῦ κύβου διπλασιασμόν. κἀν γεωμετρίᾳ πρῶτος κύβον εὗρεν, ὥς φησι Πλάτων ἐν Πολιτείᾳ.", "st": "8.83"}, {"sp": "HDR", "t": "ΑΛΚΜΑΙΩΝ"}, {"sp": "N", "t": "Ἀλκμαίων Κροτωνιάτης. καὶ οὗτος Πυθαγόρου διήκουσε· καὶ τὰ πλεῖστά γε ἰατρικὰ λέγει, ὅμως δὲ καὶ φυσιολογεῖ ἐνίοτε λέγων δύο τὰ πολλά ἐστι τῶν ἀνθρωπίνων. δοκεῖ δὲ πρῶτος φυσικὸν λόγον συγγεγραφέναι, καθά φησι Φαβωρῖνος ἐν Παντοδαπῇ ἱστορίᾳ, καὶ τὴν σελήνην καθόλου 〈τε τὰ ὑπὲρ〉 ταύτην ἔχειν ἀΐδιον φύσιν.", "st": "8.83b"}, {"sp": "N", "t": "Ἦν δὲ Πειρίθου υἱός, ὡς αὐτὸς ἐναρχόμενος τοῦ συγγράμματός φησιν· Ἀλκμαίων Κροτωνιήτης τάδε ἔλεξε Πειρίθου υἱὸς Βροτίνῳ καὶ Λέοντι καὶ Βαθύλλω· ιπερὶ τῶν ἀφανέων, περὶ τῶν θνητῶν σαφήνειαν μὲν θεοὶ ἔχοντι, ὡς δ’ ἀνθρώποις τεκμαίρεσθαι’ καὶ τὰ ἑξῆς·", "st": "8.83c"}, {"sp": "N", "t": "ἔφη δὲ καὶ τὴν ψυχὴν ἀθάνατον, καὶ κινεῖσθαι αὐτὴν συνεχὲς ὡς τὸν ἥλιον.", "st": "8.83d"}, {"sp": "HDR", "t": "ΙΠΠΑΣΟΣ"}, {"sp": "N", "t": "Ἵππασος Μεταποντῖνος καὶ αὐτὸς Πυθαγορικός.", "st": "8.84"}, {"sp": "N", "t": "ἔφη δὲ χρόνον ὡρισμένον εἶναι τῆς τοῦ κόσμου μεταβολῆς καὶ πεπερασμένον εἶναι τὸ πᾶν καὶ ἀεικίνητον.", "st": "8.84b"}, {"sp": "N", "t": "Φησὶ δ’ αὐτὸν Δημήτριος ἐν Ὁμωνύμοις μηδὲν καταλιπεῖν σύγγραμμα.", "st": "8.84c"}, {"sp": "N", "t": "γεγόνασι δ’ Ἵππασοι δύο, οὗτός τε καὶ ἕτερος γεγραφὼς ἐν πέντε βιβλίοις Λακώνων πολιτείαν· ἦν δὲ καὶ αὐτὸς Λάκων.", "st": "8.84d"}, {"sp": "HDR", "t": "ΦΙΛΟΛΑΟΣ"}, {"sp": "N", "t": "Φιλόλαος Κροτωνιάτης Πυθαγορικός. παρὰ τούτου Πλάτων ὠνήσασθαι τὰ βιβλία τὰ Πυθαγορικὰ Δίωνι γράφει.", "st": "8.84e"}, {"sp": "N", "t": "ἐτελεύτα δὲ νομισθεὶς ἐπιτίθεσθαι τυραννίδι. καὶ ἡμῶν ἐστιν εἰς αὐτόν·<br>τὴν ὑπόνοιαν πᾶσι μάλιστα λέγω θεραπεύειν· εἰ γὰρ καὶ μὴ δρᾷς, ἀλλὰ δοκεῖς, ἀτυχεῖς. οὕτω καὶ Φιλόλαον ἀνεῖλε Κρότων ποτὲ πάτρη, ὥς μιν ἔδοξε θέλειν δῶμα τύραννον ἔχειν.", "st": "8.84f"}, {"sp": "N", "t": "Δοκεῖ δ’ αὐτῷ πάντα ἀνάγκῃ καὶ ἁρμονίᾳ γίνεσθαι. καὶ τὴν γῆν κινεῖσθαι κατὰ κύκλον πρῶτον εἰπεῖν· οἱ δ’ Ἱκέταν 〈τὸν〉 Συρακόσιόν φασιν.", "st": "8.85"}, {"sp": "N", "t": "Γέγραφε δὲ βιβλίον ἕν, ὅ φησιν Ἕρμιππος λέγειν τινὰ τῶν συγγραφέων Πλάτωνα τὸν φιλόσοφον παραγενόμενον εἰς Σικελίαν πρὸς Διονύσιον ὠνήσασθαι παρὰ τῶν συγγενῶν τοῦ Φιλολάου ἀργυρίου Ἀλεξανδρινῶν μνῶν τετταράκοντα καὶ ἐντεῦθεν μεταγεγραφέναι τὸν Τίμαιον. ἕτεροι δὲ λέγουσι τὸν Πλάτωνα λαβεῖν αὐτά, παρὰ Διονυσίου παραιτησάμενον ἐκ τῆς φυλακῆς νεανίσκον ἀπηγμένον τῶν τοῦ Φιλολάου μαθητῶν. Τοῦτόν φησι Δημήτριος ἐν Ὁμωνύμοις πρῶτον ἐκδοῦναι τῶν Πυθαγορικῶν 〈βιβλία καὶ ἐπιγράψαι〉 Περὶ φύσεως, ὧν ἀρχὴ ἥδε·", "st": "8.85b"}, {"sp": "N", "t": "ἁ φύσις δ’ ἐν τῷ κόσμῳ ἁρμόχθη ἐξ ἀπείρων τε καὶ περαινόντων καὶ ὅλος ὁ κόσμος καὶ τὰ ἐν αὐτῷ πάντα.", "st": "8.85c"}, {"sp": "HDR", "t": "ΕΥΔΟΞΟΣ"}, {"sp": "N", "t": "Εὔδοξος Αἰσχίνου Κνίδιος, ἀστρολόγος, γεωμέτρης, ἰατρός, νομοθέτης. οὗτος τὰ μὲν γεωμετρικὰ Ἀρχύτα διήκουσε, τὰ δ’ ἰατρικὰ Φιλιστίωνος τοῦ Σικελιώτου, καθὰ Καλλίμαχος ἐν τοῖς Πίναξί φησι. Σωτίων δ’ ἐν ταῖς Διαδοχαῖς λέγει καὶ Πλάτωνος αὐτὸν ἀκοῦσαι. γενόμενον γὰρ ἐτῶν τριῶν που καὶ εἴκοσι καὶ στενῶς διακείμενον κατὰ κλέος τῶν Σωκρατικῶν εἰς Ἀθήνας ἀπᾶραι σὺν Θεομέδοντι τῷ ἰατρῷ, τρεφόμενον ὑπ’ αὐτοῦ· οἱ δέ, καὶ παιδικὰ ὄντα· καταχθέντα δ’ εἰς τὸν Πειραιᾶ ὁσημέραι ἀνιέναι Ἀθήναζε καὶ ἀκούσαντα τῶν σοφιστῶν αὐτόθι ὑποστρέφειν. δύο δὴ μῆνας διατρίψαντα οἴκαδ’ ἐπανελθεῖν καὶ πρὸς τῶν φίλων ἐρανισθέντα εἰς Αἴγυπτον ἀπᾶραι μετὰ Χρυσίππου τοῦ ἰατροῦ, συστατικὰς φέροντα παρ’ Ἀγησιλάου πρὸς Νεκτάναβιν· τὸν δὲ τοῖς ἱερεῦσιν αὐτὸν συστῆσαι.", "st": "8.86"}, {"sp": "N", "t": "καὶ τέτταρας μῆνας πρὸς ἐνιαυτῷ διατρίψαντ’ αὐτόθι ξυρόμενόν θ’ ὑπήνην καὶ ὀφρὺν τὴν Ὀκταετηρίδα κατά τινας συγγράψαι. ἐντεῦθέν τε γενέσθαι ἐν Κυζίκῳ καὶ τῇ Προποντίδι σοφιστεύοντα· ἀλλὰ καὶ παρὰ Μαυσωλὸν ἀφικέσθαι. ἔπειθ’ οὕτως ἐπανελθεῖν Ἀθήναζε, πάνυ πολλοὺς περὶ ἑαυτὸν ἔχοντα μαθητάς, ὥς φασί τινες, ὑπὲρ τοῦ Πλάτωνα λυπῆσαι, ὅτι τὴν ἀρχὴν αὐτὸν παρεπέμψατο. τινὲς δέ φασι καὶ συμπόσιον ἔχοντι τῷ Πλάτωνι αὐτὸν τὴν ἡμικύκλιον κατάκλισιν, πολλῶν ὄντων, εἰσηγήσασθαι.", "st": "8.88"}, {"sp": "N", "t": "φησὶ δ’ αὐτὸν Νικόμαχος ὁ Ἀριστοτέλους τὴν ἡδονὴν λέγειν τὸ ἀγαθόν.", "st": "8.88b"}, {"sp": "N", "t": "ἀπεδέχθη δὴ ἐν τῇ πατρίδι μεγαλοτίμως, ὡς τό γε περὶ αὐτοῦ ψήφισμα γενόμενον δηλοῖ. ἀλλὰ καὶ παρὰ τοῖς Ἕλλησιν ἐπιφανέστατος ἐγένετο, γράψας τοῖς ἰδίοις πολίταις νόμους, ὥς φησιν Ἕρμιππος ἐν τετάρτῃ Περὶ τῶν ἑπτὰ σοφῶν, καὶ ἀστρολογούμενα καὶ γεωμετρούμενα καὶ ἕτερ’ ἄττα ἀξιόλογα.", "st": "8.88c"}, {"sp": "N", "t": "Ἔσχε δὲ καὶ θυγατέρας τρεῖς, Ἀκτίδα, Φιλτίδα, Δελφίδα. φησὶ δ’ αὐτὸν Ἐρατοσθένης ἐν τοῖς Πρὸς Βάτωνα καὶ Κυνῶν διαλόγους συνθεῖναι· οἱ δέ, γεγραφέναι μὲν Αἰγυπτίους τῇ αὑτῶν φωνῇ, τοῦτον δὲ μεθερμηνεύσαντα ἐκδοῦναι τοῖς Ἕλλησι. τούτου διήκουσε Χρύσιππος ὁ Ἐρίνεω Κνίδιος τά τε περὶ θεῶν καὶ κόσμου καὶ τῶν μετεωρολογουμένων, τὰ δ’ ἰατρικὰ παρὰ Φιλιστίωνος τοῦ Σικελιώτου. Κατέλιπε δὲ καὶ ὑπομνήματα κάλλιστα.", "st": "8.89"}, {"sp": "N", "t": "τούτου γέγονε παῖς Ἀρισταγόρας, οὗ Χρύσιππος Ἀεθλίου μαθητής, οὗ τὰ θεραπεύματα φέρεται ὁρατικά, τῶν φυσικῶν θεωρημάτων [τῶν] ὑπὸ τὴν διάνοιαν αὐτοῦ πεσόντων.", "st": "8.89b"}, {"sp": "N", "t": "Γεγόνασι δ’ Εὔδοξοι τρεῖς· αὐτὸς οὗτος, ἕτερος Ῥόδιος ἱστορίας γεγραφώς, τρίτος Σικελιώτης παῖς Ἀγαθοκλέους, ποιητὴς κωμῳδίας, νίκας ἑλὼν ἀστικὰς μὲν τρεῖς, Ληναϊκὰς δὲ πέντε, καθά φησιν Ἀπολλόδωρος ἐν Χρονικοῖς. εὑρίσκομεν δὲ καὶ ἄλλον ἰατρὸν Κνίδιον, περὶ οὗ φησιν Εὔδοξος ἐν Γῆς περιόδῳ ὡς εἴη παραγγέλλων ἀεὶ συνεχὲς κινεῖν τὰ ἄρθρα πάσῃ γυμνασίᾳ, ἀλλὰ καὶ τὰς αἰσθήσεις ὁμοίως.", "st": "8.90"}, {"sp": "N", "t": "Ὁ δ’ αὐτός φησι τὸν Κνίδιον Εὔδοξον ἀκμάσαι κατὰ τὴν τρίτην καὶ ἑκατοστὴν Ὀλυμπιάδα, εὑρεῖν τε τὰ περὶ τὰς καμπύλας γραμμάς. ἐτελεύτησε δὲ τρίτον ἄγων καὶ πεντηκοστὸν ἔτος. ὅτε δὲ συνεγένετο ἐν Αἰγύπτῳ Χονούφιδι τῷ Ἡλιουπολίτῃ, ὁ Ἆπις αὐτοῦ θοἰμάτιον περιελιχμήσατο. ἔνδοξον οὖν αὐτὸν ἀλλ’ ὀλιγοχρόνιον ἔφασαν οἱ ἱερεῖς ἔσεσθαι, καθά φησι Φαβωρῖνος ἐν Ἀπομνημονεύμασιν. Ἔστι δὲ καὶ ἡμῶν εἰς αὐτὸν οὕτως ἔχον·<br>ἐν Μέμφει λόγος ἐστὶν προμαθεῖν τὴν ἰδίην Εὔδοξόν ποτε μοῖραν παρὰ τοῦ καλλικέρω ταύρου. κοὐδὲν ἔλεξεν· βοῒ γὰρ πόθεν λόγος; φύσις οὐκ ἔδωκε μόσχῳ λάλον Ἄπιδι στόμα. παρὰ δ’ αὐτὸν λέχριος στὰς ἐλιχμήσατο στολήν, προφανῶς τοῦτο διδάσκων, Ἀποδύσῃ βιοτὴν ὅσον οὔπω. διὸ καί οἱ ταχέως ἦλθε μόρος, δεκάκις πέντ’ ἐπὶ τρισσαῖς ἐσιδόντι Πλειάδας.", "st": "8.91"}, {"sp": "N", "t": "Τοῦτον ἀντὶ Εὐδόξου Ἔνδοξον ἐκάλουν διὰ τὴν λαμπρότητα τῆς φήμης. Ἐπειδὴ δὲ περὶ τῶν ἐλλογίμων Πυθαγορικῶν διεληλύθαμεν, νῦν ἤδη περὶ τῶν σποράδην, ὥς φασι, διαλεχθῶμεν· λεκτέον δὲ πρῶτον περὶ Ἡρακλείτου.", "st": "8.91b"}, {"sp": "HDR", "t": "Βιβλίον Θ"}, {"sp": "HDR", "t": "ΗΡΑΚΛΕΙΤΟΣ"}, {"sp": "N", "t": "Ἡράκλειτος Βλόσωνος ἤ, ὥς τινες, Ἡράκωντος Ἐφέσιος. οὗτος ἤκμαζε μὲν κατὰ τὴν ἐνάτην καὶ ἑξηκοστὴν Ὀλυμπιάδα.", "st": "9.1"}, {"sp": "N", "t": "μεγαλόφρων δὲ γέγονε παρ’ ὁντιναοῦ καὶ ὑπερόπτης, ὡς καὶ ἐκ τοῦ συγγράμματος αὐτοῦ δῆλον, ἐν ᾧ φησι, πολυμαθίη νόον οὐ διδάσκει· Ἡσίοδον γὰρ ἂν ἐδίδαξε καὶ Πυθαγόρην, αὖτίς τε Ξενοφάνεά τε καὶ Ἑκαταῖον. εἶναι γὰρ ἓν τὸ σοφόν, ἐπίστασθαι γνώμην, ὁτέη ἐκυβέρνησε πάντα διὰ πάντων. τόν τε Ὅμηρον ἔφασκεν ἄξιον ἐκ τῶν ἀγώνων ἐκβάλλεσθαι καὶ ῥαπίζεσθαι, καὶ Ἀρχίλοχον ὁμοίως. Ἔλεγε δὲ καὶ ὕβριν χρὴ σβεννύναι μᾶλλον ἢ πυρκαϊὴν καὶ μάχεσθαι χρὴ τὸν δῆμον ὑπὲρ τοῦ νόμου ὅκωσπερ τείχεος. καθάπτεται δὲ καὶ τῶν Ἐφεσίων ἐπὶ τῷ τὸν ἑταῖρον ἐκβαλεῖν Ἑρμόδωρον, ἐν οἷς φησιν, ἄξιον Ἐφεσίοις ἡβηδὸν ἀποθανεῖν πᾶσι καὶ τοῖς ἀνήβοις τὴν πόλιν καταλιπεῖν, οἵτινες Ἑρμόδωρον ἄνδρα ἑωυτῶν ὀνήιστον ἐξέβαλον λέγοντες, Ἡμέων μηδὲ εἷς ὀνήιστος ἔστω· εἰ δέ τις τοιοῦτος, ἄλλῃ τε καὶ μετ’ ἄλλων.", "st": "9.2"}, {"sp": "N", "t": "ἀξιούμενος δὲ καὶ νόμους θεῖναι πρὸς αὐτῶν ὑπερεῖδε διὰ τὸ ἤδη κεκρατῆσθαι τῇ πονηρᾷ πολιτείᾳ τὴν πόλιν. ἀναχωρήσας δ’ εἰς τὸ ἱερὸν τῆς Ἀρτέμιδος μετὰ τῶν παίδων ἠστραγάλιζε· περιστάντων δ’ αὐτὸν τῶν Ἐφεσίων, τί, ὦ κάκιστοι, θαυμάζετε; εἶπεν· ἢ οὐ κρεῖττον τοῦτο ποιεῖν ἢ μεθ’ ὑμῶν πολιτεύεσθαι;", "st": "9.3"}, {"sp": "N", "t": "Καὶ τέλος μισανθρωπήσας καὶ ἐκπατήσας ἐν τοῖς ὄρεσι διητᾶτο, πόας σιτούμενος καὶ βοτάνας. καὶ μέντοι καὶ διὰ τοῦτο περιτραπεὶς εἰς ὕδερον κατῆλθεν εἰς ἄστυ καὶ τῶν ἰατρῶν αἰνιγματωδῶς ἐπυνθάνετο εἰ δύναιντ’ ἐξ ἐπομβρίας αὐχμὸν ποιῆσαι· τῶν δὲ μὴ συνιέντων, αὑτὸν εἰς βουστάσιον κατορύξας τῇ τῶν βολίτων ἀλέᾳ ἤλπισεν ἐξατμισθήσεσθαι. οὐδὲν δ’ ἀνύων οὐδ’ οὕτως, ἐτελεύτα βιοὺς ἔτη ἑξήκοντα. Καὶ ἔστιν εἰς αὐτὸν ἡμῶν οὕτως ἔχον·<br>πολλάκις Ἡράκλειτον ἐθαύμασα, πῶς ποτε τὸ ζῆν ὧδε διαντλήσας δύσμορος εἶτ’ ἔθανεν· σῶμα γὰρ ἀρδεύσασα κακὴ νόσος ὕδατι φέγγος ἔσβεσεν ἐν βλεφάροις καὶ σκότον ἠγάγετο.", "st": "9.4"}, {"sp": "N", "t": "Ἕρμιππος δέ φησι λέγειν αὐτὸν τοῖς ἰατροῖς εἴ τις δύναται 〈τὰ〉 ἔντερα κεινώσας τὸ ὑγρὸν ἐξερᾶσαι· ἀπειπόντων δέ, θεῖναι αὑτὸν εἰς τὸν ἥλιον καὶ κελεύειν τοὺς παῖδας βολίτοις καταπλάττειν· οὕτω δὴ κατατεινόμενον δευτεραῖον τελευτῆσαι καὶ θαφθῆναι ἐν τῇ ἀγορᾷ. Νεάνθης δ’ ὁ Κυζικηνός φησι μὴ δυνηθέντ’ αὐτὸν ἀποσπάσαι τὰ βόλιτα μεῖναι καὶ διὰ τὴν μεταβολὴν ἀγνοηθέντα κυνόβρωτον γενέσθαι.", "st": "9.4b"}, {"sp": "N", "t": "Γέγονε δὲ θαυμάσιος ἐκ παίδων, ὅτε καὶ νέος ὢν ἔφασκε μηδὲν εἰδέναι, τέλειος μέντοι γενόμενος πάντ’ ἐγνωκέναι. ἤκουσέ τ’ οὐδενός, ἀλλ’ αὑτὸν ἔφη διζήσασθαι καὶ μαθεῖν πάντα παρ’ ἑαυτοῦ. Σωτίων δέ φησιν εἰρηκέναι τινὰς Ξενοφάνους αὐτὸν ἀκηκοέναι· λέγειν τε Ἀρίστωνα ἐν τῷ Περὶ Ἡρακλείτου καὶ τὸν ὕδερον αὐτὸν θεραπευθῆναι, ἀποθανεῖν δ’ ἄλλῃ νόσῳ.", "st": "9.5"}, {"sp": "N", "t": "τοῦτο δὲ καὶ Ἱππόβοτός φησι. Τὸ δὲ φερόμενον αὐτοῦ βιβλίον ἐστὶ μὲν ἀπὸ τοῦ συνέχοντος Περὶ φύσεως, διῄρηται δ’ εἰς τρεῖς λόγους, εἴς τε τὸν περὶ τοῦ παντὸς καὶ πολιτικὸν καὶ θεολογικόν. ἀνέθηκε δ’ αὐτὸ εἰς τὸ τῆς Ἀρτέμιδος ἱερόν, ὡς μέν τινες, ἐπιτηδεύσας ἀσαφέστερον γράψαι, ὅπως οἱ δυνάμενοι 〈μόνοι〉 προσίοιεν αὐτῷ καὶ μὴ ἐκ τοῦ δημώδους εὐκαταφρόνητον ᾖ. τοῦτον δὲ καὶ ὁ Τίμων ὑπογράφει λέγων,<br>τοῖς δ’ ἔνι κοκκυστής, ὀχλολοίδορος Ἡράκλειτος, αἰνικτὴς ἀνόρουσε.", "st": "9.6"}, {"sp": "N", "t": "Θεόφραστος δέ φησιν ὑπὸ μελαγχολίας τὰ μὲν ἡμιτελῆ, τὰ δ’ ἄλλοτ’ ἄλλως ἔχοντα γράψαι. σημεῖον δ’ αὐτοῦ τῆς μεγαλοφροσύνης Ἀντισθένης φησὶν ἐν Διαδοχαῖς· ἐκχωρῆσαι γὰρ τἀδελφῷ τῆς βασιλείας. τοσαύτην δὲ δόξαν ἔσχε τὸ σύγγραμμα ὡς καὶ αἱρετιστὰς ἀπ’ αὐτοῦ γενέσθαι τοὺς κληθέντας Ἡρακλειτείους.", "st": "9.6b"}, {"sp": "N", "t": "Ἐδόκει δ’ αὐτῷ καθολικῶς μὲν τάδε· ἐκ πυρὸς τὰ πάντα συνεστάναι καὶ εἰς τοῦτο ἀναλύεσθαι· πάντα δὲ γίνεσθαι καθ’ εἱμαρμένην καὶ διὰ τῆς ἐναντιοδρομίας ἡρμόσθαι τὰ ὄντα· καὶ πάντα ψυχῶν εἶναι καὶ δαιμόνων πλήρη. εἴρηκε δὲ καὶ περὶ τῶν ἐν κόσμῳ συνισταμένων πάντων παθῶν, ὅτι τε ὁ ἥλιός ἐστι τὸ μέγεθος οἷος φαίνεται. λέγεται δὲ καὶ ψυχῆς πείρατα ἰὼν οὐκ ἂν ἐξεύροιο, πᾶσαν ἐπιπορευόμενος ὁδόν· οὕτω βαθὺν λόγον ἔχει. τήν τ’ οἴησιν ἱερὰν νόσον ἔλεγε καὶ τὴν ὅρασιν ψεύδεσθαι. λαμπρῶς τ’ ἐνίοτε ἐν τῷ συγγράμματι καὶ σαφῶς ἐκβάλλει, ὥστε καὶ τὸν νωθέστατον ῥᾳδίως γνῶναι καὶ δίαρμα ψυχῆς λαβεῖν· ἥ τε βραχύτης καὶ τὸ βάρος τῆς ἑρμηνείας ἀσύγκριτον.", "st": "9.7"}, {"sp": "N", "t": "Καὶ τὰ ἐπὶ μέρους δὲ αὐτῷ ὧδ’ ἔχει τῶν δογμάτων· πῦρ εἶναι στοιχεῖον καὶ πυρὸς ἀμοιβὴν τὰ πάντα, ἀραιώσει καὶ πυκνώσει γινόμενα. σαφῶς δ’ οὐδὲν ἐκτίθεται. γίνεσθαί τε πάντα κατ’ ἐναντιότητα καὶ ῥεῖν τὰ ὅλα ποταμοῦ δίκην, πεπεράνθαι τε τὸ πᾶν καὶ ἕνα εἶναι κόσμον· γεννᾶσθαί τε αὐτὸν ἐκ πυρὸς καὶ πάλιν ἐκπυροῦσθαι κατά τινας περιόδους ἐναλλὰξ τὸν σύμπαντα αἰῶνα· τοῦτο δὲ γίνεσθαι καθ’ εἱμαρμένην. τῶν δὲ ἐναντίων τὸ μὲν ἐπὶ τὴν γένεσιν ἄγον καλεῖσθαι πόλεμον καὶ ἔριν, τὸ δ’ ἐπὶ τὴν ἐκπύρωσιν ὁμολογίαν καὶ εἰρήνην, καὶ τὴν μεταβολὴν ὁδὸν ἄνω κάτω, τόν τε κόσμον γίνεσθαι κατ’ αὐτήν.", "st": "9.8"}, {"sp": "N", "t": "Πυκνούμενον γὰρ τὸ πῦρ ἐξυγραίνεσθαι συνιστάμενόν τε γίνεσθαι ὕδωρ, πηγνύμενον δὲ τὸ ὕδωρ εἰς γῆν τρέπεσθαι· καὶ ταύτην ὁδὸν ἐπὶ τὸ κάτω εἶναι. πάλιν τε αὖ τὴν γῆν χεῖσθαι, ἐξ ἧς τὸ ὕδωρ γίνεσθαι, ἐκ δὲ τούτου τὰ λοιπά, σχεδὸν πάντα ἐπὶ τὴν ἀναθυμίασιν ἀνάγων τὴν ἀπὸ τῆς θαλάττης· αὕτη δέ ἐστιν ἡ ἐπὶ τὸ ἄνω ὁδός. γίνεσθαι δ’ ἀναθυμιάσεις ἀπό τε γῆς καὶ θαλάττης, ἃς μὲν λαμπρὰς καὶ καθαράς, ἃς δὲ σκοτεινάς. αὔξεσθαι δὲ τὸ μὲν πῦρ ὑπὸ τῶν λαμπρῶν, τὸ δὲ ὑγρὸν ὑπὸ τῶν ἑτέρων. τὸ δὲ περιέχον ὁποῖόν ἐστιν οὐ δηλοῖ· εἶναι μέντοι ἐν αὐτῷ σκάφας ἐπεστραμμένας κατὰ κοῖλον πρὸς ἡμᾶς, ἐν αἷς ἀθροιζομένας τὰς λαμπρὰς ἀναθυμιάσεις ἀποτελεῖν φλόγας, ἃς εἶναι τὰ ἄστρα. λαμπροτάτην δὲ εἶναι τὴν τοῦ ἡλίου φλόγα καὶ θερμοτάτην. τὰ μὲν γὰρ ἄλλα ἄστρα πλεῖον ἀπέχειν ἀπὸ γῆς καὶ διὰ τοῦτο ἧττον λάμπειν καὶ θάλπειν, τὴν δὲ σελήνην προσγειοτέραν οὖσαν μὴ διὰ τοῦ καθαροῦ φέρεσθαι τόπου. τὸν μέντοι ἥλιον ἐν διαυγεῖ καὶ ἀμιγεῖ κινεῖσθαι καὶ σύμμετρον ἀφ’ ἡμῶν ἔχειν διάστημα· τοιγάρτοι μᾶλλον θερμαίνειν τε καὶ φωτίζειν. ἐκλείπειν τε ἥλιον καὶ σελήνην, ἄνω στρεφομένων τῶν σκαφῶν· τούς τε κατὰ μῆνα τῆς σελήνης σχηματισμοὺς γίνεσθαι στρεφομένης ἐν αὐτῇ κατὰ μικρὸν τῆς σκάφης. ἡμέραν τε καὶ νύκτα γίνεσθαι καὶ μῆνας καὶ ὥρας ἐτείους καὶ ἐνιαυτοὺς ὑετούς τε καὶ πνεύματα καὶ τὰ τούτοις ὅμοια κατὰ τὰς διαφόρους ἀναθυμιάσεις.", "st": "9.9"}, {"sp": "N", "t": "τὴν μὲν γὰρ λαμπρὰν ἀναθυμίασιν φλογωθεῖσαν ἐν τῷ κύκλῳ τοῦ ἡλίου ἡμέραν ποιεῖν, τὴν δὲ ἐναντίαν ἐπικρατήσασαν νύκτ’ ἀποτελεῖν· καὶ ἐκ μὲν τοῦ λαμπροῦ τὸ θερμὸν αὐξόμενον θέρος ποιεῖν, ἐκ δὲ τοῦ σκοτεινοῦ τὸ ὑγρὸν πλεονάζον χειμῶνα ἀπεργάζεσθαι. ἀκολούθως δὲ τούτοις καὶ περὶ τῶν ἄλλων αἰτιολογεῖ.", "st": "9.11"}, {"sp": "N", "t": "περὶ δὲ τῆς γῆς οὐδὲν ἀποφαίνεται ποία τίς ἐστιν, ἀλλ’ οὐδὲ περὶ τῶν σκαφῶν. καὶ ταῦτα μὲν ἦν αὐτῷ τὰ δοκοῦντα.", "st": "9.11b"}, {"sp": "N", "t": "Τὰ δὲ περὶ Σωκράτους καὶ ὅσα ἐντυχὼν τῷ συγγράμματι εἴποι, κομίσαντος Εὐριπίδου, καθά φησιν Ἀρίστων, ἐν τῷ περὶ Σωκράτους εἰρήκαμεν. Σέλευκος μέντοι φησὶν ὁ γραμματικὸς Κρότωνά τινα ἱστορεῖν ἐν τῷ Κατακολυμβητῇ Κράτητά τινα πρῶτον εἰς τὴν Ἑλλάδα κομίσαι τὸ βιβλίον· 〈ὃν〉 καὶ εἰπεῖν Δηλίου τινὸς δεῖσθαι κολυμβητοῦ, ὃς οὐκ ἀποπνιγήσεται ἐν αὐτῷ. ἐπιγράφουσι δ’ αὐτῷ οἱ μὲν Μούσας, οἱ δὲ Περὶ φύσεως, Διόδοτος δὲ<br>ἀκριβὲς οἰάκισμα πρὸς σταθμὴν βίου,", "st": "9.12"}, {"sp": "N", "t": "ἄλλοι γνώμον’ ἠθῶν, 〈τοῦ θ’ ὅλου〉 κόσμου τρόπιν ἑνός τε ξυμπάντων τε.", "st": "9.12b"}, {"sp": "N", "t": "φασὶ δ’ αὐτὸν ἐρωτηθέντα διὰ τί σιωπᾷ, φάναι ἵν’ ὑμεῖς λαλῆτε.", "st": "9.12c"}, {"sp": "N", "t": "ἐπόθησε δ’ αὐτοῦ καὶ Δαρεῖος μετασχεῖν καὶ ἔγραψεν ὧδε πρὸς αὐτόν·", "st": "9.12d"}, {"sp": "N", "t": "“Βασιλεὺς Δαρεῖος πατρὸς Υστάσπεω Ἡράκλειτον Ἐφέσιον σοφὸν ἄνδρα προσαγορεύει χαίρειν.", "st": "9.13"}, {"sp": "N", "t": "“Καταβέβλησαι λόγον Περὶ φύσεως δυσνόητόν τε καὶ δυσεξήγητον. ἔν τισι μὲν οὖν ἑρμηνευόμενος κατὰ λέξιν σὴν δοκεῖ δύναμίν τινα περιέχειν θεωρίας κόσμου τε τοῦ σύμπαντος καὶ τῶν ἐν τούτῳ γινομένων, ἅπερ ἐστὶν ἐν θειοτάτῃ κείμενα κινήσει· τῶν δὲ πλείστων ἐποχὴν ἔχοντα, ὥστε καὶ τοὺς ἐπὶ πλεῖστον μετεσχηκότας συγγραμμάτων διαπορεῖσθαι τῆς ὀρθῆς δοκούσης γεγράφθαι παρὰ σοὶ ἐξηγήσεως. βασιλεὺς οὖν Δαρεῖος Ὑστάσπου βούλεται τῆς σῆς ἀκροάσεως μετασχεῖν καὶ παιδείας Ἑλληνικῆς. ἔρχου δὴ συντόμως πρὸς ἐμὴν ὄψιν καὶ βασίλειον οἶκον. Ἕλληνες γὰρ ἐπὶ τὸ πλεῖστον ἀνεπισήμαντοι σοφοῖς ἀνδράσιν ὄντες παρορῶσι τὰ καλῶς ὑπ’ αὐτῶν ἐνδεικνύμενα πρὸς σπουδαίαν ἀκοὴν καὶ μάθησιν. παρ’ ἐμοὶ δ’ ὑπάρχει σοι πᾶσα μὲν προεδρία, καθ’ ἡμέραν δὲ καλὴ καὶ σπουδαία προσαγόρευσις καὶ βίος εὐδόκιμος σαῖς παραινέσεσιν.", "st": "9.14"}, {"sp": "N", "t": "“Ἡράκλειτος Ἐφέσιος βασιλέϊ Δαρείῳ πατρὸς Ὑστάσπεω χαίρειν.", "st": "9.14b"}, {"sp": "N", "t": "“Ὁκόσοι τυγχάνουσιν ὄντες ἐπιχθόνιοι τῆς μὲν ἀληθηίης καὶ δικαιοπραγμοσύνης ἀπέχονται, ἀπληστίῃ δὲ καὶ δοξοκοπίῃ προσέχουσι κακῆς ἕνεκα ἀνοίης. ἐγὼ δ’ ἀμνηστίην ἔχων πάσης πονηρίης καὶ κόρον φεύγων παντὸς οἰκειούμενον φθόνῳ καὶ διὰ τὸ περιίστασθαι ὑπερηφανίην οὐκ ἂν ἀφικοίμην εἰς Περσῶν χώρην, ὀλίγοις ἀρκεόμενος κατ’ ἐμὴν γνώμην.", "st": "9.14c"}, {"sp": "N", "t": "Τοιοῦτος μὲν ἁνὴρ καὶ πρὸς βασιλέα. Δημήτριος δέ φησιν ἐν τοῖς Ὁμωνύμοις καὶ Ἀθηναίων αὐτὸν ὑπερφρονῆσαι, δόξαν ἔχοντα παμπλείστην, καταφρονούμενόν τε ὑπὸ τῶν Ἐφεσίων ἑλέσθαι μᾶλλον τὰ οἰκεῖα. μέμνηται αὐτοῦ καὶ ὁ Φαληρεὺς Δημήτριος ἐν τῇ Σωκράτους ἀπολογίᾳ.", "st": "9.15"}, {"sp": "N", "t": "πλεῖστοί τέ εἰσιν ὅσοι ἐξήγηνται αὐτοῦ τὸ σύγγραμμα· καὶ γὰρ Ἀντισθένης καὶ Ἡρακλείδης ὁ Ποντικὸς Κλεάνθης τε καὶ Σφαῖρος ὁ Στωικός, πρὸς δὲ Παυσανίας ὁ κληθεὶς Ἡρακλειτιστής, Νικομήδης τε καὶ Διονύσιος· τῶν δὲ γραμματικῶν Διόδοτος, ὃς οὔ φησι περὶ φύσεως εἶναι τὸ σύγγραμμα, ἀλλὰ περὶ πολιτείας, τὸ δὲ περὶ φύσεως ἐν παραδείγματος εἴδει κεῖσθαι. Ἱερώνυμος δέ φησι καὶ Σκυθῖνον τὸν τῶν ἰάμβων ποιητὴν ἐπιβαλέσθαι τὸν ἐκείνου λόγον διὰ μέτρου ἐκβάλλειν.", "st": "9.16"}, {"sp": "N", "t": "πολλά τ’ εἰς αὐτὸν ἐπιγράμματα φέρεται, ἀτὰρ δὴ καὶ τόδε·<br>Ἡράκλειτος ἐγώ· τί μ’ ἄνω κάτω ἕλκετ’ ἄμουσοι; οὐχ ὑμῖν ἐπόνουν, τοῖς δ’ ἔμ’ ἐπισταμένοις. εἷς ἐμοὶ ἄνθρωπος τρισμύριοι, οἱ δ’ ἀνάριθμοι οὐδείς. ταῦτ’ αὐδῶ καὶ παρὰ Φερσεφόνῃ.", "st": "9.16b"}, {"sp": "N", "t": "καὶ ἄλλο τοιόνδε·<br>μὴ ταχὺς Ἡρακλείτου ἐπ’ ὀμφαλὸν εἴλεε βίβλον τοὐφεσίου· μάλα τοι δύσβατος ἀτραπιτός. ὀρφνὴ καὶ σκότος ἐστὶν ἀλάμπετον· ἢν δέ σε μύστης εἰσαγάγῃ, φανεροῦ λαμπρότερ’ ἠελίου.", "st": "9.16c"}, {"sp": "N", "t": "Γεγόνασι δ’ Ἡράκλειτοι πέντε· πρῶτος αὐτὸς οὗτος· δεύτερος ποιητὴς λυρικός, οὗ ἐστι τῶν δώδεκα θεῶν ἐγκώμιον· τρίτος ἐλεγείας ποιητὴς Ἁλικαρνασσεύς, εἰς ὃν Καλλίμαχος πεποίηκεν οὕτως·<br>εἶπέ τις, Ἡράκλειτε, τεὸν μόρον, ἐς δ’ ἐμὲ δάκρυ ἤγαγεν, ἐμνήσθην δ’ ὁσσάκις ἀμφότεροι ἥλιον ἐν λέσχῃ κατεδύσαμεν. ἀλλὰ σὺ μέν που, ξεῖν’ Ἁλικαρνασσεῦ, τετράπαλαι σποδιή, αἱ δὲ τεαὶ ζώουσιν ἀηδόνες, ᾗσιν ὁ πάντων ἁρπάκτης Ἀΐδης οὐκ ἐπὶ χεῖρα βαλεῖ.", "st": "9.17"}, {"sp": "N", "t": "τέταρτος Λέσβιος, ἱστορίαν γεγραφὼς Μακεδονικήν· πέμπτος σπουδογέλοιος, ἀπὸ κιθαρῳδίας μεταβεβηκὼς εἰς 〈τόδε〉 τὸ εἶδος.", "st": "9.17b"}, {"sp": "HDR", "t": "ΞΕΝΟΦΑΝΗΣ"}, {"sp": "N", "t": "Ξενοφάνης Δεξίου ἤ, ὡς Ἀπολλόδωρος, Ὀρθομένους Κολοφώνιος ἐπαινεῖται πρὸς τοῦ Τίμωνος· φησὶ γοῦν,<br>Ξεινοφάνην θ’ ὑπάτυφον, Ὁμηραπάτην ἐπικόπτην.", "st": "9.18"}, {"sp": "N", "t": "οὗτος ἐκπεσὼν τῆς πατρίδος ἐν Ζάγκλῃ τῆς Σικελίας * * * διέτριβε δὲ καὶ ἐν Κατάνῃ.", "st": "9.18b"}, {"sp": "N", "t": "διήκουσε δὲ κατ’ ἐνίους μὲν οὐδενός, κατ’ ἐνίους δὲ Βότωνος Ἀθηναίου ἤ, ὥς τινες, Ἀρχελάου. καί, ὡς Σωτίων φησί, κατ’ Ἀναξίμανδρον ἦν.", "st": "9.18c"}, {"sp": "N", "t": "γέγραφε δὲ καὶ ἐν ἔπεσι καὶ ἐλεγείας καὶ ἰάμβους καθ’ Ἡσιόδου καὶ Ὁμήρου, ἐπικόπτων αὐτῶν τὰ περὶ θεῶν εἰρημένα. ἀλλὰ καὶ αὐτὸς ἐρραψῴδει τὰ ἑαυτοῦ. ἀντιδοξάσαι τε λέγεται Θαλῇ καὶ Πυθαγόρᾳ, καθάψασθαι δὲ καὶ Ἐπιμενίδου. μακροβιώτατός τε γέγονεν, ὥς που καὶ αὐτός φησιν· ἤδη δ’ ἑπτά τ’ ἔασι καὶ ἑξήκοντ’ ἐνιαυτοὶ βληστρίζοντες ἐμὴν φροντίδ’ ἀν’ Ἑλλάδα γῆν· ἐκ γενετῆς δὲ τότ’ ἦσαν ἐείκοσι πέντε τε πρὸς τοῖς, εἴπερ ἐγὼ περὶ τῶνδ’ οἶδα λέγειν ἐτύμως.", "st": "9.19"}, {"sp": "N", "t": "Φησὶ δὲ τέτταρα εἶναι τῶν ὄντων στοιχεῖα, κόσμους δ’ ἀπείρους, οὐ παραλλακτοὺς δέ. τὰ νέφη συνίστασθαι τῆς ἀφ’ ἡλίου ἀτμίδος ἀναφερομένης καὶ αἰρούσης αὐτὰ εἰς τὸ περιέχον. οὐσίαν θεοῦ σφαιροειδῆ, μηδὲν ὅμοιον ἔχουσαν ἀνθρώπῳ· ὅλον δὲ ὁρᾶν καὶ ὅλον ἀκούειν, μὴ μέντοι ἀναπνεῖν· σύμπαντά τε εἶναι νοῦν καὶ φρόνησιν καὶ ἀΐδιον. πρῶτός τε ἀπεφήνατο ὅτι πᾶν τὸ γινόμενον φθαρτόν ἐστι καὶ ἡ ψυχὴ πνεῦμα. Ἔφη δὲ καὶ τὰ πολλὰ ἥσσω νοῦ εἶναι. καὶ τοῖς τυράννοις ἐντυγχάνειν ἢ ὡς ἥκιστα ἢ ὡς ἥδιστα.", "st": "9.20"}, {"sp": "N", "t": "Ἐμπεδοκλέους δὲ εἰπόντος αὐτῷ ὅτι ἀνεύρετός ἐστιν ὁ σοφός, εἰκότως, ἔφη· σοφὸν γὰρ εἶναι δεῖ τὸν ἐπιγνωσόμενον τὸν σοφόν. φησὶ δὲ Σωτίων πρῶτον αὐτὸν εἰπεῖν ἀκατάληπτ’ εἶναι τὰ πάντα, πλανώμενος.", "st": "9.20b"}, {"sp": "N", "t": "Ἐποίησε δὲ καὶ Κολοφῶνος κτίσιν καὶ τὸν εἰς Ἐλέαν τῆς Ἰταλίας ἀποικισμὸν ἔπη δισχίλια. καὶ ἤκμαζε κατὰ τὴν ἑξηκοστὴν Ὀλυμπιάδα.", "st": "9.20c"}, {"sp": "N", "t": "φησὶ δὲ Δημήτριος ὁ Φαληρεὺς ἐν τῷ Περὶ γήρως καὶ Παναίτιος ὁ Στωικὸς ἐν τῷ Περὶ εὐθυμίας ταῖς ἰδίαις χερσὶ θάψαι τοὺς υἱεῖς αὐτόν, καθάπερ καὶ Ἀναξαγόραν. δοκεῖ δὲ πεπρᾶσθαι ὑπὸ * * 〈καὶ λελύσθαι ὑπὸ〉 τῶν Πυθαγορικῶν Παρμενίσκου καὶ Ὀρεστάδου, καθά φησι Φαβωρῖνος ἐν Ἀπομνημονευμάτων πρώτῳ.", "st": "9.20d"}, {"sp": "N", "t": "γέγονε δὲ καὶ ἄλλος Ξενοφάνης Λέσβιος ποιητὴς ἰάμβων.", "st": "9.20e"}, {"sp": "N", "t": "Καὶ οὗτοι μὲν οἱ σποράδην.", "st": "9.20f"}, {"sp": "HDR", "t": "ΠΑΡΜΕΝΙΔΗΣ"}, {"sp": "N", "t": "Ξενοφάνους δὲ διήκουσε Παρμενίδης Πύρητος Ἐλεάτης (τοῦτον Θεόφραστος ἐν τῇ Ἐπιτομῇ Ἀναξιμάνδρου φησὶν ἀκοῦσαι). ὅμως δ’ οὖν ἀκούσας καὶ Ξενοφάνους οὐκ ἠκολούθησεν αὐτῷ. ἐκοινώνησε δὲ καὶ Ἀμεινίᾳ Διοχαίτα τῷ Πυθαγορικῷ, ὡς ἔφη Σωτίων, ἀνδρὶ πένητι μέν, καλῷ δὲ καὶ ἀγαθῷ. ᾧ καὶ μᾶλλον ἠκολούθησε καὶ ἀποθανόντος ἡρῷον ἱδρύσατο γένους τε ὑπάρχων λαμπροῦ καὶ πλούτου, καὶ ὑπ’ Ἀμεινίου ἀλλ’ οὐχ ὑπὸ Ξενοφάνους εἰς ἡσυχίαν προετράπη.", "st": "9.21"}, {"sp": "N", "t": "Πρῶτος δ’ οὗτος τὴν γῆν ἀπέφαινε σφαιροειδῆ καὶ ἐν μέσῳ κεῖσθαι. δύο τε εἶναι στοιχεῖα, πῦρ καὶ γῆν, καὶ τὸ μὲν δημιουργοῦ τάξιν ἔχειν, τὴν δ’ ὕλης. γένεσίν τ’ ἀνθρώπων ἐξ ἡλίου πρῶτον γενέσθαι· αὐτὸν δὲ ὑπερέχειν τὸ θερμὸν καὶ τὸ ψυχρόν, ἐξ ὧν τὰ πάντα συνεστάναι. καὶ τὴν ψυχὴν καὶ τὸν νοῦν ταὐτὸν εἶναι, καθὰ μέμνηται καὶ Θεόφραστος ἐν τοῖς Φυσικοῖς, πάντων σχεδὸν ἐκτιθέμενος τὰ δόγματα.", "st": "9.22"}, {"sp": "N", "t": "δισσήν τε ἔφη τὴν φιλοσοφίαν, τὴν μὲν κατ’ ἀλήθειαν, τὴν δὲ κατὰ δόξαν. διὸ καί φησί που·<br>χρεὼ δέ σε πάντα πυθέσθαι ἠμὲν Ἀληθείης εὐκυκλέος ἀτρεμὲς ἦτορ, ἠδὲ βροτῶν δόξας, ταῖς οὐκ ἔνι πίστις ἀληθής.", "st": "9.22b"}, {"sp": "N", "t": "Καὶ αὐτὸς δὲ διὰ ποιημάτων φιλοσοφεῖ, καθάπερ Ἡσίοδός τε καὶ Ξενοφάνης καὶ Ἐμπεδοκλῆς. κριτήριον δὲ τὸν λόγον εἶπε· τάς τε αἰσθήσεις μὴ ἀκριβεῖς ὑπάρχειν. φησὶ γοῦν·<br>μηδέ σ’ ἔθος πολύπειρον ὁδὸν κατὰ τήνδε βιάσθω νωμᾶν ἄσκοπον ὄμμα καὶ ἠχήεσσαν ἀκουὴν καὶ γλῶσσαν, κρῖναι δὲ λόγῳ πολύδηριν ἔλεγχον.", "st": "9.22c"}, {"sp": "N", "t": "διὸ καὶ περὶ αὐτοῦ φησιν ὁ Τίμων·<br>Παρμενίδου τε βίην μεγαλόφρονος οὐ πολύδοξον, ὅς ῥ’ ἀπὸ φαντασίας ἀπάτης ἀνενείκατο νώσεις.", "st": "9.23"}, {"sp": "N", "t": "εἰς τοῦτον καὶ Πλάτων τὸν διάλογον γέγραφε, Παρμενίδην ἐπιγράψας ἢ Περὶ ἰδεῶν. Ἤκμαζε δὲ κατὰ τὴν ἐνάτην καὶ ἑξηκοστὴν Ὀλυμπιάδα. καὶ δοκεῖ πρῶτος πεφωρακέναι τὸν αὐτὸν εἶναι Ἕσπερον καὶ Φωσφόρον, ὥς φησι Φαβωρῖνος ἐν πέμπτῳ Ἀπομνημονευμάτων· οἱ δὲ Πυθαγόραν· Καλλίμαχος δέ φησι μὴ εἶναι αὐτοῦ τὸ ποίημα.", "st": "9.23b"}, {"sp": "N", "t": "λέγεται δὲ καὶ νόμους θεῖναι τοῖς πολίταις, ὥς φησι Σπεύσιππος ἐν τῷ Περὶ φιλοσόφων. καὶ πρῶτος ἐρωτῆσαι τὸν Ἀχιλλέα λόγον, ὡς Φαβωρῖνος ἐν Παντοδαπῇ ἱστορίᾳ.", "st": "9.23c"}, {"sp": "N", "t": "Γέγονε δὲ καὶ ἕτερος Παρμενίδης, ῥήτωρ τεχνογράφος.", "st": "9.23d"}, {"sp": "HDR", "t": "ΜΕΛΙΣΣΟΣ"}, {"sp": "N", "t": "Μέλισσος Ἰθαιγένους Σάμιος. οὗτος ἤκουσε Παρμενίδου· ἀλλὰ καὶ εἰς λόγους ἦλθεν Ἡρακλείτῳ· ὅτε καὶ συνέστησεν αὐτὸν τοῖς Ἐφεσίοις ἀγνοοῦσι, καθάπερ Ἱπποκράτης Δημόκριτον Ἀβδηρίταις.", "st": "9.24"}, {"sp": "N", "t": "γέγονε δὲ καὶ πολιτικὸς ἀνὴρ καὶ ἀποδοχῆς παρὰ τοῖς πολίταις ἠξιωμένος· ὅθεν ναύαρχος αἱρεθεὶς ἔτι καὶ μᾶλλον ἐθαυμάσθη διὰ τὴν οἰκείαν ἀρετήν.", "st": "9.24b"}, {"sp": "N", "t": "Ἐδόκει δ’ αὐτῷ τὸ πᾶν ἄπειρον εἶναι καὶ ἀναλλοίωτον καὶ ἀκίνητον καὶ ἓν ὅμοιον ἑαυτῷ καὶ πλῆρες· κίνησίν τε μὴ εἶναι, δοκεῖν δ’ εἶναι. ἀλλὰ καὶ περὶ θεῶν ἔλεγε μὴ δεῖν ἀποφαίνεσθαι·", "st": "9.24c"}, {"sp": "N", "t": "μὴ γὰρ εἶναι γνῶσιν αὐτῶν. Φησὶ δ’ Ἀπολλόδωρος ἠκμακέναι αὐτὸν κατὰ τὴν τετάρτην καὶ ὀγδοηκοστὴν Ὀλυμπιάδα.", "st": "9.24d"}, {"sp": "HDR", "t": "ΖΗΝΩΝ ΕΛΕΑΤΗΣ"}, {"sp": "N", "t": "Ζήνων Ἐλεάτης. τοῦτον Ἀπολλόδωρός φησιν εἶναι ἐν Χρονικοῖς [Πύρητος τὸν δὲ Παρμενίδην] φύσει μὲν Τελευταγόρου, θέσει δὲ Παρμενίδου 〈τὸν δὲ Παρμενίδην Πύρητος〉.", "st": "9.25"}, {"sp": "N", "t": "περὶ τούτου καὶ Μελίσσου Τίμων φησὶ ταῦτα·<br>ἀμφοτερογλώσσου τε μέγα σθένος οὐκ ἀλαπαδνὸν Ζήνωνος πάντων ἐπιλήπτορος, ἠδὲ Μέλισσον, πολλῶν φαντασμῶν ἐπάνω, παύρων γε μὲν ἥσσω.", "st": "9.25b"}, {"sp": "N", "t": "Ὁ δὴ Ζήνων διακήκοε Παρμενίδου καὶ γέγονεν αὐτοῦ παιδικά.", "st": "9.25c"}, {"sp": "N", "t": "καὶ εὐμήκης ἦν, καθά φησι Πλάτων ἐν τῷ Παρμενίδῃ, ὁ δ’ αὐτὸς ἐν τῷ Σοφιστῇ καὶ ἐν τῷ Φαίδρῳ 〈αὐτοῦ μέμνηται〉 καὶ Ἐλεατικὸν Παλαμήδην αὐτὸν καλεῖ.", "st": "9.25d"}, {"sp": "N", "t": "φησὶ δ’ Ἀριστοτέλης εὑρετὴν αὐτὸν γενέσθαι διαλεκτικῆς, ὥσπερ Ἐμπεδοκλέα ῥητορικῆς. Γέγονε δὲ ἀνὴρ γενναιότατος καὶ ἐν φιλοσοφίᾳ καὶ ἐν πολιτείᾳ· φέρεται γοῦν αὐτοῦ βιβλία πολλῆς συνέσεως γέμοντα.", "st": "9.26"}, {"sp": "N", "t": "καθελεῖν δὲ θελήσας Νέαρχον τὸν τύραννον—οἱ δὲ Διομέδοντα—συνελήφθη, καθά φησιν Ἡρακλείδης ἐν τῇ Σατύρου ἐπιτομῇ. ὅτε καὶ ἐξεταζόμενος τοὺς συνειδότας καὶ περὶ τῶν ὅπλων ὧν ἦγεν εἰς Λιπάραν, πάντας ἐμήνυσεν αὐτοῦ τοὺς φίλους, βουλόμενος αὐτὸν ἔρημον καταστῆσαι· εἶτα περί τινων εἰπεῖν ἔχειν τινα 〈ἔφη〉 αὐτῷ πρὸς τὸ οὖς καὶ δακὼν οὐκ ἀνῆκεν ἕως ἀπεκεντήθη, ταὐτὸν Ἀριστογείτονι τῷ τυραννοκτόνῳ παθών. Δημήτριος δέ φησιν ἐν τοῖς Ὁμωνύμοις τὸν μυκτῆρα αὐτὸν ἀποτραγεῖν.", "st": "9.27"}, {"sp": "N", "t": "Ἀντισθένης δὲ ἐν ταῖς Διαδοχαῖς φησι μετὰ τὸ μηνῦσαι τοὺς φίλους ἐρωτηθῆναι πρὸς τοῦ τυράννου εἴ τις ἄλλος εἴη· τὸν δὲ εἰπεῖν, σὺ ὁ τῆς πόλεως ἀλιτήριος. πρός τε τοὺς παρεστῶτας φάναι· θαυμάζω ὑμῶν τὴν δειλίαν, εἰ τούτων ἕνεκεν ὧν νῦν ἐγὼ ὑπομένω, δουλεύετε τῷ τυράννῳ· καὶ τέλος ἀποτραγόντα τὴν γλῶτταν προσπτύσαι αὐτῷ· τοὺς δὲ πολίτας παρορμηθέντας αὐτίκα τὸν τύραννον καταλεῦσαι. ταὐτὰ δὲ σχεδὸν οἱ πλείους λαλοῦσιν.", "st": "9.27b"}, {"sp": "N", "t": "Ἕρμιππος δέ φησιν εἰς ὅλμον αὐτὸν βληθῆναι καὶ κατακοπῆναι. Καὶ εἰς αὐτὸν ἡμεῖς εἴπομεν οὕτως·<br>ἤθελες, ὦ Ζήνων, καλὸν ἤθελες ἄνδρα τύραννον κτείνας ἐκλῦσαι δουλοσύνης Ἐλέαν. ἀλλ’ ἐδάμης· δὴ γάρ σε λαβὼν ὁ τύραννος ἐν ὅλμῳ κόψε. τί τοῦτο λέγω; σῶμα γάρ, οὐχὶ δὲ σέ.", "st": "9.28"}, {"sp": "N", "t": "Γέγονε δὲ τά τε ἄλλα ἀγαθὸς ὁ Ζήνων, ἀλλὰ καὶ ὑπεροπτικὸς τῶν μειζόνων κατ’ ἴσον Ἡρακλείτῳ· καὶ γὰρ οὗτος τὴν πρότερον μὲν Ὑέλην, ὕστερον δ’ Ἐλέαν, Φωκαέων οὖσαν ἀποικίαν, αὑτοῦ δὲ πατρίδα, πόλιν εὐτελῆ καὶ μόνον ἄνδρας ἀγαθοὺς τρέφειν ἐπισταμένην ἠγάπησε μᾶλλον τῆς Ἀθηναίων μεγαλαυχίας, οὐκ ἐπιδημήσας πώμαλα πρὸς αὐτούς, ἀλλ’ αὐτόθι καταβιούς.", "st": "9.28b"}, {"sp": "N", "t": "Οὗτος καὶ τὸν Ἀχιλλέα πρῶτος λόγον ἠρώτησε [Φαβωρῖνος δέ φησι Παρμενίδην] καὶ ἄλλους συχνούς.", "st": "9.29"}, {"sp": "N", "t": "ἀρέσκει δ’ αὐτῷ τάδε· κόσμους εἶναι κενόν τε μὴ εἶναι· γεγενῆσθαι δὲ τὴν τῶν πάντων φύσιν ἐκ θερμοῦ καὶ ψυχροῦ καὶ ξηροῦ καὶ ὑγροῦ, λαμβανόντων αὐτῶν εἰς ἄλληλα τὴν μεταβολήν· γένεσίν τε ἀνθρώπων ἐκ γῆς εἶναι καὶ ψυχὴν κρᾶμα ὑπάρχειν ἐκ τῶν προειρημένων κατὰ μηδενὸς τούτων ἐπικράτησιν.", "st": "9.29b"}, {"sp": "N", "t": "Τοῦτόν φασι λοιδορούμενον ἀγανακτῆσαι· αἰτιασαμένου δέ τινος, φάναι ἐὰν μὴ λοιδορούμενος προσποιῶμαι, οὐδ’ ἐπαινούμενος αἰσθήσομαι.", "st": "9.29c"}, {"sp": "N", "t": "Ὅτι δὲ γεγόνασι Ζήνωνες ὀκτὼ ἐν τῷ Κιτιεῖ διειλέγμεθα. ἤκμαζε δ’ οὗτος κατὰ τὴν ἐνάτην 〈καὶ ἑβδομηκοστὴν〉 Ὀλυμπιάδα.", "st": "9.29d"}, {"sp": "HDR", "t": "ΛΕΥΚΙΠΠΟΣ"}, {"sp": "N", "t": "Λεύκιππος Ἐλεάτης, ὡς δέ τινες, Ἀβδηρίτης, κατ’ ἐνίους δὲ Μιλήσιος.", "st": "9.30"}, {"sp": "N", "t": "οὗτος ἤκουσε Ζήνωνος. ἤρεσκε δ’ αὐτῷ ἄπειρα εἶναι τὰ πάντα καὶ εἰς ἄλληλα μεταβάλλειν, τό τε πᾶν εἶναι κενὸν καὶ πλῆρες [σωμάτων]. τούς τε κόσμους γίνεσθαι σωμάτων εἰς τὸ κενὸν ἐμπιπτόντων καὶ ἀλλήλοις περιπλεκομένων· ἔκ τε τῆς κινήσεως κατὰ τὴν αὔξησιν αὐτῶν γίνεσθαι τὴν τῶν ἀστέρων φύσιν. φέρεσθαι δὲ τὸν ἥλιον ἐν μείζονι κύκλῳ περὶ τὴν σελήνην· τὴν γῆν ὀχεῖσθαι περὶ τὸ μέσον δινουμένην· σχῆμά τ’ αὐτῆς τυμπανῶδες εἶναι. πρῶτός τε ἀτόμους ἀρχὰς ὑπεστήσατο.", "st": "9.30b"}, {"sp": "N", "t": "〈καὶ〉 κεφαλαιωδῶς μὲν ταῦτα· ἐπὶ μέρους δ’ ὧδε ἔχει. Τὸ μὲν πᾶν ἄπειρόν φησιν, ὡς προείρηται· τούτου δὲ τὸ μὲν πλῆρες εἶναι, τὸ δὲ κενόν, 〈ἃ〉 καὶ στοιχεῖά φησι. κόσμους τε ἐκ τούτων ἀπείρους εἶναι καὶ διαλύεσθαι εἰς ταῦτα. γίνεσθαι δὲ τοὺς κόσμους οὕτω· φέρεσθαι κατ’ ἀποτομὴν ἐκ τῆς ἀπείρου πολλὰ σώματα παντοῖα τοῖς σχήμασιν εἰς μέγα κενόν, ἅπερ ἀθροισθέντα δίνην ἀπεργάζεσθαι μίαν, καθ’ ἣν προσκρούοντα 〈ἀλλήλοις〉 καὶ παντοδαπῶς κυκλούμενα διακρίνεσθαι χωρὶς τὰ ὅμοια πρὸς τὰ ὅμοια.", "st": "9.31"}, {"sp": "N", "t": "ἰσορρόπων δὲ διὰ τὸ πλῆθος μηκέτι δυναμένων περιφέρεσθαι, τὰ μὲν λεπτὰ χωρεῖν εἰς τὸ ἔξω κενόν, ὥσπερ διαττώμενα· τὰ δὲ λοιπὰ συμμένειν καὶ περιπλεκόμενα συγκατατρέχειν ἀλλήλοις καὶ ποιεῖν πρῶτόν τι σύστημα σφαιροειδές.", "st": "9.31b"}, {"sp": "N", "t": "τοῦτο δ’ οἷον ὑμένα ἀφίστασθαι, περιέχοντ’ ἐν ἑαυτῷ παντοῖα σώματα· ὧν κατὰ τὴν τοῦ μέσου ἀντέρεισιν περιδινουμένων λεπτὸν γενέσθαι τὸν πέριξ ὑμένα, συρρεόντων ἀεὶ τῶν συνεχῶν κατ’ ἐπίψαυσιν τῆς δίνης. καὶ οὕτω γενέσθαι τὴν γῆν, συμμενόντων τῶν ἐνεχθέντων ἐπὶ τὸ μέσον.", "st": "9.32"}, {"sp": "N", "t": "αὐτόν τε πάλιν τὸν περιέχοντα οἷον ὑμένα αὔξεσθαι κατὰ τὴν ἐπέκκρισιν τῶν ἔξωθεν σωμάτων· δίνῃ τε φερόμενον αὐτὸν ὧν ἂν ἐπιψαύοῃ, ταῦτα ἐπικτᾶσθαι. τούτων δέ τινα συμπλεκόμενα ποιεῖν σύστημα, τὸ μὲν πρῶτον κάθυγρον καὶ πηλῶδες, ξηρανθέντα καὶ περιφερόμενα σὺν τῇ τοῦ ὅλου δίνῃ, εἶτ’ ἐκπυρωθέντα τὴν τῶν ἀστέρων ἀποτελέσαι φύσιν. Εἶναι δὲ τὸν τοῦ ἡλίου κύκλον ἐξώτατον, τὸν δὲ τῆς σελήνης προσγειότατον, τῶν ἄλλων μεταξὺ τούτων.", "st": "9.33"}, {"sp": "N", "t": "καὶ πάντα μὲν τὰ ἄστρα πυροῦσθαι διὰ τὸ τάχος τῆς φορᾶς, τὸν δ’ ἥλιον 〈καὶ〉 ὑπὸ τῶν ἀστέρων ἐκπυροῦσθαι· τὴν δὲ σελήνην τοῦ πυρὸς ὀλίγον μεταλαμβάνειν. ἐκλείπειν δ’ ἥλιον καὶ σελήνην 〈* * τὴν δὲ λόξωσιν τοῦ Ζῳδιακοῦ γενέσθαι〉 τῷ κεκλίσθαι τὴν γῆν πρὸς μεσημβρίαν· τὰ δὲ πρὸς ἄρκτῳ ἀεί τε νίφεσθαι καὶ κατάψυχρα εἶναι καὶ πήγνυσθαι.", "st": "9.33b"}, {"sp": "N", "t": "καὶ τὸν μὲν ἥλιον ἐκλείπειν σπανίως, τὴν δὲ σελήνην συνεχές, διὰ τὸ ἀνίσους εἶναι τοὺς κύκλους αὐτῶν.", "st": "9.33c"}, {"sp": "N", "t": "εἶναί τε ὥσπερ γενέσεις κόσμου, οὕτω καὶ αὐξήσεις καὶ φθίσεις καὶ φθοράς, κατά τινα ἀνάγκην, ἣν ὁποία ἐστὶν 〈οὐ〉 διασαφεῖ.", "st": "9.33d"}, {"sp": "HDR", "t": "ΔΗΜΟΚΡΙΤΟΣ"}, {"sp": "N", "t": "Δημόκριτος Ἡγησιστράτου, οἱ δὲ Ἀθηνοκρίτου, τινὲς Δαμασίππου Ἀβδηρίτης ἤ, ὡς ἔνιοι, Μιλήσιος.", "st": "9.34"}, {"sp": "N", "t": "οὗτος μάγων τινῶν διήκουσε καὶ Χαλδαίων, Ξέρξου τοῦ βασιλέως τῷ πατρὶ αὐτοῦ ἐπιστάτας καταλιπόντος, ἡνίκα ἐξενίσθη παρ’ αὐτῷ, καθά φησι καὶ Ἡρόδοτος· παρ’ ὧν τά τε περὶ θεολογίας καὶ ἀστρολογίας ἔμαθεν ἔτι παῖς ὤν. ὕστερον δὲ Λευκίππῳ παρέβαλε καὶ Ἀναξαγόρᾳ κατά τινας, ἔτεσιν ὢν αὐτοῦ νεώτερος τετταράκοντα. Φαβωρῖνος δέ φησιν ἐν Παντοδαπῇ ἱστορίᾳ λέγειν Δημόκριτον περὶ Ἀναξαγόρου ὡς οὐκ εἴησαν αὐτοῦ αἱ δόξαι αἵ τε περὶ ἡλίου καὶ σελήνης, ἀλλὰ ἀρχαῖαι, τὸν δ’ ὑφῃρῆσθαι. διασύρειν τε αὐτοῦ τὰ περὶ τῆς διακοσμήσεως καὶ τοῦ νοῦ, ἐχθρῶς ἔχοντα πρὸς αὐτὸν ὅτι δὴ μὴ προσήκατο αὐτόν. πῶς οὖν κατά τινας ἀκήκοεν αὐτοῦ; Φησὶ δὲ Δημήτριος ἐν Ὁμωνύμοις καὶ Ἀντισθένης ἐν Διαδοχαῖς ἀποδημῆσαι αὐτὸν καὶ εἰς Αἴγυπτον πρὸς τοὺς ἱερέας γεωμετρίαν μαθησόμενον καὶ πρὸς Χαλδαίους εἰς τὴν Περσίδα καὶ εἰς τὴν Ἐρυθρὰν θάλασσαν γενέσθαι. τοῖς τε Γυμνοσοφισταῖς φασί τινες συμμῖξαι αὐτὸν ἐν Ἰνδίᾳ καὶ εἰς Αἰθιοπίαν ἐλθεῖν.", "st": "9.35"}, {"sp": "N", "t": "τρίτον τε ὄντα ἀδελφὸν νείμασθαι τὴν οὐσίαν· καὶ οἱ μὲν πλείους φασὶ τὴν ἐλάττω μοῖραν ἑλέσθαι τὴν ἐν ἀργυρίῳ, χρείαν ἔχοντα 〈διὰ τὸ〉 ἀποδημῆσαι τούτου κἀκείνων δολίως ὑποπτευσάντων. ὁ δὲ Δημήτριος ὑπὲρ ἑκατὸν τάλαντά φησιν εἶναι αὐτῷ τὸ μέρος, ἃ πάντα καταναλῶσαι.", "st": "9.36"}, {"sp": "N", "t": "λέγει δ’ ὅτι τοσοῦτον ἦν φιλόπονος ὥστε τοῦ περικήπου δωμάτιόν τι ἀποτεμόμενος κατάκλειστος ἦν· καί ποτε τοῦ πατρὸς αὐτοῦ πρὸς θυσίαν βοῦν ἀγαγόντος καὶ αὐτόθι προσδήσαντος, ἱκανὸν χρόνον μὴ γνῶναι, ἕως αὐτὸν ἐκεῖνος διαναστήσας προφάσει τῆς θυσίας καὶ τὰ περὶ τὸν βοῦν διηγήσατο.", "st": "9.36b"}, {"sp": "N", "t": "δοκεῖ δέ, φησί, καὶ Ἀθήναζε ἐλθεῖν καὶ μὴ σπουδάσαι γνωσθῆναι, δόξης καταφρονῶν. καὶ εἰδέναι μὲν Σωκράτη, ἀγνοεῖσθαι δὲ ὑπ’ αὐτοῦ· ἦλθον γάρ, φησίν, εἰς Ἀθήνας καὶ οὔτις με ἔγνωκεν. Εἴπερ οἱ Ἀντερασταὶ Πλάτωνός εἰσι, φησὶ Θρασύλος, οὗτος ἂν εἴη ὁ παραγενόμενος ἀνώνυμος, τῶν περὶ Οἰνοπίδην καὶ Ἀναξαγόραν ἕτερος, ἐν τῇ πρὸς Σωκράτην ὁμιλίᾳ διαλεγόμενος περὶ φιλοσοφίας, ᾧ, φησίν, ὡς πεντάθλῳ ἔοικεν ὁ φιλόσοφος, καὶ ἦν ὡς ἀληθῶς ἐν φιλοσοφίᾳ πένταθλος· τὰ γὰρ φυσικὰ καὶ τὰ ἠθικὰ 〈ἤσκητο〉, ἀλλὰ καὶ τὰ μαθηματικὰ καὶ τοὺς ἐγκυκλίους λόγους καὶ περὶ τεχνῶν πᾶσαν εἶχεν ἐμπειρίαν. τούτου ἐστὶ καὶ τὸ λόγος ἔργου σκιή. Δημήτριος δὲ ὁ Φαληρεὺς ἐν τῇ Σωκράτους ἀπολογίᾳ μηδὲ ἐλθεῖν φησιν αὐτὸν εἰς Ἀθήνας. τοῦτο δὲ καὶ μεῖζον, εἴγε τοσαύτης πόλεως ὑπερεφρόνησεν, οὐκ ἐκ τόπου δόξαν λαβεῖν βουλόμενος, ἀλλὰ τόπῳ δόξαν περιθεῖναι προελόμενος.", "st": "9.37"}, {"sp": "N", "t": "Δῆλον δὲ κἀκ τῶν συγγραμμάτων οἷος ἦν. δοκεῖ δέ, φησὶν ὁ Θρασύλος, ζηλωτὴς γεγονέναι τῶν Πυθαγορικῶν· ἀλλὰ καὶ αὐτοῦ Πυθαγόρου μέμνηται, θαυμάζων αὐτὸν ἐν τῷ ὁμωνύμῳ συγγράμματι. πάντα δὲ δοκεῖν παρὰ τούτου λαβεῖν καὶ αὐτοῦ δ’ ἂν ἀκηκοέναι, εἰ μὴ τὰ τῶν χρόνων ἐμάχετο. πάντως μέντοι τῶν Πυθαγορικῶν τινος ἀκοῦσαί φησιν αὐτὸν Γλαῦκος ὁ Ῥηγῖνος, κατὰ τοὺς αὐτοὺς χρόνους αὐτῷ γεγονώς.", "st": "9.38"}, {"sp": "N", "t": "φησὶ δὲ καὶ Ἀπολλόδωρος ὁ Κυζικηνὸς Φιλολάῳ αὐτὸν συγγεγονέναι. Ἤσκει δέ, φησὶν ὁ Ἀντισθένης, καὶ ποικίλως δοκιμάζειν τὰς φαντασίας, ἐρημάζων ἐνίοτε καὶ τοῖς τάφοις ἐνδιατρίβων.", "st": "9.38b"}, {"sp": "N", "t": "ἐλθόντα δή φησιν αὐτὸν ἐκ τῆς ἀποδημίας ταπεινότατα διάγειν, ἅτε πᾶσαν τὴν οὐσίαν καταναλωκότα· τρέφεσθαί τε διὰ τὴν ἀπορίαν ἀπὸ τἀδελφοῦ Δαμάσου. ὡς δὲ προειπών τινα τῶν μελλόντων εὐδοκίμησε, λοιπὸν ἐνθέου δόξης παρὰ τοῖς πλείστοις ἠξιώθη. νόμου δ’ ὄντος τὸν ἀναλώσαντα τὴν πατρῴαν οὐσίαν μὴ ἀξιοῦσθαι ταφῆς ἐν τῇ πατρίδι, φησὶν ὁ Ἀντισθένης συνέντα, μὴ ὑπεύθυνος γενηθείη πρός τινων φθονούντων καὶ συκοφαντούντων, ἀναγνῶναι αὐτοῖς τὸν Μέγαν διάκοσμον, ὃς ἁπάντων αὐτοῦ τῶν συγγραμμάτων προέχει· καὶ πεντακοσίοις ταλάντοις τιμηθῆναι· μὴ μόνον δέ, ἀλλὰ καὶ χαλκαῖς εἰκόσι· καὶ τελευτήσαντ’ αὐτὸν δημοσίᾳ ταφῆναι, βιώσαντα ὑπὲρ τὰ ἑκατὸν ἔτη. ὁ δὲ Δημήτριος τοὺς συγγενέας αὐτοῦ φησιν ἀναγνῶναι τὸν Μέγαν διάκοσμον, ὃν μόνον ἑκατὸν ταλάντων τιμηθῆναι.", "st": "9.39"}, {"sp": "N", "t": "ταὐτὰ δὲ καὶ Ἱππόβοτός φησιν. Ἀριστόξενος δ’ ἐν τοῖς Ἱστορικοῖς ὑπομνήμασί φησι Πλάτωνα θελῆσαι συμφλέξαι τὰ Δημοκρίτου συγγράμματα, ὁπόσα ἐδυνήθη συναγαγεῖν, Ἀμύκλαν δὲ καὶ Κλεινίαν τοὺς Πυθαγορικοὺς κωλῦσαι αὐτόν, ὡς οὐδὲν ὄφελος· παρὰ πολλοῖς γὰρ εἶναι ἤδη τὰ βιβλία. καὶ δῆλον δέ· πάντων γὰρ σχεδὸν τῶν ἀρχαίων μεμνημένος ὁ Πλάτων οὐδαμοῦ Δημοκρίτου διαμνημονεύει, ἀλλ’ οὐδ’ ἔνθ’ ἀντειπεῖν τι αὐτῷ δέοι, δῆλον 〈ὅτι〉 εἰδὼς ὡς πρὸς τὸν ἄριστον αὐτῷ τῶν φιλοσόφων 〈ὁ ἀγὼν〉 ἔσοιτο· ὅν γε καὶ Τίμων τοῦτον ἐπαινέσας τὸν τρόπον ἔχει·<br>οἷον Δημόκριτόν τε περίφρονα, ποιμένα μύθων, ἀμφίνοον λεσχῆνα μετὰ πρώτοισιν ἀνέγνων.", "st": "9.39b"}, {"sp": "N", "t": "Γέγονε δὲ τοῖς χρόνοις, ὡς αὐτός φησιν ἐν τῷ Μικρῷ διακόσμῳ, νέος κατὰ πρεσβύτην Ἀναξαγόραν, ἔτεσιν αὐτοῦ νεώτερος τετταράκοντα. συντετάχθαι δέ φησι τὸν Μικρὸν διάκοσμον ἔτεσιν ὕστερον τῆς Ἰλίου ἁλώσεως τριάκοντα καὶ ἑπτακοσίοις. γεγόνοι δ’ ἄν, ὡς μὲν Ἀπολλόδωρος ἐν Χρονικοῖς, κατὰ τὴν ὀγδοηκοστὴν Ὀλυμπιάδα· ὡς δὲ Θρασύλος ἐν τῷ ἐπιγραφομένῳ Τὰ πρὸ τῆς ἀναγνώσεως τῶν Δημοκρίτου βιβλίων, κατὰ τὸ τρίτον ἔτος τῆς ἑβδόμης καὶ ἑβδομηκοστῆς Ὀλυμπιάδος, ἐνιαυτῷ, φησί, πρεσβύτερος ὢν Σωκράτους. εἴη ἂν οὖν κατ’ Ἀρχέλαον τὸν Ἀναξαγόρου μαθητὴν καὶ τοὺς περὶ Οἰνοπίδην· καὶ γὰρ τούτου μέμνηται. μέμνηται δὲ καὶ τῆς περὶ τοῦ ἑνὸς δόξης τῶν περὶ Παρμενίδην καὶ Ζήνωνα, ὡς κατ’ αὐτὸν μάλιστα διαβεβοημένων, καὶ Πρωταγόρου τοῦ Ἀβδηρίτου, ὃς ὁμολογεῖται κατὰ Σωκράτην γεγονέναι.", "st": "9.41"}, {"sp": "N", "t": "Φησὶ δ’ Ἀθηνόδωρος ἐν ὀγδόῃ Περιπάτων, ἐλθόντος Ἱπποκράτους πρὸς αὐτόν, κελεῦσαι κομισθῆναι γάλα· καὶ θεασάμενον τὸ γάλα εἰπεῖν εἶναι αἰγὸς πρωτοτόκου καὶ μελαίνης· ὅθεν τὴν ἀκρίβειαν αὐτοῦ θαυμάσαι τὸν Ἱπποκράτην. ἀλλὰ καὶ κόρης ἀκολουθούσης τῷ Ἱπποκράτει, τῇ μὲν πρώτῃ ἡμέρᾳ ἀσπάσασθαι οὕτω χαῖρε κόρη, τῇ δ’ ἐχομένῃ χαῖρε γύναι· καὶ ἦν ἡ κόρη τῆς νυκτὸς διεφθαρμένη.", "st": "9.41b"}, {"sp": "N", "t": "Τελευτῆσαι δὲ τὸν Δημόκριτόν φησιν Ἕρμιππος τοῦτον τὸν τρόπον. ἤδη ὑπέργηρων ὄντα πρὸς τῷ καταστρέφειν εἶναι. τὴν οὖν ἀδελφὴν λυπεῖσθαι ὅτι ἐν τῇ τῶν θεσμοφόρων ἑορτῇ μέλλοι τεθνήξεσθαι καὶ τῇ θεῷ τὸ καθῆκον αὐτὴ οὐ ποιήσειν τὸν δὲ θαρρεῖν εἰπεῖν καὶ κελεῦσαι αὑτῷ προσφέρειν ἄρτους θερμοὺς ὁσημέραι. τούτους δὴ ταῖς ῥισὶ προσφέρων διεκράτησεν αὑτὸν τὴν ἑορτήν· ἐπειδὴ δὲ παρῆλθον αἱ ἡμέραι, τρεῖς δ’ ἦσαν, ἀλυπότατα τὸν βίον προήκατο, ὥς φησιν ὁ Ἵππαρχος, ἐννέα πρὸς τοῖς ἑκατὸν ἔτη βιούς. Ἡμεῖς τ’ εἰς αὐτὸν ἐν τῇ Παμμέτρῳ τοῦτον ἐποιήσαμεν τὸν τρόπον·<br>καὶ τίς ἔφυ σοφὸς ὧδε, τίς ἔργον ἔρεξε τοσοῦτον ὅσσον ὁ παντοδαὴς ἤνυσε Δημόκριτος; ὃς Θάνατον παρεόντα τρί’ ἤματα δώμασιν ἔσχεν καὶ θερμοῖς ἄρτων ἄσθμασιν ἐξένισεν.", "st": "9.43"}, {"sp": "N", "t": "τοιοῦτος μὲν ὁ βίος τἀνδρός.", "st": "9.43b"}, {"sp": "N", "t": "Δοκεῖ δ’ αὐτῷ τάδε· ἀρχὰς εἶναι τῶν ὅλων ἀτόμους καὶ κενόν, τὰ δ’ ἄλλα πάντα νενομίσθαι· ἀπείρους τε εἶναι κόσμους καὶ γενητοὺς καὶ φθαρτούς. μηδέν τε ἐκ τοῦ μὴ ὄντος γίνεσθαι μηδὲ εἰς τὸ μὴ ὂν φθείρεσθαι. καὶ τὰς ἀτόμους δὲ ἀπείρους εἶναι κατὰ μέγεθος καὶ πλῆθος, φέρεσθαι δ’ ἐν τῷ ὅλῳ δινουμένας, καὶ οὕτω πάντα τὰ συγκρίματα γεννᾶν, πῦρ, ὕδωρ, ἀέρα, γῆν· εἶναι γὰρ καὶ ταῦτα ἐξ ἀτόμων τινῶν συστήματα· ἅπερ εἶναι ἀπαθῆ καὶ ἀναλλοίωτα διὰ τὴν στερρότητα. τόν τε ἥλιον καὶ τὴν σελήνην ἐκ τοιούτων λείων καὶ περιφερῶν ὄγκων συγκεκρίσθαι, καὶ τὴν ψυχὴν ὁμοίως· ἣν καὶ νοῦν ταὐτὸν εἶναι. ὁρᾶν δ’ ἡμᾶς κατ’ εἰδώλων ἐμπτώσεις. Πάντα τε κατ’ ἀνάγκην γίνεσθαι, τῆς δίνης αἰτίας οὔσης τῆς γενέσεως πάντων, ἣν ἀνάγκην λέγει. τέλος δ’ εἶναι τὴν εὐθυμίαν, οὐ τὴν αὐτὴν οὖσαν τῇ ἡδονῇ, ὡς ἔνιοι παρακούσαντες ἐξεδέξαντο, ἀλλὰ καθ’ ἣν γαληνῶς καὶ εὐσταθῶς ἡ ψυχὴ διάγει, ὑπὸ μηδενὸς ταραττομένη φόβου ἢ δεισιδαιμονίας ἢ ἄλλου τινὸς πάθους. καλεῖ δ’ αὐτὴν καὶ εὐεστὼ καὶ πολλοῖς ἄλλοις ὀνόμασι. ποιότητας δὲ νόμῳ εἶναι, φύσει δ’ ἄτομα καὶ κενόν.", "st": "9.44"}, {"sp": "N", "t": "καὶ ταῦτα μὲν αὐτῷ ἐδόκει. Τὰ δὲ βιβλία αὐτοῦ καὶ Θρασύλος ἀναγέγραφε κατὰ τάξιν οὕτως ὡσπερεὶ καὶ τὰ Πλάτωνος κατὰ τετραλογίαν.", "st": "9.44b"}, {"sp": "N", "t": "Ἔστι δὲ ἠθικὰ μὲν τάδε·<br>Πυθαγόρης.<br>Περὶ τῆς τοῦ σοφοῦ διαθέσεως.<br>Περὶ τῶν ἐν Ἅιδου.<br>Τριτογένεια (τοῦτο δέ ἐστιν, ὅτι τρία γίνεται ἐξ αὐτῆς, ἃ πάντα ἀνθρώπινα συνέχει).<br>Περὶ ἀνδραγαθίας ἢ περὶ ἀρετῆς.<br>Ἀμαλθείης κέρας.<br>Περὶ εὐθυμίης.<br>Ὑπομνημάτων ἠθικῶν· ἡ γὰρ Εὐεστὼ οὐχ εὑρίσκεται.<br>καὶ ταῦτα μὲν τὰ ἠθικά. Φυσικὰ δὲ τάδε·", "st": "9.46"}, {"sp": "N", "t": "Μέγας διάκοσμος (ὃν οἱ περὶ Θεόφραστον Λευκίππου φασὶν εἶναι).<br>Μικρὸς διάκοσμος.<br>Κοσμογραφίη.<br>Περὶ τῶν πλανήτων.<br>Περὶ φύσεως πρῶτον.<br>Περὶ ἀνθρώπου φύσιος (ἢ Περὶ σαρκός), δεύτερον.<br>Περὶ νοῦ.<br>Περὶ αἰσθησίων (ταῦτά τινες ὁμοῦ γράφοντες Περὶ ψυχῆς ἐπιγράφουσι).<br>Περὶ χυμῶν.<br>Περὶ χροῶν. Περὶ τῶν διαφερόντων ῥυσμῶν.<br>Περὶ ἀμειψιρυσμιῶν.<br>Κρατυντήρια (ὅπερ ἐστὶν ἐπικριτικὰ τῶν προειρημένων).<br>Περὶ εἰδώλων ἢ περὶ προνοίας.<br>Περὶ λογικῶν ἢ κανὼν α′ β′ γ’.<br>Ἀπορημάτων.<br>ταῦτα καὶ περὶ φύσεως. Τὰ δὲ ἀσύντακτά ἐστι τάδε·", "st": "9.47"}, {"sp": "N", "t": "Αἰτίαι οὐράνιαι.<br>Αἰτίαι ἀέριοι.<br>Αἰτίαι ἐπίπεδοι.<br>Αἰτίαι περὶ πυρὸς καὶ τῶν ἐν πυρί.<br>Αἰτίαι περὶ φωνῶν.<br>Αἰτίαι περὶ σπερμάτων καὶ φυτῶν καὶ καρπῶν.<br>Αἰτίαι περὶ ζῴων α′ β′ γ′.<br>Αἰτίαι σύμμικτοι.<br>Περὶ τῆς λίθου.", "st": "9.47b"}, {"sp": "N", "t": "ταῦτα καὶ τὰ ἀσύντακτα. Μαθηματικὰ δὲ τάδε·<br>Περὶ διαφορῆς γωνίης ἢ Περὶ ψαύσιος κύκλου καὶ σφαίρης.<br>Περὶ γεωμετρίης.<br>Γεωμετρικῶν.<br>Ἀριθμοί.<br>Περὶ ἀλόγων γραμμῶν καὶ ναστῶν αʹ βʹ.<br>Ἐκπετάσματα. Μέγας ἐνιαυτὸς ἢ Ἀστρονομίη, παράπηγμα.<br>Ἅμιλλα κλεψύδρας 〈καὶ οὐρανοῦ〉.<br>Οὐρανογραφίη.<br>Γεωγραφίη.<br>Πολογραφίη.<br>Ἀκτινογραφίη.<br>τοσαῦτα καὶ τὰ μαθηματικά. Μουσικὰ δὲ τάδε·", "st": "9.48"}, {"sp": "N", "t": "Περὶ ῥυθμῶν καὶ ἁρμονίης.<br>Περὶ ποιήσιος.<br>Περὶ καλλοσύνης ἐπέων.<br>Περὶ εὐφώνων καὶ δυσφώνων γραμμάτων.<br>Περὶ Ὁμήρου ἢ ὀρθοεπείης καὶ γλωσσέων.<br>Περὶ ἀοιδῆς.<br>Περὶ ῥημάτων.<br>Ὀνομαστικῶν.<br>τοσαῦτα καὶ τὰ μουσικά. Τεχνικὰ δὲ τάδε·", "st": "9.48b"}, {"sp": "N", "t": "Πρόγνωσις.<br>Περὶ διαίτης ἢ διαιτητικόν.<br>[Ἢ] Ἰητρικὴ γνώμη.<br>Αἰτίαι περὶ ἀκαιριῶν καὶ ἐπικαιριῶν.<br>Περὶ γεωργίης ἢ Γεωμετρικόν.<br>Περὶ ζωγραφίης.<br>Τακτικὸν καὶ<br>Ὁπλομαχικόν.<br>τοσαῦτα καὶ τάδε.", "st": "9.48c"}, {"sp": "N", "t": "Τάττουσι δέ τινες κατ’ ἰδίαν ἐκ τῶν Ὑπομνημάτων καὶ ταῦτα·<br>Περὶ τῶν ἐν Βαβυλῶνι ἱερῶν γραμμάτων.<br>Περὶ τῶν ἐν Μερόῃ.<br>Ὠκεανοῦ περίπλους.<br>Περὶ ἱστορίης.<br>Χαλδαϊκὸς λόγος.<br>Φρύγιος λόγος.<br>Περὶ πυρετοῦ καὶ τῶν ἀπὸ νόσου βησσόντων.<br>Νομικὰ αἴτια.<br>Χειρόκμητα [ἢ] προβλήματα.", "st": "9.49"}, {"sp": "N", "t": "Τὰ δ’ ἄλλα ὅσα τινὲς ἀναφέρουσιν εἰς αὐτὸν τὰ μὲν ἐκ τῶν αὐτοῦ διεσκεύασται, τὰ δ’ ὁμολογουμένως ἐστὶν ἀλλότρια. ταῦτα καὶ περὶ τῶν βιβλίων αὐτοῦ καὶ τοσαῦτα.", "st": "9.49b"}, {"sp": "N", "t": "Γεγόνασι δὲ Δημόκριτοι ἕξ· πρῶτος αὐτὸς οὗτος, δεύτερος Χῖος μουσικὸς κατὰ τὸν αὐτὸν χρόνον, τρίτος ἀνδριαντοποιὸς οὗ μέμνηται Ἀντίγονος, τέταρτος περὶ τοῦ ἱεροῦ τοῦ ἐν Ἐφέσῳ γεγραφὼς καὶ τῆς πόλεως Σαμοθρᾴκης, πέμπτος ποιητὴς ἐπιγραμμάτων σαφὴς καὶ ἀνθηρός, ἕκτος Περγαμηνὸς ἀπὸ ῥητορικῶν λόγων 〈εὐδοκιμήσας〉.", "st": "9.49c"}, {"sp": "HDR", "t": "ΠΡΩΤΑΓΟΡΑΣ"}, {"sp": "N", "t": "Πρωταγόρας Ἀρτέμωνος ἤ, ὡς Ἀπολλόδωρος καὶ Δείνων ἐν Περσικῷ ε’, Μαιανδρίου Ἀβδηρίτης, καθά φησιν Ἡρακλείδης ὁ Ποντικὸς ἐν τοῖς Περὶ νόμων, ὃς καὶ Θουρίοις νόμους γράψαι φησὶν αὐτόν· ὡς δ’ Εὔπολις ἐν Κόλαξιν, Τήιος· φησὶ γάρ,<br>Ἔνδοθι μέν ἐστι Πρωταγόρας ὁ Τήιος.", "st": "9.50"}, {"sp": "N", "t": "οὗτος καὶ Πρόδικος ὁ Κεῖος λόγους ἀναγινώσκοντες ἠρανίζοντο· καὶ Πλάτων ἐν τῷ Πρωταγόρᾳ φησὶ βαρύφωνον εἶναι τὸν Πρόδικον.", "st": "9.50b"}, {"sp": "N", "t": "διήκουσε δ’ ὁ Πρωταγόρας Δημοκρίτου. ἐκαλεῖτό τε Σοφία, ὥς φησι Φαβωρῖνος ἐν Παντοδαπῇ ἱστορίᾳ.", "st": "9.50c"}, {"sp": "N", "t": "Καὶ πρῶτος ἔφη δύο λόγους εἶναι περὶ παντὸς πράγματος ἀντικειμένους ἀλλήλοις· οἷς καὶ συνηρώτα, πρῶτος τοῦτο πράξας. ἀλλὰ καὶ ἤρξατό που τοῦτον τὸν τρόπον· πάντων χρημάτων μέτρον ἄνθρωπος, τῶν μὲν ὄντων ὡς ἔστιν, τῶν δὲ οὐκ ὄντων ὡς οὐκ ἔστιν. ἔλεγέ τε μηδὲν εἶναι ψυχὴν παρὰ τὰς αἰσθήσεις, καθὰ καὶ Πλάτων φησὶν ἐν Θεαιτήτῳ, καὶ πάντ’ εἶναι ἀληθῆ. καὶ ἀλλαχοῦ δὲ τοῦτον ἤρξατο τὸν τρόπον· περὶ μὲν θεῶν οὐκ ἔχω εἰδέναι οὔθ’ ὡς εἰσίν, οὔθ’ ὡς οὐκ εἰσίν· πολλὰ γὰρ τὰ κωλύοντα εἰδέναι, ἥ τ’ ἀδηλότης καὶ βραχὺς ὢν ὁ βίος τοῦ ἀνθρώπου. διὰ ταύτην δὲ τὴν ἀρχὴν τοῦ συγγράμματος ἐξεβλήθη πρὸς Ἀθηναίων· καὶ τὰ βιβλί’ αὐτοῦ κατέκαυσαν ἐν τῇ ἀγορᾷ, ὑπὸ κήρυκι ἀναλεξάμενοι παρ’ ἑκάστου τῶν κεκτημένων.", "st": "9.51"}, {"sp": "N", "t": "Οὗτος πρῶτος μισθὸν εἰσεπράξατο μνᾶς ἑκατόν· καὶ πρῶτος μέρη χρόνου διώρισε καὶ καιροῦ δύναμιν ἐξέθετο καὶ λόγων ἀγῶνας ἐποιήσατο καὶ σοφίσματα τοῖς πραγματολογοῦσι προσήγαγε· καὶ τὴν διάνοιαν ἀφεὶς πρὸς τοὔνομα διελέχθη καὶ τὸ νῦν ἐπιπόλαιον γένος τῶν ἐριστικῶν ἐγέννησεν· ἵνα καὶ Τίμων φησὶ περὶ αὐτοῦ,<br>Πρωταγόρης τ’ ἐπίμεικτος ἐριζέμεναι εὖ εἰδώς.", "st": "9.51b"}, {"sp": "N", "t": "οὗτος καὶ τὸ Σωκρατικὸν εἶδος τῶν λόγων πρῶτος ἐκίνησε. καὶ τὸν Ἀντισθένους λόγον τὸν πειρώμενον ἀποδεικνύειν ὡς οὐκ ἔστιν ἀντιλέγειν, οὗτος πρῶτος διείλεκται, καθά φησι Πλάτων ἐν Εὐθυδήμῳ. καὶ πρῶτος κατέδειξε τὰς πρὸς τὰς θέσεις ἐπιχειρήσεις, ὥς φησιν Ἀρτεμίδωρος ὁ διαλεκτικὸς ἐν τῷ Πρὸς Χρύσιππον. καὶ πρῶτος τὴν καλουμένην τύλην, ἐφ’ ἧς τὰ φορτία βαστάζουσιν, εὗρεν, ὥς φησιν Ἀριστοτέλης ἐν τῷ Περὶ παιδείας· φορμοφόρος γὰρ ἦν, ὡς καὶ Ἐπίκουρός πού φησι. καὶ τοῦτον τὸν τρόπον ἤρθη πρὸς Δημοκρίτου ξύλα δεδεκὼς ὀφθείς.", "st": "9.53"}, {"sp": "N", "t": "διεῖλέ τε τὸν λόγον πρῶτος εἰς τέτταρα, εὐχωλήν, ἐρώτησιν, ἀπόκρισιν, ἐντολήν· (οἱ 〈·〉ὲ εἰς ἑπτά, διήγησιν, ἐρώτησιν, ἀπόκρισιν, ἐντολήν, ἀπαγγελίαν, εὐχωλήν, κλῆσιν), οὓς καὶ πυθμένας εἶπε λόγων. Ἀλκιδάμας δὲ τέτταρας λόγους φησί, φάσιν, ἀπόφασιν, ἐρώτησιν, προσαγόρευσιν.", "st": "9.54"}, {"sp": "N", "t": "Πρῶτον δὲ τῶν λόγων ἑαυτοῦ ἀνέγνω τὸν Περὶ θεῶν, οὗ τὴν ἀρχὴν ἄνω παρεθέμεθα· ἀνέγνω δ’ Ἀθήνησιν ἐν τῇ Εὐριπίδου οἰκίᾳ ἤ, ὥς τινες, ἐν τῇ Μεγακλείδου· ἄλλοι ἐν Λυκείῳ, μαθητοῦ τὴν φωνὴν αὐτῷ χρήσαντος Ἀρχαγόρου τοῦ Θεοδότου. κατηγόρησε δ’ αὐτοῦ Πυθόδωρος Πολυζήλου, εἷς τῶν τετρακοσίων· Ἀριστοτέλης δ’ Εὔαθλόν φησιν.", "st": "9.54b"}, {"sp": "N", "t": "Ἔστι δὲ τὰ σωζόμενα αὐτοῦ βιβλία τάδε·<br>* * Τέχνη ἐριστικῶν.<br>Περὶ πάλης.<br>Περὶ τῶν μαθημάτων.<br>Περὶ πολιτείας.<br>Περὶ φιλοτιμίας.<br>Περὶ ἀρετῶν.<br>Περὶ τῆς ἐν ἀρχῇ καταστάσεως.<br>Περὶ τῶν ἐν Ἅιδου.<br>Περὶ τῶν οὐκ ὀρθῶς τοῖς ἀνθρώποις πρασσομένων.<br>Προστακτικός.<br>Δίκη ὑπὲρ μισθοῦ, Ἀντιλογιῶν α′ β′.", "st": "9.55"}, {"sp": "N", "t": "καὶ ταῦτα μὲν αὐτῷ τὰ βιβλία. γέγραφε δὲ καὶ Πλάτων εἰς αὐτὸν διάλογον.", "st": "9.55b"}, {"sp": "N", "t": "Φησὶ δὲ Φιλόχορος, πλέοντος αὐτοῦ ἐς Σικελίαν, τὴν ναῦν καταποντωθῆναι· καὶ τοῦτο αἰνίττεσθαι Εὐριπίδην ἐν τῷ Ἰξίονι. ἔνιοι κατὰ τὴν ὁδὸν τελευτῆσαι αὐτόν, βιώσαντα ἔτη πρὸς τὰ ἐνενήκοντα· Ἀπολλόδωρος δέ φησιν ἑβδομήκοντα, σοφιστεῦσαι δὲ τεσσαράκοντα καὶ ἀκμάζειν κατὰ τὴν τετάρτην καὶ ὀγδοηκοστὴν Ὀλυμπιάδα. Ἔστι καὶ εἰς τοῦτον ἡμῶν οὕτως ἔχον·<br>καὶ σεῦ, Πρωταγόρη, φάτιν ἔκλυον, ὡς ἄρ’ Ἀθηνέων ἔκ ποτ’ ἰὼν καθ’ ὁδὸν πρέσβυς ἐὼν ἔθανες· εἵλετο γάρ σε φυγεῖν Κέκροπος πόλις· ἀλλὰ σὺ μέν που Παλλάδος ἄστυ φύγες, Πλουτέα δ’ οὐκ ἔφυγες.", "st": "9.56"}, {"sp": "N", "t": "Λέγεται δέ ποτ’ αὐτὸν ἀπαιτοῦντα τὸν μισθὸν Εὔαθλον τὸν μαθητήν, ἐκείνου εἰπόντος, ἀλλ’ οὐδέπω νίκην νενίκηκα, εἰπεῖν, ἀλλ’ ἐγὼ μὲν ἂν νικήσω, ὅτι ἐγὼ ἐνίκησα, λαβεῖν με δεῖ·", "st": "9.56b"}, {"sp": "N", "t": "ἐὰν δὲ σύ, ὅτι σύ. Γέγονε δὲ καὶ ἄλλος Πρωταγόρας ἀστρολόγος, εἰς ὃν καὶ Εὐφορίων ἐπικήδειον ἔγραψε· καὶ τρίτος Στωικὸς φιλόσοφος.", "st": "9.56c"}, {"sp": "HDR", "t": "ΔΙΟΓΕΝΗΣ ΑΠΟΛΛΩΝΙΑΤΗΣ"}, {"sp": "N", "t": "Διογένης Ἀπολλοθέμιδος Ἀπολλωνιάτης, ἀνὴρ φυσικὸς καὶ ἄγαν ἐλλόγιμος. ἤκουσε δέ, φησὶν Ἀντισθένης, Ἀναξιμένους. ἦν δὲ τοῖς χρόνοις κατ’ Ἀναξαγόραν. τοῦτόν φησιν ὁ Φαληρεὺς Δημήτριος ἐν τῇ Σωκράτους ἀπολογίᾳ διὰ μέγαν φθόνον μικροῦ κινδυνεῦσαι Ἀθήνησιν.", "st": "9.57"}, {"sp": "N", "t": "Ἐδόκει δὲ αὐτῷ τάδε· στοιχεῖον εἶναι τὸν ἀέρα, κόσμους ἀπείρους καὶ κενὸν ἄπειρον· τόν τε ἀέρα πυκνούμενον καὶ ἀραιούμενον γεννητικὸν εἶναι τῶν κόσμων· οὐδὲν ἐκ τοῦ μὴ ὄντος γίνεσθαι οὐδ’ εἰς τὸ μὴ ὂν φθείρεσθαι· τὴν γῆν στρογγύλην, ἠρεισμένην ἐν τῷ μέσῳ, τὴν σύστασιν εἰληφυῖαν κατὰ τὴν ἐκ τοῦ θερμοῦ περιφορὰν καὶ πῆξιν ὑπὸ τοῦ ψυχροῦ.", "st": "9.57b"}, {"sp": "N", "t": "Ἀρχὴ δὲ αὐτῷ τοῦ συγγράμματος ἥδε·", "st": "9.57c"}, {"sp": "N", "t": "λόγου παντὸς ἀρχόμενον δοκεῖ μοι χρεὼν εἶναι τὴν ἀρχὴν ἀναμφισβήτητον παρέχεσθαι, τὴν δ’ ἑρμηνείαν ἁπλῆν καὶ σεμνήν.", "st": "9.57d"}, {"sp": "HDR", "t": "ΑΝΑΞΑΡΧΟΣ"}, {"sp": "N", "t": "Ἀνάξαρχος Ἀβδηρίτης. οὗτος ἤκουσε Διογένους τοῦ Σμυρναίου· ὁ δὲ Μητροδώρου τοῦ Χίου, ὃς ἔλεγε μηδ’ αὐτὸ τοῦτ’ εἰδέναι ὅτι οὐδὲν οἶδε. Μητρόδωρον δὲ Νεσσᾶ τοῦ Χίου, οἱ δὲ Δημοκρίτου φασὶν ἀκοῦσαι.", "st": "9.58"}, {"sp": "N", "t": "ὁ δ’ οὖν Ἀνάξαρχος καὶ Ἀλεξάνδρῳ συνῆν καὶ ἤκμαζε κατὰ τὴν δεκάτην καὶ ἑκατοστὴν Ὀλυμπιάδα καὶ εἶχεν ἐχθρὸν Νικοκρέοντα τὸν Κύπρου τύραννον· καί ποτ’ ἐν συμποσίῳ τοῦ Ἀλεξάνδρου ἐρωτήσαντος αὐτὸν τί ἄρα δοκεῖ τὸ δεῖπνον, εἰπεῖν φασιν, ὦ βασιλεῦ, πάντα πολυτελῶς· ἔδει δὲ λοιπὸν κεφαλὴν σατράπου τινὸς παρατεθεῖσθαι· ἀπορρίπτων πρὸς τὸν Νικοκρέοντα. ὁ δὲ μνησικακήσας μετὰ τὴν τελευτὴν τοῦ βασιλέως ὅτε πλέων ἀκουσίως προσηνέχθη τῇ Κύπρῳ ὁ Ἀνάξαρχος, συλλαβὼν αὐτὸν καὶ εἰς ὅλμον βαλὼν ἐκέλευσε τύπτεσθαι σιδηροῖς ὑπέροις. τὸν δ’ οὐ φροντίσαντα τῆς τιμωρίας εἰπεῖν ἐκεῖνο δὴ τὸ περιφερόμενον, πτίσσε τὸν Ἀναξάρχου θύλακον, Ἀνάξαρχον δὲ οὐ πτίσσεις. κελεύσαντος δὲ τοῦ Νικοκρέοντος καὶ τὴν γλῶτταν αὐτοῦ ἐκτμηθῆναι, λόγος ἀποτραγόντα προσπτύσαι αὐτῷ. καὶ ἔστιν ἡμῶν εἰς αὐτὸν οὕτως 〈ἔχον〉·<br>πτίσσετε, Νικοκρέων, ἔτι καὶ μάλα· θύλακός ἐστι· πτίσσετ’· Ἀνάξαρχος δ’ ἐν Διός ἐστι πάλαι. καί σε διαστείλασα γνάφοις ὀλίγον τάδε λέξει ῥήματα Φερσεφόνη, ἔρρε μυλωθρὲ κακέ.", "st": "9.59"}, {"sp": "N", "t": "Οὗτος διὰ τὴν ἀπάθειαν καὶ εὐκολίαν τοῦ βίου Εὐδαιμονικὸς ἐκαλεῖτο· καὶ ἦν ἐκ τοῦ ῥᾴστου δυνατὸς σωφρονίζειν. τὸν γοῦν Ἀλέξανδρον οἰόμενον εἶναι θεὸν ἐπέστρεψεν· ἐπειδὴ γὰρ ἔκ τινος πληγῆς εἶδεν αὐτῷ καταρρέον αἷμα, δείξας τῇ χειρὶ πρὸς αὐτόν φησι, τουτὶ μὲν αἷμα καὶ οὐκ<br>ἰχὼρ οἷός πέρ τε ῥέει μακάρεσσι θεοῖσι.", "st": "9.60"}, {"sp": "N", "t": "Πλούταρχος δ’ αὐτὸν Ἀλέξανδρον τοῦτο λέξαι πρὸς τοὺς φίλους φησίν.", "st": "9.60b"}, {"sp": "N", "t": "ἀλλὰ καὶ ἄλλοτε προπίνοντα αὐτῷ τὸν Ἀνάξαρχον δεῖξαι τὴν κύλικα καὶ εἰπεῖν<br>βεβλήσεταί τις θεῶν βροτησίᾳ χερί.", "st": "9.60c"}, {"sp": "HDR", "t": "ΠΥΡΡΩΝ"}, {"sp": "N", "t": "Πύρρων Ἠλεῖος Πλειστάρχου μὲν ἦν υἱός, καθὰ καὶ Διοκλῆς ἱστορεῖ·", "st": "9.61"}, {"sp": "N", "t": "ὥς φησι δ’ Ἀπολλόδωρος ἐν Χρονικοῖς, πρότερον ἦν ζωγράφος, καὶ ἤκουσε Βρύσωνος τοῦ Στίλπωνος, ὡς Ἀλέξανδρος ἐν Διαδοχαῖς, εἶτ’ Ἀναξάρχου, ξυνακολουθῶν πανταχοῦ, ὡς καὶ τοῖς Γυμνοσοφισταῖς ἐν Ἰνδίᾳ συμμίξαι καὶ τοῖς Μάγοις.", "st": "9.61b"}, {"sp": "N", "t": "ὅθεν γενναιότατα δοκεῖ φιλοσοφῆσαι, τὸ τῆς ἀκαταληψίας καὶ ἐποχῆς εἶδος εἰσαγαγών, ὡς Ἀσκάνιος ὁ Ἀβδηρίτης φησίν· οὐδὲν γὰρ ἔφασκεν οὔτε καλὸν οὔτ’ αἰσχρὸν οὔτε δίκαιον οὔτ’ ἄδικον· καὶ ὁμοίως ἐπὶ πάντων μηδὲν εἶναι τῇ ἀλῃθείᾳ, νόμῳ δὲ καὶ ἔθει πάντα τοὺς ἀνθρώπους πράττειν· οὐ γὰρ μᾶλλον τόδε ἢ τόδε εἶναι ἕκαστον. Ἀκόλουθος δ’ ἦν καὶ τῷ βίῳ, μηδὲν ἐκτρεπόμενος μηδὲ φυλαττόμενος, ἅπαντα ὑφιστάμενος, ἁμάξας, εἰ τύχοι, καὶ κρημνοὺς καὶ κύνας καὶ ὅλως μηδὲν ταῖς αἰσθήσεσιν ἐπιτρέπων. σώζεσθαι μέντοι, καθά φασιν οἱ περὶ τὸν Καρύστιον Ἀντίγονον, ὑπὸ τῶν γνωρίμων παρακολουθούντων. Αἰνεσίδημος δέ φησι φιλοσοφεῖν μὲν αὐτὸν κατὰ τὸν τῆς ἐποχῆς λόγον, μὴ μέντοι γ’ ἀπροοράτως ἕκαστα πράττειν. ὁ δὲ πρὸς τὰ ἐνενήκοντα ἔτη κατεβίω.", "st": "9.62"}, {"sp": "N", "t": "Ἀντίγονος δέ φησιν ὁ Καρύστιος ἐν τῷ Περὶ Πύρρωνος τάδε περὶ αὐτοῦ, ὅτι τὴν ἀρχὴν ἄδοξός τ’ ἦν καὶ πένης καὶ ζωγράφος. σώζεσθαί τ’ αὐτοῦ ἐν Ἤλιδι ἐν τῷ γυμνασίῳ λαμπαδιστὰς μετρίως ἔχοντας. ἐκπατεῖν τ’ αὐτὸν καὶ ἐρημάζειν, σπανίως ποτ’ ἐπιφαινόμενον τοῖς οἴκοι. τοῦτο δὲ ποιεῖν ἀκούσαντα Ἰνδοῦ τινος ὀνειδίζοντος Ἀναξάρχῳ ὡς οὐκ ἂν ἕτερόν τινα διδάξαι οὗτος ἀγαθόν, αὐτὸς αὐλὰς βασιλικὰς θεραπεύων. ἀεί τ’ εἶναι ἐν τῷ αὐτῷ καταστήματι, ὥστ’ εἰ καί τις αὐτὸν καταλίποι μεταξὺ λέγοντα, αὑτῷ διαπεραίνειν τὸν λόγον, καίτοι κεκινημένον τε 〈* * *〉 ὄντα ἐν νεότητι. πολλάκις, φησί, καὶ ἀπεδήμει, μηδενὶ προειπών, καὶ συνερρέμβετο οἷστισιν ἤθελεν. καί ποτ’ Ἀναξάρχου εἰς τέλμα ἐμπεσόντος, παρῆλθεν οὐ βοηθήσας· τινῶν δὲ αἰτιωμένων, αὐτὸς Ἀνάξαρχος ἐπῄνει τὸ ἀδιάφορον καὶ ἄστοργον αὐτοῦ.", "st": "9.63"}, {"sp": "N", "t": "Καταληφθεὶς δέ ποτε καὶ αὑτῷ λαλῶν καὶ ἐρωτηθεὶς τὴν αἰτίαν ἔφη μελετᾶν χρηστὸς εἶναι. ἔν τε ταῖς ζητήσεσιν ὑπ’ οὐδενὸς κατεφρονεῖτο διὰ τὸ 〈καὶ δι〉εξοδικῶς λέγειν καὶ πρὸς ἐρώτησιν· ὅθεν καὶ Ναυσιφάνην ἤδη νεανίσκον ὄντα θηραθῆναι. ἔφασκε γοῦν γίνεσθαι δεῖν τῆς μὲν διαθέσεως τῆς Πυρρωνείου, τῶν δὲ λόγων τῶν ἑαυτοῦ. ἔλεγέ τε πολλάκις καὶ Ἐπίκουρον θαυμάζοντα τὴν Πύρρωνος ἀναστροφὴν συνεχὲς αὐτοῦ πυνθάνεσθαι περὶ αὐτοῦ.", "st": "9.64"}, {"sp": "N", "t": "οὕτω δ’ αὐτὸν ὑπὸ τῆς πατρίδος τιμηθῆναι ὥστε καὶ ἀρχιερέα καταστῆσαι αὐτὸν καὶ δι’ ἐκεῖνον πᾶσι τοῖς φιλοσόφοις ἀτέλειαν ψηφίσασθαι. Καὶ δὴ καὶ ζηλωτὰς εἶχε πολλοὺς τῆς ἀπραγμοσύνης· ὅθεν καὶ ὁ Τίμων περὶ αὐτοῦ φησιν οὕτως ἐν τῷ Πύθωνι * * * καὶ ἐν τοῖς Σίλλοις· Ὦ γέρον, ὦ Πύρρων, πῶς ἢ πόθεν ἔκδυσιν εὗρες λατρείης δοξῶν [τε] κενεοφροσύνης τε σοφιστῶν, καὶ πάσης ἀπάτης πειθοῦς τ’ ἀπελύσαο δεσμά; οὐδ’ ἔμελέν σοι ταῦτα μεταλλῆσαι, τίνες αὖραι Ἑλλάδ’ ἔχουσι, πόθεν τε καὶ εἰς ὅ, τι κύρει ἕκαστα.", "st": "9.65"}, {"sp": "N", "t": "καὶ πάλιν ἐν τοῖς Ἰνδαλμοῖς·<br>τοῦτό μοι, ὦ Πύρρων, ἱμείρεται ἦτορ ἀκοῦσαι, πῶς ποτ’ ἀνὴρ ἔτ’ ἄγεις ῥᾷστα μεθ’ ἡσυχίης μοῦνος ἐν ἀνθρώποισι θεοῦ τρόπον ἡγεμονεύων.", "st": "9.65b"}, {"sp": "N", "t": "Ἀθηναῖοι δὲ καὶ πολιτείᾳ αὐτὸν ἐτίμησαν, καθά φησι Διοκλῆς, ἐπὶ τῷ Κότυν τὸν Θρᾷκα διαχρήσασθαι.", "st": "9.65c"}, {"sp": "N", "t": "εὐσεβῶς δὲ καὶ τῇ ἀδελφῇ συνεβίω μαίᾳ οὔσῃ, καθά φησιν Ἐρατοσθένης ἐν τῷ Περὶ πλούτου καὶ πενίας, ὅτε καὶ αὐτὸς φέρων εἰς τὴν ἀγορὰν ἐπίπρασκεν ὀρνίθια, εἰ τύχοι, καὶ χοιρίδια, καὶ τὰ ἐπὶ τῆς οἰκίας ἐκάθαιρεν ἀδιαφόρως. λέγεται δὲ καὶ δέλφακα λούειν αὐτὸς ὑπ’ ἀδιαφορίας. καὶ χολήσας τι ὑπὲρ τῆς ἀδελφῆς, Φιλίστα δ’ ἐκαλεῖτο, πρὸς τὸν ἐπιλαβόμενον εἰπεῖν ὡς οὐκ ἐν γυναίῳ ἡ ἐπίδειξις τῆς ἀδιαφορίας. καὶ κυνός ποτ’ ἐπενεχθέντος διασοβηθέντα εἰπεῖν πρὸς τὸν αἰτιασάμενον, ὡς χαλεπὸν εἴη ὁλοσχερῶς ἐκδῦναι τὸν ἄνθρωπον· διαγωνίζεσθαι δ’ ὡς οἷόν τε πρῶτον μὲν τοῖς ἔργοις πρὸς τὰ πράγματα, εἰ δὲ μή, τῷ γε λόγῳ. Φασὶ δὲ καὶ σηπτικῶν φαρμάκων καὶ τομῶν καὶ καύσεων ἐπί τινος ἕλκους αὐτῷ προσενεχθέντων, ἀλλὰ μηδὲ τὰς ὀφρῦς συναγαγεῖν. καὶ ὁ Τίμων δὲ διασαφεῖ τὴν διάθεσιν αὐτοῦ ἐν οἷς πρὸς Πύθωνα διέξεισιν. ἀλλὰ καὶ Φίλων ὁ Ἀθηναῖος, γνώριμος αὐτοῦ γεγονώς, ἔλεγεν ὡς ἐμέμνητο μάλιστα μὲν Δημοκρίτου, εἶτα δὲ καὶ Ὁμήρου, θαυμάζων αὐτὸν καὶ συνεχὲς λέγων,<br>οἵη περ φύλλων γενεή, τοίη δὲ καὶ ἀνδρῶν·", "st": "9.66"}, {"sp": "N", "t": "καὶ ὅτι σφηξὶ καὶ μυίαις καὶ ὀρνέοις εἴκαζε τοὺς ἀνθρώπους. προφέρεσθαι δὲ καὶ τάδε·<br>ἀλλά, φίλος, θάνε καὶ σύ· τίη ὀλοφύρεαι οὕτως; κάτθανε καὶ Πάτροκλος, ὅ περ σέο πολλὸν ἀμείνων·", "st": "9.66b"}, {"sp": "N", "t": "καὶ ὅσα συντείνει εἰς τὸ ἀβέβαιον καὶ κενόσπουδον ἅμα καὶ παιδαριῶδες τῶν ἀνθρώπων. Ποσειδώνιος δὲ καὶ τοιοῦτόν τι διέξεισι περὶ αὐτοῦ. τῶν γὰρ συμπλεόντων αὐτῷ ἐσκυθρωπακότων ὑπὸ χειμῶνος, αὐτὸς γαληνὸς ὢν ἀνέρρωσε τὴν ψυχήν, δείξας ἐν τῷ πλοίῳ χοιρίδιον ἐσθίον καὶ εἰπὼν ὡς χρὴ τὸν σοφὸν ἐν τοιαύτῃ καθεστάναι ἀταραξίᾳ. μόνος δὲ Νουμήνιος καὶ δογματίσαι φησὶν αὐτόν.", "st": "9.68"}, {"sp": "N", "t": "τούτου πρὸς τοῖς ἄλλοις καὶ μαθηταὶ γεγόνασιν ἐλλόγιμοι, ὧν Εὐρύλοχος· οὗ φέρεται ἐλάσσωμα τόδε. φασὶ γὰρ ὡς οὕτω παρωξύνθη ποτὲ ὥστε τὸν ὀβελίσκον ἄρας μετὰ τῶν κρεῶν ἕως τῆς ἀγορᾶς ἐδίωκε τὸν μάγειρον. καὶ ἐν Ἤλιδι καταπονούμενος ὑπὸ τῶν ζητούντων ἐν τοῖς λόγοις, ἀπορρίψας θοιμάτιον διενήξατο [πέραν] τὸν Ἀλφειόν. ἦν οὖν πολεμιώτατος τοῖς σοφισταῖς, ὡς καὶ Τίμων φησίν. Ὁ δὲ Φίλων τὰ πλεῖστα διελέγετο ἑαυτῷ. ὅθεν καὶ περὶ τούτου φησὶν οὕτως·<br>ἢ τὸν ἀπ’ ἀνθρώπων αὐτόσχολον αὐτολαλητὴν οὐκ ἐμπαζόμενον δόξης ἐρίδων τε Φίλωνα.", "st": "9.69"}, {"sp": "N", "t": "Πρὸς τούτοις διήκουε τοῦ Πύρρωνος Ἑκαταῖός τε ὁ Ἀβδηρίτης καὶ Τίμων ὁ Φλιάσιος ὁ τοὺς Σίλλους πεποιηκώς, περὶ οὗ λέξομεν, ἔτι τε Ναυσιφάνης 〈ὁ〉 Τήιος, οὗ φασί τινες ἀκοῦσαι Ἐπίκουρον.", "st": "9.69b"}, {"sp": "N", "t": "οὗτοι πάντες Πυρρώνειοι μὲν ἀπὸ τοῦ διδασκάλου, ἀπορητικοὶ δὲ καὶ σκεπτικοὶ καὶ ἔτι ἐφεκτικοὶ καὶ ζητητικοὶ ἀπὸ τοῦ οἷον δόγματος προσηγορεύοντο. ζητητικοὶ μὲν οὖν ἀπὸ τοῦ πάντοτε ζητεῖν τὴν ἀλήθειαν, σκεπτικοὶ δ’ ἀπὸ τοῦ σκέπτεσθαι ἀεὶ καὶ μηδέποτε εὑρίσκειν, ἐφεκτικοὶ δ’ ἀπὸ τοῦ μετὰ τὴν ζήτησιν πάθους· λέγω δὲ τὴν ἐποχήν· ἀπορητικοὶ δ’ ἀπὸ τοῦ τοὺς δογματικοὺς ἀπορεῖν καὶ αὐτούς.", "st": "9.70"}, {"sp": "N", "t": "Πυρρώνειοι δὲ ἀπὸ Πύρρωνος. Θεοδόσιος δ’ ἐν τοῖς Σκεπτικοῖς κεφαλαίοις οὔ φησι δεῖν Πυρρώνειον καλεῖσθαι τὴν σκεπτικήν· εἰ γὰρ τὸ καθ’ ἕτερον κίνημα τῆς διανοίας ἄληπτόν ἐστιν, οὐκ εἰσόμεθα τὴν Πύρρωνος διάθεσιν· μὴ εἰδότες δὲ οὐδὲ Πυρρώνειοι καλοίμεθ’ ἄν. πρὸς τῷ μηδὲ πρῶτον εὑρηκέναι τὴν σκεπτικὴν Πύρρωνα μηδ’ ἔχειν τι δόγμα. λέγοιτο δ’ ἄν τις Πυρρώνειος ὁμότροπος. Ταύτης δὲ τῆς αἱρέσεως ἔνιοί φασιν Ὅμηρον 〈·〉, ἐπεὶ περὶ τῶν αὐτῶν πραγμάτων παρ’ ὁντινοῦν ἄλλοτ’ ἄλλως ἀποφαίνεται καὶ οὐδὲν ὁρικῶς δογματίζει περὶ τὴν ἀπόφασιν. ἔπειτα καὶ τὰ τῶν ἑπτὰ σοφῶν σκεπτικὰ εἶναι, οἷον τὸ Μηδὲν ἄγαν, καὶ Ἐγγύα, πάρα δ’ ἄτα· δηλοῦσθαι γὰρ τῷ βεβαίως καὶ πεπεισμένως διεγγυωμένῳ ἐπακολουθεῖν ἄτην. ἀλλὰ καὶ Ἀρχίλοχον καὶ Εὐριπίδην σκεπτικῶς ἔχειν, ἐν οἷς Ἀρχίλοχος μέν φησι·<br>τοῖος ἀνθρώποισι θυμός, Γλαῦκε Λεπτίνεω πάϊ, γίγνεται θνητοῖς ὁκοίην Ζεὺς ἐπ’ ἡμέρην ἄγει.", "st": "9.71"}, {"sp": "N", "t": "Εὐριπίδης δέ·<br>(ὦ Ζεῦ,) τί δῆτα τοὺς ταλαιπώρους βροτοὺς φρονεῖν λέγουσι; σοῦ γὰρ ἐξηρτήμεθα δρῶμέν τε τοιάδ’ ἃ ’ν σὺ τυγχάνῃς θέλων.", "st": "9.71b"}, {"sp": "N", "t": "Οὐ μὴν ἀλλὰ καὶ Ξενοφάνης καὶ Ζήνων ὁ Ἐλεάτης καὶ Δημόκριτος κατ’ αὐτοὺς σκεπτικοὶ τυγχάνουσιν· ἐν οἷς Ξενοφάνης μέν φησι,<br>καὶ τὸ μὲν οὖν σαφὲς οὔτις ἀνὴρ ἴδεν οὐδέ τις ἔσται εἰδώς.", "st": "9.72"}, {"sp": "N", "t": "Ζήνων δὲ τὴν κίνησιν ἀναιρεῖ λέγων, τὸ κινούμενον οὔτ’ ἐν ᾧ ἐστι τόπῳ κινεῖται οὔτ’ ἐν ᾧ μὴ ἔστι· Δημόκριτος δὲ τὰς ποιότητας ἐκβάλλων, ἵνα φησί, νόμῳ ψυχρόν, νόμῳ θερμόν, ἐτεῇ δὲ ἄτομα καὶ κενόν· καὶ πάλιν, ἐτεῇ δὲ οὐδὲν ἴδμεν· ἐν βυθῷ γὰρ ἡ ἀλήθεια. καὶ Πλάτωνα τὸ μὲν ἀληθὲς θεοῖς τε καὶ θεῶν παισὶν ἐκχωρεῖν, τὸν δ’ εἰκότα λόγον ζητεῖν. καὶ Εὐριπίδην λέγειν· τίς δ’ οἶδεν εἰ τὸ ζῆν μέν ἐστι κατθανεῖν, τὸ κατθανεῖν δὲ ζῆν νομίζεται βροτοῖς;", "st": "9.73"}, {"sp": "N", "t": "ἀλλὰ καὶ Ἐμπεδοκλέα·<br>οὕτως οὔτ’ ἐπιδερκτὰ τάδ’ ἀνδράσιν οὔτ’ ἐπακουστὰ οὔτε νόῳ περιληπτά·<br>καὶ ἐπάνω,<br>αὐτὸ μόνον πεισθέντες ὅτῳ προσέκυρσεν ἕκαστος·", "st": "9.73b"}, {"sp": "N", "t": "ἔτι μὴν Ἡράκλειτον, μὴ εἰκῆ περὶ τῶν μεγίστων συμβαλλώμεθα· καὶ Ἱπποκράτην [ἔπειτα] ἐνδοιαστῶς καὶ ἀνθρωπίνως ἀποφαίνεσθαι· καὶ πρὶν Ὅμηρον,<br>στρεπτὴ δὲ γλῶσσ’ ἐστὶ βροτῶν, πολέες δ’ ἔνι μῦθοι·", "st": "9.73c"}, {"sp": "N", "t": "καὶ<br>ἐπέων δὲ πολὺς νομὸς ἔνθα καὶ ἔνθα·<br>καὶ<br>ὁπποῖόν κ’ εἴπῃσθα ἔπος, τοῖόν κ’ ἐπακούσαις·", "st": "9.73d"}, {"sp": "N", "t": "τὴν ἰσοσθένειαν λέγων καὶ ἀντίθεσιν τῶν λόγων. Διετέλουν δὴ οἱ σκεπτικοὶ τὰ τῶν αἱρέσεων δόγματα πάντ’ ἀνατρέποντες, αὐτοὶ δ’ οὐδὲν ἀπεφαίνοντο δογματικῶς, ἕως δὲ τοῦ προφέρεσθαι τὰ τῶν ἄλλων καὶ διηγεῖσθαι μηδὲν ὁρίζοντες, μηδ’ αὐτὸ τοῦτο. ὥστε καὶ τὸ μὴ ὁρίζειν ἀνῄρουν, λέγοντες οἷον Οὐδὲν ὁρίζομεν, ἐπεὶ ὥριζον ἄν· προφερόμεθα δέ, φασί, τὰς ἀποφάσεις εἰς μήνυσιν τῆς ἀπροπτωσίας, ὡς, εἰ καὶ νεύσαντας, τοῦτο ἐνεδέχετο δηλῶσαι· διὰ τῆς οὖν Οὐδὲν ὁρίζομεν φωνῆς τὸ τῆς ἀρρεψίας πάθος δηλοῦται· ὁμοίως δὲ καὶ διὰ τῆς Οὐδὲν μᾶλλον καὶ τῆς Παντὶ λόγῳ λόγος ἀντίκειται καὶ τῶν ὁμοίων. λέγεται δὲ τὸ Οὐδὲν μᾶλλον καὶ θετικῶς, ὡς ὁμοίων τινῶν ὄντων· οἷον, Οὐδὲν μᾶλλον ὁ πειρατὴς κακός ἐστιν ἢ ὁ ψεύστης. ὑπὸ δὲ τῶν σκεπτικῶν οὐ θετικῶς ἀλλ’ ἀναιρετικῶς λέγεται, ὡς ὑπὸ τοῦ ἀνασκευάζοντος καὶ λέγοντος, Οὐ μᾶλλον ἡ Σκύλλα γέγονεν ἢ ἡ Χίμαιρα. αὐτὸ δὲ τὸ Μᾶλλον ποτὲ μὲν συγκριτικῶς ἐκφέρεται, ὡς ὅταν φῶμεν μᾶλλον τὸ μέλι γλυκὺ ἢ τὴν σταφίδα· ποτὲ δὲ θετικῶς καὶ ἀναιρετικῶς, ὡς ὅταν φῶμεν, Μᾶλλον ἡ ἀρετὴ ὠφελεῖ ἢ βλάπτει· σημαίνομεν γὰρ ὅτι ἡ ἀρετὴ ὠφελεῖ, βλάπτει δ’ οὔ. ἀναιροῦσι δ’ οἱ σκεπτικοὶ καὶ αὐτὴν τὴν Οὐδὲν μᾶλλον φωνήν· ὡς γὰρ οὐ μᾶλλόν ἐστι πρόνοια ἢ οὐκ ἔστιν, οὕτω καὶ τὸ Οὐδὲν μᾶλλον οὐ μᾶλλόν ἐστιν ἢ οὐκ ἔστι. σημαίνει οὖν ἡ φωνή, καθά φησι καὶ Τίμων ἐν τῷ Πύθωνι, τὸ μηδὲν ὁρίζειν, ἀλλ’ ἀπροσθετεῖν.", "st": "9.74"}, {"sp": "N", "t": "ἡ δὲ Παντὶ λόγῳ φωνὴ καὶ αὐτὴ συνάγει τὴν ἐποχήν· τῶν μὲν γὰρ πραγμάτων διαφωνούντων, τῶν δὲ λόγων ἰσοσθενούντων ἀγνωσία τῆς ἀληθείας ἐπακολουθεῖ·", "st": "9.74b"}, {"sp": "N", "t": "καὶ αὐτῷ δὲ τούτῳ τῷ λόγῳ λόγος ἀντίκειται, ὃς καὶ αὐτὸς μετὰ τὸ ἀνελεῖν τοὺς ἄλλους ὑφ’ ἑαυτοῦ περιτραπεὶς ἀπόλλυται, κατ’ ἴσον τοῖς καθαρτικοῖς, ἃ τὴν ὕλην προεκκρίναντα καὶ αὐτὰ ὑπεκκρίνεται καὶ ἐξαπόλλυται. Πρὸς ὅ φασιν οἱ δογματικοὶ * * μὴ αἴρειν τὸν λόγον, ἀλλὰ προσεπισχυρίζειν. μόνον οὖν διακόνοις ἐχρῶντο τοῖς λόγοις· οὐ γὰρ οἷόν τε ἦν μὴ λόγῳ λόγον ἀνελεῖν· καθ’ ὃν τρόπον εἰώθαμεν λέγειν τόπον μὴ εἶναι καὶ δεῖ πάντως τὸν τόπον εἰπεῖν, ἀλλ’ οὐ δογματικῶς, ἀποδεικτικῶς δέ· καὶ μηδὲν γίνεσθαι κατ’ ἀνάγκην καὶ δεῖ τὴν ἀνάγκην εἰπεῖν. τοιούτῳ τινὶ τρόπῳ τῆς ἑρμηνείας ἐχρῶντο· οἷα γὰρ φαίνεται τὰ πράγματα, μὴ τοιαῦτα εἶναι τῇ φύσει, ἀλλὰ μόνον φαίνεσθαι· ζητεῖν τ’ ἔλεγον οὐχ ἅπερ νοοῦσιν, ὅ τι γὰρ νοεῖται δῆλον, ἀλλ’ ὧν ταῖς αἰσθήσεσι μετίσχουσιν.", "st": "9.77"}, {"sp": "N", "t": "Ἔστιν οὖν ὁ Πυρρώνειος λόγος μήνυσίς τις τῶν φαινομένων ἢ τῶν ὁπωσοῦν νοουμένων, καθ’ ἣν πάντα πᾶσι συμβάλλεται καὶ συγκρινόμενα πολλὴν ἀνωμαλίαν καὶ ταραχὴν ἔχοντα εὑρίσκεται, καθά φησιν Αἰνεσίδημος ἐν τῇ εἰς τὰ Πυρρώνεια ὑποτυπώσει. πρὸς δὲ τὰς ἐν ταῖς σκέψεσιν ἀντιθέσεις προαποδεικνύντες καθ’ οὓς τρόπους πείθει τὰ πράγματα, κατὰ τοὺς αὐτοὺς ἀνῄρουν τὴν περὶ αὐτῶν πίστιν· πείθειν γὰρ τά τε κατ’ αἴσθησιν συμφώνως ἔχοντα καὶ τὰ μηδέποτε ἢ σπανίως γοῦν μεταπίπτοντα τά τε συνήθη καὶ τὰ νόμοις διεσταλμένα καὶ τὰ τέρποντα καὶ τὰ θαυμαζόμενα. ἐδείκνυσαν οὖν ἀπὸ τῶν ἐναντίων τοῖς πείθουσιν ἴσας τὰς πιθανότητας.", "st": "9.78"}, {"sp": "N", "t": "Αἱ δ’ ἀπορίαι κατὰ τὰς συμφωνίας τῶν φαινομένων ἢ νοουμένων, ἃς ἀπεδίδοσαν, ἦσαν κατὰ δέκα τρόπους, καθ’ οὓς τὰ ὑποκείμενα παραλλάττοντα ἐφαίνετο. τούτους δὲ τοὺς δέκα τρόπους τίθησιν.", "st": "9.78b"}, {"sp": "N", "t": "[Εἷς] πρῶτος ὁ παρὰ τὰς διαφορὰς τῶν ζῴων πρὸς ἡδονὴν καὶ ἀλγηδόνα καὶ βλάβην καὶ ὠφέλειαν. συνάγεται δὲ δι’ αὐτοῦ τὸ μὴ τὰς αὐτὰς ἀπὸ τῶν αὐτῶν προσπίπτειν φαντασίας καὶ τὸ διότι τῇ τοιαύτῃ μάχῃ ἀκολουθεῖ τὸ ἐπέχειν· τῶν γὰρ ζῴων τὰ μὲν χωρὶς μίξεως γίνεσθαι, ὡς τὰ πυρίβια καὶ ὁ Ἀράβιος φοῖνιξ καὶ εὐλαί· τὰ δ’ ἐξ ἐπιπλοκῆς, ὡς ἄνθρωποι καὶ τὰ ἄλλα· καὶ τὰ μὲν οὕτως, τὰ δ’ οὕτως συγκέκριται· διὸ καὶ τῇ αἰσθήσει διαφέρει, ὡς κίρκοι μὲν ὀξύτατοι, κύνες δ’ ὀσφρητικώτατοι. εὔλογον οὖν τοῖς διαφόροις τοὺς ὀφθαλμοὺς διάφορα καὶ τὰ φαντάσματα προσπίπτειν· καὶ τῇ μὲν αἰγὶ τὸν θαλλὸν εἶναι ἐδώδιμον, ἀνθρώπῳ δὲ πικρόν, καὶ τὸ κώνειον ὄρτυγι μὲν τρόφιμον, ἀνθρώπῳ δὲ θανάσιμον, καὶ ὁ ἀπόπατος ὑῒ μὲν ἐδώδιμος, ἵππῳ δ’ οὔ.", "st": "9.80"}, {"sp": "N", "t": "Δεύτερος ὁ παρὰ τὰς τῶν ἀνθρώπων φύσεις καὶ τὰς ἰδιοσυγκρισίας· Δημοφῶν γοῦν ὁ Ἀλεξάνδρου τραπεζοκόμος ἐν σκιᾷ ἐθάλπετο, ἐν ἡλίῳ δ’ ἐρρίγου. Ἄνδρων δ’ ὁ Ἀργεῖος, ὥς φησιν Ἀριστοτέλης, διὰ τῆς ἀνύδρου Λιβύης ὥδευεν ἄποτος. καὶ ὁ μὲν ἰατρικῆς, ὁ δὲ γεωργίας, ἄλλος δ’ ἐμπορίας ὀρέγεται· καὶ ταὐτὰ οὓς μὲν βλάπτει, οὓς δὲ ὠφελεῖ·", "st": "9.81"}, {"sp": "N", "t": "ὅθεν ἐφεκτέον. Τρίτος ὁ παρὰ τὰς τῶν αἰσθητικῶν πόρων διαφοράς. τὸ γοῦν μῆλον ὁράσει μὲν ὠχρόν, γεύσει δὲ γλυκύ, ὀσφρήσει δ’ εὑῶδες ὑποπίπτει. καὶ ἡ αὐτὴ δὲ μορφὴ παρὰ τὰς διαφορὰς τῶν κατόπτρων ἀλλοία θεωρεῖται. ἀκολουθεῖ οὖν μὴ μᾶλλον εἶναι τοῖον τὸ φαινόμενον ἢ ἀλλοῖον.", "st": "9.81b"}, {"sp": "N", "t": "Τέταρτος ὁ παρὰ τὰς διαθέσεις καὶ κοινῶς παραλλαγάς, οἷον ὑγίειαν, νόσον, ὕπνον, ἐγρήγορσιν, χαράν, λύπην, νεότητα, γῆρας, θάρσος, φόβον, ἔνδειαν, πλήρωσιν, μῖσος, φιλίαν, θερμασίαν, ψύξιν· παρὰ τὸ πνεῖν, παρὰ τὸ πιεσθῆναι τοὺς πόρους. ἀλλοῖα οὖν φαίνεται τὰ προσπίπτοντα παρὰ τὰς ποιὰς διαθέσεις. οὐδὲ γὰρ οἱ μαινόμενοι παρὰ φύσιν ἔχουσι· τί γὰρ μᾶλλον ἐκεῖνοι ἢ ἡμεῖς; καὶ γὰρ ἡμεῖς τὸν ἥλιον ὡς ἑστῶτα βλέπομεν. Θέων δ’ ὁ Τιθοραιεὺς ὁ στωικὸς κοιμώμενος περιεπάτει ἐν τῷ ὕπνῳ καὶ Περικλέους δοῦλος ἐπ’ ἄκρου τοῦ τέγους.", "st": "9.82"}, {"sp": "N", "t": "Πέμπτος ὁ παρὰ τὰς ἀγωγὰς καὶ τοὺς νόμους καὶ τὰς μυθικὰς πίστεις καὶ τὰς ἐθνικὰς συνθήκας καὶ δογματικὰς ὑπολήψεις. ἐν τούτῳ περιέχεται τὰ περὶ καλῶν καὶ αἰσχρῶν, περὶ ἀληθῶν καὶ ψευδῶν, περὶ ἀγαθῶν καὶ κακῶν, περὶ θεῶν καὶ γενέσεως καὶ φθορᾶς τῶν φαινομένων πάντων. τὸ γοῦν αὐτὸ παρ’ οἷς μὲν δίκαιον, παρ’ οἷς δὲ ἄδικον· καὶ ἄλλοις μὲν ἀγαθόν, ἄλλοις δὲ κακόν. Πέρσαι μὲν γὰρ οὐκ ἄτοπον ἡγοῦνται θυγατρὶ μίγνυσθαι, Ἕλληνες δ’ ἔκθεσμον. καὶ Μασσαγέται μέν, ὥς φησι καὶ Εὔδοξος ἐν τῇ πρώτῃ τῆς Περιόδου, κοινὰς ἔχουσι τὰς γυναῖκας, Ἕλληνες δ’ οὔ· Κίλικές τε λῃστείαις ἔχαιρον, ἀλλ’ οὐχ Ἕλληνες. θεούς τ’ ἄλλοι ἄλλους ἡγοῦνται· καὶ οἱ μὲν προνοεῖσθαι, οἱ δ’ οὔ. θάπτουσι δ’ Αἰγύπτιοι μὲν ταριχεύοντες, Ῥωμαῖοι δὲ καίοντες, Παίονες δ’ εἰς λίμνας ῥιπτοῦντες·", "st": "9.83"}, {"sp": "N", "t": "ὅθεν περὶ τἀληθοῦς ἡ ἐποχή. Ἕκτος ὁ παρὰ τὰς μίξεις καὶ κοινωνίας, καθ’ ὃν εἰλικρινῶς οὐδὲν καθ’ αὑτὸ φαίνεται, ἀλλὰ σὺν ἀέρι, σὺν φωτί, σὺν ὑγρῷ, σὺν στερεῷ, θερμότητι, ψυχρότητι, κινήσει, ἀναθυμιάσεσιν, ἄλλαις δυνάμεσιν. ἡ γοῦν πορφύρα διάφορον ὑποφαίνει χρῶμα ἐν ἡλίῳ καὶ σελήνῃ καὶ λύχνῳ. καὶ τὸ ἡμέτερον χρῶμα ἀλλοῖον ὑπὸ τὴν μεσημβρίαν φαίνεται καὶ ὑπὸ δύσιν· καὶ ὁ ἐν ἀέρι ὑπὸ δυοῖν κουφιζόμενος λίθος ἐν ὕδατι ῥᾳδίως μετατίθεται, ἤτοι βαρὺς ὢν καὶ ὑπὸ τοῦ ὕδατος κουφιζόμενος ἢ ἐλαφρὸς [ὢν] καὶ ὑπὸ τοῦ ἀέρος βαρυνόμενος. ἀγνοοῦμεν οὖν τὸ κατ’ ἰδίαν, ὡς ἔλαιον ἐν μύρῳ.", "st": "9.85"}, {"sp": "N", "t": "Ἕβδομος ὁ παρὰ τὰς ἀποστάσεις καὶ ποιὰς θέσεις καὶ τοὺς τόπους καὶ τὰ ἐν τοῖς τόποις. κατὰ τοῦτον τὸν τρόπον τὰ δοκοῦντ’ εἶναι μεγάλα μικρὰ φαίνεται, τὰ τετράγωνα στρογγύλα, τὰ ὁμαλὰ ἐξοχὰς ἔχοντα, τὰ ὀρθὰ κεκλασμένα, τὰ ὠχρὰ ἑτερόχροα. ὁ γοῦν ἥλιος παρὰ τὸ διάστημα μικρὸς φαίνεται· καὶ τὰ ὄρη πόρρωθεν ἀεροειδῆ καὶ λεῖα, ἐγγύθεν δὲ τραχέα. ἔτι ὁ ἥλιος ἀνίσχων μὲν ἀλλοῖος, μεσουρανῶν δ’ οὐχ ὅμοιος. καὶ τὸ αὐτὸ σῶμα ἐν μὲν ἄλσει ἀλλοῖον, ἐν δὲ ψιλῇ γῇ ἕτερον· καὶ ἡ εἰκὼν παρὰ τὴν ποιὰν θέσιν, ὅ τε τῆς περιστερᾶς τράχηλος παρὰ τὴν στροφήν. ἐπεὶ οὖν οὐκ ἔνι ἔξω τόπων καὶ θέσεων ταῦτα κατανοῆσαι, ἀγνοεῖται ἡ φύσις αὐτῶν.", "st": "9.86"}, {"sp": "N", "t": "Ὄγδοος ὁ παρὰ τὰς ποσότητας καὶ ποιότητας αὐτῶν ἢ θερμότητας ἢ ψυχρότητας ἢ ταχύτητας ἢ βραδύτητας ἢ ὠχρότητας ἢ ἑτεροχροιότητας. ὁ γοῦν οἶνος μέτριος μὲν ληφθεὶς ῥώννυσι, πλείων δὲ παρίησιν· ὁμοίως καὶ ἡ τροφὴ καὶ τὰ ὅμοια.", "st": "9.86b"}, {"sp": "N", "t": "Ἔνατος ὁ παρὰ τὸ ἐνδελεχὲς ἢ ξένον ἢ σπάνιον. οἱ γοῦν σεισμοὶ παρ’ οἷς συνεχῶς ἀποτελοῦνται οὐ θαυμάζονται, οὐδ’ ὁ ἥλιος, ὅτι καθ’ ἡμέραν ὁρᾶται.", "st": "9.87"}, {"sp": "N", "t": "τὸν ἔνατον Φαβωρῖνος ὄγδοον, Σέξτος δὲ καὶ Αἰνεσίδημος δέκατον· ἀλλὰ καὶ τὸν δέκατον Σέξτος ὄγδοόν φησι, Φαβωρῖνος δὲ ἔνατον.", "st": "9.87b"}, {"sp": "N", "t": "Δέκατος ὁ κατὰ τὴν πρὸς ἄλλα σύμβλησιν, καθάπερ τὸ κοῦφον παρὰ τὸ βαρύ, τὸ ἰσχυρὸν παρὰ τὸ ἀσθενές, τὸ μεῖζον παρὰ τὸ ἔλαττον, τὸ ἄνω παρὰ τὸ κάτω. τὸ γοῦν δεξιὸν φύσει μὲν οὐκ ἔστι δεξιόν, κατὰ δὲ τὴν ὡς πρὸς τὸ ἕτερον σχέσιν νοεῖται· μετατεθέντος γοῦν ἐκείνου, οὐκέτ’ ἐστὶ δεξιόν. ὁμοίως καὶ πατὴρ καὶ ἀδελφὸς ὡς πρός τι καὶ ἡμέρα ὡς πρὸς τὸν ἥλιον καὶ πάντα ὡς πρὸς τὴν διάνοιαν. ἄγνωστα οὖν τὰ πρός τι [ὡς] καθ’ ἑαυτά.", "st": "9.88"}, {"sp": "N", "t": "καὶ οὗτοι μὲν οἱ δέκα τρόποι. Οἱ δὲ περὶ Ἀγρίππαν τούτοις ἄλλους πέντε προσεισάγουσι, τόν τ’ ἀπὸ τῆς διαφωνίας καὶ τὸν εἰς ἄπειρον ἐκβάλλοντα καὶ τὸν πρός τι καὶ τὸν ἐξ ὑποθέσεως καὶ τὸν δι’ ἀλλήλων.", "st": "9.88b"}, {"sp": "N", "t": "ὁ μὲν οὖν ἀπὸ τῆς διαφωνίας ὃ ἂν προτεθῇ ζήτημα παρὰ τοῖς φιλοσόφοις ἢ τῇ συνηθείᾳ, πλείστης μάχης καὶ ταραχῆς πλῆρες ἀποδεικνύει·", "st": "9.88c"}, {"sp": "N", "t": "ὁ δ’ εἰς ἄπειρον ἐκβάλλων οὐκ ἐᾷ βεβαιοῦσθαι τὸ ζητούμενον, διὰ τὸ ἄλλο ἀπ’ ἄλλου τὴν πίστιν λαμβάνειν καὶ οὕτως εἰς ἄπειρον.", "st": "9.88d"}, {"sp": "N", "t": "ὁ δὲ πρός τι οὐδέν φησι καθ’ ἑαυτὸ λαμβάνεσθαι, ἀλλὰ μεθ’ ἑτέρου.", "st": "9.89"}, {"sp": "N", "t": "ὅθεν ἄγνωστα εἶναι. ὁ δ’ ἐξ ὑποθέσεως τρόπος συνίσταται, οἰομένων τινῶν τὰ πρῶτα τῶν πραγμάτων αὐτόθεν δεῖν λαμβάνειν ὡς πιστὰ καὶ μὴ αἰτεῖσθαι· ὅ ἐστι μάταιον· τὸ ἐναντίον γάρ τις ὑποθήσεται.", "st": "9.89b"}, {"sp": "N", "t": "ὁ δὲ δι’ ἀλλήλων τρόπος συνίσταται ὅταν τὸ ὀφεῖλον τοῦ ζητουμένου πράγματος εἶναι βεβαιωτικὸν χρείαν ἔχῃ τῆς ἐκ τοῦ ζητουμένου πίστεως, οἷον εἰ τὸ εἶναι πόρους τις βεβαιῶν διὰ τὸ ἀπορροίας γίνεσθαι, αὐτὸ τοῦτο παραλαμβάνοι πρὸς βεβαίωσιν το〈ῦ〉 ἀπορροίας γίνεσθαι.", "st": "9.89c"}, {"sp": "N", "t": "Ἀνῄρουν δ’ οὗτοι καὶ πᾶσαν ἀπόδειξιν καὶ κριτήριον καὶ σημεῖον καὶ αἴτιον καὶ κίνησιν καὶ μάθησιν καὶ γένεσιν καὶ τὸ φύσει τι εἶναι ἀγαθὸν ἢ κακόν. πᾶσα γὰρ ἀπόδειξις, φασίν, ἢ ἐξ ἀποδεδειγμένων σύγκειται χρημάτων ἢ ἐξ ἀναποδείκτων. εἰ μὲν οὖν ἐξ ἀποδεδειγμένων, κἀκεῖνα δεήσεταί τινος ἀποδείξεως κἀντεῦθεν εἰς ἄπειρον· εἰ δ’ ἐξ ἀναποδείκτων, ἤτοι πάντων ἢ τινῶν ἢ καὶ ἑνὸς μόνου δισταζομένου, καὶ τὸ ὅλον εἶναι ἀναπόδεικτον. εἰ δὲ δοκεῖ, φασίν, ὑπάρχειν τινὰ μηδεμιᾶς ἀποδείξεως δεόμενα, θαυμαστοὶ τῆς γνώμης, εἰ μὴ συνιᾶσιν ὅτι εἰς αὐτὸ τοῦτο πρῶτον, ὡς ἄρ’ ἐξ αὑτῶν ἔχει τὴν πίστιν, ἀποδείξεως χρή. οὐδὲ γὰρ τὸ τέτταρα εἶναι τὰ στοιχεῖα ἐκ τοῦ τέτταρα εἶναι τὰ στοιχεῖα βεβαιωτέον.", "st": "9.90"}, {"sp": "N", "t": "πρὸς τῷ καὶ τῶν κατὰ μέρος ἀποδείξεων ἀπιστουμένων ἄπιστον εἶναι καὶ τὴν γενικὴν ἀπόδειξιν. ἵνα τε γνῶμεν ὅτι ἔστιν ἀπόδειξις, κριτηρίου δεῖ· καὶ ὅτι ἔστι κριτήριον, ἀποδείξεως δεῖ· ὅθεν ἑκάτερα ἀκατάληπτα ἀναπεμπόμενα ἐπ’ ἄλληλα.", "st": "9.90b"}, {"sp": "N", "t": "πῶς ἂν οὖν καταλαμβάνοιτο τὰ ἄδηλα, τῆς ἀποδείξεως ἀγνοουμένης; ζητεῖται δ’ οὐκ εἰ φαίνεται τοιαῦτα, ἀλλ’ εἰ καθ’ ὑπόστασιν οὕτως ἔχει.", "st": "9.90c"}, {"sp": "N", "t": "Εὐήθεις δὲ τοὺς δογματικοὺς ἀπέφαινον. τὸ γὰρ ἐξ ὑποθέσεως περαινόμενον οὐ σκέψεως ἀλλὰ θέσεως ἔχει λόγον. τοιούτῳ δὲ λόγῳ καὶ ὑπὲρ ἀδυνάτων ἔστιν ἐπιχειρεῖν. τοὺς δ’ οἰομένους μὴ δεῖν ἐκ τῶν κατὰ περίστασιν κρίνειν τἀληθὲς μηδ’ ἐκ τῶν κατὰ φύσιν νομοθετεῖν, ἔλεγον αὐτοὺς μέτρα τῶν πάντων ὁρίζειν, οὐχ ὁρῶντας ὅτι πᾶν τὸ φαινόμενον κατ’ ἀντιπερίστασιν καὶ διάθεσιν φαίνεται. ἤτοι γοῦν πάντ’ ἀληθῆ ῥητέον ἢ πάντα ψευδῆ. εἰ δ’ ἔνιά ἐστιν ἀληθῆ, τίνι διακριτέον; οὔτε γὰρ αἰσθήσει τὰ κατ’ αἴσθησιν, πάντων ἴσων αὐτῇ φαινομένων, οὔτε νοήσει διὰ τὴν αὐτὴν αἰτίαν. ἄλλη δὲ παρὰ ταύτας εἰς ἐπίκρισιν δύναμις οὐχ ὁρᾶται. ὁ οὖν, φασί, περί τινος διαβεβαιούμενος αἰσθητοῦ ἢ νοητοῦ πρότερον ὀφείλει τὰς περὶ τούτου δόξας καταστῆσαι· οἱ μὲν γὰρ ταῦτα, οἱ δὲ ταῦτα ἀνῃρήκασι. δεῖ δ’ ἢ δι’ αἰσθητοῦ ἢ νοητοῦ κριθῆναι. ἑκάτερα δὲ ἀμφισβητεῖται. οὐδὲ τοίνυν δυνατὸν τὰς περὶ αἰσθητῶν ἢ νοητῶν ἐπικρῖναι δόξας· εἴ τε διὰ τὴν ἐν ταῖς νοήσεσι μάχην ἀπιστητέον πᾶσιν, ἀναιρεθήσεται τὸ μέτρον ᾧ δοκεῖ τὰ πάντα διακριβοῦσθαι·", "st": "9.92"}, {"sp": "N", "t": "πᾶν οὖν ἴσον ἡγήσονται. ἔτι, φασίν, ὁ συζητῶν ἡμῖν τὸ φαινόμενον πιστός ἐστιν ἢ οὔ. εἰ μὲν οὖν πιστός ἐστιν, οὐδὲν ἕξει λέγειν πρὸς τὸν ᾧ φαίνεται τοὐναντίον· ὡς γὰρ αὐτὸς πιστός ἐστι τὸ φαινόμενον λέγων, οὕτω καὶ ὁ ἐναντίος· εἰ δ’ ἄπιστος, καὶ αὐτὸς ἀπιστηθήσεται τὸ φαινόμενον λέγων. Τό τε πεῖθον οὐχ ὑποληπτέον ἀληθὲς ὑπάρχειν. οὐ γὰρ πάντας τὸ αὐτὸ πείθει οὐδὲ τοὺς αὐτοὺς συνεχές. γίνεται δὲ καὶ παρὰ τὰ ἐκτὸς ἡ πιθανότης, παρὰ τὸ ἔνδοξον τοῦ λέγοντος ἢ παρὰ τὸ φροντιστικὸν ἢ παρὰ τὸ αἱμύλον ἢ παρὰ τὸ σύνηθες ἢ παρὰ τὸ κεχαρισμένον.", "st": "9.94"}, {"sp": "N", "t": "Ἀνῄρουν δὲ καὶ τὸ κριτήριον λόγῳ τοιῷδε. ἤτοι κέκριται καὶ τὸ κριτήριον ἢ ἄκριτόν ἐστιν. ἀλλ’ εἰ μὲν ἄκριτόν ἐστιν, ἄπιστον καθέστηκε καὶ διημάρτηκε τἀληθοῦς καὶ τοῦ ψεύδους· εἰ δὲ κέκριται, ἓν τῶν κατὰ μέρος γενήσεται κρινομένων, ὥστ’ ἂν τὸ αὐτὸ καὶ κρίνειν καὶ κρίνεσθαι καὶ τὸ κεκρικὸς τὸ κριτήριον ὑφ’ ἑτέρου κριθήσεται κἀκεῖνο ὑπ’ ἄλλου καὶ οὕτως εἰς ἄπειρον. πρὸς τῷ καὶ διαφωνεῖσθαι τὸ κριτήριον, τῶν μὲν τὸν ἄνθρωπον κριτήριον εἶναι λεγόντων, τῶν δὲ τὰς αἰσθήσεις, ἄλλων τὸν λόγον, ἐνίων τὴν καταληπτικὴν φαντασίαν.", "st": "9.95"}, {"sp": "N", "t": "καὶ ὁ μὲν ἄνθρωπος καὶ πρὸς αὑτὸν διαφωνεῖ καὶ πρὸς τοὺς ἄλλους, ὡς δῆλον ἐκ τῶν διαφόρων νόμων καὶ ἐθῶν. αἱ δ’ αἰσθήσεις ψεύδονται, ὁ δὲ λόγος διάφωνος. ἡ δὲ καταληπτικὴ φαντασία ὑπὸ νοῦ κρίνεται καὶ ὁ νοῦς ποικίλως τρέπεται. ἄγνωστον οὖν ἐστι τὸ κριτήριον καὶ διὰ τοῦτο ἡ ἀλήθεια.", "st": "9.95b"}, {"sp": "N", "t": "Σημεῖόν τ’ οὐκ εἶναι· εἰ γάρ ἐστι, φασί, σημεῖον, ἤτοι αἰσθητόν ἐστιν ἢ νοητόν· αἰσθητὸν μὲν οὖν οὐκ ἔστιν, ἐπεὶ τὸ αἰσθητὸν κοινόν ἐστι, τὸ δὲ σημεῖον ἴδιον. καὶ τὸ μὲν αἰσθητὸν τῶν κατὰ διαφοράν, τὸ δὲ σημεῖον τῶν πρός τι. νοητὸν δ’ οὐκ ἔστιν, ἐπεὶ τὸ νοητὸν ἤτοι φαινόμενόν ἐστι φαινομένου ἢ ἀφανὲς ἀφανοῦς ἢ ἀφανὲς φαινομένου ἢ φαινόμενον ἀφανοῦς· οὐδὲν δὲ τούτων ἐστίν· οὐκ ἄρ’ ἐστὶ σημεῖον.", "st": "9.96"}, {"sp": "N", "t": "φαινόμενον μὲν οὖν φαινομένου οὐκ ἔστιν, ἐπεὶ τὸ φαινόμενον οὐ δεῖται σημείου· ἀφανὲς δ’ ἀφανοῦς οὐκ ἔστιν, ἐπεὶ δεῖ φαίνεσθαι τὸ ἐκκαλυπτόμενον ὑπό τινος· ἀφανὲς δὲ φαινομένου οὐ δύναται, καθότι δεῖ φαίνεσθαι τὸ ἑτέρῳ παρέξον ἀφορμὴν καταλήψεως· φαινόμενον δ’ ἀφανοῦς οὐκ ἔστιν, ὅτι τὸ σημεῖον τῶν πρός τι ὂν συγκαταλαμβάνεσθαι ὀφείλει τῷ οὗ ἐστι σημεῖον, τὸ δὲ μὴ ἔστιν. οὐδὲν ἄρα τῶν ἀδήλων ἂν καταλαμβάνοιτο· διὰ γὰρ τῶν σημείων λέγεται τὰ ἄδηλα καταλαμβάνεσθαι.", "st": "9.97"}, {"sp": "N", "t": "Ἀναιροῦσι δὲ τὸ αἴτιον ὧδε· τὸ αἴτιον τῶν πρός τι ἔστι· πρὸς γὰρ τὸ αἰτιατόν ἐστι· τὰ δὲ πρός τι ἐπινοεῖται μόνον, ὑπάρχει δ’ οὔ· καὶ τὸ αἴτιον οὖν ἐπινοοῖτ’ ἂν μόνον, ἐπεὶ εἴπερ ἐστὶν αἴτιον, ὀφείλει ἔχειν τὸ οὗ λέγεται αἴτιον, ἐπεὶ οὐκ ἔσται αἴτιον. καὶ ὥσπερ ὁ πατήρ, μὴ παρόντος τοῦ πρὸς ὃ λέγεται πατήρ, οὐκ ἂν εἴη πατήρ, οὑτωσὶ καὶ τὸ αἴτιον· οὐ πάρεστι δὲ πρὸς ὃ νοεῖται τὸ αἴτιον· οὔτε γὰρ γένεσις οὔτε φθορὰ οὔτ’ ἄλλο τι· οὐκ ἄρ’ ἐστὶν αἴτιον. καὶ μὴν εἰ ἔστιν αἴτιον, ἤτοι σῶμα σώματός ἐστιν αἴτιον ἢ ἀσώματον ἀσωμάτου· οὐδὲν δὲ τούτων· οὐκ ἄρ’ ἐστὶν αἴτιον. σῶμα μὲν οὖν σώματος οὐκ ἂν εἴη αἴτιον, ἐπείπερ ἀμφότερα τὴν αὐτὴν ἔχει φύσιν. καὶ εἰ τὸ ἕτερον αἴτιον λέγεται παρ’ ὅσον ἐστὶ σῶμα, καὶ τὸ λοιπόν, σῶμα ὄν, αἴτιον γενήσεται. κοινῶς δ’ ἀμφοτέρων αἰτίων ὄντων, οὐδὲν ἔσται τὸ πάσχον.", "st": "9.98"}, {"sp": "N", "t": "ἀσώματον δ’ ἀσωμάτου οὐκ ἂν εἴη αἴτιον διὰ τὸν αὐτὸν λόγον· ἀσώματον δὲ σώματος οὐκ ἔστιν αἴτιον, ἐπεὶ οὐδὲν ἀσώματον ποιεῖ σῶμα. σῶμα δ’ ἀσωμάτου οὐκ ἂν εἴη αἴτιον, ὅτι τὸ γενόμενον τῆς πασχούσης ὕλης ὀφείλει εἶναι· μηδὲν δὲ πάσχον διὰ τὸ ἀσώματον εἶναι οὐδ’ ἂν ὑπό τινος γένοιτο· οὐκ ἔστι τοίνυν αἴτιον. ᾧ συνεισάγεται τὸ ἀνυποστάτους εἶναι τὰς τῶν ὅλων ἀρχάς· δεῖ γὰρ εἶναί τι τὸ ποιοῦν καὶ δρῶν.", "st": "9.98b"}, {"sp": "N", "t": "Ἀλλὰ μὴν οὐδὲ κίνησίς ἐστι· τὸ γὰρ κινούμενον ἤτοι ἐν ᾧ ἐστι τόπῳ κινεῖται ἢ ἐν ᾧ μὴ ἔστιν· καὶ ἐν ᾧ μέν ἐστι τόπῳ οὐ κινεῖται, ἐν ᾧ δ’ οὐκ ἔστιν οὐδὲ κινεῖται· οὐκ ἔστιν οὖν κίνησις.", "st": "9.98c"}, {"sp": "N", "t": "Ἀνῄρουν δὲ καὶ μάθησιν. εἴπερ, φασί, διδάσκεταί τι, ἤτοι τὸ ὂν τῷ εἶναι διδάσκεται ἢ τὸ μὴ ὂν τῷ μὴ εἶναι. οὔτε δὲ τὸ ὂν τῷ εἶναι διδάσκεται —ἡ γὰρ τῶν ὄντων φύσις πᾶσι φαίνεται καὶ γινώσκεται—οὔτε τὸ μὴ ὂν τῷ μὴ ὄντι· τῷ γὰρ μὴ ὄντι οὐδὲν συμβέβηκεν, ὥστ’ οὐδὲ τὸ διδάσκεσθαι.", "st": "9.100"}, {"sp": "N", "t": "Οὐδὲ μὴν γένεσίς ἐστι, φασίν. οὔτε γὰρ τὸ ὂν γίνεται, ἔστι γάρ, οὔτε τὸ μὴ ὄν, οὐδὲ γὰρ ὑφέστηκε· τὸ δὲ μὴ ὑφεστὼς μηδ’ ὂν οὐδὲ τὸ γίνεσθαι εὐτύχηκε.", "st": "9.100b"}, {"sp": "N", "t": "Φύσει τε μὴ εἶναι ἀγαθὸν ἢ κακόν· εἰ γάρ τί ἐστι φύσει ἀγαθὸν καὶ κακόν, πᾶσιν ὀφείλει ἀγαθὸν ἢ κακὸν ὑπάρχειν, ὥσπερ ἡ χιὼν πᾶσι ψυχρόν· κοινὸν δ’ οὐδὲν πάντων ἀγαθὸν ἢ κακόν ἐστιν· οὐκ ἄρα ἐστὶ φύσει ἀγαθὸν ἢ κακόν. ἤτοι γὰρ πᾶν τὸ ὑπό τινος δοξαζόμενον ῥητέον ἀγαθὸν ἢ οὐ πᾶν· καὶ πᾶν μὲν οὐ ῥητέον, ἐπεὶ τὸ αὐτὸ ὑφ’ οὗ μὲν δοξάζεται ἀγαθόν, ὡς ἡ ἡδονὴ ὑπὸ Ἐπικούρου· ὑφ’ οὗ δὲ κακόν, ὑπ’ Ἀντισθένους. συμβήσεται τοίνυν τὸ αὐτὸ ἀγαθόν τ’ εἶναι καὶ κακόν. εἰ δ’ οὐ πᾶν λέγομεν τὸ ὑπό τινος δοξαζόμενον ἀγαθόν, δεήσει ἡμᾶς διακρίνειν τὰς δόξας· ὅπερ οὐκ ἐνδεχόμενόν ἐστι διὰ τὴν ἰσοσθένειαν τῶν λόγων. ἄγνωστον οὖν τὸ φύσει ἀγαθόν.", "st": "9.101"}, {"sp": "N", "t": "Ἔστι δὲ καὶ τὸν ὅλον τῆς συναγωγῆς αὐτῶν τρόπον συνιδεῖν ἐκ τῶν ἀπολειφθεισῶν συντάξεων. αὐτὸς μὲν γὰρ ὁ Πύρρων οὐδὲν ἀπέλιπεν, οἱ μέντοι συνήθεις αὐτοῦ Τίμων καὶ Αἰνεσίδημος καὶ Νουμήνιος καὶ Ναυσιφάνης καὶ ἄλλοι τοιοῦτοι. Οἷς ἀντιλέγοντες οἱ δογματικοί φασιν αὐτοὺς καταλαμβάνεσθαι καὶ δογματίζειν· ἐν ᾧ γὰρ δοκοῦσι διελέγχειν καταλαμβάνονται· καὶ γὰρ ἐν τῷ αὐτῷ κρατύνουσι καὶ δογματίζουσι. καὶ γὰρ ὅτε φασὶ μηδὲν ὁρίζειν καὶ παντὶ λόγῳ λόγον ἀντικεῖσθαι, αὐτὰ ταῦτα καὶ ὁρίζονται καὶ δογματίζουσι. πρὸς οὓς ἀποκρίνονται, Περὶ μὲν ὧν ὡς ἄνθρωποι πάσχομεν, ὁμολογοῦμεν· καὶ γὰρ ὅτι ἡμέρα ἐστὶ καὶ ὅτι ζῶμεν καὶ ἄλλα πολλὰ τῶν ἐν τῷ βίῳ φαινομένων διαγινώσκομεν· περὶ δ’ ὧν οἱ δογματικοὶ διαβεβαιοῦνται τῷ λόγῳ, φάμενοι κατειλῆφθαι, περὶ τούτων ἐπέχομεν ὡς ἀδήλων, μόνα δὲ τὰ πάθη γινώσκομεν. τὸ μὲν γὰρ ὅτι ὁρῶμεν ὁμολογοῦμεν καὶ τὸ ὅτι τόδε νοοῦμεν γινώσκομεν, πῶς δ’ ὁρῶμεν ἢ πῶς νοοῦμεν ἀγνοοῦμεν· καὶ ὅτι τόδε λευκὸν φαίνεται διηγηματικῶς λέγομεν, οὐ διαβεβαιούμενοι ὅτι καὶ ὄντως ἐστί. περὶ δὲ τῆς Οὐδὲν ὁρίζω φωνῆς καὶ τῶν ὁμοίων λέγομεν ὡς οὐ δογμάτων· οὐ γάρ εἰσιν ὅμοια τῷ λέγειν ὅτι σφαιροειδής ἐστιν ὁ κόσμος. ἀλλὰ γὰρ τὸ μὲν ἄδηλον, αἱ δ’ ἐξομολογήσεις εἰσί.", "st": "9.102"}, {"sp": "N", "t": "ἐν ᾧ οὖν λέγομεν μηδὲν ὁρίζειν, οὐδ’ αὐτὸ τοῦτο ὁρίζομεν.", "st": "9.102b"}, {"sp": "N", "t": "Πάλιν οἱ δογματικοί φασιν καὶ τὸν βίον αὐτοὺς ἀναιρεῖν, ἐν ᾧ πάντ’ ἐκβάλλουσιν ἐξ ὧν ὁ βίος συνέστηκεν. οἱ δὲ ψεύδεσθαί φασιν αὐτούς· οὐ γὰρ τὸ ὁρᾶν ἀναιρεῖν, ἀλλὰ τὸ πῶς ὁρᾶν ἀγνοεῖν. καὶ γὰρ τὸ φαινόμενον τιθέμεθα, οὐχ ὡς καὶ τοιοῦτον ὄν. καὶ ὅτι τὸ πῦρ καίει αἰσθανόμεθα· εἰ δὲ φύσιν ἔχει καυστικὴν ἐπέχομεν. καὶ ὅτι κινεῖταί τις βλέπομεν, καὶ ὅτι φθείρεται πῶς δὲ ταῦτα γίνεται οὐκ ἴσμεν. μόνον οὖν, φασίν, ἀνθιστάμεθα πρὸς τὰ παρυφιστάμενα τοῖς φαινομένοις ἄδηλα. καὶ γὰρ ὅτε τὴν εἰκόνα ἐξοχὰς λέγομεν ἔχειν, τὸ φαινόμενον διασαφοῦμεν· ὅταν δ’ εἴπωμεν μὴ ἔχειν αὐτὴν ἐξοχάς, οὐκέτι ὃ φαίνεται, ἕτερον δὲ λέγομεν· ὅθεν καὶ ὁ Τίμων ἐν τῷ Πύθωνί φησι μὴ ἐκβεβηκέναι τὴν συνήθειαν. καὶ ἐν τοῖς Ἰνδαλμοῖς οὕτω λέγει,<br>ἀλλὰ τὸ φαινόμενον πάντη σθένει οὗπερ ἂν ἔλθῃ.", "st": "9.105"}, {"sp": "N", "t": "καὶ ἐν τοῖς Περὶ αἰσθήσεών φησι, τὸ μέλι ὅτι ἐστὶ γλυκὺ οὐ τίθημι, τὸ δ’ ὅτι φαίνεται ὁμολογῶ. Καὶ Αἰνεσίδημος ἐν τῷ πρώτῳ τῶν Πυρρωνείων λόγων οὐδέν φησιν ὁρίζειν τὸν Πύρρωνα δογματικῶς διὰ τὴν ἀντιλογίαν, τοῖς δὲ φαινομένοις ἀκολουθεῖν. ταὐτὰ δὲ λέγει κἀν τῷ Κατὰ σοφίας κἀν τῷ Περὶ ζητήσεως.", "st": "9.106"}, {"sp": "N", "t": "ἀλλὰ καὶ Ζεῦξις ὁ Αἰνεσιδήμου γνώριμος ἐν τῷ Περὶ διττῶν λόγων καὶ Ἀντίοχος ὁ Λαοδικεὺς καὶ Ἀπελλᾶς ἐν τῷ Ἀγρίππᾳ τιθέασι τὰ φαινόμενα μόνα. ἔστιν οὖν κριτήριον κατὰ τοὺς σκεπτικοὺς τὸ φαινόμενον, ὡς καὶ Αἰνεσίδημός φησιν·", "st": "9.106b"}, {"sp": "N", "t": "οὕτω δὲ καὶ Ἐπίκουρος. Δημόκριτος δὲ μηδὲν εἶναι τῶν φαινομένων, τὰ δὲ μὴ εἶναι. πρὸς τοῦτο τὸ κριτήριον τῶν φαινομένων οἱ δογματικοί φασιν ὅτι ὅτ’ ἀπὸ τῶν αὐτῶν διάφοροι προσπίπτουσι φαντασίαι, ὡς ἀπὸ τοῦ πύργου ἢ στρογγύλου ἢ τετραγώνου, ὁ σκεπτικὸς εἰ μὲν οὐδετέραν προκρινεῖ, ἀπρακτήσει· εἰ δὲ τῇ ἑτέρᾳ κατακολουθήσει, οὐκέτι τὸ ἰσοσθενές, φασί, τοῖς φαινομένοις ἀποδώσει. πρὸς οὓς οἱ σκεπτικοί φασιν ὅτι ὅτε προσπίπτουσιν ἀλλοῖαι φαντασίαι, ἑκατέρας ἐροῦμεν φαίνεσθαι· καὶ διὰ τοῦτο τὰ φαινόμενα τιθέναι ὅτι φαίνεται.", "st": "9.107"}, {"sp": "N", "t": "τέλος δὲ οἱ σκεπτικοί φασι τὴν ἐποχήν, ᾗ σκιᾶς τρόπον ἐπακολουθεῖ ἡ ἀταραξία, ὥς φασιν οἵ τε περὶ τὸν Τίμωνα καὶ Αἰνεσίδημον· οὔτε γὰρ τάδ’ ἑλούμεθα ἢ ταῦτα φευξόμεθα ὅσα περὶ ἡμᾶς ἐστι· τὰ δ’ ὅσα περὶ ἡμᾶς οὐκ ἔστιν, ἀλλὰ κατ’ ἀνάγκην, οὐ δυνάμεθα φεύγειν, ὡς τὸ πεινῆν καὶ διψῆν καὶ ἀλγεῖν· οὐκ ἔστι γὰρ λόγῳ περιελεῖν ταῦτα.", "st": "9.108"}, {"sp": "N", "t": "λεγόντων δὲ τῶν δογματικῶν ὡς δυνήσεται βιοῦν ὁ σκεπτικὸς μὴ φεύγων τό, εἰ κελευσθείη, κρεουργεῖν τὸν πατέρα, φασὶν οἱ σκεπτικοὶ ὡς δυνήσεται βιοῦν 〈ὥστε〉 * * περὶ τῶν δογματικῶν ζητήσεων ἐπέχειν, οὐ περὶ τῶν βιωτικῶν καὶ τηρητικῶν. ὥστε καὶ αἱρούμεθά τι κατὰ τὴν συνήθειαν καὶ φεύγομεν καὶ νόμοις χρώμεθα.", "st": "9.108b"}, {"sp": "N", "t": "τινὲς δὲ καὶ τὴν ἀπάθειαν, ἄλλοι δὲ τὴν πρᾳότητα τέλος εἰπεῖν φασι τοὺς σκεπτικούς.", "st": "9.108c"}, {"sp": "HDR", "t": "ΤΙΜΩΝ"}, {"sp": "N", "t": "Ἀπολλωνίδης ὁ Νικαεὺς ὁ παρ’ ἡμῶν ἐν τῷ πρώτῳ τῶν Εἰς τοὺς Σίλλους ὑπομνήματι, ἃ προσφωνεῖ Τιβερίῳ Καίσαρι, φησὶ τὸν Τίμωνα εἶναι πατρὸς μὲν Τιμάρχου, Φλιάσιον δὲ τὸ γένος· νέον δὲ καταλειφθέντα χορεύειν, ἔπειτα καταγνόντα ἀποδημῆσαι εἰς Μέγαρα πρὸς Στίλπωνα· κἀκείνῳ συνδιατρίψαντα αὖθις ἐπανελθεῖν οἴκαδε καὶ γῆμαι. εἶτα πρὸς Πύρρωνα εἰς Ἦλιν ἀποδημῆσαι μετὰ τῆς γυναικὸς κἀκεῖ διατρίβειν ἕως αὐτῷ παῖδες ἐγένοντο, ὧν τὸν μὲν πρεσβύτερον Ξάνθον ἐκάλεσε καὶ ἰατρικὴν ἐδίδαξε καὶ διάδοχον τοῦ βίου κατέλιπε. ὁ δ’ ἐλλόγιμος ἦν, ὡς καὶ Σωτίων ἐν τῷ ἑνδεκάτῳ φησίν. ἀπορῶν μέντοι τροφῶν ἀπῆρεν εἰς τὸν Ἑλλήσποντον καὶ τὴν Προποντίδα· ἐν Χαλκηδόνι τε σοφιστεύων ἐπὶ πλέον ἀποδοχῆς ἠξιώθη· ἐντεῦθέν τε πορισάμενος ἀπῆρεν εἰς Ἀθήνας, κἀκεῖ διέτριβε μέχρι καὶ τελευτῆς, ὀλίγον χρόνον εἰς Θήβας διαδραμών. ἐγνώσθη δὲ καὶ Ἀντιγόνῳ τῷ βασιλεῖ καὶ Πτολεμαίῳ τῷ Φιλαδέλφῳ, ὡς αὐτὸς ἐν τοῖς ἰάμβοις αὑτῷ μαρτυρεῖ.", "st": "9.109"}, {"sp": "N", "t": "Ἦν δέ, φησὶν ὁ Ἀντίγονος, καὶ φιλοπότης καὶ ἀπὸ τῶν φιλοσόφων εἰ σχολάζοι ποιήματα συνέγραφε καὶ ἔπη καὶ τραγῳδίας καὶ σατύρους καὶ δράματα κωμικὰ τριάκοντα, τὰ δὲ τραγικὰ ἑξήκοντα, σίλλους τε καὶ κιναίδους.", "st": "9.109b"}, {"sp": "N", "t": "φέρεται δ’ αὐτοῦ καὶ καταλογάδην βιβλία εἰς ἐπῶν τείνοντα μυριάδας δύο, ὧν καὶ Ἀντίγονος ὁ Καρύστιος μέμνηται, ἀναγεγραφὼς αὐτοῦ καὶ αὐτὸς τὸν βίον. τῶν δὲ σίλλων τρία ἐστίν, ἐν οἷς ὡς ἂν σκεπτικὸς ὢν πάντας λοιδορεῖ καὶ σιλλαίνει τοὺς δογματικοὺς ἐν παρῳδίας εἴδει. ὧν τὸ μὲν πρῶτον αὐτοδιήγητον ἔχει τὴν ἑρμηνείαν, τὸ δὲ δεύτερον καὶ τρίτον ἐν διαλόγου σχήματι. φαίνεται γοῦν ἀνακρίνων Ξενοφάνην τὸν Κολοφώνιον περὶ ἑκάστων, ὁ δ’ αὐτῷ διηγούμενός ἐστι· καὶ ἐν μὲν τῷ δευτέρῳ περὶ τῶν ἀρχαιοτέρων, ἐν δὲ τῷ τρίτῳ περὶ τῶν ὑστέρων· ὅθεν δὴ αὐτῷ τινες καὶ Ἐπίλογον ἐπέγραψαν.", "st": "9.111"}, {"sp": "N", "t": "τὸ δὲ πρῶτον ταὐτὰ περιέχει πράγματα, πλὴν ὅτι μονοπρόσωπός ἐστιν ἡ ποίησις· ἀρχὴ δὲ αὐτῷ ἥδε,<br>ἕσπετε νῦν μοι ὅσοι πολυπράγμονές ἐστε σοφισταί.", "st": "9.112"}, {"sp": "N", "t": "Ἐτελεύτησε δ’ ἐγγὺς ἐτῶν ἐνενήκοντα, ὥς φησιν ὁ Ἀντίγονος καὶ Σωτίων ἐν τῷ ἑνδεκάτῳ. τοῦτον ἐγὼ καὶ ἑτερόφθαλμον ἤκουσα, ἐπεὶ καὶ αὐτὸς αὑτὸν Κύκλωπα ἐκάλει.", "st": "9.112b"}, {"sp": "N", "t": "γέγονε καὶ ἕτερος Τίμων ὁ μισάνθρωπος.", "st": "9.112c"}, {"sp": "N", "t": "Ὁ δ’ οὖν φιλόσοφος καὶ φιλόκηπος ἦν σφόδρα καὶ ἰδιοπράγμων, ὡς καὶ Ἀντίγονός φησι. λόγος γοῦν εἰπεῖν Ἱερώνυμον τὸν περιπατητικὸν ἐπ’ αὐτοῦ, Ὡς παρὰ τοῖς Σκύθαις καὶ οἱ φεύγοντες τοξεύουσι καὶ οἱ διώκοντες, οὕτω τῶν φιλοσόφων οἱ μὲν διώκοντες θηρῶσι τοὺς μαθητάς, οἱ δὲ φεύγοντες, καθάπερ καὶ ὁ Τίμων.", "st": "9.112d"}, {"sp": "N", "t": "Ἦν δὲ καὶ ὀξὺς νοῆσαι καὶ διαμυκτηρίσαι· φιλογράμματός τε καὶ τοῖς ποιηταῖς μύθους γράψαι ἱκανὸς καὶ δράματα συνδιατιθέναι. μετεδίδου δὲ τῶν τραγῳδιῶν Ἀλεξάνδρῳ καὶ Ὁμήρῳ. θορυβούμενός θ’ ὑπὸ τῶν θεραπαινῶν καὶ κυνῶν ἐποίει μηδέν, σπουδάζων περὶ τὸ ἠρεμάζειν. φασὶ δὲ καὶ Ἄρατον πυθέσθαι αὐτοῦ πῶς τὴν Ὁμήρου ποίησιν ἀσφαλῆ κτήσαιτο, τὸν δὲ εἰπεῖν, εἰ τοῖς ἀρχαίοις ἀντιγράφοις ἐντυγχάνοι καὶ μὴ τοῖς ἤδη διωρθωμένοις. εἰκῆ τε αὐτῷ ἔκειτο τὰ ποιήματα, ἐνίοτε ἡμίβρωτα· ὥστε καὶ Ζωπύρῳ τῷ ῥήτορι ἀναγινώσκοντά τι ἐπιτυλίττειν καὶ κατὰ τὸ ἐπελθὸν διεξιέναι· ἐλθόντα τ’ ἐφ’ ἡμισείας, οὕτως εὑρεῖν τὸ ἀπόσπασμα τέως ἀγνοοῦντα. τοσοῦτον ἦν ἀδιάφορος. ἀλλὰ καὶ εὔρους·", "st": "9.113"}, {"sp": "N", "t": "ὡς μηδ’ ἀριστᾶν συγχωρεῖν. φασὶ δ’ αὐτὸν Ἀρκεσίλαον θεασάμενον διὰ τῶν Κερκώπων ἰόντα, εἰπεῖν, τί σὺ δεῦρο, ἔνθαπερ ἡμεῖς οἱ ἐλεύθεροι; συνεχές τε ἐπιλέγειν εἰώθει πρὸς τοὺς τὰς αἰσθήσεις μετ’ ἐπιμαρτυροῦντος τοῦ νοῦ ἐγκρίνοντας,<br>συνῆλθεν Ἀτταγᾶς τε καὶ Νουμήνιος.", "st": "9.113b"}, {"sp": "N", "t": "εἰώθει δὲ καὶ παίζειν τοιαῦτα. πρὸς οὖν τὸν θαυμάζοντα πάντα ἔφη, τί δ’ οὐ θαυμάζεις ὅτι τρεῖς ὄντες τέτταρας ἔχομεν ὀφθαλμούς; ἦν δ’ αὐτός τε ἑτερόφθαλμος καὶ ὁ Διοσκουρίδης μαθητὴς αὐτοῦ, καὶ ὁ πρὸς ὃν ἔλεγεν ὑγιής. ἐρωτηθεὶς δέ ποθ’ ὑπὸ τοῦ Ἀρκεσιλάου διὰ τί παρείη ἐκ Θηβῶν, ἔφη, ἵν’ ὑμᾶς ἀναπεπταμένους ὁρῶν γελῶ. ὅμως δὲ καθαπτόμενος Ἀρκεσιλάου ἐν τοῖς σίλλοις ἐπῄνεκεν αὐτὸν ἐν τῷ ἐπιγραφομένῳ Ἀρκεσιλάου περιδείπνῳ.", "st": "9.115"}, {"sp": "N", "t": "Τούτου διάδοχος, ὡς μὲν Μηνόδοτός φησι, γέγονεν οὐδείς, ἀλλὰ διέλιπεν ἡ ἀγωγὴ ἕως αὐτὴν Πτολεμαῖος ὁ Κυρηναῖος ἀνεκτήσατο. ὡς δ’ Ἱππόβοτός φησι καὶ Σωτίων, διήκουσαν αὐτοῦ Διοσκουρίδης Κύπριος καὶ Νικόλοχος Ῥόδιος καὶ Εὐφράνωρ Σελευκεὺς Πραΰλους τ’ ἀπὸ Τρωάδος, ὃς οὕτω καρτερικὸς ἐγένετο, καθά φησι Φύλαρχος ἱστορῶν, ὥστ’ ἀδίκως ὑπομεῖναι ὡς ἐπὶ προδοσίᾳ κολασθῆναι, μηδὲ λόγου τοὺς πολίτας καταξιώσας. Εὐφράνορος δὲ διήκουσεν Εὔβουλος Ἀλεξανδρεύς, οὗ Πτολεμαῖος, οὗ Σαρπηδὼν καὶ Ἡρακλείδης, Ἡρακλείδου δ’ Αἰνεσίδημος Κνώσιος, ὃς καὶ Πυρρωνείων λόγων ὀκτὼ συνέγραψε βιβλία· οὗ Ζεύξιππος ὁ πολίτης, οὗ Ζεῦξις ὁ Γωνιόπους, οὗ Ἀντίοχος Λαοδικεὺς ἀπὸ Λύκου· τούτου δὲ Μηνόδοτος ὁ Νικομηδεύς, ἰατρὸς ἐμπειρικός, καὶ Θειωδᾶς Λαοδικεύς· Μηνοδότου δὲ Ἡρόδοτος Ἀριέως Ταρσεύς· Ἡροδότου δὲ διήκουσε Σέξτος ὁ ἐμπειρικός, οὗ καὶ τὰ δέκα τῶν Σκεπτικῶν καὶ ἄλλα κάλλιστα· Σέξτου δὲ διήκουσε Σατορνῖνος ὁ Κυθηνᾶς, ἐμπειρικὸς καὶ αὐτός.", "st": "9.116"}, {"sp": "HDR", "t": "Βιβλίον Ι"}, {"sp": "HDR", "t": "ΕΠΙΚΟΥΡΟΣ"}, {"sp": "N", "t": "Ἐπίκουρος Νεοκλέους καὶ Χαιρεστράτης, Ἀθηναῖος, τῶν δήμων Γαργήττιος, γένους τοῦ τῶν Φιλαϊδῶν, ὥς φησι Μητρόδωρος ἐν τῷ Περὶ εὐγενείας. τοῦτόν φασιν ἄλλοι τε καὶ Ἡρακλείδης ἐν τῇ Σωτίωνος ἐπιτομῇ κληρουχησάντων Ἀθηναίων τὴν Σάμον ἐκεῖθι τραφῆναι· ὀκτωκαιδεκέτη δ’ ἐλθεῖν εἰς Ἀθήνας, Ξενοκράτους μὲν ἐν Ἀκαδημείᾳ, Ἀριστοτέλους δ’ ἐν Χαλκίδι διατρίβοντος. τελευτήσαντος δὲ Ἀλεξάνδρου τοῦ Μακεδόνος καὶ τῶν Ἀθηναίων ἐκπεσόντων ὑπὸ Περδίκκου μετελθεῖν εἰς Κολοφῶνα πρὸς τὸν πατέρα·", "st": "10.1"}, {"sp": "N", "t": "χρόνον δέ τινα διατρίψαντα αὐτόθι καὶ μαθητὰς ἀθροίσαντα πάλιν ἐπανελθεῖν εἰς Ἀθήνας ἐπὶ Ἀναξικράτους· καὶ μέχρι μέν τινος κατ’ ἐπιμιξίαν τοῖς ἄλλοις φιλοσοφεῖν, ἔπειτα ἰδίᾳ ἀπο〈φαίνεσθαι〉 τὴν ἀπ’ αὐτοῦ κληθεῖσαν αἵρεσιν συστήσαντα. ἐφάψασθαι δὲ φιλοσοφίας αὐτός φησιν ἔτη γεγονὼς τετταρεσκαίδεκα. Ἀπολλόδωρος δ’ ὁ Ἐπικούρειος ἐν τῷ πρώτῳ περὶ τοῦ Ἐπικούρου βίου φησὶν ἐλθεῖν αὐτὸν ἐπὶ φιλοσοφίαν καταγνόντα τῶν γραμματιστῶν, ἐπειδὴ μὴ ἐδυνήθησαν ἑρμηνεῦσαι αὐτῷ τὰ περὶ τοῦ παρ’ Ἡσιόδῳ χάους.", "st": "10.2"}, {"sp": "N", "t": "φησὶ δ’ Ἕρμιππος γραμματοδιδάσκαλον αὐτὸν γεγενῆσθαι, ἔπειτα μέντοι περιτυχόντα τοῖς Δημοκρίτου βιβλίοις ἐπὶ φιλοσοφίαν ᾆξαι· διὸ καὶ τὸν Τίμωνα φάσκειν περὶ αὐτοῦ·<br>ὕστατος αὖ φυσικῶν καὶ κύντατος, ἐκ Σάμου ἐλθὼν γραμμαδιδασκαλίδης, ἀναγωγότατος ζωόντων.", "st": "10.3"}, {"sp": "N", "t": "Συνεφιλοσόφουν δ’ αὐτῷ προτρεψαμένῳ καὶ οἱ ἀδελφοὶ τρεῖς ὄντες, Νεοκλῆς Χαιρέδημος Ἀριστόβουλος, καθά φησι Φιλόδημος ὁ Ἐπικούρειος ἐν τῷ δεκάτῳ τῆς τῶν φιλοσόφων συντάξεως· ἀλλὰ καὶ δοῦλος Μῦς ὄνομα, καθά φησι Μυρωνιανὸς ἐν Ὁμοίοις ἱστορικοῖς κεφαλαίοις.", "st": "10.3b"}, {"sp": "N", "t": "Διότιμος δ’ ὁ Στωικὸς δυσμενῶς ἔχων πρὸς αὐτὸν πικρότατα αὐτὸν διαβέβληκεν, ἐπιστολὰς φέρων πεντήκοντα ἀσελγεῖς ὡς Ἐπικούρου· καὶ ὁ τὰ εἰς Χρύσιππον ἀναφερόμενα ἐπιστόλια ὡς Ἐπικούρου συντάξας. ἀλλὰ καὶ οἱ περὶ Ποσειδώνιον τὸν στωικὸν καὶ Νικόλαος καὶ Σωτίων ἐν τῷ δωδεκάτῳ τῶν ἐπιγραφομένων Διοκλείων ἐλέγχων, ἅ ἐστι δ’ πρὸς τοῖς κ’, καὶ Διονύσιος ὁ Ἁλικαρνασσεύς. καὶ γὰρ σὺν τῇ μητρὶ περιιόντα αὐτὸν ἐς τὰ οἰκίδια καθαρμοὺς ἀναγινώσκειν, καὶ σὺν τῷ πατρὶ γράμματα διδάσκειν λυπροῦ τινος μισθαρίου. ἀλλὰ καὶ τῶν ἀδελφῶν ἕνα προαγωγεύειν, Λεοντίῳ καὶ συνεῖναι τῇ ἑταίρᾳ. τὰ δὲ Δημοκρίτου περὶ τῶν ἀτόμων καὶ Ἀριστίππου περὶ τῆς ἡδονῆς ὡς ἴδια λέγειν〈·〉 μὴ εἶναί τε γνησίως ἀστόν, ὡς Τιμοκράτης φησὶ καὶ Ἡρόδοτος ἐν τῷ Περὶ Ἐπικούρου ἐφηβείας.", "st": "10.4"}, {"sp": "N", "t": "Μιθρῆν τε αἰσχρῶς κολακεύειν τὸν Λυσιμάχου διοικητήν, ἐν ταῖς ἐπιστολαῖς Παιᾶνα καὶ ἄνακτα καλοῦντα· ἀλλὰ καὶ Ἰδομενέα καὶ Ἡρόδοτον καὶ Τιμοκράτην τοὺς ἔκπυστα αὐτοῦ τὰ κρύφια ποιήσαντας ἐγκωμιάζειν καὶ κολακεύειν αὐτὸ τοῦτο. ἔν τε ταῖς ἐπιστολαῖς πρὸς μὲν Λεόντιον Παιὰν ἄναξ, φίλον Λεοντάριον, οἵου κροτοθορύβου ἡμᾶς ἐνέπλησας ἀναγνόντας σου τὸ ἐπιστόλιον· πρὸς δὲ Θεμίσταν τὴν Λεοντέως γυναῖκα Οἷός τε φησίν εἰμί, ἐὰν μὴ ὑμεῖς πρός με ἀφίκησθε, αὐτὸς τρικύλιστος, ὅπου ἂν ὑμεῖς καὶ Θεμίστα παρακαλῆτε, ὠθεῖσθαι. πρὸς δὲ Πυθοκλέα ὡραῖον ὄντα Καθεδοῦμαι φησὶ προσδοκῶν τὴν ἱμερτὴν καὶ ἰσόθεόν σου εἴσοδον. καὶ πάλιν πρὸς Θεμίσταν γράφων νομίζειν αὐτῇ παραινεῖν, καθά φησι Θεόδωρος ἐν τῷ τετάρτῳ τῶν Πρὸς Ἐπίκουρον.", "st": "10.5"}, {"sp": "N", "t": "καὶ ἄλλαις δὲ πολλαῖς ἑταίραις γράφειν, καὶ μάλιστα Λεοντίῳ, ἧς καὶ Μητρόδωρον ἐρασθῆναι. ἔν τε τῷ Περὶ τέλους γράφειν οὕτως· Οὐ γὰρ ἔγωγε ἔχω τί νοήσω τἀγαθόν, ἀφαιρῶν μὲν τὰς διὰ χυλῶν ἡδονάς, ἀφαιρῶν δὲ τὰς δι’ ἀφροδισίων καὶ τὰς δι’ ἀκροαμάτων καὶ τὰς διὰ μορφῆς. ἔν τε τῇ πρὸς Πυθοκλέα ἐπιστολῇ γράφειν Παιδείαν δὲ πᾶσαν, μακάριε, φεῦγε τἀκάτιον ἀράμενος.", "st": "10.6"}, {"sp": "N", "t": "Ἐπίκτητός τε κιναιδολόγον αὐτὸν καλεῖ καὶ τὰ μάλιστα λοιδορεῖ. Καὶ μὴν καὶ Τιμοκράτης ἐν τοῖς ἐπιγραφομένοις Εὐφραντοῖς ὁ Μητροδώρου μὲν ἀδελφός, μαθητὴς δὲ αὐτοῦ τῆς σχολῆς ἐκφοιτήσας φησὶ δὶς αὐτὸν τῆς ἡμέρας ἐμεῖν ἀπὸ τρυφῆς, ἑαυτόν τε διηγεῖται μόγις ἐκφυγεῖν ἰσχῦσαι τὰς νυκτερινὰς ἐκείνας φιλοσοφίας καὶ τὴν μυστικὴν ἐκείνην συνδιαγωγήν. τόν τε Ἐπίκουρον πολλὰ κατὰ τὸν λόγον ἠγνοηκέναι καὶ πολὺ μᾶλλον κατὰ τὸν βίον, τό τε σῶμα ἐλεεινῶς διακεῖσθαι, ὡς πολλῶν ἐτῶν μὴ δύνασθαι ἀπὸ τοῦ φορείου διαναστῆναι· μνᾶν τε ἀναλίσκειν ἡμερησίαν εἰς τὴν τράπεζαν, ὡς αὐτὸς ἐν τῇ πρὸς Λεόντιον ἐπιστολῇ γράφει καὶ ἐν τῇ πρὸς τοὺς ἐν Μυτιλήνῃ φιλοσόφους. συνεῖναί τε αὐτῷ τε καὶ Μητροδώρῳ ἑταίρας καὶ ἄλλας, Μαμμάριον καὶ Ἡδεῖαν καὶ Ἐρώτιον καὶ Νικίδιον.", "st": "10.7"}, {"sp": "N", "t": "καὶ ἐν ταῖς ἑπτὰ καὶ τριάκοντα βίβλοις ταῖς Περὶ φύσεως τὰ πλεῖστα ταὐτὰ λέγειν καὶ ἀντιγράφειν ἐν αὐταῖς ἄλλοις τε καὶ Ναυσιφάνει τὰ πλεῖστα καὶ αὐτῇ λέξει φάσκειν οὕτως· Ἀλλ’ ἴτωσαν· εἶχε γὰρ ἐκεῖνος ὠδίνων τὴν ἀπὸ τοῦ στόματος καύχησιν τὴν σοφιστικήν, καθάπερ καὶ ἄλλοι πολλοὶ τῶν ἀνδραπόδων. καὶ αὐτὸν Ἐπίκουρον ἐν ταῖς ἐπιστολαῖς περὶ Ναυσιφάνους λέγειν· Ταῦτα ἤγαγεν αὐτὸν εἰς ἔκστασιν τοιαύτην, ὥστε μοι λοιδορεῖσθαι καὶ ἀποκαλεῖν διδάσκαλον. πλεύμονά τε αὐτὸν ἐκάλει καὶ ἀγράμματον καὶ ἀπατεῶνα καὶ πόρνην· τούς τε περὶ Πλάτωνα Διονυσοκόλακας καὶ αὐτὸν Πλάτωνα χρυσοῦν, καὶ Ἀριστοτέλη ἄσωτον, 〈ὃν〉 καταφαγόντα τὴν πατρῴαν οὐσίαν στρατεύεσθαι καὶ φαρμακοπωλεῖν· φορμοφόρον τε Πρωταγόραν καὶ γραφέα Δημοκρίτου καὶ ἐν κώμαις γράμματα διδάσκειν· Ἡράκλειτόν τε κυκητὴν καὶ Δημόκριτον Ληρόκριτον καὶ Ἀντίδωρον Σαννίδωρον· τούς τε Κυνικοὺς ἐχθροὺς τῆς Ἑλλάδος· καὶ τοὺς διαλεκτικοὺς πολυφθόρους, Πύρρωνα δ’ ἀμαθῆ καὶ ἀπαίδευτον.", "st": "10.8"}, {"sp": "N", "t": "Μεμήνασι δ’ οὗτοι. τῷ γὰρ ἀνδρὶ μάρτυρες ἱκανοὶ τῆς ἀνυπερβλήτου πρὸς πάντας εὐγνωμοσύνης ἥ τε πατρὶς χαλκαῖς εἰκόσι τιμήσασα οἵ τε φίλοι τοσοῦτοι τὸ πλῆθος ὡς μηδ’ ἂν πόλεσιν ὅλαις μετρεῖσθαι δύνασθαι· οἵ τε γνώριμοι πάντες ταῖς δογματικαῖς αὐτοῦ σειρῆσι προσκατασχεθέντες, πλὴν Μητροδώρου τοῦ Στρατονικέως πρὸς Καρνεάδην ἀποχωρήσαντος, τάχα βαρυνθέντος ταῖς ἀνυπερβλήτοις αὐτοῦ χρηστότησιν· ἥ τε διαδοχή, πασῶν σχεδὸν ἐκλιπουσῶν τῶν ἄλλων, ἐσαεὶ διαμένουσα καὶ νηρίθμους ἀρχὰς ἀπολύουσα ἄλλην ἐξ ἄλλης τῶν γνωρίμων· ἥ τε πρὸς τοὺς γονέας εὐχαριστία καὶ ἡ πρὸς τοὺς ἀδελφοὺς εὐποιία πρός τε τοὺς οἰκέτας ἡμερότης, ὡς δῆλον κἀκ τῶν διαθηκῶν αὐτοῦ καὶ ὅτι αὐτοὶ συνεφιλοσόφουν αὐτῷ, ὧν ἦν ἐνδοξότατος ὁ προειρημένος Μῦς· καθόλου τε ἡ πρὸς πάντας αὐτοῦ φιλανθρωπία.", "st": "10.9"}, {"sp": "N", "t": "τῆς μὲν γὰρ πρὸς θεοὺς ὁσιότητος καὶ πρὸς πατρίδα φιλίας ἄλεκτος ἡ διάθεσις· ὑπερβολῇ γὰρ ἐπιεικείας οὐδὲ πολιτείας ἥψατο. καὶ χαλεπωτάτων δὲ καιρῶν κατασχόντων τηνικάδε τὴν Ἑλλάδα, αὐτόθι καταβιῶναι, δὶς ἢ τρὶς τοὺς περὶ τὴν Ἰωνίαν τόπους πρὸς τοὺς φίλους διαδραμόντα. οἳ καὶ πανταχόθεν πρὸς αὐτὸν ἀφικνοῦντο καὶ συνεβίουν αὐτῷ ἐν τῷ κήπῳ, καθά φησι καὶ Ἀπολλόδωρος· ὃν καὶ ὀγδοήκοντα μνῶν πρίασθαι.", "st": "10.9b"}, {"sp": "N", "t": "Διοκλῆς δ’ ἐν τῇ τρίτῃ τῆς ἐπιδρομῆς φησιν εὐτελέστατα καὶ λιτότατα διαιτώμενοι. κοτύλῃ γοῦν, φησίν, οἰνιδίου ἠρκοῦντο, τὸ δὲ πᾶν ὕδωρ ἦν αὐτοῖς ποτόν. τόν τ’ Ἐπίκουρον μὴ ἀξιοῦν εἰς τὸ κοινὸν κατατίθεσθαι τὰς οὐσίας, καθάπερ τὸν Πυθαγόραν κοινὰ τὰ φίλων λέγοντα· ἀπιστούντων γὰρ εἶναι τὸ τοιοῦτον· εἰ δ’ ἀπίστων οὐδὲ φίλων. αὐτός τέ φησιν ἐν ταῖς ἐπιστολαῖς, ὕδατι μόνον ἀρκεῖσθαι καὶ ἄρτῳ λιτῷ. καί, πέμψον μοι τυροῦ, φησί, κυθριδίου, ἵν’ ὅταν βούλωμαι πολυτελεύσασθαι δύνωμαι. τοιοῦτος ἦν ὁ τὴν ἡδονὴν εἶναι τέλος δογματίζων, ὃν καὶ Ἀθήναιος δι’ ἐπιγράμματος οὕτως ὑμνεῖ· ἄνθρωποι, μοχθεῖτε τὰ χείρονα, καὶ διὰ κέρδος ἄπληστοι νεικέων ἄρχετε καὶ πολέμων· τᾶς φύσιος δ’ ὁ πλοῦτος ὅρον τινὰ βαιὸν ἐπίσχει, αἱ δὲ κεναὶ κρίσιες τὰν ἀπέραντον ὁδόν. τοῦτο Νεοκλῆος πινυτὸν τέκος ἢ παρὰ Μουσέων ἔκλυεν ἢ Πυθοῦς ἐξ ἱερῶν τριπόδων.", "st": "10.11"}, {"sp": "N", "t": "εἰσόμεθα δὲ καὶ μᾶλλον προϊόντες ἔκ τε τῶν δογμάτων ἔκ τε τῶν ῥητῶν αὐτοῦ.", "st": "10.11b"}, {"sp": "N", "t": "Μάλιστα δ’ ἀπεδέχετο, φησὶ Διοκλῆς, τῶν ἀρχαίων Ἀναξαγόραν, καίτοι ἔν τισιν ἀντειρηκὼς αὐτῷ, καὶ Ἀρχέλαον τὸν Σωκράτους διδάσκαλον. ἐγύμναζε δέ, φησί, τοὺς γνωρίμους καὶ διὰ μνήμης ἔχειν τὰ ἑαυτοῦ συγγράμματα. Τοῦτον Ἀπολλόδωρος ἐν Χρονικοῖς Ναυσιφάνους ἀκοῦσαί φησι καὶ Πραξιφάνους· αὐτὸς δὲ οὔ φησιν, ἀλλ’ ἑαυτοῦ, ἐν τῇ πρὸς Εὐρύλοχον ἐπιστολῇ. ἀλλ’ οὐδὲ Λεύκιππόν τινα γεγενῆσθαί φησι φιλόσοφον, οὔτε αὐτὸς οὔτε Ἕρμαρχος, ὃν ἔνιοί φασι καὶ Ἀπολλόδωρος ὁ Ἐπικούρειος διδάσκαλον Δημοκρίτου γεγενῆσθαι. Δημήτριος δέ φησιν ὁ Μάγνης καὶ Ξενοκράτους αὐτὸν ἀκοῦσαι.", "st": "10.13"}, {"sp": "N", "t": "Κέχρηται δὲ λέξει κυρίᾳ κατὰ τῶν πραγμάτων, ἣν ὅτι ἰδιωτάτη ἐστίν, Ἀριστοφάνης ὁ γραμματικὸς αἰτιᾶται. σαφὴς δ’ ἦν οὕτως, ὡς καὶ ἐν τῷ Περὶ ῥητορικῆς ἀξιοῖ μηδὲν ἄλλο ἢ σαφήνειαν ἀπαιτεῖν. καὶ ἐν ταῖς ἐπιστολαῖς ἀντὶ τοῦ Χαίρειν Εὖ πράττειν καὶ Σπουδαίως ζῆν. Ἀρίστων δέ φησιν ἐν τῷ Ἐπικούρου βίῳ τὸν Κανόνα γράψαι αὐτὸν ἐκ τοῦ Ναυσιφάνους Τρίποδος, οὗ καὶ ἀκοῦσαί φησιν αὐτόν, ἀλλὰ καὶ Παμφίλου τοῦ Πλατωνικοῦ ἐν Σάμῳ.", "st": "10.14"}, {"sp": "N", "t": "ἄρξασθαί τε φιλοσοφεῖν ἐτῶν ὑπάρχοντα δυοκαίδεκα, ἀφηγήσασθαι δὲ τῆς σχολῆς ἐτῶν ὄντα δύο πρὸς τοῖς τριάκοντα. Ἐγεννήθη δέ, φησὶν Ἀπολλόδωρος ἐν Χρονικοῖς, κατὰ τὸ τρίτον ἔτος τῆς ἐνάτης καὶ ἑκατοστῆς Ὀλυμπιάδος ἐπὶ Σωσιγένους ἄρχοντος μηνὸς γαμηλιῶνος ἑβδόμῃ, ἔτεσιν ὕστερον τῆς Πλάτωνος τελευτῆς ἑπτά. ὑπάρχοντα δ’ αὐτὸν ἐτῶν δύο καὶ τριάκοντα πρῶτον ἐν Μυτιλήνῃ καὶ Λαμψάκῳ συστήσασθαι σχολὴν ἐπὶ ἔτη πέντε· ἔπειτα οὕτως εἰς Ἀθήνας μετελθεῖν καὶ τελευτῆσαι κατὰ τὸ δεύτερον ἔτος τῆς ἑβδόμης καὶ εἰκοστῆς καὶ ἑκατοστῆς Ὀλυμπιάδος ἐπὶ Πυθαράτου ἔτη βιώσαντα δύο πρὸς τοῖς ἑβδομήκοντα. τήν τε σχολὴν διαδέξασθαι Ἕρμαρχον Ἀγεμόρτου Μυτιληναῖον.", "st": "10.15"}, {"sp": "N", "t": "τελευτῆσαι δ’ αὐτὸν λίθῳ τῶν οὔρων ἐπισχεθέντων, ὥς φησι καὶ Ἕρμαρχος ἐν ἐπιστολαῖς, ἡμέρας νοσήσαντα τεσσαρεσκαίδεκα. ὅτε καί φησιν Ἕρμιππος ἐμβάντα αὐτὸν εἰς πύελον χαλκῆν κεκραμένην ὕδατι θερμῷ καὶ αἰτήσαντα ἄκρατον ῥοφῆσαι· τοῖς τε φίλοις παραγγείλαντα τῶν δογμάτων μεμνῆσθαι, οὕτω τελευτῆσαι. Καὶ ἔστιν ἡμῶν εἰς αὐτὸν οὕτω·<br>χαίρετε, καὶ μέμνησθε τὰ δόγματα· τοῦτ’ Ἐπίκουρος ὕστατον εἶπε φίλοις τοὔπος ἀποφθίμενος· θερμὴν ἐς πύελον γὰρ ἐληλύθεεν καὶ ἄκρατον ἔσπασεν, εἶτ’ Ἀΐδην ψυχρὸν ἐπεσπάσατο.", "st": "10.16"}, {"sp": "N", "t": "οὗτος μὲν ὁ βίος τἀνδρός, ἥδε 〈δὲ〉 ἡ τελευτή.", "st": "10.16b"}, {"sp": "N", "t": "Καὶ διέθετο ὧδε· “Κατὰ τάδε δίδωμι τὰ ἐμαυτοῦ πάντα Ἀμυνομάχῳ Φιλοκράτους Βατῆθεν καὶ Τιμοκράτει Δημητρίου Ποταμίῳ κατὰ τὴν ἐν τῷ Μητρῴῳ ἀναγεγραμμένην ἑκατέρῳ δόσιν, ἐφ’ ᾧ τε τὸν μὲν κῆπον καὶ τὰ προσόντα αὐτῷ παρέξουσιν Ἑρμάρχῳ Ἀγεμόρτου Μυτιληναίῳ καὶ τοῖς συμφιλοσοφοῦσιν αὐτῷ καὶ οἷς ἂν Ἕρμαρχος καταλίπῃ διαδόχοις τῆς φιλοσοφίας, ἐνδιατρίβειν κατὰ φιλοσοφίαν· καὶ ἀεὶ δὲ τοῖς φιλοσοφοῦσιν ἀπὸ ἡμῶν, ὅπως ἂν συνδιασώσωσιν Ἀμυνομάχῳ καὶ Τιμοκράτει κατὰ τὸ δυνατόν, τὴν ἐν τῷ κήπῳ διατριβὴν παρακατατίθεμαι τοῖς τ’ αὐτῶν κληρονόμοις, ἐν ᾧ ἂν τρόπῳ ἀσφαλέστατον ᾖ, ὅπως ἂν κἀκεῖνοι διατηρῶσιν τὸν κῆπον, καθάπερ καὶ αὐτοὶ οἷς ἂν οἱ ἀπὸ ἡμῶν φιλοσοφοῦντες παραδῶσιν. τὴν δ’ οἰκίαν τὴν ἐν Μελίτῃ παρεχέτωσαν Ἀμυνόμαχος καὶ Τιμοκράτης ἐνοικεῖν Ἑρμάρχῳ καὶ τοῖς μετ’ αὐτοῦ φιλοσοφοῦσιν, ἕως ἂν Ἕρμαρχος ζῇ.", "st": "10.17"}, {"sp": "N", "t": "“Ἐκ δὲ τῶν γινομένων προσόδων τῶν δεδομένων ἀφ’ ἡμῶν Ἀμυνομάχῳ καὶ Τιμοκράτει κατὰ τὸ δυνατὸν μεριζέσθωσαν μεθ’ Ἑρμάρχου σκοπούμενοι εἴς τε τὰ ἐναγίσματα τῷ τε πατρὶ καὶ τῇ μητρὶ καὶ τοῖς ἀδελφοῖς, καὶ ἡμῖν εἰς τὴν εἰθισμένην ἄγεσθαι γενέθλιον ἡμέραν ἑκάστου ἔτους τῇ προτέρᾳ δεκάτῃ τοῦ Γαμηλιῶνος, ὥσπερ καὶ εἰς τὴν γινομένην σύνοδον ἑκάστου μηνὸς ταῖς εἰκάσι τῶν συμφιλοσοφούντων ἡμῖν εἰς τὴν ἡμῶν τε καὶ Μητροδώρου 〈μνήμην〉 κατατεταγμένην. συντελείτωσαν δὲ καὶ τὴν τῶν ἀδελφῶν ἡμέραν τοῦ Ποσειδεῶνος· συντελείτωσαν δὲ καὶ τὴν Πολυαίνου τοῦ Μεταγειτνιῶνος καθάπερ καὶ ἡμεῖς.", "st": "10.18"}, {"sp": "N", "t": "“Ἐπιμελείσθωσαν δὲ καὶ Ἀμυνόμαχος καὶ Τιμοκράτης τοῦ υἱοῦ τοῦ Μητροδώρου Ἐπικούρου καὶ τοῦ υἱοῦ τοῦ Πολυαίνου, φιλοσοφούντων αὐτῶν καὶ συζώντων μεθ’ Ἑρμάρχου. ὡσαύτως δὲ τῆς θυγατρὸς τῆς Μητροδώρου τὴν ἐπιμέλειαν ποιείσθωσαν, καὶ εἰς ἡλικίαν ἐλθοῦσαν ἐκδότωσαν ᾧ ἂν Ἕρμαρχος ἕληται τῶν φιλοσοφούντων μετ’ αὐτοῦ, οὔσης αὐτῆς εὐτάκτου καὶ πειθαρχούσης Ἑρμάρχῳ. διδότωσαν δ’ Ἀμυνόμαχος καὶ Τιμοκράτης ἐκ τῶν ὑπαρχουσῶν ἡμῖν προσόδων εἰς τροφὴν τούτοις, ὅ τι ἂν αὐτοῖς κατ’ ἐνιαυτὸν ἐπιδέχεσθαι δοκῇ σκοπουμένοις μεθ’ Ἑρμάρχου. “Ποιείσθωσαν δὲ μεθ’ ἑαυτῶν καὶ Ἕρμαρχον κύριον τῶν προσόδων, ἵνα μετὰ τοῦ συγκαταγεγηρακότος ἡμῖν ἐν φιλοσοφίᾳ καὶ καταλελειμμένου ἡγεμόνος τῶν συμφιλοσοφούντων ἡμῖν ἕκαστα γίνηται. τὴν δὲ προῖκα τῷ θήλει παιδίῳ, ἐπειδὰν εἰς ἡλικίαν ἔλθῃ, μερισάτωσαν Ἀμυνόμαχος καὶ Τιμοκράτης ὅσον ἂν ἐπιδέχηται ἀπὸ τῶν ὑπαρχόντων ἀφαιροῦντες μετὰ τῆς Ἑρμάρχου γνώμης. ἐπιμελείσθωσαν δὲ καὶ Νικάνορος, καθάπερ καὶ ἡμεῖς, ἵν’ ὅσοι τῶν συμφιλοσοφούντων ἡμῖν χρείαν ἐν τοῖς ἰδίοις παρεσχημένοι καὶ τὴν πᾶσαν οἰκειότητα ἐνδεδειγμένοι συγκαταγηράσκειν μεθ’ ἡμῶν προείλοντο ἐν φιλοσοφίᾳ, μηδενὸς τῶν ἀναγκαίων ἐνδεεῖς καθεστήκωσιν παρὰ τὴν ἡμετέραν δύναμιν.", "st": "10.19"}, {"sp": "N", "t": "“Δοῦναι δὲ τὰ βιβλία τὰ ὑπάρχοντα ἡμῖν πάντα Ἑρμάρχῳ. “Ἐὰν δέ τι τῶν ἀνθρωπίνων περὶ Ἕρμαρχον γένηται πρὸ τοῦ τὰ Μητροδώρου παιδία εἰς ἡλικίαν ἐλθεῖν, δοῦναι Ἀμυνόμαχον καὶ Τιμοκράτην, ὅπως ἂν εὐτακτούντων αὐτῶν ἕκαστα γίνηται τῶν ἀναγκαίων, κατὰ τὸ δυνατὸν ἀπὸ τῶν καταλελειμμένων ὑφ’ ἡμῶν προσόδων. καὶ τῶν λοιπῶν ἁπάντων ὡς συντετάχαμεν ἐπιμελείσθωσαν, ὅπως ἂν κατὰ τὸ ἐνδεχόμενον ἕκαστα γίγνηται.", "st": "10.21"}, {"sp": "N", "t": "ἀφίημι δὲ τῶν παίδων ἐλεύθερον Μῦν, Νικίαν, Λύκωνα· ἀφίημι δὲ καὶ Φαίδριον ἐλευθερίᾳ.", "st": "10.21b"}, {"sp": "N", "t": "Ἤδη δὲ τελευτῶν γράφει πρὸς Ἰδομενέα τήνδε ἐπιστολήν·", "st": "10.22"}, {"sp": "N", "t": "“Τὴν μακαρίαν ἄγοντες καὶ ἅμα τελευταίαν ἡμέραν τοῦ βίου ἐγράφομεν ὑμῖν ταυτί. στραγγουρία τε παρηκολουθήκει καὶ δυσεντερικὰ πάθη ὑπερβολὴν οὐκ ἀπολείποντα τοῦ ἐν ἑαυτοῖς μεγέθους. ἀντιπαρετάττετο δὲ πᾶσι τούτοις τὸ κατὰ ψυχὴν χαῖρον ἐπὶ τῇ τῶν γεγονότων ἡμῖν διαλογισμῶν μνήμῃ. σὺ δ’ ἀξίως τῆς ἐκ μειρακίου παραστάσεως πρὸς ἐμὲ καὶ φιλοσοφίαν ἐπιμελοῦ τῶν παίδων Μητροδώρου.", "st": "10.22b"}, {"sp": "N", "t": "Καὶ διέθετο μὲν ὧδε. Μαθητὰς δὲ ἔσχε πολλοὺς μέν, σφόδρα δὲ ἐλλογίμους Μητρόδωρον Ἀθηναίου ἢ Τιμοκράτους καὶ Σάνδης Λαμψακηνόν· ὃς ἀφ’ οὗ τὸν ἄνδρα ἔγνω, οὐκ ἀπέστη ἀπ’ αὐτοῦ πλὴν ἓξ μηνῶν εἰς τὴν οἰκείαν, ἔπειτ’ ἐπανῆλθε. γέγονε δὲ ἀγαθὸς πάντα, καθὰ καὶ Ἐπίκουρος ἐν προηγουμέναις γραφαῖς μαρτυρεῖ καὶ ἐν τῷ τρίτῳ Τιμοκράτους. τοιοῦτος δ’ ὢν καὶ τὴν ἀδελφὴν Βατίδα ἐξέδοτο Ἰδομενεῖ, καὶ Λεόντιον τὴν Ἀττικὴν ἑταίραν ἀναλαβὼν εἶχε παλλακήν. ἦν δὲ καὶ ἀκατάπληκτος πρός τε τὰς ὀχλήσεις καὶ τὸν θάνατον, ὡς Ἐπίκουρος ἐν τῷ πρώτῳ Μητροδώρῳ φησί. φασὶ δὲ καὶ πρὸ ἑπτὰ ἐτῶν αὐτοῦ τελευτῆσαι πεντηκοστὸν τρίτον ἔτος ἄγοντα, καὶ αὐτὸς Ἐπίκουρος ἐν ταῖς προειρημέναις διαθήκαις, ὡς προαπεληλυθότος αὐτοῦ δηλονότι, ἐπισκήπτει περὶ τῆς ἐπιμελείας αὐτοῦ τῶν παίδων. ἔσχε δὲ καὶ τὸν προειρημένον εἰκαῖόν τινα ἀδελφὸν τοῦ Μητροδώρου Τιμοκράτην.", "st": "10.23"}, {"sp": "N", "t": "Βιβλία δέ ἐστι τοῦ Μητροδώρου τάδε·<br>Πρὸς τοὺς ἰατροὺς τρία.<br>Περὶ αἰσθήσεων.<br>Πρὸς Τιμοκράτην.<br>Περὶ μεγαλοψυχίας.<br>Περὶ τῆς Ἐπικούρου ἀρρωστίας.<br>Πρὸς τοὺς διαλεκτικούς.<br>Πρὸς τοὺς σοφιστὰς ἐννέα.<br>Περὶ τῆς ἐπὶ σοφίαν πορείας.<br>Περὶ τῆς μεταβολῆς.<br>Περὶ πλούτου.<br>Πρὸς Δημόκριτον.<br>Περὶ εὐγενείας.", "st": "10.24"}, {"sp": "N", "t": "Ἦν καὶ Πολύαινος Ἀθηνοδώρου Λαμψακηνός, ἐπιεικὴς καὶ φιλικός, ὡς οἱ περὶ Φιλόδημόν φασι.", "st": "10.24b"}, {"sp": "N", "t": "καὶ ὁ διαδεξάμενος αὐτὸν Ἕρμαρχος Ἀγεμόρτου Μυτιληναῖος, ἀνὴρ πατρὸς μὲν πένητος, τὰς δ’ ἀρχὰς προσέχων ῥητορικοῖς. Φέρεται καὶ τούτου βιβλία κάλλιστα τάδε· Ἐπιστολικὰ περὶ Ἐμπεδοκλέους εἴκοσι καὶ δύο.<br>Περὶ τῶν μαθημάτων.<br>Πρὸς Πλάτωνα.<br>Πρὸς Ἀριστοτέλην.<br>Ἐτελεύτα δὲ παραλύσει, γενόμενος ἱκανὸς ἀνήρ.", "st": "10.25"}, {"sp": "N", "t": "Λεοντεύς τε Λαμψακηνὸς ὁμοίως καὶ ἡ τούτου γυνὴ Θεμίστα, πρὸς ἣν καὶ γέγραφεν ὁ Ἐπίκουρος·", "st": "10.25b"}, {"sp": "N", "t": "ἔτι τε Κολώτης καὶ Ἰδομενεύς, καὶ αὐτοὶ Λαμψακηνοί. καὶ οὗτοι μὲν ἐλλόγιμοι, ὧν ἦν καὶ Πολύστρατος ὁ διαδεξάμενος Ἕρμαρχον· ὃν διεδέξατο Διονύσιος· ὃν Βασιλείδης. καὶ Ἀπολλόδωρος δ’ ὁ Κηποτύραννος γέγονεν ἐλλόγιμος, ὃς ὑπὲρ τετρακόσια συνέγραψε βιβλία· δύο τε Πτολεμαῖοι Ἀλεξανδρεῖς, ὅ τε μέλας καὶ ὁ λευκός. Ζήνων τε ὁ Σιδώνιος, ἀκροατὴς Ἀπολλοδώρου, πολυγράφος ἀνήρ· καὶ Δημήτριος ὁ ἐπικληθεὶς Λάκων· Διογένης τε ὁ Ταρσεὺς ὁ τὰς ἐπιλέκτους σχολὰς συγγράψας· καὶ Ὠρίων καὶ ἄλλοι οὓς οἱ γνήσιοι Ἐπικούρειοι σοφιστὰς ἀποκαλοῦσιν.", "st": "10.26"}, {"sp": "N", "t": "Ἦσαν δὲ καὶ ἄλλοι Ἐπίκουροι τρεῖς· ὅ τε Λεοντέως υἱὸς καὶ Θεμίστας· ἕτερος Μάγνης· τέταρτος ὁπλομάχος.", "st": "10.26b"}, {"sp": "N", "t": "Γέγονε δὲ πολυγραφώτατος ὁ Ἐπίκουρος, πάντας ὑπερβαλλόμενος πλήθει βιβλίων· κύλινδροι μὲν γὰρ πρὸς τοὺς τριακοσίους εἰσί. γέγραπται δὲ μαρτύριον ἔξωθεν ἐν αὐτοῖς οὐδέν, ἀλλ’ αὐτοῦ εἰσιν Ἐπικούρου φωναί. ἐζήλου δὲ αὐτὸν Χρύσιππος ἐν πολυγραφίᾳ, καθά φησι καὶ Καρνεάδης παράσιτον αὐτὸν τῶν βιβλίων ἀποκαλῶν· εἰ γάρ τι γράψαι ὁ Ἐπίκουρος, φιλονεικεῖ τοσοῦτον γράψαι ὁ Χρύσιππος. καὶ διὰ τοῦτο καὶ πολλάκις ταὐτὰ γέγραφε καὶ τὸ ἐπελθόν, καὶ ἀδιόρθωτα εἴακε τῷ ἐπείγεσθαι· καὶ τὰ μαρτύρια τοσαῦτά ἐστιν ὡς ἐκείνων μόνων γέμειν τὰ βιβλία, καθάπερ καὶ παρὰ Ζήνωνι ἔστιν εὑρεῖν καὶ παρὰ Ἀριστοτέλει.", "st": "10.27"}, {"sp": "N", "t": "καὶ τὰ συγγράμματα μὲν Ἐπικούρῳ τοσαῦτα καὶ τηλικαῦτα, ὧν τὰ βέλτιστά ἐστι τάδε·<br>Περὶ φύσεως ἑπτὰ καὶ τριάκοντα.<br>Περὶ ἀτόμων καὶ κενοῦ.<br>Περὶ ἔρωτος.<br>Ἐπιτομὴ τῶν πρὸς τοὺς φυσικούς.<br>Πρὸς τοὺς Μεγαρικούς.<br>Διαπορίαι.<br>Κύριαι δόξαι.<br>Περὶ αἱρέσεων καὶ φυγῶν.<br>Περὶ τέλους.<br>Περὶ κριτηρίου ἢ Κανών.<br>Χαιρέδημος.<br>Περὶ θεῶν.<br>Περὶ ὁσιότητος. Ἡγησιάναξ.<br>Περὶ βίων δ’.<br>Περὶ δικαιοπραγίας.<br>Νεοκλῆς πρὸς Θεμίσταν.<br>Συμπόσιον.<br>Εὐρύλοχος πρὸς Μητρόδωρον.<br>Περὶ τοῦ ὁρᾶν.<br>Περὶ τῆς ἐν τῇ ἀτόμῳ γωνίας.<br>Περὶ ἁφῆς.<br>Περὶ εἱμαρμένης.<br>Περὶ παθῶν δόξαι πρὸς Τιμοκράτην.<br>Προγνωστικόν.<br>Προτρεπτικός.<br>Περὶ εἰδώλων.<br>Περὶ φαντασίας.<br>Ἀριστόβουλος.<br>Περὶ μουσικῆς.<br>Περὶ δικαιοσύνης καὶ τῶν ἄλλων ἀρετῶν.<br>Περὶ δώρων καὶ χάριτος.<br>Πολυμήδης.<br>Τιμοκράτης γ’.<br>Μητρόδωρος ε’.<br>Ἀντίδωρος β′.<br>Περὶ νόσων δόξαι πρὸς Μίθρην.<br>Καλλιστόλας.<br>Περὶ βασιλείας.<br>Ἀναξιμένης.<br>Ἐπιστολαί.", "st": "10.28"}, {"sp": "N", "t": "Ἃ δὲ αὐτῷ δοκεῖ ἐν αὐτοῖς, ἐκθέσθαι πειράσομαι τρεῖς ἐπιστολὰς αὐτοῦ παραθέμενος, ἐν αἷς πᾶσαν τὴν ἑαυτοῦ φιλοσοφίαν ἐπιτέτμηται· θήσομεν δὲ καὶ τὰς Κυρίας αὐτοῦ δόξας καὶ εἴ τι ἔδοξεν ἐκλογῆς ἀξίως ἀνεφθέγχθαι, ὥστε σὲ πανταχόθεν καταμαθεῖν τὸν ἄνδρα κἂν κρίνειν εἰδέναι.", "st": "10.29"}, {"sp": "N", "t": "Τὴν μὲν οὖν πρώτην ἐπιστολὴν γράφει πρὸς Ἡρόδοτον 〈ἥτις ἐστὶ περὶ τῶν φυσικῶν· τὴν δὲ δευτέραν πρὸς Πυθοκλέα〉, ἥτις ἐστὶ περὶ μεταρσίων· τὴν τρίτην πρὸς Μενοικέα, ἔστι δ’ ἐν αὐτῇ τὰ περὶ βίων.", "st": "10.29b"}, {"sp": "N", "t": "ἀρκτέον δὴ ἀπὸ τῆς πρώτης, ὀλίγα προειπόντα περὶ τῆς διαιρέσεως τῆς κατ’ αὐτὸν φιλοσοφίας.", "st": "10.29c"}, {"sp": "N", "t": "Διαιρεῖται τοίνυν εἰς τρία, τό τε κανονικὸν καὶ φυσικὸν καὶ ἠθικόν. τὸ μὲν οὖν κανονικὸν ἐφόδους ἐπὶ τὴν πραγματείαν ἔχει, καὶ ἔστιν ἐν ἑνὶ τῷ ἐπιγραφομένῳ Κανών· τὸ δὲ φυσικὸν τὴν περὶ φύσεως θεωρίαν πᾶσαν, καὶ ἔστιν ἐν ταῖς Περὶ φύσεως βίβλοις ἑπτὰ καὶ τριάκοντα καὶ ταῖς ἐπιστολαῖς κατὰ στοιχεῖον· τὸ δὲ ἠθικὸν τὰ περὶ αἱρέσεως καὶ φυγῆς· ἔστι δὲ καὶ ἐν ταῖς Περὶ βίων βίβλοις καὶ ἐπιστολαῖς καὶ τῷ Περὶ τέλους. εἰώθασι μέντοι τὸ κανονικὸν ὁμοῦ τῷ φυσικῷ τάττειν· καλοῦσι δ’ αὐτὸ περὶ κριτηρίου καὶ ἀρχῆς, καὶ στοιχειωτικόν· τὸ δὲ φυσικὸν περὶ γενέσεως καὶ φθορᾶς, καὶ περὶ φύσεως· τὸ δὲ ἠθικὸν περὶ αἱρετῶν καὶ φευκτῶν καὶ περὶ βίων καὶ τέλους.", "st": "10.30"}, {"sp": "N", "t": "Τὴν διαλεκτικὴν ὡς παρέλκουσαν ἀποδοκιμάζουσιν· ἀρκεῖν γὰρ τοὺς φυσικοὺς χωρεῖν κατὰ τοὺς τῶν πραγμάτων φθόγγους.", "st": "10.31"}, {"sp": "N", "t": "ἐν τοίνυν τῷ Κανόνι λέγων ἐστὶν ὁ Ἐπίκουρος κριτήρια τῆς ἀληθείας εἶναι τὰς αἰσθήσεις καὶ προλήψεις καὶ τὰ πάθη, οἱ δ’ Ἐπικούρειοι καὶ τὰς φανταστικὰς ἐπιβολὰς τῆς διανοίας. λέγει δὲ καὶ ἐν τῇ πρὸς Ἡρόδοτον ἐπιτομῇ καὶ ἐν ταῖς Κυρίαις δόξαις. πᾶσα γάρ, φησίν, αἴσθησις ἄλογός ἐστι καὶ μνήμης οὐδεμιᾶς δεκτική· οὔτε γὰρ ὑφ’ αὑτῆς οὔτε ὑφ’ ἑτέρου κινηθεῖσα δύναταί τι προσθεῖναι ἢ ἀφελεῖν· οὐδὲ ἔστι τὸ δυνάμενον αὐτὰς διελέγξαι. οὔτε γὰρ ἡ ὁμογένεια αἴσθησις τὴν ὁμογενῆ διὰ τὴν ἰσοσθένειαν, οὔθ’ ἡ ἀνομογένεια τὴν ἀνομογένειαν, οὐ γὰρ τῶν αὐτῶν εἰσι κριτικαί· οὔτε μὴν λόγος, πᾶς γὰρ λόγος ἀπὸ τῶν αἰσθήσεων ἤρτηται. οὔθ’ ἡ ἑτέρα τὴν ἑτέραν, πάσαις γὰρ προσέχομεν. καὶ τὸ τὰ ἐπαισθήματα δ’ ὑφεστάναι πιστοῦται τὴν τῶν αἰσθήσεων ἀλήθειαν. ὑφέστηκε δὲ τό τε ὁρᾶν ἡμᾶς καὶ ἀκούειν, ὥσπερ τὸ ἀλγεῖν·", "st": "10.32"}, {"sp": "N", "t": "ὅθεν καὶ περὶ τῶν ἀδήλων ἀπὸ τῶν φαινομένων χρὴ σημειοῦσθαι. καὶ γὰρ καὶ ἐπίνοιαι πᾶσαι ἀπὸ τῶν αἰσθήσεων γεγόνασι κατά τε περίπτωσιν καὶ ἀναλογίαν καὶ ὁμοιότητα καὶ σύνθεσιν, συμβαλλομένου τι καὶ τοῦ λογισμοῦ. τά τε τῶν μαινομένων φαντάσματα καὶ 〈τὰ〉 κατ’ ὄναρ ἀληθῆ, κινεῖ γάρ· τὸ δὲ μὴ ὂν οὐ κινεῖ.", "st": "10.32b"}, {"sp": "N", "t": "Τὴν δὲ πρόληψιν λέγουσιν οἱονεὶ κατάληψιν ἢ δόξαν ὀρθὴν ἢ ἔννοιαν ἢ καθολικὴν νόησιν ἐναποκειμένην, τουτέστι μνήμην τοῦ πολλάκις ἔξωθεν φανέντος, οἷον τὸ Τοιοῦτόν ἐστιν ἄνθρωπος· ἅμα γὰρ τῷ ῥηθῆναι ἄνθρωπος εὐθὺς κατὰ πρόληψιν καὶ ὁ τύπος αὐτοῦ νοεῖται προηγουμένων τῶν αἰσθήσεων. παντὶ οὖν ὀνόματι τὸ πρώτως ὑποτεταγμένον ἐναργές ἐστι· καὶ οὐκ ἂν ἐζητήσαμεν τὸ ζητούμενον, εἰ μὴ πρότερον ἐγνώκειμεν αὐτό· οἷον Τὸ πόρρω ἑστὼς ἵππος ἐστὶν ἢ βοῦς· δεῖ γὰρ κατὰ πρόληψιν ἐγνωκέναι ποτὲ ἵππου καὶ βοὸς μορφήν· οὐδ’ ἂν ὠνομάσαμέν τι μὴ πρότερον αὐτοῦ κατὰ πρόληψιν τὸν τύπον μαθόντες.", "st": "10.33"}, {"sp": "N", "t": "ἐναργεῖς οὖν εἰσιν αἱ προλήψεις· καὶ τὸ δοξαστὸν ἀπὸ προτέρου τινὸς ἐναργοῦς ἤρτηται, ἐφ’ ὃ ἀναφέροντες λέγομεν, οἷον Πόθεν ἴσμεν εἰ τοῦτό ἐστιν ἄνθρωπος;", "st": "10.33b"}, {"sp": "N", "t": "τὴν δὲ δόξαν καὶ ὑπόληψιν λέγουσιν, ἀληθῆ τέ φασι καὶ ψευδῆ· ἂν μὲν γὰρ ἐπιμαρτυρῆται ἢ μὴ ἀντιμαρτυρῆται, ἀληθῆ εἶναι· ἐὰν δὲ μὴ ἐπιμαρτυρῆται ἢ ἀντιμαρτυρῆται, ψευδῆ τυγχάνειν. ὅθεν 〈τὸ〉 προσμένον εἰσήχθη· οἷον τὸ προσμεῖναι καὶ ἐγγὺς γενέσθαι τῷ πύργῳ καὶ μαθεῖν ὁποῖος ἐγγὺς φαίνεται.", "st": "10.34"}, {"sp": "N", "t": "Πάθη δὲ λέγουσιν εἶναι δύο, ἡδονὴν καὶ ἀλγηδόνα, ἱστάμενα περὶ πᾶν ζῷον, καὶ τὴν μὲν οἰκεῖον, τὴν δὲ ἀλλότριον· δι’ ὧν κρίνεσθαι τὰς αἱρέσεις καὶ φυγάς. τῶν τε ζητήσεων εἶναι τὰς μὲν περὶ τῶν πραγμάτων, τὰς δὲ περὶ ψιλὴν τὴν φωνήν. καὶ ταῦτα δὲ περὶ τῆς διαιρέσεως καὶ τοῦ κριτηρίου στοιχειωδῶς.", "st": "10.34b"}, {"sp": "N", "t": "Ἀνιτέον δὲ ἐπὶ τὴν ἐπιστολήν. “Ἐπίκουρος Ἡροδότῳ χαίρειν.", "st": "10.34c"}, {"sp": "N", "t": "“Τοῖς μὴ δυναμένοις, ὦ Ἡρόδοτε, ἕκαστα τῶν περὶ φύσεως ἀναγεγραμμένων ἡμῖν ἐξακριβοῦν μηδὲ τὰς μείζους τῶν συντεταγμένων βίβλους διαθρεῖν ἐπιτομὴν τῆς ὅλης πραγματείας εἰς τὸ κατασχεῖν τῶν ὁλοσχερωτάτων γε δοξῶν τὴν μνήμην ἱκανῶς αὐτὸς παρεσκεύασα, ἵνα παρ’ ἑκάστους τῶν καιρῶν ἐν τοῖς κυριωτάτοις βοηθεῖν αὑτοῖς δύνωνται, καθ’ ὅσον ἂν ἐφάπτωνται τῆς περὶ φύσεως θεωρίας. καὶ τοὺς προβεβηκότας δὲ ἱκανῶς ἐν τῇ τῶν ὅλων ἐπιβλέψει τὸν τύπον τῆς ὅλης πραγματείας τὸν κατεστοιχειωμένον δεῖ μνημονεύειν· τῆς γὰρ ἀθρόας ἐπιβολῆς πυκνὸν δεόμεθα, τῆς δὲ κατὰ μέρος οὐχ ὁμοίως.", "st": "10.35"}, {"sp": "N", "t": "“Βαδιστέον μὲν οὖν καὶ ἐπ’ ἐκεῖνα συνεχῶς, ἐν 〈δὲ〉 τῇ μνήμῃ τὸ τοσοῦτο ποιητέον, ἀφ’ οὗ ἥ τε κυριωτάτη ἐπιβολὴ ἐπὶ τὰ πράγματα ἔσται καὶ δὴ καὶ τὸ κατὰ μέρος ἀκρίβωμα πᾶν ἐξευρήσεται, τῶν ὁλοσχερωτάτων τύπων εὖ περιειλημμένων καὶ μνημονευομένων· ἐπεὶ καὶ τῷ τετελεσιουργημένῳ τοῦτο κυριώτατον τοῦ παντὸς ἀκριβώματος γίνεται, τὸ ταῖς ἐπιβολαῖς ὀξέως δύνασθαι χρῆσθαι, ἑκάστων πρὸς ἁπλᾶ στοιχειώματα καὶ φωνὰς συναγομένων. οὐ γὰρ οἷόν τε τὸ πύκνωμα τῆς συνεχοῦς τῶν ὅλων περιοδείας εἰδέναι μὴ δυνάμενον διὰ βραχεῶν φωνῶν ἅπαν ἐμπεριλαβεῖν ἐν αὑτῷ τὸ καὶ κατὰ μέρος ἂν ἐξακριβωθέν. “Ὅθεν δὴ πᾶσι χρησίμης οὔσης τοῖς ᾠκειωμένοις φυσιολογίᾳ τῆς τοιαύτης ὁδοῦ, παρεγγυῶν τὸ συνεχὲς ἐνέργημα ἐν φυσιολογίᾳ καὶ τοιούτῳ μάλιστα ἐγγαληνίζων τῷ βίῳ ἐποίησά σοι καὶ τοιαύτην τινὰ ἐπιτομὴν καὶ στοιχείωσιν τῶν ὅλων δοξῶν.", "st": "10.36"}, {"sp": "N", "t": "“Πρῶτον μὲν οὖν τὰ ὑποτεταγμένα τοῖς φθόγγοις, ὦ Ἡρόδοτε, δεῖ εἰληφέναι, ὅπως ἂν τὰ δοξαζόμενα ἢ ζητούμενα ἢ ἀπορούμενα ἔχωμεν εἰς ταῦτα ἀνάγοντες ἐπικρίνειν, καὶ μὴ ἄκριτα πάντα ἡμῖν 〈ἴῃ〉 εἰς ἄπειρον ἀποδεικνύουσιν ἢ κενοὺς φθόγγους ἔχωμεν. ἀνάγκη γὰρ τὸ πρῶτον ἐννόημα καθ’ ἕκαστον φθόγγον βλέπεσθαι καὶ μηθὲν ἀποδείξεως προσδεῖσθαι, εἴπερ ἕξομεν τὸ ζητούμενον ἢ ἀπορούμενον καὶ δοξαζόμενον ἐφ’ ὃ ἀνάξομεν.", "st": "10.38"}, {"sp": "N", "t": "“Ἔτι τε τὰς αἰσθήσεις δεῖ πάντως τηρεῖν καὶ ἁπλῶς τὰς παρούσας ἐπιβολὰς εἴτε διανοίας εἴθ’ ὅτου δήποτε τῶν κριτηρίων, ὁμοίως δὲ καὶ τὰ ὑπάρχοντα πάθη, ὅπως ἂν καὶ τὸ προσμένον καὶ τὸ ἄδηλον ἔχωμεν οἷς σημειωσόμεθα.", "st": "10.38b"}, {"sp": "N", "t": "“Ταῦτα δεῖ διαλαβόντας συνορᾶν ἤδη περὶ τῶν ἀδήλων· πρῶτον μὲν ὅτι οὐδὲν γίνεται ἐκ τοῦ μὴ ὄντος. πᾶν γὰρ ἐκ παντὸς ἐγίνετ’ ἂν σπερμάτων γε οὐθὲν προσδεόμενον. καὶ εἰ ἐφθείρετο δὲ τὸ ἀφανιζόμενον εἰς τὸ μὴ ὄν, πάντα ἂν ἀπωλώλει τὰ πράγματα, οὐκ ὄντων εἰς ἃ διελύετο. καὶ μὴν καὶ τὸ πᾶν ἀεὶ τοιοῦτον ἦν οἷον νῦν ἐστι, καὶ ἀεὶ τοιοῦτον ἔσται. οὐθὲν γάρ ἐστιν εἰς ὃ μεταβαλεῖ. παρὰ γὰρ τὸ πᾶν οὐθέν ἐστιν, ὃ ἂν εἰσελθὸν εἰς αὐτὸ τὴν μεταβολὴν ποιήσαιτο.", "st": "10.39"}, {"sp": "N", "t": "“Ἀλλὰ μὴν καὶ [τοῦτο καὶ ἐν τῇ Μεγάλῃ ἐπιτομῇ φησι κατ’ ἀρχὴν καὶ ἐν τῇ ά Περὶ φύσεως] τὸ πᾶν ἐστι σώματα καὶ κενόν· σώματα μὲν γὰρ ὡς ἔστιν, αὐτὴ ἡ αἴσθησις ἐπὶ πάντων μαρτυρεῖ, καθ’ ἣν ἀναγκαῖον τὸ ἄδηλον τῷ λογισμῷ τεκμαίρεσθαι· εἰ δὲ μὴ ἦν ὃ κενὸν καὶ χώραν καὶ ἀναφῆ φύσιν ὀνομάζομεν, οὐκ ἂν εἶχε τὰ σώματα ὅπου ἦν οὐδὲ δι’ οὗ ἐκινεῖτο, καθάπερ φαίνεται κινούμενα. παρὰ δὲ ταῦτα οὐθὲν οὐδ’ ἐπινοηθῆναι δύναται οὔτε περιληπτῶς οὔτε ἀναλόγως τοῖς περιληπτοῖς ὡς καθ’ ὅλας φύσεις λαμβανόμενα καὶ μὴ ὡς τὰ τούτων συμπτώματα ἢ συμβεβηκότα λεγόμενα.", "st": "10.40"}, {"sp": "N", "t": "“Καὶ μὴν καὶ τῶν [τοῦτο καὶ ἐν τῇ πρώτῃ Περὶ φύσεως καὶ τῇ ιδ’ καὶ ιε’ καὶ τῇ Μεγάλῃ ἐπιτομῇ] σωμάτων τὰ μέν ἐστι συγκρίσεις, τὰ δ’ ἐξ ὧν αἱ συγκρίσεις πεποίηνται· ταῦτα δέ ἐστιν ἄτομα καὶ ἀμετάβλητα, εἴπερ μὴ μέλλει πάντα εἰς τὸ μὴ ὂν φθαρήσεσθαι, ἀλλ’ ἰσχύοντα ὑπομένειν ἐν ταῖς διαλύσεσι τῶν συγκρίσεων, πλήρη τὴν φύσιν ὄντα, οἷα δὴ οὐκ ἔχοντα ὅπῃ ἢ ὅπως διαλυθήσεται. ὥστε τὰς ἀρχὰς ἀτόμους ἀναγκαῖον εἶναι σωμάτων φύσεις.", "st": "10.41"}, {"sp": "N", "t": "“Ἀλλὰ μὴν καὶ τὸ πᾶν ἄπειρόν ἐστι. τὸ γὰρ πεπερασμένον ἄκρον ἔχει· τὸ δὲ ἄκρον παρ’ ἕτερόν τι θεωρεῖται· 〈τὸ δὲ πᾶν οὐ παρ’ ἕτερόν τι θεωρεῖται·〉 ὥστε οὐκ ἔχον ἄκρον πέρας οὐκ ἔχει· πέρας δὲ οὐκ ἔχον ἄπειρον ἂν εἴη καὶ οὐ πεπερασμένον. “Καὶ μὴν καὶ τῷ πλήθει τῶν σωμάτων ἄπειρόν ἐστι τὸ πᾶν καὶ τῷ μεγέθει τοῦ κενοῦ. εἴ τε γὰρ ἦν τὸ κενὸν ἄπειρον, τὰ δὲ σώματα ὡρισμένα, οὐθαμοῦ ἂν ἔμενε τὰ σώματα, ἀλλ’ ἐφέρετο κατὰ τὸ ἄπειρον κενὸν διεσπαρμένα, οὐκ ἔχοντα τὰ ὑπερείδοντα καὶ στέλλοντα κατὰ τὰς ἀνακοπάς· εἴ τε τὸ κενὸν ἦν ὡρισμένον, οὐκ ἂν εἶχε τὰ ἄπειρα σώματα ὅπου ἐνέστη.", "st": "10.42"}, {"sp": "N", "t": "“Πρός τε τούτοις τὰ ἄτομα τῶν σωμάτων καὶ μεστά, ἐξ ὧν καὶ αἱ συγκρίσεις γίνονται καὶ εἰς ἃ διαλύονται, ἀπερίληπτά ἐστι ταῖς διαφοραῖς τῶν σχημάτων· οὐ γὰρ δυνατὸν γενέσθαι τὰς τοσαύτας διαφορὰς ἐκ τῶν αὐτῶν σχημάτων περιειλημμένων. καὶ καθ’ ἑκάστην δὲ σχημάτισιν ἁπλῶς ἄπειροί εἰσιν αἱ ὅμοιαι, ταῖς δὲ διαφοραῖς οὐχ ἁπλῶς", "st": "10.42b"}, {"sp": "N", "t": "ἄπειροι ἀλλὰ μόνον ἀπερίληπτοι, [οὐδὲ γάρ φησιν ἐνδοτέρω εἰς ἄπειρον τὴν τομὴν τυγχάνειν. λέγει δέ, ἐπειδὴ αἱ ποιότητες μεταβάλλονται, εἰ μέλλει τις μὴ καὶ τοῖς μεγέθεσιν ἁπλῶς εἰς ἄπειρον αὐτὰς ἐκβάλλειν].", "st": "10.43"}, {"sp": "N", "t": "“Κινοῦνταί τε συνεχῶς αἱ ἄτομοι [φησὶ δὲ ἐνδοτέρω καὶ ἰσοταχῶς αὐτὰς κινεῖσθαι τοῦ κενοῦ τὴν εἶξιν ὁμοίαν παρεχομένου καὶ τῇ κουφοτάτῃ καὶ τῇ βαρυτάτῃ.] τὸν αἰῶνα, καὶ αἱ μὲν εἰς μακρὰν ἀπ’ ἀλλήλων διιστάμεναι, αἱ δὲ αὐτοῦ τὸν παλμὸν ἴσχουσιν, ὅταν τύχωσι τῇ περιπλοκῇ κεκλειμέναι ἢ στεγαζόμενοι παρὰ τῶν πλεκτικῶν. “Ἥ τε γὰρ τοῦ κενοῦ φύσις ἡ διορίζουσα ἑκάστην αὐτὴν τοῦτο παρασκευάζει, τὴν ὑπέρεισιν οὐχ οἵα τε οὖσα ποιεῖσθαι· ἥ τε στερεότης ἡ ὑπάρχουσα αὐταῖς κατὰ τὴν σύγκρουσιν τὸν ἀποπαλμὸν ποιεῖ, ἐφ’ ὁπόσον ἂν ἡ περιπλοκὴ τὴν ἀποκατάστασιν ἐκ τῆς συγκρούσεως διδῷ. ἀρχὴ δὲ τούτων οὐκ ἔστιν, ἀιδίων τῶν ἀτόμων οὐσῶν καὶ τοῦ κενοῦ.", "st": "10.44"}, {"sp": "N", "t": "[φησὶ δ’ ἐνδοτέρω μηδὲ ποιότητά τινα περὶ τὰς ἀτόμους εἶναι πλὴν σχήματος καὶ μεγέθους καὶ βάρους· τὸ δὲ χρῶμα παρὰ τὴν θέσιν τῶν ἀτόμων ἀλλάττεσθαι ἐν ταῖς Δώδεκα στοιχειώσεσί φησι. πᾶν τε μέγεθος μὴ εἶναι περὶ αὐτάς· οὐδέποτε γοῦν ἄτομος ὤφθη αἰσθήσει.] “Ἡτοσαύτη δὴ φωνὴ τούτων πάντων μνημονευομένων τὸν ἱκανὸν τύπον ὑποβάλλει 〈ταῖς περὶ〉 τῆς τῶν ὄντων φύσεως ἐπινοίαις.", "st": "10.45"}, {"sp": "N", "t": "“Ἀλλὰ μὴν καὶ κόσμοι ἄπειροί εἰσιν, οἵ θ’ ὅμοιοι τούτῳ καὶ ἀνόμοιοι. αἵ τε γὰρ ἄτομοι ἄπειροι οὖσαι, ὡς ἄρτι ἀπεδείχθη, φέρονται καὶ πορρωτάτω. οὐ γὰρ κατανήλωνται αἱ τοιαῦται ἄτομοι, ἐξ ὧν ἂν γένοιτο κόσμος ἢ ὑφ’ ὧν ἂν ποιηθείη, οὔτ’ εἰς ἕνα οὔτ’ εἰς πεπερασμένους, οὔθ’ ὅσοι τοιοῦτοι οὔθ’ ὅσοι διάφοροι τούτοις. ὥστε οὐδὲν τὸ ἐμποδοστατῆσόν ἐστι πρὸς τὴν ἀπειρίαν τῶν κόσμων.", "st": "10.45b"}, {"sp": "N", "t": "“Καὶ μὴν καὶ τύποι ὁμοιοσχήμονες τοῖς στερεμνίοις εἰσί, λεπτότησιν ἀπέχοντες μακρὰν τῶν φαινομένων. οὔτε γὰρ συστάσεις ἀδυνατοῦσιν ἐν τῷ περιέχοντι γίνεσθαι τοιαῦται οὔτ’ ἐπιτηδειότητες πρὸς κατεργασίας τῶν κοιλωμάτων καὶ λεπτοτήτων γίνεσθαι, οὔτε ἀπόρροιαι τὴν ἑξῆς θέσιν καὶ βάσιν διατηροῦσαι, ἥνπερ καὶ ἐν τοῖς στερεμνίοις εἶχον· τούτους δὲ τοὺς τύπους εἴδωλα προσαγορεύομεν. καὶ μὴν καὶ ἡ διὰ τοῦ κενοῦ φορὰ κατὰ μηδεμίαν ἀπάντησιν τῶν ἀντικοψόντων γινομένη πᾶν μῆκος περιληπτὸν ἐν ἀπερινοήτῳ χρόνῳ συντελεῖ. βράδους γὰρ καὶ τάχους ἀντικοπὴ καὶ οὐκ ἀντικοπὴ ὁμοίωμα λαμβάνει. “Οὐ μὴν οὐδ’ ἅμα κατὰ τοὺς διὰ λόγου θεωρητοὺς χρόνους αὐτὸ τὸ φερόμενον σῶμα ἐπὶ τοὺς πλείους τόπους ἀφικνεῖται — ἀδιανόητον γάρ,— καὶ τοῦτο συναφικνούμενον ἐν αἰσθητῷ χρόνῳ ὅθεν δήποθεν τοῦ ἀπείρου οὐκ ἐξ οὗ ἂν περιλάβωμεν τὴν φορὰν τόπου ἔσται ἀφιστάμενον· ἀντικοπῇ γὰρ ὅμοιον ἔσται, κἂν μέχρι τοσούτου τὸ τάχος τῆς φορᾶς μὴ ἀντικόπτον καταλίπωμεν.", "st": "10.46"}, {"sp": "N", "t": "χρήσιμον δὴ καὶ τοῦτο κατασχεῖν τὸ στοιχεῖον. εἶθ’ ὅτι τὰ εἴδωλα ταῖς λεπτότησιν ἀνυπερβλήτοις κέχρηται, οὐθὲν ἀντιμαρτυρεῖ τῶν φαινομένων· ὅθεν καὶ τάχη ἀνυπέρβλητα ἔχει, πάντα πόρον σύμμετρον ἔχοντα πρὸς τῷ 〈τῷ〉 ἀπείρῳ αὐτῶν μηθὲν ἀντικόπτειν ἢ ὀλίγα ἀντικόπτειν, πολλαῖς δὲ καὶ ἀπείροις εὐθὺς ἀντικόπτειν τι.", "st": "10.46b"}, {"sp": "N", "t": "“Πρός τε τούτοις, ὅτι ἡ γένεσις τῶν εἰδώλων ἅμα νοήματι συμβαίνει. καὶ γὰρ ῥεῦσις ἀπὸ τῶν σωμάτων τοῦ ἐπιπολῆς συνεχής, οὐκ ἐπίδηλος τῇ μειώσει διὰ τὴν ἀνταναπλήρωσιν, σῴζουσα τὴν ἐπὶ τοῦ στερεμνίου θέσιν καὶ τάξιν τῶν ἀτόμων ἐπὶ πολὺν χρόνον, εἰ καὶ ἐνίοτε συγχεομένη ὑπάρχει, καὶ συστάσεις ἐν τῷ περιέχοντι ὀξεῖαι διὰ τὸ μὴ δεῖν κατὰ βάθος τὸ συμπλήρωμα γίνεσθαι, καὶ ἄλλοι δὲ τρόποι τινὲς γεννητικοὶ τῶν τοιούτων φύσεων εἰσίν.", "st": "10.48"}, {"sp": "N", "t": "οὐθὲν γὰρ τούτων ἀντιμαρτυρεῖται ταῖς αἰσθήσεσιν, ἂν βλέπῃ τίς τινα τρόπον τὰς ἐναργείας ἵνα καὶ τὰς συμπαθείας ἀπὸ τῶν ἔξωθεν πρὸς ἡμᾶς ἀνοίσει. “Δεῖ δὲ καὶ νομίζειν ἐπεισιόντος τινὸς ἀπὸ τῶν ἔξωθεν ὁρᾶν ἡμᾶς καὶ διανοεῖσθαι· οὐ γὰρ ἂν ἐναποσφραγίσαιτο τὰ ἔξω τὴν ἑαυτῶν φύσιν τοῦ τε χρώματος καὶ τῆς μορφῆς διὰ τοῦ ἀέρος τοῦ μεταξὺ ἡμῶν τε κἀκείνων, οὐδὲ διὰ τῶν ἀκτίνων ἢ ὡνδήποτε ῥευμάτων ἀφ’ ἡμῶν πρὸς ἐκεῖνα παραγινομένων, οὕτως ὡς τύπων τινῶν ἐπεισιόντων ἡμῖν ἀπὸ τῶν πραγμάτων ὁμοχρόων τε καὶ ὁμοιομόρφων κατὰ τὸ ἐναρμόττον μέγεθος εἰς τὴν ὄψιν ἢ τὴν διάνοιαν, ὠκέως ταῖς φοραῖς χρωμένων, εἶτα διὰ ταύτην τὴν αἰτίαν τοῦ ἑνὸς καὶ συνεχοῦς τὴν φαντασίαν ἀποδιδόντων καὶ τὴν συμπάθειαν ἀπὸ τοῦ ὑποκειμένου σῳζόντων κατὰ τὸν ἐκεῖθεν σύμμετρον ἐπερεισμὸν ἐκ τῆς κατὰ βάθος ἐν τῷ στερεμνίῳ τῶν ἀτόμων πάλσεως. καὶ ἣν ἂν λάβωμεν φαντασίαν ἐπιβλητικῶς τῇ διανοίᾳ ἢ τοῖς αἰσθητηρίοις εἴτε μορφῆς εἴτε συμβεβηκότων, μορφή ἐστιν αὕτη τοῦ στερεμνίου, γινομένη κατὰ τὸ ἑξῆς πύκνωμα ἢ ἐγκατάλειμμα τοῦ εἰδώλου·", "st": "10.49"}, {"sp": "N", "t": "τὸ δὲ ψεῦδος καὶ τὸ διημαρτημένον ἐν τῷ προσδοξαζομένῳ ἀεί ἐστιν 〈ἐπὶ τοῦ προσμένοντος〉 ἐπιμαρτυρηθήσεσθαι ἢ μὴ ἀντιμαρτυρηθήσεσθαι, εἶτ’ οὐκ ἐπιμαρτυρουμένου 〈ἢ ἀντιμαρτυρουμένου〉 [κατά τινα κίνησιν ἐν ἡμῖν αὐτοῖς συνημμένην τῇ φανταστικῇ ἐπιβολῇ, διάληψιν δὲ ἔχουσαν, καθ’ ἣν τὸ ψεῦδος γίνεται.] “Ἥ τε γὰρ ὁμοιότης τῶν φαντασμῶν οἱονεὶ ἐν εἰκόνι λαμβανομένων ἢ καθ’ ὕπνους γινομένων ἢ κατ’ ἄλλας τινὰς ἐπιβολὰς τῆς διανοίας ἢ τῶν λοιπῶν κριτηρίων οὐκ ἄν ποτε ὑπῆρχε τοῖς οὖσί τε καὶ ἀληθέσι προσαγορευομένοις, εἰ μὴ ἦν τινα καὶ τοιαῦτα πρὸς ἃ παραβάλλομεν· τὸ δὲ διημαρτημένον οὐκ ἂν ὑπῆρχεν, εἰ μὴ ἐλαμβάνομεν καὶ ἄλλην τινὰ κίνησιν ἐν ἡμῖν αὐτοῖς συνημμένην μὲν τῇ φανταστικῇ ἐπιβολῇ, διάληψιν δὲ ἔχουσαν· κατὰ δὲ ταύτην, ἐὰν μὲν μὴ ἐπιμαρτυρηθῇ ἢ ἀντιμαρτυρηθῇ, τὸ ψεῦδος γίνεται· ἐὰν δὲ ἐπιμαρτυρηθῇ ἢ μὴ ἀντιμαρτυρηθῇ, τὸ ἀληθές.", "st": "10.51"}, {"sp": "N", "t": "“Καὶ ταύτην οὖν σφόδρα γε δεῖ τὴν δόξαν κατέχειν, ἵνα μήτε τὰ κριτήρια ἀναιρῆται τὰ κατὰ τὰς ἐναργείας μήτε τὸ διημαρτημένον ὁμοίως βεβαιούμενον πάντα συνταράττῃ.", "st": "10.52"}, {"sp": "N", "t": "“Ἀλλὰ μὴν καὶ τὸ ἀκούειν γίνεται ῥεύματος φερομένου ἀπὸ τοῦ φωνοῦντος ἢ ἠχοῦντος ἢ ψοφοῦντος ἢ ὁπωσδήποτε ἀκουστικὸν πάθος παρασκευάζοντος. τὸ δὲ ῥεῦμα τοῦτο εἰς ὁμοιομερεῖς ὄγκους διασπείρεται, ἅμα τινὰ διασῴζοντας συμπάθειαν πρὸς ἀλλήλους καὶ ἑνότητα ἰδιότροπον, διατείνουσαν πρὸς τὸ ἀποστεῖλαν καὶ τὴν ἐπαίσθησιν τὴν ἐπ’ ἐκείνου ὡς τὰ πολλὰ ποιοῦσαν, εἰ δὲ μή γε, τὸ ἔξωθεν μόνον ἔνδηλον παρασκευάζουσαν· ἄνευ γὰρ ἀναφερομένης τινὸς ἐκεῖθεν συμπαθείας οὐκ ἂν γένοιτο ἡ τοιαύτη ἐπαίσθησις. οὐκ αὐτὸν οὖν δεῖ νομίζειν τὸν ἀέρα ὑπὸ τῆς προιεμένης φωνῆς ἢ καὶ τῶν ὁμογενῶν σχηματίζεσθαι—πολλὴν γὰρ ἔνδειαν ἕξει τοῦτο πάσχων ὑπ’ ἐκείνης, —ἀλλ’ εὐθὺς τὴν γινομένην πληγὴν ἐν ἡμῖν, ὅταν φωνὴν ἀφίωμεν, τοιαύτην ἔκθλιψιν ὄγκων τινῶν ῥεύματος πνευματώδους ἀποτελεστικῶν ποιεῖσθαι, ἣ τὸ πάθος τὸ ἀκουστικὸν ἡμῖν παρασκευάζει.", "st": "10.53"}, {"sp": "N", "t": "“Καὶ μὴν καὶ τὴν ὀσμὴν νομιστέον, ὥσπερ καὶ τὴν ἀκοὴν οὐκ ἄν ποτε οὐθὲν πάθος ἐργάσασθαι, εἰ μὴ ὄγκοι τινὲς ἦσαν ἀπὸ τοῦ πράγματος ἀποφερόμενοι σύμμετροι πρὸς τοῦτο τὸ αἰσθητήριον κινεῖν, οἱ μὲν τοῖοι τεταραγμένως καὶ ἀλλοτρίως, οἱ δὲ τοῖοι ἀταράχως καὶ οἰκείως ἔχοντες.", "st": "10.53b"}, {"sp": "N", "t": "“Καὶ μὴν καὶ τὰς ἀτόμους νομιστέον μηδεμίαν ποιότητα τῶν φαινομένων προσφέρεσθαι πλὴν σχήματος καὶ βάρους καὶ μεγέθους καὶ ὅσα ἐξ ἀνάγκης σχήματος συμφυῆ ἐστι. ποιότης γὰρ πᾶσα μεταβάλλει· αἱ δὲ ἄτομοι οὐδὲν μεταβάλλουσιν, ἐπειδή περ δεῖ τι ὑπομένειν ἐν ταῖς διαλύσεσι τῶν συγκρίσεων στερεὸν καὶ ἀδιάλυτον, ὃ τὰς μεταβολὰς οὐκ εἰς τὸ μὴ ὂν ποιήσεται οὐδ’ ἐκ τοῦ μὴ ὄντος, ἀλλὰ κατὰ μεταθέσεις ἐν πολλοῖς, τινῶν δὲ καὶ προσόδους καὶ ἀφόδους. ὅθεν ἀναγκαῖον τὰ μετατιθέμενα ἄφθαρτα εἶναι καὶ τὴν τοῦ μεταβάλλοντος φύσιν οὐκ ἔχοντα, ὀγκοὺς δὲ καὶ σχηματισμοὺς ἰδίους· ταῦτα γὰρ καὶ ἀναγκαῖον ὑπομένειν. “Καὶ γὰρ ἐν τοῖς παρ’ ἡμῖν μετασχηματιζομένοις κατὰ τὴν περιαίρεσιν τὸ σχῆμα ἐνυπάρχον λαμβάνεται, αἱ δὲ ποιότητες οὐκ ἐνυπάρχουσαι ἐν τῷ μεταβάλλοντι, ὥσπερ ἐκεῖνο καταλείπεται, ἀλλ’ ἐξ ὅλου τοῦ σώματος ἀπολλύμεναι. ἱκανὰ οὖν τὰ ὑπολειπόμενα ταῦτα τὰς τῶν συγκρίσεων διαφορὰς ποιεῖν, ἐπειδή περ ὑπολείπεσθαί γέ τινα ἀναγκαῖον καὶ μὴ εἰς τὸ μὴ ὂν φθείρεσθαι.", "st": "10.54"}, {"sp": "N", "t": "“Ἀλλὰ μὴν οὐδὲ δεῖ νομίζειν πᾶν μέγεθος ἐν ταῖς ἀτόμοις ὑπάρχειν, ἵνα μὴ τὰ φαινόμενα ἀντιμαρτυρῇ· παραλλαγὰς δέ τινας μεγεθῶν νομιστέον εἶναι. βέλτιον γὰρ καὶ τούτου προσόντος τὰ κατὰ τὰ πάθη καὶ τὰς αἰσθήσεις γινόμενα ἀποδοθήσεται. πᾶν δὲ μέγεθος ὑπάρχειν οὔτε χρήσιμόν ἐστι πρὸς τὰς τῶν ποιοτήτων διαφοράς, ἀφῖχθαί τε ἅμ’ ἔδει καὶ πρὸς ἡμᾶς ὁρατὰς ἀτόμους·", "st": "10.56"}, {"sp": "N", "t": "ὃ οὐ θεωρεῖται γινόμενον οὔθ’ ὅπως ἂν γένοιτο ὁρατὴ ἄτομος ἔστιν ἐπινοῆσαι. “Πρὸς δὲ τούτοις οὐ δεῖ νομίζειν ἐν τῷ ὡρισμένῳ σώματι ἀπείρους ὄγκους εἶναι οὐδ’ ὁπηλίκους οὖν. ὥστε οὐ μόνον τὴν εἰς ἄπειρον τομὴν ἐπὶ τοὔλαττον ἀναιρετέον, ἵνα μὴ πάντα ἀσθενῆ ποιῶμεν κἀν ταῖς περιλήψεσι τῶν ἀθρόων εἰς τὸ μὴ ὂν ἀναγκαζώμεθα τὰ ὄντα θλίβοντες καταναλίσκειν, ἀλλὰ καὶ τὴν μετάβασιν μὴ νομιστέον γίνεσθαι ἐν τοῖς ὡρισμένοις εἰς ἄπειρον μηδ’ ἐπὶ τοὔλαττον. “Οὔτε γὰρ ὅπως, ἐπειδὰν ἅπαξ τις εἴπῃ ὅτι ἄπειροι ὄγκοι ἔν τινι ὑπάρχουσιν ἢ ὁπηλίκοι οὖν, ἔστι νοῆσαι ὅπως ἂν ἔτι τοῦτο πεπερασμένον εἴη τὸ μέγεθος. πηλίκοι γάρ τινες δῆλον ὡς οἱ ἄπειροί εἰσιν ὄγκοι· καὶ οὗτοι ὁπηλίκοι ἄν ποτε ὦσιν, ἄπειρον ἂν ἦν καὶ τὸ μέγεθος. ἄκρον τε ἔχοντος τοῦ πεπερασμένου διαληπτόν, εἰ μὴ καὶ καθ’ ἑαυτὸ θεωρητόν, οὐκ ἔστι μὴ οὐ καὶ τὸ ἑξῆς τούτου τοιοῦτον νοεῖν καὶ οὕτω κατὰ τὸ ἑξῆς εἰς τοὔμπροσθεν βαδίζοντα εἰς τὸ ἄπειρον ὑπάρχειν καὶ τὸ τοιοῦτον ἀφικνεῖσθαι τῇ ἐννοίᾳ.", "st": "10.57"}, {"sp": "N", "t": "“Τό τε ἐλάχιστον τὸ ἐν τῇ αἰσθήσει δεῖ κατανοεῖν ὅτι οὔτε τοιοῦτόν ἐστιν οἷον τὸ τὰς μεταβάσεις ἔχον οὔτε πάντῃ πάντως ἀνόμοιον, ἀλλ’ ἔχον μέν τινα κοινότητα τῶν μεταβατῶν, διάληψιν δὲ μερῶν οὐκ ἔχον· ἀλλ’ ὅταν διὰ τὴν τῆς κοινότητος προσεμφέρειαν οἰηθῶμεν διαλήψεσθαί τι αὐτοῦ, τὸ μὲν ἐπιτάδε, τὸ δὲ ἐπέκεινα, τὸ ἴσον ἡμῖν δεῖ προσπίπτειν. ἑξῆς τε θεωροῦμεν ταῦτα ἀπὸ τοῦ πρώτου καταρχόμενοι καὶ οὐκ ἐν τῷ αὐτῷ, οὐδὲ μέρεσι μερῶν ἁπτόμενα, ἀλλ’ ἢ ἐν τῇ ἰδιότητι τῇ ἑαυτῶν τὰ μεγέθη καταμετροῦντα, τὰ πλείω πλεῖον καὶ τὰ ἐλάττω ἔλαττον. “Ταύτῃ τῇ ἀναλογίᾳ νομιστέον καὶ τὸ ἐν τῇ ἀτόμῳ ἐλάχιστον κεχρῆσθαι· μικρότητι γὰρ ἐκεῖνο δῆλον ὡς διαφέρει τοῦ κατὰ τὴν αἴσθησιν θεωρουμένου, ἀναλογίᾳ δὲ τῇ αὐτῇ κέχρηται. ἐπεί περ καὶ ὅτι μέγεθος ἔχει ἡ ἄτομος, κατὰ τὴν ἐνταῦθα ἀναλογίαν κατηγορήσαμεν, μικρόν τι μόνον μακρὰν ἐκβαλόντες.", "st": "10.58"}, {"sp": "N", "t": "ἔτι τε τὰ ἐλάχιστα καὶ ἀμιγῆ πέρατα δεῖ νομίζειν τῶν μηκῶν τὸ καταμέτρημα ἐξ αὑτῶν πρώτων τοῖς μείζοσι καὶ ἐλάττοσι παρασκευάζοντα τῇ διὰ λόγου θεωρίᾳ ἐπὶ τῶν ἀοράτων. ἡ γὰρ κοινότης ἡ ὑπάρχουσα αὐτοῖς πρὸς τὰ ἀμετάβολα ἱκανὴ τὸ μέχρι τούτου συντελέσαι, συμφόρησιν δὲ ἐκ τούτων κίνησιν ἐχόντων οὐχ οἷόν τε γίνεσθαι.", "st": "10.58b"}, {"sp": "N", "t": "“Καὶ μὴν καὶ τοῦ ἀπείρου ὡς μὲν ἀνωτάτω καὶ κατώτατω οὐ δεῖ κατηγορεῖν τὸ ἄνω ἢ κάτω. ἴσμεν μέντοι τὸ ὑπὲρ κεφαλῆς, ὅθεν ἂν στῶμεν, εἰς ἄπειρον ἄγειν ὄν, μηδέποτε φανεῖσθαι τοῦτο ἡμῖν, ἢ τὸ ὑποκάτω τοῦ νοηθέντος εἰς ἄπειρον, ἅμα ἄνω τε εἶναι καὶ κάτω πρὸς τὸ αὐτό· τοῦτο γὰρ ἀδύνατον διανοηθῆναι.", "st": "10.60"}, {"sp": "N", "t": "ὥστε ἔστι μίαν λαβεῖν φορὰν τὴν ἄνω νοουμένην εἰς ἄπειρον καὶ μίαν τὴν κάτω, ἂν καὶ μυριάκις πρὸς τοὺς πόδας τῶν ἐπάνω τὸ παρ’ ἡμῶν φερόμενον εἰς τοὺς ὑπὲρ κεφαλῆς ἡμῶν τόπους ἀφικνῆται ἢ ἐπὶ τὴν κεφαλὴν τῶν ὑποκάτω τὸ παρ’ ἡμῶν κάτω φερόμενον· ἡ γὰρ ὅλη φορὰ οὐθὲν ἧττον ἑκατέρα ἑκατέρᾳ ἀντικειμένη ἐπ’ ἄπειρον νοεῖται.", "st": "10.60b"}, {"sp": "N", "t": "“Καὶ μὴν καὶ ἰσοταχεῖς ἀναγκαῖον τὰς ἀτόμους εἶναι, ὅταν διὰ τοῦ κενοῦ εἰσφέρωνται μηθενὸς ἀντικόπτοντος. οὔτε γὰρ τὰ βαρέα θᾶττον οἰσθήσεται τῶν μικρῶν καὶ κούφων, ὅταν γε δὴ μηδὲν ἀπαντᾷ αὐτοῖς· οὔτε τὰ μικρὰ τῶν μεγάλων, πάντα πόρον σύμμετρον ἔχοντα, ὅταν μηθὲν μηδὲ ἐκείνοις ἀντικόπτῃ· οὔθ’ ἡ ἄνω οὔθ’ ἡ εἰς τὸ πλάγιον διὰ τῶν κρούσεων φορά, οὔθ’ ἡ κάτω διὰ τῶν ἰδίων βαρῶν. ἐφ’ ὁπόσον γὰρ ἂν κατίσχῃ ἑκάτερον, ἐπὶ τοσοῦτο ν ἅμα νοήματι τὴν φορὰν σχήσει, ἕως ἀντικόψῃ ἢ ἔξωθεν ἢ ἐκ τοῦ ἰδίου βάρους πρὸς τὴν τοῦ πλήξαντος δύναμιν.", "st": "10.61"}, {"sp": "N", "t": "“Ἀλλὰ μὴν καὶ κατὰ τὰς συγκρίσεις θάττων ἑτέρα ἑτέρας 〈φορ〉ηθήσεται τῶν ἀτόμων ἰσοταχῶν οὐσῶν, τῷ ἐφ’ ἕνα τόπον φέρεσθαι τὰς ἐν τοῖς ἀθροίσμασιν ἀτόμους κατὰ τὸν ἐλάχιστον συνεχῆ χρόνον, εἰ 〈καὶ〉 μὴ ἐφ’ ἕνα κατὰ τοὺς λόγῳ θεωρητοὺς χρόνους· ἀλλὰ πυκνὸν ἀντικόπτουσιν, ἕως ἂν ὑπὸ τὴν αἴσθησιν τὸ συνεχὲς τῆς φορᾶς γίνηται. τὸ γὰρ προσδοξαζόμενον περὶ τοῦ ἀοράτου, ὡς ἄρα καὶ οἱ διὰ λόγου θεωρητοὶ χρόνοι τὸ συνεχὲς τῆς φορᾶς ἕξουσιν, οὐκ ἀληθές ἐστιν ἐπὶ τῶν τοιούτων· ἐπεὶ τό γε θεωρούμενον πᾶν ἢ κατ’ ἐπιβολὴν λαμβανόμενον τῇ διανοίᾳ ἀληθές ἐστι.", "st": "10.62"}, {"sp": "N", "t": "“Μετὰ δὲ ταῦτα δεῖ συνορᾶν ἀναφέροντα ἐπὶ τὰς αἰσθήσεις καὶ τὰ πάθη—οὕτω γὰρ ἡ βεβαιοτάτη πίστις ἔσται,—ὅτι ἡ ψυχὴ σῶμά ἐστι λεπτομερὲς παρ’ ὅλον τὸ ἄθροισμα παρεσπαρμένον, προσεμφερέστατον δὲ πνεύματι θερμοῦ τινα κρᾶσιν ἔχοντι καὶ πῇ μὲν τούτῳ προσεμφερές, πῇ δὲ τούτῳ· ἔστι δὲ τὸ 〈τρίτον〉 μέρος πολλὴν παραλλαγὴν εἰληφὸς τῇ λεπτομερείᾳ καὶ αὐτῶν τούτων, συμπαθὲς δὲ τούτῳ μᾶλλον καὶ τῷ λοιπῷ ἀθροίσματι· τοῦτο δὲ πᾶν αἱ δυνάμεις τῆς ψυχῆς δηλοῦσι καὶ τὰ πάθη καὶ αἱ εὐκινησίαι καὶ αἱ διανοήσεις καὶ ὧν στερόμενοι θνῄσκομεν. καὶ μὴν ὅτι ἔχει ἡ ψυχὴ τῆς αἰσθήσεως τὴν πλείστην αἰτίαν δεῖ κατέχειν· οὐ μὴν εἰλήφει ἂν ταύτην, εἰ μὴ ὑπὸ τοῦ λοιποῦ ἀθροίσματος ἐστεγάζετό πως. τὸ δὲ λοιπὸν ἄθροισμα παρασκευάσαν ἐκείνῃ τὴν αἰτίαν ταύτην μετείληφε καὶ αὐτὸ τοιούτου συμπτώματος παρ’ ἐκείνης, οὐ μέντοι πάντων ὧν ἐκείνη κέκτηται·", "st": "10.63"}, {"sp": "N", "t": "διὸ ἀπαλλαγείσης τῆς ψυχῆς οὐκ ἔχει τὴν αἴσθησιν. οὐ γὰρ αὐτὸ ἐν ἑαυτῷ ταύτην ἐκέκτητο τὴν δύναμιν, ἀλλ’ ἕτερον ἅμα συγγεγενημένον αὐτῷ παρεσκεύαζεν, ὃ διὰ τῆς συντελεσθείσης περὶ αὐτὸ δυνάμεως κατὰ τὴν κίνησιν σύμπτωμα αἰσθητικὸν εὐθὺς ἀποτελοῦν ἑαυτῷ ἀπεδίδου κατὰ τὴν ὁμούρησιν καὶ συμπάθειαν καὶ ἐκείνῳ, καθάπερ εἶπον. “Διὸ δὴ καὶ ἐνυπάρχουσα ἡ ψυχὴ οὐδέποτε ἄλλου τινὸς μέρους ἀπηλλαγμένου ἀναισθητεῖ· ἀλλ’ ἃ ἂν καὶ ταύτης ξυναπόληται τοῦ στεγάζοντος λυθέντος εἴθ’ ὅλου εἴτε καὶ μέρους τινός, ἐάν περ διαμένῃ, ἕξει τὴν αἴσθησιν.", "st": "10.65"}, {"sp": "N", "t": "τὸ δὲ λοιπὸν ἄθροισμα διαμένον καὶ ὅλον καὶ κατὰ μέρος οὐκ ἔχει τὴν αἴσθησιν ἐκείνου ἀπηλλαγμένου, ὅσον ποτέ ἐστι τὸ συντεῖνον τῶν ἀτόμων πλῆθος εἰς τὴν τῆς ψυχῆς φύσιν. καὶ μὴν καὶ λυομένου τοῦ ὅλου ἀθροίσματος ἡ ψυχὴ διασπείρεται καὶ οὐκέτι ἔχει τὰς αὐτὰς δυνάμεις οὐδὲ κινεῖται, ὥσπερ οὐδ’ αἴσθησιν κέκτηται. “Οὐ γὰρ οἷόν τε νοεῖν αὐτὸ αἰσθανόμενον μὴ ἐν τούτῳ τῷ συστήματι καὶ ταῖς κινήσεσι ταύταις χρώμενον, ὅταν τὰ στεγάζοντα καὶ περιέχοντα μὴ τοιαῦτα ᾖ, ἐν οἷς νῦν οὖσα ἔχει ταύτας τὰς κινήσεις.", "st": "10.66"}, {"sp": "N", "t": "[λέγει ἐν ἄλλοις καὶ ἐξ ἀτόμων αὐτὴν συγκεῖσθαι λειοτάτων καὶ στρογγυλωτάτων, πολλῷ τινι διαφερουσῶν τῶν τοῦ πυρός· καὶ τὸ μέν τι ἄλογον αὐτῆς, ὃ τῷ λοιπῷ παρεσπάρθαι σώματι· τὸ δὲ λογικὸν ἐν τῷ θώρακι, ὡς δῆλον ἔκ τε τῶν φόβων καὶ τῆς χαρᾶς. ὕπνον τε γίνεσθαι τῶν τῆς ψυχῆς μερῶν τῶν παρ’ ὅλην τὴν σύγκρισιν παρεσπαρμένων ἐγκατεχομένων ἢ διαφορουμένων, εἶτα συμπιπτόντων τοῖς ἐπερεισμοῖς. τό τε σπέρμα ἀφ’ ὅλων τῶν σωμάτων φέρεσθαι.]", "st": "10.66b"}, {"sp": "N", "t": "“Ἀλλὰ μὴν καὶ τόδε γε δεῖ προσκατανοεῖν, ὅ τι τὸ ἀσώματον λέγομεν κατὰ τὴν πλείστην ὁμιλίαν τοῦ ὀνόματος ἐπὶ τοῦ καθ’ ἑαυτὸ νοηθέντος ἄν· καθ’ ἑαυτὸ δὲ οὐκ ἔστι νοῆσαι τὸ ἀσώματον πλὴν τοῦ κενοῦ. τὸ δὲ κενὸν οὔτε ποιῆσαι οὔτε παθεῖν δύναται, ἀλλὰ κίνησιν μόνον δι’ ἑαυτοῦ τοῖς σώμασι παρέχεται. ὥστε οἱ λέγοντες ἀσώματον εἶναι τὴν ψυχὴν ματαΐζουσιν. οὐθὲν γὰρ ἂν ἐδύνατο ποιεῖν οὔτε πάσχειν, εἰ ἦν τοιαύτη· νῦν δ’ ἐναργῶς ἀμφότερα ταῦτα διαλαμβάνεται περὶ τὴν ψυχὴν τὰ συμπτώματα.", "st": "10.67"}, {"sp": "N", "t": "“Ταῦτα οὖν πάντα τὰ διαλογίσματα τὰ περὶ ψυχῆς ἀνάγων τις ἐπὶ τὰ πάθη καὶ τὰς αἰσθήσεις, μνημονεύων τῶν ἐν ἀρχῇ ῥηθέντων, ἱκανῶς κατόψεται τοῖς τύποις ἐμπεριειλημμένα εἰς τὸ κατὰ μέρος ἀπὸ τούτων ἐξακριβοῦσθαι βεβαίως.", "st": "10.68"}, {"sp": "N", "t": "“Ἀλλὰ μὴν καὶ τὰ σχήματα καὶ τὰ χρώματα καὶ τὰ μεγέθη καὶ τὰ βάρη καὶ ὅσα ἄλλα κατηγορεῖται σώματος ὡσανεὶ συμβεβηκότα ἢ πᾶσιν ἢ τοῖς ὁρατοῖς καὶ κατὰ τὴν αἴσθησιν αὐτὴν γνωστά, οὔθ’ ὡς καθ’ ἑαυτάς εἰσι φύσεις δοξαστέον—οὐ γὰρ δυνατὸν ἐπινοῆσαι τοῦτο— οὔτε ὅλως ὡς οὐκ εἰσίν, οὔθ’ ὡς ἕτερ’ ἄττα προσυπάρχοντα τούτῳ ἀσώματα, οὔθ’ ὡς μόρια τούτου, ἀλλ’ ὡς τὸ ὅλον σῶμα καθόλου ἐκ τούτων πάντων τὴν ἑαυτοῦ φύσιν ἔχον ἀίδιον, οὐχ οἷον δὲ εἶναι συμπεφορημένον — ὥσπερ ὅταν ἐξ αὐτῶν τῶν ὄγκων μεῖζον ἄθροισμα συστῇ ἤτοι τῶν πρώτων ἢ τῶν τοῦ ὅλου μεγεθῶν τοῦδέ τινος ἐλαττόνων,—ἀλλὰ μόνον, ὡς λέγω, ἐκ τούτων ἁπάντων τὴν ἑαυτοῦ φύσιν ἔχον ἀίδιον.", "st": "10.69"}, {"sp": "N", "t": "καὶ ἐπιβολὰς μὲν ἔχοντα ἰδίας πάντα ταῦτά ἐστι καὶ διαλήψεις, συμπαρακολουθοῦντος δὲ τοῦ ἀθρόου καὶ οὐθαμῇ ἀποσχιζομένου, ἀλλὰ κατὰ τὴν ἀθρόαν ἔννοιαν τοῦ σώματος κατηγορίαν εἰληφότος. “Καὶ μὴν καὶ τοῖς σώμασι συμπίπτει πολλάκις καὶ οὐκ ἀίδιον παρακολουθεῖν οὔτ’ ἐν τοῖς ἀοράτοις καὶ οὔτε ἀσώματα. ὥστε δὴ κατὰ τὴν πλείστην φορὰν τούτῳ τῷ ὀνόματι χρώμενοι φανερὰ ποιοῦμεν τὰ συμπτώματα οὔτε τὴν τοῦ ὅλου φύσιν ἔχειν, ὃ συλλαβόντες κατὰ τὸ ἀθρόον σῶμα προσαγορεύομεν, οὔτε τὴν τῶν ἀίδιον παρακολουθούντων, ὧν ἄνευ σῶμα οὐ δυνατὸν νοεῖσθαι. κατ’ ἐπιβολὰς δ’ ἄν τινας παρακολουθοῦντος τοῦ ἀθρόου ἕκαστα προσαγορευθείη, ἀλλ’ ὅτε δήποτε ἕκαστα συμβαίνοντα θεωρεῖται, οὐκ ἀίδιον τῶν συμπτωμάτων παρακολουθούντων. καὶ οὐκ ἐξελατέον ἐκ τοῦ ὄντος ταύτην τὴν ἐνάργειαν, ὅτι οὐκ ἔχει τὴν τοῦ ὅλου φύσιν ᾧ συμβαίνει ὃ δὴ καὶ σῶμα προσαγορεύομεν, οὐδὲ τὴν τῶν ἀίδιον παρακολουθούντων, οὐδ’ αὖ καθ’ αὑτὰ νομιστέον—οὐδὲ γὰρ τοῦτο διανοητὸν οὔτ’ ἐπὶ τούτων οὔτ’ ἐπὶ τῶν ἀίδιον συμβεβηκότων,—ἀλλ’ ὅπερ καὶ φαίνεται, συμπτώματα πάντα 〈κατὰ〉 τὰ σώματα νομιστέον, καὶ οὐκ ἀίδιον παρακολουθοῦντα οὐδ’ αὖ φύσεως καθ’ ἑαυτὰ τάγμα ἔχοντα, ἀλλ’ ὃν τρόπον αὐτὴ ἡ αἴσθησις τὴν ἰδιότητα ποιεῖ, θεωρεῖται.", "st": "10.70"}, {"sp": "N", "t": "“Καὶ μὴν καὶ τόδε γε δεῖ προσκατανοῆσαι σφοδρῶς· τὸν γὰρ δὴ χρόνον οὐ ζητητέον ὥσπερ καὶ τὰ λοιπά, ὅσα ἐν ὑποκειμένῳ ζητοῦμεν ἀνάγοντες ἐπὶ τὰς βλεπομένας παρ’ ἡμῖν αὐτοῖς προλήψεις, ἀλλ’ αὐτὸ τὸ ἐνάργημα, καθ’ ὃ τὸν πολὺν ἢ ὀλίγον χρόνον ἀναφωνοῦμεν, συγγενικῶς τοῦτο περιφέροντες, ἀναλογιστέον. καὶ οὔτε διαλέκτους ὡς βελτίους μεταληπτέον, ἀλλ’ αὐταῖς ταῖς ὑπαρχούσαις κατ’ αὐτοῦ χρηστέον, οὔτε ἄλλο τι κατ’ αὐτοῦ κατηγορητέον, ὡς τὴν αὐτὴν οὐσίαν ἔχοντος τῷ ἰδιώματι τούτῳ—καὶ γὰρ τοῦτο ποιοῦσί τινες — ἀλλὰ μόνον ᾧ συμπλέκομεν τὸ ἴδιον τοῦτο καὶ παραμετροῦμεν, μάλιστα ἐπιλογιστέον. καὶ γὰρ τοῦτο οὐκ ἀποδείξεως προσδεῖται ἀλλ’ ἐπιλογισμοῦ, ὅτι ταῖς ἡμέραις καὶ ταῖς νυξὶ συμπλέκομεν καὶ τοῖς τούτων μέρεσιν, ὡσαύτως δὲ καὶ τοῖς πάθεσι καὶ ταῖς ἀπαθείαις, καὶ κινήσεσι καὶ στάσεσιν, ἴδιόν τι σύμπτωμα περὶ ταῦτα πάλιν αὐτὸ τοῦτο ἐννοοῦντες, καθ’ ὃ χρόνον ὀνομάζομεν.", "st": "10.72"}, {"sp": "N", "t": "[φησὶ δὲ τοῦτο καὶ ἐν τῇ δευτέρᾳ Περὶ φύσεως καὶ ἐν τῇ Μεγάλῃ ἐπιτομῇ.] “Ἐπί τε τοῖς προειρημένοις τοὺς κόσμους δεῖ καὶ πᾶσαν σύγκρισιν πεπερασμένην τὸ ὁμοειδὲς τοῖς θεωρουμένοις πυκνῶς ἔχουσαν νομίζειν γεγονέναι ἀπὸ τοῦ ἀπείρου, πάντων τούτων ἐκ συστροφῶν ἰδίων ἀποκεκριμένων καὶ μειζόνων καὶ ἐλαττόνων· καὶ πάλιν διαλύεσθαι πάντα, τὰ μὲν θᾶττον, τὰ δὲ βραδύτερον, καὶ τὰ μὲν ὑπὸ τῶν τοιῶνδε, τὰ δὲ ὑπὸ τῶν τοιῶνδε τοῦτο πάσχοντα.", "st": "10.72b"}, {"sp": "N", "t": "[δῆλον οὖν ὡς καὶ φθαρτούς φησι τοὺς κόσμους, μεταβαλλόντων τῶν μερῶν. καὶ ἐν ἄλλοις τὴν γῆν τῷ ἀέρι ἐποχεῖσθαι.]", "st": "10.72c"}, {"sp": "N", "t": "“Ἔτι δὲ καὶ τοὺς κόσμους οὔτε ἐξ ἀνάγκης δεῖ νομίζειν ἕνα σχηματισμὸν ἔχοντας * * [ἀλλὰ καὶ διαφόρους αὐτοὺς ἐν τῇ ιβ’ Περὶ φύσεως αὐτός φησιν· οὓς μὲν γὰρ σφαιροειδεῖς, καὶ ᾠοειδεῖς ἄλλους, καὶ ἀλλοιοσχήμονας ἑτέρους·", "st": "10.74"}, {"sp": "N", "t": "οὐ μέντοι πᾶν σχῆμα ἔχειν. οὐδὲ ζῷα εἶναι ἀποκριθέντα ἀπὸ τοῦ ἀπείρου.] οὐδὲ γὰρ ἂν ἀποδείξειεν οὐδείς, ὡς 〈ἐν〉 μὲν τῷ τοιούτῳ καὶ οὐκ ἂν ἐμπεριελήφθη τὰ τοιαῦτα σπέρματα, ἐξ ὧν ζῷά τε καὶ φυτὰ καὶ τὰ λοιπὰ πάντα 〈τὰ〉 θεωρούμενα συνίσταται, ἐν δὲ τῷ τοιούτῳ οὐκ ἂν ἐδυνήθη. [ὡσαύτως δὲ καὶ ἐντραφῆναι. τὸν αὐτὸν δὲ τρόπον καὶ ἐπὶ γῆς νομιστέον.]", "st": "10.74b"}, {"sp": "N", "t": "“Ἀλλὰ μὴν ὑποληπτέον καὶ τὴν φύσιν πολλὰ καὶ παντοῖα ὑπὸ αὐτῶν τῶν πραγμάτων διδαχθῆναί τε καὶ ἀναγκασθῆναι· τὸν δὲ λογισμὸν τὰ ὑπὸ ταύτης παρεγγυηθέντα ὕστερον ἐπακριβοῦν καὶ προσεξευρίσκειν ἐν μὲν τισὶ θᾶττον, ἐν δὲ τισὶ βραδύτερον καὶ ἐν μὲν τισὶ περιόδοις καὶ χρόνοις 〈μείζους λαμβάνειν ἐπιδόσεις〉, ἐν δὲ τισὶ καὶ ἐλάττους. “Ὅθεν καὶ τὰ ὀνόματα ἐξ ἀρχῆς μὴ θέσει γενέσθαι, ἀλλ’ αὐτὰς τὰς φύσεις τῶν ἀνθρώπων καθ’ ἕκαστα ἔθνη ἴδια πάσχουσας πάθη καὶ ἰδία λαμβανούσας φαντάσματα ἰδίως τὸν ἀέρα ἐκπέμπειν στελλόμενον ὑφ’ ἑκάστων τῶν παθῶν καὶ τῶν φαντασμάτων, ὡς ἄν ποτε καὶ ἡ παρὰ τοὺς τόπους τῶν ἐθνῶν διαφορὰ ᾖ· ὕστερον δὲ κοινῶς καθ’ ἕκαστα ἔθνη τὰ ἴδια τεθῆναι πρὸς τὸ τὰς δηλώσεις ἧττον ἀμφιβόλους γενέσθαι ἀλλήλοις καὶ συντομωτέρως δηλουμένας· τινὰ δὲ καὶ οὐ συνορώμενα πράγματα εἰσφέροντας τοὺς συνειδότας παρεγγυῆσαί τινας φθόγγους ἀναγκασθέντας ἀναφωνῆσαι, τοὺς δὲ τῷ λογισμῷ ἑλομένους κατὰ τὴν πλείστην αἰτίαν οὕτως ἑρμηνεῦσαι.", "st": "10.75"}, {"sp": "N", "t": "“Καὶ μὴν ἐν τοῖς μετεώροις φορὰν καὶ τροπὴν καὶ ἔκλειψιν καὶ ἀνατολὴν καὶ δύσιν καὶ τὰ σύστοιχα τούτοις μήτε λειτουργοῦντός τινος νομίζειν δεῖ γενέσθαι καὶ διατάττοντος ἢ διατάξοντος καὶ ἅμα τὴν πᾶσαν μακαριότητα ἔχοντος μετ’ ἀφθαρσίας (οὐ γὰρ συμφωνοῦσιν πραγματεῖαι καὶ φροντίδες καὶ ὀργαὶ καὶ χάριτες μακαριότητι, ἀλλ’ ἐν ἀσθενείᾳ καὶ φόβῳ καὶ προσδεήσει τῶν πλησίον ταῦτα γίγνεται), μήτε αὖ πυρὸς ἀνάμματα συνεστραμμένου τὴν μακαριότητα κεκτημένα κατὰ βούλησιν τὰς κινήσεις ταύτας λαμβάνειν· ἀλλὰ πᾶν τὸ σέμνωμα τηρεῖν, κατὰ πάντα ὀνόματα φερόμενον ἐπὶ τὰς τοιαύτας ἐννοίας, ἵνα μηδ’ ὑπεναντίαι ἐξ αὐτῶν 〈γένωνται〉 τῷ σεμνώματι δόξαι· εἰ δὲ μή, τὸν μέγιστον τάραχον ἐν ταῖς ψυχαῖς αὐτὴ ἡ ὑπεναντιότης παρασκευάσει. ὅθεν δὴ κατὰ τὰς ἐξ ἀρχῆς ἐναπολήψεις τῶν συστροφῶν τούτων ἐν τῇ τοῦ κόσμου γενέσει δεῖ δοξάζειν καὶ τὴν ἀνάγκην ταύτην καὶ περίοδον συντελεῖσθαι.", "st": "10.77"}, {"sp": "N", "t": "“Καὶ μὴν καὶ τὸ τὴν ὑπὲρ τῶν κυριωτάτων αἰτίαν ἐξακριβῶσαι φυσιολογίας ἔργον εἶναι δεῖ νομίζειν, καὶ τὸ μακάριον ἐνταῦθα πεπτωκέναι καὶ ἐν τῷ τίνες φύσεις αἱ θεωρούμεναι κατὰ τὰ μετέωρα ταυτί, καὶ ὅσα συντείνει πρὸς τὴν εἰς τοῦτο ἀκρίβειαν. “Ἔτι τε οὐ τὸ πλεοναχῶς ἐν τοῖς τοιούτοις εἶναι καὶ τὸ ἐνδεχόμενον καὶ ἄλλως πως ἔχειν, ἀλλ’ ἁπλῶς μὴ εἶναι ἐν ἀφθάρτῳ καὶ μακαρίᾳ φύσει τῶν διάκρισιν ὑποβαλλόντων ἢ τάραχον μηθέν· καὶ τοῦτο καταλαβεῖν τῇ διανοίᾳ ἔστιν ἁπλῶς εἶναι. “Τὸ δ’ ἐν τῇ ἱστορίᾳ πεπτωκός, τῆς δύσεως καὶ ἀνατολῆς καὶ τροπῆς καὶ ἐκλείψεως καὶ ὅσα συγγενῆ τούτοις μηθὲν ἔτι πρὸς τὸ μακάριον τὰς γνώσεις συντείνειν, ἀλλ’ ὁμοίως τοὺς φόβους ἔχειν τοὺς ταῦτα κατειδότας, τίνες δ’ αἱ φύσεις ἀγνοοῦντας καὶ τίνες αἱ κυριώταται αἰτίαι, καὶ εἰ μὴ προσῄδεισαν ταῦτα· τάχα δὲ καὶ πλείους, ὅταν τὸ θάμβος ἐκ τῆς τούτων προσκατανοήσεως μὴ δύνηται τὴν λύσιν λαμβάνειν καὶ τὴν περὶ τῶν κυριωτάτων οἰκονομίαν.", "st": "10.78"}, {"sp": "N", "t": "“Διὸ δὴ κἂν πλείους αἰτίας εὑρίσκωμεν τροπῶν καὶ δύσεων καὶ ἀνατολῶν καὶ ἐκλείψεων καὶ τῶν τοιουτοτρόπων, ὥσπερ καὶ ἐν τοῖς κατὰ μέρος γινομένοις ἦν, οὐ δεῖ νομίζειν τὴν ὑπὲρ τούτων χρείαν ἀκρίβειαν μὴ ἀπειληφέναι, ὅση πρὸς τὸ ἀτάραχον καὶ μακάριον ἡμῶν συντείνει. ὥστε παραθεωροῦντας ποσαχῶς παρ’ ἡμῖν τὸ ὅμοιον γίνεται, αἰτιολογητέον ὑπέρ τε τῶν μετεώρων καὶ παντὸς τοῦ ἀδήλου, καταφρονοῦντας τῶν οὔτε τὸ μοναχῶς ἔχον ἢ γινόμενον γνωριζόντων οὔτε τὸ πλεοναχῶς συμβαῖνον, τὴν ἐκ τῶν ἀποστημάτων φαντασίαν παριδόντων, ἔτι τε ἀγνοούντων καὶ ἐν ποίοις οὐκ ἐστιν ἀταρακτῆσαι 〈καὶ ἐν ποίοις ὁμοίως ἀταρακτῆσαι.〉 ἂν οὖν οἰώμεθα καὶ ὡδί πως ἐνδεχόμενον αὐτὸ γίνεσθαι, αὐτὸ τὸ ὅτι πλεοναχῶς γίνεται γνωρίζοντες, ὥσπερ κἂν ὅτι ὡδί πως γίνεται εἴδωμεν, ἀταρακτήσομεν.", "st": "10.80"}, {"sp": "N", "t": "“Ἐπὶ δὲ τούτοις ὅλως ἅπασιν ἐκεῖνο δεῖ κατανοεῖν, ὅτι τάραχος ὁ κυριώτατος ταῖς ἀνθρωπίναις ψυχαῖς γίνεται ἐν τῷ ταῦτά τε μακάρια δοξάζειν 〈εἶναι〉 καὶ ἄφθαρτα, καὶ ὑπεναντίας ἔχειν τούτῳ βουλήσεις ἅμα καὶ πράξεις καὶ αἰτίας, καὶ ἐν τῷ αἰώνιόν τι δεινὸν ἀεὶ προσδοκᾶν ἢ ὑποπτεύειν κατὰ τοὺς μύθους εἴ τε καὶ αὐτὴν τὴν ἀναισθησίαν τὴν ἐν τῷ τεθνάναι φοβουμένους ὥσπερ οὖσαν κατ’ αὐτούς, καὶ ἐν τῷ μὴ δόξαις ταῦτα πάσχειν ἀλλ’ ἀλόγῳ γέ τινι παραστάσει, ὅθεν μὴ ὁρίζοντας τὸ δεινὸν τὴν ἴσην ἢ καὶ ἐπιτεταμένην ταραχὴν λαμβάνειν τῷ εἰκαίως δοξάζοντι ταῦτα· ἡ δὲ ἀταραξία τὸ τούτων πάντων ἀπολελύσθαι καὶ συνεχῆ μνήμην ἔχειν τῶν ὅλων καὶ κυριωτάτων. “Ὅθεν τοῖς πάθεσι προσεκτέον τοῖς παροῦσι, κατὰ μὲν τὸ κοινὸν ταῖς κοιναῖς, κατὰ δὲ τὸ ἴδιον ταῖς ἰδίαις, καὶ πάσῃ τῇ παρούσῃ καθ’ ἕκαστον τῶν κριτηρίων ἐναργείᾳ. ἂν γὰρ τούτοις προσέχωμεν, τὸ ὅθεν ὁ τάραχος καὶ ὁ φόβος ἐγίνετο ἐξαιτιολογήσομεν ὀρθῶς καὶ ἀπολύσομεν, ὑπέρ τε μετεώρων αἰτιολογοῦντες καὶ τῶν λοιπῶν τῶν ἀεὶ παρεμπιπτόντων, ὅσα φοβεῖ τοὺς λοιποὺς ἐσχάτως.", "st": "10.81"}, {"sp": "N", "t": "“Ταῦτά σοι, ὦ Ἡρόδοτε, ἔστι κεφαλαιωδέστατα ὑπὲρ τῆς τῶν ὅλων φύσεως ἐπιτετμημένα. ὥστ’ ἐὰν γένηται δυνατὸς ὁ λόγος οὗτος κατασχεθεὶς μετ’ ἀκριβείας, οἶμαι, ἐὰν μὴ καὶ πρὸς ἅπαντα βαδίσῃ τις τῶν κατὰ μέρος ἀκριβωμάτων, ἀσύμβλητον αὐτὸν πρὸς τοὺς λοιποὺς ἀνθρώπους ἁδρότητα λήψεσθαι. καὶ γὰρ καὶ καθαρὰ ἀφ’ ἑαυτοῦ ποιήσει πολλὰ τῶν κατὰ μέρος ἐξακριβουμένων κατὰ τὴν ὅλην πραγματείαν ἡμῖν, καὶ αὐτὰ ταῦτα ἐν μνήμῃ τιθέμενα συνεχῶς βοηθήσει. “Τοιαῦτα γάρ ἐστιν, ὥστε καὶ τοὺς κατὰ μέρος ἤδη ἐξακριβοῦντας ἱκανῶς ἢ καὶ τελείως, εἰς τὰς τοιαύτας ἀναλύοντας ἐπιβολάς, τὰς πλείστας τῶν περιοδειῶν ὑπὲρ τῆς ὅλης φύσεως ποιεῖσθαι· ὅσοι δὲ μὴ παντελῶς τῶν ἀποτελουμένων εἰσίν, ἐκ τούτων καὶ κατὰ τὸν ἄνευ φθόγγων τρόπον τὴν ἅμα νοήματι περίοδον τῶν κυριωτάτων πρὸς γαληνισμὸν ποιοῦνται.", "st": "10.83"}, {"sp": "N", "t": "Καὶ ἥδε μέν ἐστιν αὐτῷ ἐπιστολὴ περὶ τῶν φυσικῶν.", "st": "10.83b"}, {"sp": "N", "t": "περὶ δὲ τῶν μετεώρων ἥδε. “Ἐπίκουρος Πυθοκλεῖ χαίρειν.", "st": "10.83c"}, {"sp": "N", "t": "“Ἤνεγκέ μοι Κλέων ἐπιστολὴν παρά σου, ἐν ᾗ φιλοφρονούμενός τε περὶ ἡμᾶς διετέλεις ἀξίως τῆς ἡμετέρας περὶ σεαυτὸν σπουδῆς καὶ οὐκ ἀπιθάνως ἐπειρῶ μνημονεύειν τῶν εἰς μακάριον βίον συντεινόντων διαλογισμῶν, ἐδέου τε σεαυτῷ περὶ τῶν μετεώρων σύντομον καὶ εὐπερίγραφον διαλογισμὸν ἀποστεῖλαι, ἵνα ῥᾳδίως μνημονεύῃς· τὰ γὰρ ἐν ἄλλοις ἡμῖν γεγραμμένα δυσμνημόνευτα εἶναι, καί τοι, ὡς ἔφης, συνεχῶς αὐτὰ βαστάζεις.", "st": "10.84"}, {"sp": "N", "t": "ἡμεῖς δὲ ἡδέως τέ σου τὴν δέησιν ἀπεδεξάμεθα καὶ ἐλπίσιν ἡδείαις συνεσχέθημεν. γράψαντες οὖν τὰ λοιπὰ πάντα συντελοῦμεν ἅπερ ἠξίωσας πολλοῖς καὶ ἄλλοις ἐσόμενα χρήσιμα τὰ διαλογίσματα ταῦτα, καὶ μάλιστα τοῖς νεωστὶ φυσιολογίας γνησίου γεγευμένοις καὶ τοῖς εἰς ἀσχολίας βαθυτέρας τῶν ἐγκυκλίων τινὸς ἐμπεπλεγμένοις. καλῶς δὴ αὐτὰ διάλαβε, καὶ διὰ μνήμης ἔχων ὀξέως αὐτὰ περιόδευε μετὰ τῶν λοιπῶν ὧν ἐν τῇ μικρᾷ ἐπιτομῇ πρὸς Ἡρόδοτον ἀπεστείλαμεν.", "st": "10.85"}, {"sp": "N", "t": "“Πρῶτον μὲν οὖν μὴ ἄλλο τι τέλος ἐκ τῆς περὶ μετεώρων γνώσεως εἴτε κατὰ συναφὴν λεγομένων εἴτε αὐτοτελῶς νομίζειν εἶναι ἤπερ ἀταραξίαν καὶ πίστιν βέβαιον, καθάπερ καὶ ἐπὶ τῶν λοιπῶν.", "st": "10.85b"}, {"sp": "N", "t": "μήτε τὸ ἀδύνατον παραβιάζεσθαι μήτε ὁμοίαν κατὰ πάντα τὴν θεωρίαν ἔχειν ἢ τοῖς περὶ βίων λόγοις ἢ τοῖς κατὰ τὴν τῶν ἄλλων φυσικῶν προβλημάτων κάθαρσιν, οἷον ὅτι τὸ πᾶν σώματα καὶ ἀναφὴς φύσις ἐστίν, ἢ ὅτι ἄτομα 〈τὰ〉 στοιχεῖα, καὶ πάντα τὰ τοιαῦτα ὅσα μοναχὴν ἔχει τοῖς φαινομένοις συμφωνίαν·", "st": "10.86"}, {"sp": "N", "t": "ὅπερ ἐπὶ τῶν μετεώρων οὐχ ὑπάρχει, ἀλλὰ ταῦτά γε πλεοναχὴν ἔχει καὶ τῆς γενέσεως αἰτίαν καὶ τῆς οὐσίας ταῖς αἰσθήσεσι σύμφωνον κατηγορίαν. “Οὐ γὰρ κατὰ ἀξιώματα κενὰ καὶ νομοθεσίας φυσιολογητέον, ἀλλ’ ὡς τὰ φαινόμενα ἐκκαλεῖται· οὐ γὰρ ἤδη ἀλογίας καὶ κενῆς δόξης ὁ βίος ἡμῶν ἔχει χρείαν, ἀλλὰ τοῦ ἀθορύβως ἡμᾶς ζῆν.", "st": "10.87"}, {"sp": "N", "t": "πάντα μὲν οὖν γίνεται ἀσείστως καί, πάντων κατὰ πλεοναχὸν τρόπον ἐκκαθαιρομένων, συμφώνως τοῖς φαινομένοις, ὅταν τις τὸ πιθανολογούμενον ὑπὲρ αὐτῶν δεόντως καταλίπῃ· ὅταν δέ τις τὸ μὲν ἀπολίπῃ, τὸ δὲ ἐκβάλῃ ὁμοίως σύμφωνον ὂν τῷ φαινομένῳ, δῆλον ὅτι καὶ ἐκ παντὸς ἐκπίπτει φυσιολογήματος ἐπὶ δὲ τὸν μῦθον καταρρεῖ.", "st": "10.87b"}, {"sp": "N", "t": "σημεῖα δὲ ἐπὶ τῶν ἐν τοῖς μετεώροις συντελουμένων φέρειν τῶν παρ’ ἡμῖν τινα φαινομένων, ἃ θεωρεῖται ᾗ ὑπάρχει, καὶ οὐ τὰ ἐν τοῖς μετεώροις φαινόμενα· ταῦτα γὰρ ἐνδέχεται πλεοναχῶς γενέσθαι. τὸ μέντοι φάντασμα ἑκάστου τηρητέον καὶ ἔτι τὰ συναπτόμενα τούτῳ διαιρετέον, ἃ οὐκ ἀντιμαρτυρεῖται τοῖς παρ’ ἡμῖν γινομένοις πλεοναχῶς συντελεῖσθαι.", "st": "10.88"}, {"sp": "N", "t": "“Κόσμος ἐστὶ περιοχή τις οὐρανοῦ, ἄστρα τε καὶ γῆν καὶ πάντα τὰ φαινόμενα περιέχουσα, ἀποτομὴν ἔχουσα ἀπὸ τοῦ ἀπείρου καὶ λήγουσα [καὶ καταλήγουσα ἐν πέρατι ἢ ἀραιῷ ἢ πυκνῷ καὶ οὗ λυομένου πάντα τὰ ἐν αὐτῷ σύγχυσιν λήψεται.] ἢ ἐν περιαγομένῳ ἢ ἐν στάσιν ἔχοντι καὶ στρογγύλην ἢ τρίγωνον ἢ οἵαν δήποτε περιγραφήν· πανταχῶς γὰρ ἐνδέχεται· τῶν γὰρ φαινομένων οὐδὲν ἀντιμαρτυρεῖ 〈ἐν〉 τῷδε τῷ κόσμῳ, ἐν ᾧ λῆγον οὐκ ἔστι καταλαβεῖν. “Ὅτι δὲ καὶ τοιοῦτοι κόσμοι εἰσὶν ἄπειροι τὸ πλῆθος ἔστι καταλαβεῖν, καὶ ὅτι καὶ ὁ τοιοῦτος δύναται κόσμος γίνεσθαι καὶ ἐν κόσμῳ καὶ μετακοσμίῳ, ὃ λέγομεν μεταξὺ κόσμων διάστημα, ἐν πολυκένῳ τόπῳ καὶ οὐκ ἐν μεγάλῳ εἰλικρινεῖ καὶ κενῷ, καθάπερ τινές φασιν, ἐπιτηδείων τινῶν σπερμάτων ῥυέντων ἀφ’ ἑνὸς κόσμου ἢ μετακοσμίου ἢ καὶ ἀπὸ πλειόνων κατὰ μικρὸν προσθέσεις τε καὶ διαρθρώσεις καὶ μεταστάσεις ποιούντων ἐπ’ ἄλλον τόπον, ἐὰν οὕτω τύχῃ, καὶ ἐπαρδεύσεις ἐκ τῶν ἐχόντων ἐπιτηδείως ἕως τελειώσεως καὶ διαμονῆς ἐφ’ ὅσον τὰ ὑποβληθέντα θεμέλια τὴν προσδοχὴν δύναται ποιεῖσθαι.", "st": "10.89"}, {"sp": "N", "t": "οὐ γὰρ ἀθροισμὸν δεῖ μόνον γενέσθαι οὐδὲ δῖνον ἐν ᾧ ἐνδέχεται κόσμον γίνεσθαι κενῷ κατὰ τὸ δοξαζόμενον ἐξ ἀνάγκης αὔξεσθαί τε, ἕως ἂν ἑτέρῳ προσκρούσῃ, καθάπερ τῶν φυσικῶν καλουμένων φησί τις· τοῦτο γὰρ μαχόμενόν ἐστι τοῖς φαινομένοις.", "st": "10.90"}, {"sp": "N", "t": "“Ἥλιός τε καὶ σελήνη καὶ τὰ λοιπὰ ἄστρα οὐ καθ’ ἑαυτὰ γενόμενα ὕστερον ἐμπεριελαμβάνετο ὑπὸ τοῦ κόσμου [καὶ ὅσα γε δὴ σῴζει], ἀλλ’ εὐθὺς διεπλάττετο καὶ αὔξησιν ἐλάμβανεν [ὁμοίως δὲ καὶ γῆ καὶ θάλαττα] κατὰ προσκρίσεις καὶ δινήσεις λεπτομερῶν τινων φύσεων, ἤτοι πνευματικῶν ἢ πυροειδῶν ἢ συναμφοτέρων· καὶ γὰρ ταῦτα οὕτως ἡ αἴσθησις ὑποβάλλει.", "st": "10.90b"}, {"sp": "N", "t": "“Τὸ δὲ μέγεθος ἡλίου τε καὶ τῶν λοιπῶν ἄστρων κατὰ μὲν τὸ πρὸς ἡμᾶς τηλικοῦτόν ἐστιν ἡλίκον φαίνεται·", "st": "10.91"}, {"sp": "N", "t": "[τοῦτο καὶ ἐν τῇ ια’ Περὶ φύσεως· εἰ γάρ, φησί, τὸ μέγεθος διὰ τὸ διάστημα ἀπεβεβλήκει, πολλῷ μᾶλλον ἂν τὴν χρόαν.", "st": "10.91b"}, {"sp": "N", "t": "ἄλλο γὰρ τούτῳ συμμετρότερον διάστημα οὐθέν ἐστι.] κατὰ δὲ τὸ καθ’ αὑτὸ ἤτοι μεῖζον τοῦ ὁρωμένου ἢ μικρῷ ἔλαττον ἢ τηλικοῦτον τυγχάνει. οὕτω γὰρ καὶ τὰ παρ’ ἡμῖν πυρὰ ἐξ ἀποστήματος θεωρούμενα κατὰ τὴν αἴσθησιν θεωρεῖται. καὶ πᾶν δὲ εἰς τοῦτο τὸ μέρος ἔνστημα ῥᾳδίως διαλυθήσεται, ἐάν τις τοῖς ἐναργήμασι προσέχῃ, ὅπερ ἐν τοῖς Περὶ φύσεως βιβλίοις δείκνυμεν.", "st": "10.91c"}, {"sp": "N", "t": "ἀνατολὰς καὶ δύσεις ἡλίου καὶ σελήνης καὶ τῶν λοιπῶν ἄστρων καὶ κατὰ ἄναψιν γενέσθαι δυνατὸν καὶ σβέσιν, τοιαύτης οὔσης περιστάσεως καὶ καθ’ ἑκατέρους τοὺς τόπους, ὥστε τὰ προειρημένα ἀποτελεῖσθαι· οὐδὲν γὰρ τῶν φαινομένων ἀντιμαρτυρεῖ. καὶ κατ’ ἐμφάνειάν τε ὑπὲρ γῆς καὶ πάλιν ἐπιπροσθέτησιν τὸ προειρημένον δύναιτ’ ἂν συντελεῖσθαι· οὐδὲ γάρ τι τῶν φαινομένων ἀντιμαρτυρεῖ.", "st": "10.92"}, {"sp": "N", "t": "τάς τε κινήσεις αὐτῶν οὐκ ἀδύνατον μὲν γίνεσθαι κατὰ τὴν τοῦ ὅλου οὐρανοῦ δίνην, ἢ τούτου μὲν στάσιν, αὐτῶν δὲ δίνην κατὰ τὴν ἐξ ἀρχῆς ἐν τῇ γενέσει τοῦ κόσμου ἀνάγκην ἀπογεννηθεῖσαν ἐπ’ ἀνατολῇ· * * *〈σφοδρο〉τάτῃ θερμασίᾳ κατά τινα ἐπινέμησιν τοῦ πυρὸς ἀεὶ ἐπὶ τοὺς ἑξῆς τόπους ἰόντος.", "st": "10.93"}, {"sp": "N", "t": "“Τροπὰς ἡλίου καὶ σελήνης ἐνδέχεται μὲν γίνεσθαι κατὰ λόξωσιν οὐρανοῦ οὕτω τοῖς χρόνοις κατηναγκασμένου· ὁμοίως δὲ καὶ κατὰ ἀέρος ἀντέξωσιν ἢ καὶ ὕλης ἀεὶ ἐπιτηδείας τῆς μὲν ἐχομένης ἐμπιπραμένης τῆς δ’ ἐκλιπούσης· ἢ καὶ ἐξ ἀρχῆς τοιαύτην δίνην κατειληθῆναι τοῖς ἄστροις τούτοις, ὥσθ’ οἷόν τιν’ ἕλικα κινεῖσθαι. πάντα γὰρ τὰ τοιαῦτα καὶ τὰ τούτοις συγγενῆ οὐθενὶ τῶν ἐναργημάτων διαφωνεῖ, ἐάν τις ἀεὶ ἐπὶ τῶν τοιούτων μερῶν, ἐχόμενος τοῦ δυνατοῦ, εἰς τὸ σύμφωνον τοῖς φαινομένοις ἕκαστον τούτων δύνηται ἐπάγειν, μὴ φοβούμενος τὰς ἀνδραποδώδεις ἀστρολόγων τεχνιτείας.", "st": "10.93b"}, {"sp": "N", "t": "“Κένωσίς τε σελήνης καὶ πάλιν πλήρωσις καὶ κατὰ στροφὴν τοῦ σώματος τούτου δύναιτ’ ἂν γίνεσθαι καὶ κατὰ σχηματισμοὺς ἀέρος ὁμοίως, ἔτι τε καὶ κατ’ ἐμπροσθετήσεις καὶ κατὰ πάντας τρόπους, καθ’ οὓς καὶ τὰ παρ’ ἡμῖν φαινόμενα ἐκκαλεῖται εἰς τὰς τοῦ εἴδους τούτου ἀποδόσεις, ἐὰν μή τις τὸν μοναχῆ τρόπον κατηγαπηκὼς τοὺς ἄλλους κενῶς ἀποδοκιμάζῃ, οὐ τεθεωρηκὼς τί δυνατὸν ἀνθρώπῳ θεωρῆσαι καὶ τί ἀδύνατον, καὶ διὰ τοῦτ’ ἀδύνατα θεωρεῖν ἐπιθυμῶν.", "st": "10.94"}, {"sp": "N", "t": "ἔτι τε ἐνδέχεται τὴν σελήνην ἐξ ἑαυτῆς ἔχειν τὸ φῶς, ἐνδέχεται δὲ ἀπὸ τοῦ ἡλίου. καὶ γὰρ παρ’ ἡμῖν θεωρεῖται πολλὰ μὲν ἐξ ἑαυτῶν ἔχοντα, πολλὰ δὲ ἀφ’ ἑτέρων. καὶ οὐθὲν ἐμποδοστατεῖ τῶν ἐν τοῖς μετεώροις φαινομένων, ἐάν τις τοῦ πλεοναχοῦ τρόπου ἀεὶ μνήμην ἔχῃ καὶ τὰς ἀκολούθους αὐτοῖς ὑποθέσεις ἅμα καὶ αἰτίας συνθεωρῇ καὶ μὴ ἀναβλέπων εἰς τὰ ἀνακόλουθα ταῦτ’ ὀγκοῖ ματαίως καὶ καταρρέπῃ ἄλλοτε ἄλλως ἐπὶ τὸν μοναχὸν τρόπον.", "st": "10.95"}, {"sp": "N", "t": "ἡ δὲ ἔμφασις τοῦ προσώπου ἐν αὐτῇ δύναται μὲν γίνεσθαι καὶ κατὰ παραλλαγὴν μερῶν καὶ κατ’ ἐπιπροσθέτησιν, καὶ ὅσοι ποτ’ ἂν τρόποι θεωροῖντο τὸ σύμφωνον τοῖς φαινομένοις κεκτημένοι. ἐπὶ πάντων γὰρ τῶν μετεώρων τὴν τοιαύτην ἴχνευσιν οὐ προετέον. ἢν γάρ τις ᾖ μαχόμενος τοῖς ἐναργήμασιν, οὐδέποτε δυνήσεται ἀταραξίας γνησίου μεταλαβεῖν.", "st": "10.96"}, {"sp": "N", "t": "“Ἔκλειψις ἡλίου καὶ σελήνης δύναται μὲν γίνεσθαι καὶ κατὰ σβένσιν, καθάπερ καὶ παρ’ ἡμῖν τοῦτο θεωρεῖται γιγνόμενον· καὶ ἤδη καὶ κατ’ ἐπιπροσθέτησιν ἄλλων τινῶν, ἢ γῆς ἢ ἀοράτου τινὸς ἑτέρου τοιούτου. καὶ ὧδε τοὺς οἰκείους ἀλλήλοις τρόπους συνθεωρητέον, καὶ τὰς ἅμα συγκυρήσεις τινῶν ὅτι οὐκ ἀδύνατον γίνεσθαι.", "st": "10.96b"}, {"sp": "N", "t": "[ἐν δὲ τῇ ιβ’ Περὶ φύσεως ταῦτα λέγει καὶ πρός, ἥλιον ἐκλείπειν σελήνης ἐπισκοτούσης, σελήνην δὲ τοῦ τῆς γῆς σκιάσματος, ἀλλὰ καὶ κατ’ ἀναχώρησιν.", "st": "10.96c"}, {"sp": "N", "t": "τοῦτο δὲ καὶ Διογένης ὁ Ἐπικούρειος ἐν τῇ α′ τῶν Ἐπιλέκτων.] “Ἔτι τε τάξις περιόδου, καθάπερ ἔνια καὶ παρ’ ἡμῖν τῶν τυχόντων γίνεται, λαμβανέσθω· καὶ ἡ θεία φύσις πρὸς ταῦτα μηδαμῇ προσαγέσθω, ἀλλ’ ἀλειτούργητος διατηρείσθω καὶ ἐν τῇ πάσῃ μακαριότητι· ὡς εἰ τοῦτο μὴ πραχθήσεται, ἅπασα ἡ περὶ τῶν μετεώρων αἰτιολογία ματαία ἔσται, καθάπερ τισὶν ἤδη ἐγένετο οὐ δυνατοῦ τρόπου ἐφαψαμένοις, εἰς δὲ τὸ μάταιον ἐκπεσοῦσι τῷ καθ’ ἕνα τρόπον μόνον οἴεσθαι γίνεσθαι τοὺς δ’ ἄλλους ἅπαντας τοὺς κατὰ τὸ ἐνδεχόμενον ἐκβάλλειν εἴς τε τὸ ἀδιανόητον φερομένους καὶ τὰ φαινόμενα, ἃ δεῖ σημεῖα ἀποδέχεσθαι, μὴ δυναμένους συνθεωρεῖν.", "st": "10.97"}, {"sp": "N", "t": "“Μήκη νυκτῶν καὶ ἡμερῶν παραλλάττοντα καὶ παρὰ τὸ ταχείας ἡλίου κινήσεις γίνεσθαι καὶ πάλιν βραδείας ὑπὲρ γῆς παρὰ τὰ μήκη τόπων παραλλάττοντα καὶ τόπους τινὰς περαιοῦν τάχιον ἢ βραδύτερον, ὡς καὶ παρ’ ἡμῖν τινα θεωρεῖται, οἷς συμφώνως δεῖ λέγειν ἐπὶ τῶν μετεώρων. οἱ δὲ τὸ ἓν λαμβάνοντες τοῖς τε φαινομένοις μάχονται καὶ τοῦ ᾗ δυνατὸν ἀνθρώπῳ θεωρῆσαι διαπεπτώκασιν.", "st": "10.98"}, {"sp": "N", "t": "“Ἐπισημασίαι δύνανται γίνεσθαι καὶ κατὰ συγκυρήσεις καιρῶν, καθάπερ ἐν τοῖς ἐμφανέσι παρ’ ἡμῖν ζῴοις, καὶ παρ’ ἑτεροιώσεις ἀέρος καὶ μεταβολάς. ἀμφότερα γὰρ ταῦτα οὐ μάχεται τοῖς φαινομένοις· ἐπὶ δὲ ποίοις παρὰ τοῦτο ἢ τοῦτο τὸ αἴτιον γίνεται οὐκ ἔστι συνιδεῖν.", "st": "10.99"}, {"sp": "N", "t": "“Νέφη δύναται γίνεσθαι καὶ συνίστασθαι καὶ παρὰ πιλήσεις ἀέρος πνευμάτων συνώσει, καὶ παρὰ περιπλοκὰς ἀλληλούχων ἀτόμων καὶ ἐπιτηδείων εἰς τὸ τοῦτο τελέσαι καὶ κατὰ ῥευμάτων συλλογὴν ἀπό τε γῆς καὶ ὑδάτων· καὶ κατ’ ἄλλους δὲ τρόπους πλείους αἱ τῶν τοιούτων συστάσεις οὐκ ἀδυνατοῦσι συντελεῖσθαι. ἤδη δ’ ἀπ’ αὐτῶν ᾗ μὲν θλιβομένων, ᾗ δὲ μεταβαλλόντων ὕδατα δύναται συντελεῖσθαι, ἔτι τε ῥευμάτων κατ’ ἀποφορὰν ἀπὸ ἐπιτηδείων τόπων δι’ ἀέρος κινουμένων, βιαιοτέρας ἐπαρδεύσεως γινομένης ἀπό τινων ἀθροισμάτων ἐπιτηδείων εἰς τὰς τοιαύτας ἐκπέμψεις.", "st": "10.100"}, {"sp": "N", "t": "βροντὰς ἐνδέχεται γίνεσθαι καὶ κατὰ πνεύματος ἐν τοῖς κοιλώμασι τῶν νεφῶν ἀνείλησιν, καθάπερ ἐν τοῖς ἡμετέροις ἀγγείοις, καὶ παρὰ πυρὸς πεπνευματωμένου βόμβον ἐν αὐτοῖς, καὶ κατὰ ῥήξεις δὲ νεφῶν καὶ διαστάσεις, καὶ κατὰ παρατρίψεις νεφῶν καὶ κατάξεις πῆξιν εἰληφότων κρυσταλλοειδῆ. καὶ τὸ ὅλον καὶ τοῦτο τὸ μέρος πλεοναχῶς γίνεσθαι λέγειν ἐκκαλεῖται τὰ φαινόμενα.", "st": "10.100b"}, {"sp": "N", "t": "καὶ ἀστραπαὶ δ’ ὡσαύτως γίνονται κατὰ πλείους τρόπους· καὶ γὰρ κατὰ παράτριψιν καὶ σύγκρουσιν νεφῶν ὁ πυρὸς ἀποτελεστικὸς σχηματισμὸς ἐξολισθαίνων ἀστραπὴν γεννᾷ· καὶ κατ’ ἐκριπισμὸν ἐκ τῶν νεφῶν ὑπὸ πνευμάτων τῶν τοιούτων σωμάτων ἃ τὴν λαμπηδόνα ταύτην παρασκευάζει, καὶ κατ’ ἐκπιασμόν, θλίψεως τῶν νεφῶν γινομένης, εἴθ’ ὑπ’ ἀλλήλων εἴθ’ ὑπὸ πνευμάτων· καὶ κατ’ ἐμπερίληψιν δὲ τοῦ ἀπὸ τῶν ἄστρων κατεσπαρμένου φωτός, εἶτα συνελαυνομένου ὑπὸ τῆς κινήσεως νεφῶν τε καὶ πνευμάτων καὶ διεκπίπτοντος διὰ τῶν νεφῶν· ἢ κατὰ διήθησιν 〈διὰ〉 τῶν νεφῶν τοῦ λεπτομερεστάτου φωτός, [ᾗ ἀπὸ τοῦ πυρὸς νέφη συνεφλέχθαι καὶ τὰς βροντὰς ἀποτελεῖσθαι] καὶ τὴν τούτου κίνησιν· καὶ κατὰ τὴν τοῦ πνεύματος ἐκπύρωσιν τὴν γινομένην διά τε συντονίαν φορᾶς καὶ διὰ σφοδρὰν κατείλησιν· καὶ κατὰ ῥήξεις δὲ νεφῶν ὑπὸ πνευμάτων ἔκπτωσίν τε πυρὸς ἀποτελεστικῶν ἀτόμων καὶ τὸ τῆς ἀστραπῆς φάντασμα ἀποτελουσῶν. καὶ κατ’ ἄλλους δὲ πλείους τρόπους ῥᾳδίως ἔσται καθορᾶν ἐχόμενον ἀεὶ τῶν φαινομένων καὶ τὸ τούτοις ὅμοιον δυνάμενον συνθεωρεῖν.", "st": "10.101"}, {"sp": "N", "t": "προτερεῖ δὲ ἀστραπὴ βροντῆς ἐν τοιᾷδέ τινι περιστάσει νεφῶν καὶ διὰ τὸ ἅμα τῷ τὸ πνεῦμα ἐμπίπτειν ἐξωθεῖσθαι τὸν ἀστραπῆς ἀποτελεστικὸν σχηματισμόν, ὕστερον δὲ τὸ πνεῦμα ἀνειλούμενον τὸν βόμβον ἀποτελεῖν τοῦτον· καὶ κατ’ ἔμπτωσιν δὲ ἀμφοτέρων ἅμα, τῷ τάχει συντονωτέρῳ κεχρῆσθαι πρὸς ἡμᾶς τὴν ἀστραπήν, ὑστερεῖν δὲ τὴν βροντήν, καθά περ ἐπ’ ἐνίων ἐξ ἀποστήματος θεωρουμένων καὶ πληγάς τινας ποιουμένων.", "st": "10.103"}, {"sp": "N", "t": "κεραυνοὺς ἐνδέχεται γίνεσθαι καὶ κατὰ πλείονας πνευμάτων συλλογὰς καὶ κατείλησιν ἰσχυράν τε ἐκπύρωσιν· καὶ κατάρρηξιν μέρους καὶ ἔκπτωσιν ἰσχυροτέραν αὐτοῦ ἐπὶ τοὺς κάτω τόπους, τῆς ῥήξεως γινομένης διὰ τὸ τοὺς ἑξῆς τόπους πυκνοτέρους εἶναι διὰ πίλησιν νεφῶν· καὶ κατὰ αὐτὴν δὲ τὴν τοῦ πυρὸς ἔκπτωσιν ἀνειλουμένου, καθὰ καὶ βροντὴν ἐνδέχεται γίνεσθαι, πλείονος γενομένου πυρὸς καὶ πνευματωθέντος ἰσχυρότερον καὶ ῥήξαντος τὸ νέφος διὰ τὸ μὴ δύνασθαι ὑποχωρεῖν εἰς τὰ ἑξῆς, τῷ πίλησιν γίνεσθαι [τὸ μὲν πολὺ πρὸς ὄρος τι ὑψηλόν, ἐν ᾧ μάλιστα κεραυνοὶ πίπτουσιν], ἀεὶ πρὸς ἄλληλα. καὶ κατ’ ἄλλους δὲ τρόπους πλείονας ἐνδέχεται κεραυνοὺς ἀποτελεῖσθαι· μόνον ὁ μῦθος ἀπέστω· ἀπέσται δέ, ἐάν τις καλῶς τοῖς φαινομένοις ἀκολουθῶν περὶ τῶν ἀφανῶν σημειῶται.", "st": "10.104"}, {"sp": "N", "t": "“Πρηστῆρας ἐνδέχεται γίνεσθαι καὶ κατὰ κάθεσιν νέφους εἰς τοὺς κάτω τόπους στυλοειδῶς ὑπὸ πνεύματος ἀθρόου ὠσθέντος καὶ διὰ τοῦ πνεύματος πολλοῦ φερομένου, ἅμα καὶ τὸ νέφος εἰς τὸ πλάγιον ὠθοῦντος τοῦ ἐκτὸς πνεύματος· καὶ κατὰ περίστασιν δὲ πνεύματος εἰς κύκλον, ἀέρος τινὸς ἐπισυνωθουμένου ἄνωθεν· καὶ ῥύσεως πολλῆς πνευμάτων γενομένης καὶ οὐ δυναμένης εἰς τὰ πλάγια διαρρυῆναι διὰ τὴν πέριξ τοῦ ἀέρος πίλησιν. καὶ ἕως μὲν γῆς τοῦ πρηστῆρος καθιεμένου στρόβιλοι γίνονται, ὡς ἂν καὶ ἡ ἀπογέννησις κατὰ τὴν κίνησιν τοῦ πνεύματος γίνηται· ἕως δὲ θαλάττης δῖνοι ἀποτελοῦνται.", "st": "10.105"}, {"sp": "N", "t": "“Σεισμοὺς ἐνδέχεται γίνεσθαι καὶ κατὰ πνεύματος ἐν τῇ γῇ ἀπόληψιν καὶ παρὰ μικροὺς ὄγκους αὐτῆς παράθεσιν καὶ συνεχῆ κίνησιν, ὅταν κράδανσιν τῇ γῇ παρασκευάζῃ· καὶ τὸ πνεῦμα τοῦτο ἢ ἔξωθεν ἐμπεριλαμβάνει 〈ἢ〉 ἐκ τοῦ πίπτειν εἴσω ἐδάφη εἰς ἀντροειδεῖς τόπους τῆς γῆς ἐκπνευματοῦντα ἐπειλημένον ἀέρα. 〈καὶ〉 κατ’ αὐτὴν δὲ τὴν διάδοσιν τῆς κινήσεως ἐκ τῶν πτώσεων ἐδαφῶν πολλῶν καὶ πάλιν ἀνταπόδοσιν, ὅταν πυκνώμασι σφοδροτέροις τῆς γῆς ἀπαντήσῃ, ἐνδέχεται σεισμοὺς ἀποτελεῖσθαι. καὶ κατ’ ἄλλους δὲ πλείους τρόπους τὰς κινήσεις ταύτας τῆς γῆς γίνεσθαι.", "st": "10.106"}, {"sp": "N", "t": "“Τὰ δὲ πνεύματα συμβαίνει γίνεσθαι κατὰ χρόνον ἀλλοφυλίας τινὸς ἀεὶ καὶ κατὰ μικρὸν παρεισδυομένης, καὶ καθ’ ὕδατος ἀφθόνου συλλογήν· τὰ δὲ λοιπὰ πνεύματα γίνεται καὶ ὀλίγων πεσόντων εἰς τὰ πολλὰ κοιλώματα, διαδόσεως τούτων γινομένης.", "st": "10.106b"}, {"sp": "N", "t": "“Χάλαζα συντελεῖται καὶ κατὰ πῆξιν ἰσχυροτέραν, πάντοθεν δὲ πνευματωδῶν περίστασίν τινων κᾆτα μέρισιν· καὶ 〈κατὰ〉 πῆξιν μετριωτέραν ὑδατοειδῶν τινων, 〈πνευματωδῶν δέ τινων〉 ὁμούρησιν ἅμα τήν τε σύνωσιν αὐτῶν ποιουμένην καὶ τὴν διάρρηξιν πρὸς τὸ κατὰ μέρη συνίστασθαι πηγνύμενα καὶ κατ’ ἀθροότητα. ἡ δὲ περιφέρεια οὐκ ἀδυνάτως μὲν ἔχει γίνεσθαι πάντοθεν τῶν ἄκρων ἀποτηκομένων καὶ ἐν τῇ συστάσει πάντοθεν, ὡς λέγεται, κατὰ μέρη ὁμαλῶς περιισταμένων εἴτε ὑδατοειδῶν τινων εἴτε πνευματωδῶν.", "st": "10.107"}, {"sp": "N", "t": "“Χιόνα δ’ ἐνδέχεται συντελεῖσθαι καὶ ὕδατος λεπτοῦ ἐκχεομένου ἐκ τῶν νεφῶν διὰ πόρων συμμετρίας καὶ θλίψεις ἐπιτηδείων νεφῶν ἀεὶ ὑπὸ πνεύματος σφοδράς, εἶτα τούτου πῆξιν ἐν τῇ φορᾷ λαμβάνοντος διά τινα ἰσχυρὰν ἐν τοῖς κατωτέρω τόποις τῶν νεφῶν ψυχρασίας περίστασιν. καὶ κατὰ πῆξιν δ’ ἐν τοῖς νέφεσιν ὁμαλῆ ἀραιότητα ἔχουσι τοιαύτη πρόεσις ἐκ τῶν νεφῶν γίνοιτο ἂν πρὸς ἄλληλα θλιβομένων 〈τῶν〉 ὑδατοειδῶν καὶ συμπαρακειμένων· ἃ οἱονεὶ σύνωσιν ποιούμενα χάλαζαν ἀποτελεῖ, ὃ μάλιστα γίνεται ἐν τῷ ἔαρι. καὶ κατὰ τρίψιν δὲ νεφῶν πῆξιν εἰληφότων ἀπόπαλσιν ἂν λαμβάνοι τὸ τῆς χιόνος τοῦτο ἄθροισμα. καὶ κατ’ ἄλλους δὲ τρόπους ἐνδέχεται χιόνα συντελεῖσθαι.", "st": "10.108"}, {"sp": "N", "t": "“Δρόσος συντελεῖται καὶ κατὰ σύνοδον πρὸς ἄλληλα ἐκ τοῦ ἀέρος τῶν τοιούτων, ἃ τῆς τοιαύτης ὑγρασίας ἀποτελεστικὰ γίνεται· καὶ κατ’ ἀναφορὰν δὲ ἢ ἀπὸ νοτερῶν τόπων ἢ ὕδατα κεκτημένων, ἐν οἵοις τόποις μάλιστα δρόσος συντελεῖται, εἶτα σύνοδον τούτων εἰς τὸ αὐτὸ λαβόντων καὶ ἀποτέλεσιν ὑγρασίας καὶ πάλιν φορὰν ἐπὶ τοὺς κάτω τόπους, καθά περ ὁμοίως καὶ παρ’ ἡμῖν ἐπὶ πλειόνων τοιαῦτά τινα συντελούμενα θεωρεῖται.", "st": "10.108b"}, {"sp": "N", "t": "καὶ πάχνη δὲ συντελεῖται 〈οὐ διαφερόντως〉 τῶν δρόσων, τοιούτων τινῶν πῆξίν τινα ποιὰν λαβόντων διὰ περίστασίν τινα ἀέρος ψυχροῦ.", "st": "10.109"}, {"sp": "N", "t": "“Κρύσταλλος συντελεῖται καὶ κατ’ ἔκθλιψιν μὲν τοῦ περιφεροῦς σχηματισμοῦ ἐκ τοῦ ὕδατος, σύνωσιν δὲ τῶν σκαληνῶν καὶ ὀξυγωνίων τῶν ἐν τῷ ὕδατι ὑπαρχόντων· καὶ κατὰ τὴν ἔξωθεν δὲ τῶν τοιούτων πρόσκρισιν, ἃ συνελασθέντα πῆξιν τῷ ὕδατι παρεσκεύασε, ποσὰ τῶν περιφερῶν ἐκθλίψαντα.", "st": "10.109b"}, {"sp": "N", "t": "“Ἶρις γίνεται κατὰ πρόσλαμψιν ὑπὸ τοῦ ἡλίου πρὸς ἀέρα ὑδατοειδῆ· ἢ κατὰ 〈σύμ〉φυσιν ἰδίαν τοῦ τε φωτὸς καὶ τοῦ ἀέρος, ἣ τὰ τῶν χρωμάτων τούτων ἰδιώματα ποιήσει εἴ τε πάντα εἴ τε μονοειδῶς· ἀφ’ οὗ πάλιν ἀπολάμποντος τὰ ὁμοροῦντα τοῦ ἀέρος χρῶσιν ταύτην λήψεται, οἵαν θεωροῦμεν, κατὰ πρόσλαμψιν πρὸς τὰ μέρη. τὸ δὲ τῆς περιφερείας τοῦτο φάντασμα γίνεται διὰ τὸ τὸ διάστημα πάντοθεν ἴσον ὑπὸ τῆς ὄψεως θεωρεῖσθαι, ἢ σύνωσιν τοιαύτην λαμβανουσῶν τῶν ἐν τῷ ἀέρι ἀτόμων ἢ ἐν τοῖς νέφεσιν ἀπὸ τοῦ ἡλίου ἀποφερομένων περιφέρειάν τινα καθίεσθαι τὴν σύγκρισιν ταύτην.", "st": "10.110"}, {"sp": "N", "t": "“Ἅλως περὶ τὴν σελήνην γίνεται καὶ πάντοθεν ἀέρος προσφερομένου πρὸς τὴν σελήνην ἢ τὰ ἀπ’ αὐτῆς ῥεύματα ἀποφερόμενα ὁμαλῶς ἀναστέλλοντος ἐπὶ τοσοῦτον ἐφ’ ὅσον κύκλῳ περιστῆσαι τὸ νεφοειδὲς τοῦτο καὶ μὴ τὸ παράπαν διακρῖναι, ἢ καὶ τὸν πέριξ ἀέρα αὐτῆς ἀναστέλλοντος συμμέτρως πάντοθεν εἰς τὸ περιφερὲς τὸ περὶ αὐτὴν καὶ παχυμερὲς περιστῆσαι. ὃ γίνεται κατὰ μέρη τινὰ ἤτοι ἔξωθεν βιασαμένου τινὸς ῥεύματος ἢ τῆς θερμασίας ἐπιτηδείων πόρων ἐπιλαμβανομένης εἰς τὸ τοῦτο ἀπεργάσασθαι.", "st": "10.111"}, {"sp": "N", "t": "“Κομῆται ἀστέρες γίνονται ἤτοι πυρὸς ἐν τόποις τισὶ διὰ χρόνων τινῶν ἐν τοῖς μετεώροις συστρεφομένου περιστάσεως γινομένης, ἢ ἰδίαν τινὰ κίνησιν διὰ χρόνων τοῦ οὐρανοῦ ἴσχοντος ὑπὲρ ἡμᾶς, ὥστε τὰ τοιαῦτα ἄστρα ἀναφανῆναι, ἢ αὐτὰ ἐν χρόνοις τισὶν ὁρμῆσαι διά τινα περίστασιν καὶ εἰς τοὺς καθ’ ἡμᾶς τόπους ἐλθεῖν καὶ ἐκφανῆ γενέσθαι. τήν τε ἀφάνισιν τούτων γίνεσθαι παρὰ τὰς ἀντικειμένας ταύταις αἰτίας.", "st": "10.111b"}, {"sp": "N", "t": "τινὰ ἄστρα στρέφεσθαι αὐτοῦ συμβαίνει οὐ μόνον τῷ τὸ μέρος τοῦτο τοῦ κόσμου ἑστάναι, περὶ ὃ τὸ λοιπὸν στρέφεται, καθά περ τινές φασιν, ἀλλὰ καὶ τῷ δίνην ἀέρος ἔγκυκλον αὐτῷ περιεστάναι, ἣ κωλυτικὴ γίνεται τοῦ περιπολεῖν, ὡς καὶ τὰ ἄλλα· ἢ καὶ διὰ τὸ ἑξῆς μὲν αὐτοῖς ὕλην ἐπιτηδείαν μὴ εἶναι, ἐν δὲ τούτῳ τῷ τόπῳ ἐν ᾧ κείμενα θεωρεῖται. καὶ κατ’ ἄλλους δὲ πλείονας τρόπους τοῦτο δυνατὸν συντελεῖσθαι, ἐάν τις δύνηται τὸ σύμφωνον τοῖς φαινομένοις συλλογίζεσθαι. τινὰ τῶν ἄστρων πλανᾶσθαι, εἰ οὕτω ταῖς κινήσεσι χρώμενα συμβαίνει, τινὰ δὲ ὁμαλῶς κινεῖσθαι, ἐνδέχεται μὲν καὶ παρὰ τὸ κύκλῳ κινούμενα ἐξ ἀρχῆς οὕτω κατηναγκάσθαι, ὥστε τὰ μὲν κατὰ τὴν αὐτὴν δίνην φέρεσθαι ὁμαλῆ οὖσαν, τὰ δὲ κατά τιν’ ἄλλην τισὶν ἀνωμαλίαις χρωμένην. ἐνδέχεται δὲ καὶ καθ’ οὓς τόπους φέρεται οὗ μὲν παρεκτάσεις ἀέρος εἶναι ὁμαλὰς ἐπὶ τὸ αὐτὸ συνωθούσας κατὰ τὸ ἑξῆς ὁμαλῶς τε ἐκκαούσας, οὗ δὲ ἀνωμαλεῖς οὕτως ὥστε τὰς θεωρουμένας παραλλαγὰς συντελεῖσθαι. τὸ δὲ μίαν αἰτίαν τούτων ἀποδιδόναι, πλεοναχῶς τῶν φαινομένων ἐκκαλουμένων, μανικὸν καὶ οὐ καθηκόντως πραττόμενον ὑπὸ τῶν τὴν ματαίαν ἀστρολογίαν ἐζηλωκότων καὶ εἰς τὸ κενὸν αἰτίας τινῶν ἀποδιδόντων, ὅταν τὴν θείαν φύσιν μηδαμῆ λειτουργιῶν ἀπολύωσι.", "st": "10.112"}, {"sp": "N", "t": "τινὰ ἄστρα ὑπολειπόμενά τινων θεωρεῖσθαι συμβαίνει καὶ παρὰ τὸ βραδύτερον συμπεριφέρεσθαι τὸν αὐτὸν κύκλον περιιόντα καὶ παρὰ τὸ τὴν ἐναντίαν κινεῖσθαι ἀντισπώμενα ὑπὸ τῆς αὐτῆς δίνης· καὶ παρὰ τὸ περιφέρεσθαι τὰ μὲν διὰ πλείονος τόπου, τὰ δὲ δι’ ἐλάττονος, τὴν αὐτὴν δίνην περικυκλοῦντα. τὸ δὲ ἁπλῶς ἀποφαίνεσθαι περὶ τούτων καθῆκόν ἐστι τοῖς τερατεύεσθαί τι πρὸς τοὺς πολλοὺς βουλομένοις.", "st": "10.114"}, {"sp": "N", "t": "“Οἱ λεγόμενοι ἀστέρες ἐκπίπτειν καὶ παρὰ μέρος κατὰ παράτριψιν ἑαυτῶν δύναται συντελεῖσθαι καὶ παρ’ ἔκπτωσιν οὗ ἂν ἡ ἐκπνευμάτωσις γένηται, καθά περ καὶ ἐπὶ τῶν ἀστραπῶν ἐλέγομεν· καὶ κατὰ σύνοδον δὲ ἀτόμων πυρὸς ἀποτελεστικῶν, συμφυλίας γενομένης εἰς τὸ τοῦτο τελέσαι, καὶ κίνησιν οὗ ἂν ἡ ὁρμὴ ἐξ ἀρχῆς κατὰ τὴν σύνοδον γένηται· καὶ κατὰ πνεύματος δὲ συλλογὴν ἐν πυκνώμασί τισιν ὁμιχλοειδέσι, καὶ ἐκπύρωσιν τούτου διὰ τὴν κατείλησιν, εἶτ’ ἐπέκρηξιν τῶν περιεχόντων, καὶ ἐφ’ ὃν ἂν τόπον ἡ ὁρμὴ γένηται τῆς φορᾶς, εἰς τοῦτον φερομένου. καὶ ἄλλοι δὲ τρόποι εἰς τὸ τοῦτο τελέσαι ἀμύθητοί εἰσιν.", "st": "10.115"}, {"sp": "N", "t": "“Αἱ δ’ ἐπισημασίαι αἱ γινόμεναι ἐπί τισι ζῴοις κατὰ συγκύρημα γίνονται τοῦ καιροῦ· οὐ γὰρ τὰ ζῷα ἀνάγκην τινὰ προσφέρεται τοῦ ἀποτελεσθῆναι χειμῶνα, οὐδὲ κάθηταί τις θεία φύσις παρατηροῦσα τὰς τῶν ζῴων τούτων ἐξόδους κἄπειτα τὰς ἐπισημασίας ταύτας ἐπιτελεῖ. οὐδὲ γὰρ εἰς τὸ τυχὸν ζῷον, κἂν 〈εἰ〉 μικρὸν χαριέστερον εἴη, ἡ τοιαύτη μωρία ἐμπέσοι, μὴ ὅτι εἰς παντελῆ εὐδαιμονίαν κεκτημένον.", "st": "10.116"}, {"sp": "N", "t": "Ταῦτα δὴ πάντα, Πυθόκλεις, μνημόνευσον· κατὰ πολύ τε γὰρ τοῦ μύθου ἐκβήσῃ καὶ τὰ ὁμογενῆ τούτοις συνορᾶν δυνήσῃ· μάλιστα δὲ σεαυτὸν ἀπόδος εἰς τὴν τῶν ἀρχῶν καὶ ἀπειρίας καὶ τῶν συγγενῶν τούτοις θεωρίαν, ἔτι τε κριτηρίων καὶ παθῶν, καὶ οὗ ἕνεκεν ταῦτα ἐκλογιζόμεθα· ταῦτα γὰρ μάλιστα συνθεωρούμενα ῥᾳδίως τὰς περὶ τῶν κατὰ μέρος αἰτίας συνορᾶν ποιήσει. οἱ δὲ ταῦτα μὴ καταγαπήσαντες ᾗ μάλιστα οὔτ’ 〈ἂν〉 αὐτὰ ταῦτα καλῶς συνθεωρήσαιεν οὔτε οὗ ἕνεκεν δεῖ θεωρεῖν ταῦτα περιεποιήσαντο.", "st": "10.116b"}, {"sp": "N", "t": "ταῦτα αὐτῷ καὶ περὶ τῶν μετεώρων δοκεῖ. Περὶ δὲ τῶν βιωτικῶν καὶ ὅπως χρὴ τὰ μὲν ἡμᾶς αἱρεῖσθαι, τὰ δ’ ἐκφεύγειν, οὑτωσὶ γράφει. πρότερον δὲ διέλθωμεν ἅ τε αὐτῷ δοκεῖ περὶ τοῦ σοφοῦ καὶ τοῖς ἀπ’ αὐτοῦ.", "st": "10.117"}, {"sp": "N", "t": "Βλάβας ἐξ ἀνθρώπων ἢ διὰ μῖσος ἢ διὰ φθόνον ἢ διὰ καταφρόνησιν γίνεσθαι, ὧν τὸν σοφὸν λογισμῷ περιγίνεσθαι. ἀλλὰ καὶ τὸν ἅπαξ γενόμενον σοφὸν μηκέτι τὴν ἐναντίαν λαμβάνειν διάθεσιν μηδὲ πλάττειν ἑκόντα· πάθεσι μᾶλλον συσχεθήσεσθαι· οὐκ ἂν ἐμποδίσαι πρὸς τὴν σοφίαν. οὐδὲ μὴν ἐκ πάσης σώματος ἕξεως σοφὸν γενέσθαι ἂν οὐδ’ ἐν παντὶ ἔθνει. κἂν στρεβλωθῇ δ’ ὁ σοφός, εἶναι αὐτὸν εὐδαίμονα, μόνον τε χάριν ἕξειν τὸν σοφόν, καὶ ἐπὶ φίλοις καὶ παροῦσι καὶ ἀποῦσιν ὁμοίως διά τε λόγου 〈καὶ διὰ πράξεως〉. ὅτε μέντοι στρεβλοῦται, ἔνθα καὶ μύζει καὶ οἰμώζει. γυναικί τ’ οὐ μιγήσεσθαι τὸν σοφὸν ᾗ οἱ νόμοι ἀπαγορεύουσιν, ὥς φησι Διογένης ἐν τῇ ἐπιτομῇ τῶν Ἐπικούρου ἠθικῶν δογμάτων. οὐδὲ κολάσειν οἰκέτας, ἐλεήσειν μέντοι καὶ συγγνώμην τινὶ ἕξειν τῶν σπουδαίων. ἐρασθήσεσθαι τὸν σοφὸν οὐ δοκεῖ αὐτοῖς· οὐδὲ ταφῆς φροντιεῖν· οὐδὲ θεόπεμπτον εἶναι τὸν ἔρωτα, ὡς Διογένης ἐν τῷ δωδεκάτῳ φησίν. οὐδὲ ῥητορεύσειν καλῶς. συνουσίαν δέ φασιν ὀνῆσαι μὲν οὐδέποτε, ἀγαπητὸν δὲ εἰ μὴ καὶ ἔβλαψε. Καὶ μηδὲ καὶ γαμήσειν καὶ τεκνοποιήσειν τὸν σοφόν, ὡς Ἐπίκουρος ἐν ταῖς Διαπορίαις καὶ ἐν τοῖς Περὶ φύσεως. κατὰ περίστασιν δέ ποτε βίου γαμήσειν. καὶ διατραπήσεσθαί τινας. οὐδὲ μὴν ληρήσειν ἐν μέθῃ φησὶν ὁ Ἐπίκουρος ἐν τῷ Συμποσίῳ. οὐδὲ πολιτεύσεσθαι, ὡς ἐν τῇ πρώτῃ Περὶ βίων· οὐδὲ τυραννεύσειν· οὐδὲ κυνιεῖν, ὡς ἐν τῇ δευτέρᾳ Περὶ βίων· οὐδὲ πτωχεύσειν. ἀλλὰ καὶ πηρωθέντα τὰς ὄψεις μὴ ἐξάξειν αὑτὸν τοῦ βίου,", "st": "10.118"}, {"sp": "N", "t": "ὡς ἐν τῇ αὐτῇ φησι. καὶ λυπηθήσεσθαι δὲ τὸν σοφόν, ὡς ὁ Διογένης ἐν τῇ πέμπτῃ τῶν Ἐπιλέκτων· καὶ δικάσεσθαι· καὶ συγγράμματα καταλείψειν· οὐ πανηγυριεῖν δέ· καὶ κτήσεως προνοήσεσθαι καὶ τοῦ μέλλοντος. φιλαγρήσειν. τύχῃ τ’ ἀντιτάξεσθαι, φίλον τε οὐδένα προήσεσθαι. εὐδοξίας ἐπὶ τοσοῦτον προνοήσεσθαι, ἐφ’ ὅσον μὴ καταφρονήσεσθαι· μᾶλλόν τε εὐφρανθήσεσθαι τῶν ἄλλων ἐν ταῖς θεωρίαις.", "st": "10.120"}, {"sp": "N", "t": "Εἰκόνας τε ἀναθήσειν. 〈εὖ〉 εἰ ἔχοι, ἀδιαφόρως ἂν σχοίη. μόνον τε τὸν σοφὸν ὀρθῶς ἂν περί τε μουσικῆς καὶ ποιητικῆς διαλέξεσθαι· ποιήματά τε ἐνεργείᾳ οὐκ ἂν ποιῆσαι.", "st": "10.120b"}, {"sp": "N", "t": "οὐ κινεῖσθαί τε ἕτερον ἑτέρου σοφώτερον. χρηματιεῖσθαί τε, ἀλλ’ ἀπὸ μόνης σοφίας, ἀπορήσαντα. καὶ μόναρχον ἐν καιρῷ θεραπεύσειν. καὶ ἐπιχαρήσεσθαί τινι ἐπὶ τῷ διορθώματι· καὶ σχολὴν κατασκευάσειν, ἀλλ’ οὐχ ὥστ’ ὀχλαγωγῆσαι· καὶ ἀναγνώσεσθαι ἐν πλήθει, ἀλλ’ οὐχ ἑκόντα· δογματιεῖν τε καὶ οὐκ ἀπορήσειν· καὶ καθ’ ὕπνους δὲ ὅμοιον ἔσεσθαι, καὶ ὑπὲρ φίλου ποτὲ τεθνήξεσθαι. Δοκεῖ δ’ αὐτοῖς ἁμαρτήματα ἄνισα εἶναι. καὶ τὴν ὑγίειαν τισὶ μὲν ἀγαθόν, τισὶ δ’ ἀδιάφορον. τὴν δὲ ἀνδρείαν φύσει μὴ γίνεσθαι, λογισμῷ δὲ τοῦ συμφέροντος· καὶ τὴν φιλίαν διὰ τὰς χρείας· δεῖν μέντοι προκατάρχεσθαι (καὶ γὰρ τὴν γῆν σπείρομεν), συνίστασθαι δὲ αὐτὴν κατὰ κοινωνίαν τοῖς ταῖς ἡδοναῖς ἐκπεπληρωμ〈ένοις〉. Τὴν εὐδαιμονίαν διχῆ νοεῖσθαι, τήν τε ἀκροτάτην, οἵα ἐστὶ περὶ τὸν θεόν, ἐπίτασιν οὐκ ἔχουσαν· καὶ τὴν 〈κατὰ τὴν〉 προσθήκην καὶ ἀφαίρεσιν ἡδονῶν.", "st": "10.121"}, {"sp": "N", "t": "Μετιτέον δ’ ἐπὶ τὴν ἐπιστολήν. “Ἐπίκουρος Μενοικεῖ χαίρειν.", "st": "10.121b"}, {"sp": "N", "t": "“Μήτε νέος τις ὢν μελλέτω φιλοσοφεῖν, μήτε γέρων ὑπάρχων κοπιάτω φιλοσοφῶν· οὔτε γὰρ ἄωρος οὐδείς ἐστιν οὔτε πάρωρος πρὸς τὸ κατὰ ψυχὴν ὑγιαῖνον. ὁ δὲ λέγων ἢ μήπω τοῦ φιλοσοφεῖν ὑπάρχειν ἢ παρεληλυθέναι τὴν ὥραν ὅμοιός ἐστι τῷ λέγοντι πρὸς εὐδαιμονίαν ἢ μήπω παρεῖναι τὴν ὥραν ἢ μηκέτι εἶναι τὴν ὥραν. ὥστε φιλοσοφητέον καὶ νέῳ καὶ γέροντι, τῷ μὲν ὅπως γηράσκων νεάζῃ τοῖς ἀγαθοῖς διὰ τὴν χάριν τῶν γεγονότων, τῷ δ’ ὅπως νέος ἅμα καὶ παλαιὸς ᾖ διὰ τὴν ἀφοβίαν τῶν μελλόντων.", "st": "10.122"}, {"sp": "N", "t": "μελετᾶν οὖν χρὴ τὰ ποιοῦντα τὴν εὐδαιμονίαν, εἴ περ παρούσης μὲν αὐτῆς, πάντα ἔχομεν, ἀπούσης δέ, πάντα πράττομεν εἰς τὸ ταύτην ἔχειν. “Ἃ δέ σοι συνεχῶς παρήγγελλον, ταῦτα καὶ πρᾶττε καὶ μελέτα, στοιχεῖα τοῦ καλῶς ζῆν ταῦτ’ εἶναι διαλαμβάνων. πρῶτον μὲν τὸν θεὸν ζῷον ἄφθαρτον καὶ μακάριον νομίζων, ὡς ἡ κοινὴ τοῦ θεοῦ νόησις ὑπεγράφη, μηθὲν μήτε τῆς ἀφθαρσίας ἀλλότριον μήτε τῆς μακαριότητος ἀνοίκειον αὐτῷ πρόσαπτε· πᾶν δὲ τὸ φυλάττειν αὐτοῦ δυνάμενον τὴν μετ’ ἀφθαρσίας μακαριότητα περὶ αὐτοῦ δόξαζε. θεοὶ μὲν γάρ εἰσιν. ἐναργὴς δέ ἐστιν αὐτῶν ἡ γνῶσις· οἵους δ’ αὐτοὺς 〈οἱ〉 πολλοὶ νομίζουσιν, οὐκ εἰσίν· οὐ γὰρ φυλάττουσιν αὐτοὺς οἵους νοοῦσιν. ἀσεβὴς δὲ οὐχ ὁ τοὺς τῶν πολλῶν θεοὺς ἀναιρῶν, ἀλλ’ ὁ τὰς τῶν πολλῶν δόξας θεοῖς προσάπτων. οὐ γὰρ προλήψεις εἰσίν, ἀλλ’ ὑπολήψεις ψευδεῖς αἱ τῶν πολλῶν ὑπὲρ θεῶν ἀποφάσεις· ἔνθεν αἱ μέγισται βλάβαι τε τοῖς κακοῖς ἐκ θεῶν ἐπάγονται καὶ ὠφέλειαι τοῖς ἀγαθοῖς. ταῖς γὰρ ἰδίαις οἰκειούμενοι διὰ παντὸς ἀρεταῖς τοὺς ὁμοίους ἀποδέχονται, πᾶν τὸ μὴ τοιοῦτον ὡς ἀλλότριον νομίζοντες.", "st": "10.123"}, {"sp": "N", "t": "“Συνέθιζε δὲ ἐν τῷ νομίζειν μηδὲν πρὸς ἡμᾶς εἶναι τὸν θάνατον· ἐπεὶ πᾶν ἀγαθὸν καὶ κακὸν ἐν αἰσθήσει· στέρησις δέ ἐστιν αἰσθήσεως ὁ θάνατος. ὅθεν γνῶσις ὀρθὴ τοῦ μηθὲν εἶναι πρὸς ἡμᾶς τὸν θάνατον ἀπολαυστὸν ποιεῖ τὸ τῆς ζωῆς θνητόν, οὐκ ἄπειρον προστιθεῖσα χρόνον ἀλλὰ τὸν τῆς ἀθανασίας ἀφελομένη πόθον. οὐθὲν γάρ ἐστιν ἐν τῷ ζῆν δεινὸν τῷ κατειληφότι γνησίως τὸ μηθὲν ὑπάρχειν ἐν τῷ μὴ ζῆν δεινόν. ὥστε μάταιος ὁ λέγων δεδιέναι τὸν θάνατον οὐχ ὅτι λυπήσει παρών, ἀλλ’ ὅτι λυπεῖ μέλλων. ὃ γὰρ παρὸν οὐκ ἐνοχλεῖ, προσδοκώμενον κενῶς λυπεῖ. τὸ φρικωδέστατον οὖν τῶν κακῶν ὁ θάνατος οὐθὲν πρὸς ἡμᾶς, ἐπειδή περ ὅταν μὲν ἡμεῖς ὦμεν, ὁ θάνατος οὐ πάρεστιν· ὅταν δ’ ὁ θάνατος παρῇ, τόθ’ ἡμεῖς οὐκ ἐσμέν. οὔτε οὖν πρὸς τοὺς ζῶντάς ἐστιν οὔτε πρὸς τοὺς τετελευτηκότας, ἐπειδήπερ περὶ οὓς μὲν οὐκ ἔστιν, οἱ δ’ οὐκέτι εἰσίν. ἀλλ’ οἱ πολλοὶ τὸν θάνατον ὁτὲ μὲν ὡς μέγιστον τῶν κακῶν φεύγουσιν, ὁτὲ δὲ ὡς ἀνάπαυσιν τῶν ἐν τῷ ζῆν 〈κακῶ αἱροῦνται. ὁ δὲ σοφὸς οὔτε παραιτεῖται τὸ ζῆν〉 οὔτε φοβεῖται τὸ μὴ ζῆν· οὔτε γὰρ αὐτῷ προσίσταται τὸ ζῆν οὔτε δοξάζεται κακὸν εἶναι τὸ μὴ ζῆν. ὥσπερ δὲ τὸ σιτίον οὐ τὸ πλεῖον πάντως ἀλλὰ τὸ ἥδιστον αἱρεῖται, οὕτω καὶ χρόνον οὐ τὸν μήκιστον ἀλλὰ τὸν ἥδιστον καρπίζεται. ὁ δὲ παραγγέλλων τὸν μὲν νέον καλῶς ζῆν, τὸν δὲ γέροντα καλῶς καταστρέφειν εὐήθης ἐστὶν οὐ μόνον διὰ τὸ τῆς ζωῆς ἀσπαστόν, ἀλλὰ καὶ διὰ τὸ τὴν αὐτὴν εἶναι μελέτην τοῦ καλῶς ζῆν καὶ τοῦ καλῶς ἀποθνήσκειν. πολὺ δὲ χεῖρον καὶ ὁ λέγων, καλὸν μὲν μὴ φῦναι,<br>φύντα δ’ ὅπως ὤκιστα πύλας Ἀΐδαο περῆσαι.", "st": "10.125"}, {"sp": "N", "t": "εἰ μὲν γὰρ πεποιθὼς τοῦτό φησι, πῶς οὐκ ἀπέρχεται τοῦ ζῆν; ἐν ἑτοίμῳ γὰρ αὐτῷ τοῦτ’ ἔστιν, εἴπερ ἦν βεβουλευμένον αὐτῷ βεβαίως· εἰ δὲ μωκώμενος, μάταιος ἐν τοῖς οὐκ ἐπιδεχομένοις. “Μνημονευτέον δὲ ὡς τὸ μέλλον οὔτε ἡμέτερον οὔτε πάντως οὐχ ἡμέτερον, ἵνα μήτε πάντως προσμένωμεν ὡς ἐσόμενον μήτε ἀπελπίζωμεν ὡς πάντως οὐκ ἐσόμενον. “Ἀναλογιστέον δὲ ὡς τῶν ἐπιθυμιῶν αἱ μέν εἰσι φυσικαί, αἱ δὲ κεναί. καὶ τῶν φυσικῶν αἱ μὲν ἀναγκαῖαι, αἱ δὲ φυσικαὶ μόνον· τῶν δ’ ἀναγκαίων αἱ μὲν πρὸς εὐδαιμονίαν εἰσὶν ἀναγκαῖαι, αἱ δὲ πρὸς τὴν τοῦ σώματος ἀοχλησίαν, αἱ δὲ πρὸς αὐτὸ τὸ ζῆν. τούτων γὰρ ἀπλανὴς θεωρία πᾶσαν αἵρεσιν καὶ φυγὴν ἐπανάγειν οἶδεν ἐπὶ τὴν τοῦ σώματος ὑγίειαν καὶ τὴν τῆς ψυχῆς ἀταραξίαν, ἐπεὶ τοῦτο τοῦ μακαρίως ζῆν ἐστι τέλος. τούτου γὰρ χάριν πάντα πράττομεν, ὅπως μήτε ἀλγῶμεν μήτε ταρβῶμεν· ὅταν δ’ ἅπαξ τοῦτο περὶ ἡμᾶς γένηται, λύεται πᾶς ὁ τῆς ψυχῆς χειμών, οὐκ ἔχοντος τοῦ ζῴου βαδίζειν ὡς πρὸς ἐνδέον τι καὶ ζητεῖν ἕτερον ᾧ τὸ τῆς ψυχῆς καὶ τοῦ σώματος ἀγαθὸν συμπληρωθήσεται.", "st": "10.127"}, {"sp": "N", "t": "τότε γὰρ ἡδονῆς χρείαν ἔχομεν, ὅταν ἐκ τοῦ μὴ παρεῖναι τὴν ἡδονὴν ἀλγῶμεν· ὅταν δὲ μὴ ἀλγῶμεν, οὐκέτι τῆς ἡδονῆς δεόμεθα. καὶ διὰ τοῦτο τὴν ἡδονὴν ἀρχὴν καὶ τέλος λέγομεν εἶναι τοῦ μακαρίως ζῆν· ταύτην γὰρ ἀγαθὸν πρῶτον καὶ συγγενικὸν ἔγνωμεν, καὶ ἀπὸ ταύτης καταρχόμεθα πάσης αἱρέσεως καὶ φυγῆς καὶ ἐπὶ ταύτην καταντῶμεν ὡς κανόνι τῷ πάθει πᾶν ἀγαθὸν κρίνοντες. καὶ ἐπεὶ πρῶτον ἀγαθὸν τοῦτο καὶ σύμφυτον, διὰ τοῦτο καὶ οὐ πᾶσαν ἡδονὴν αἱρούμεθα, ἀλλ’ ἔστιν ὅτε πολλὰς ἡδονὰς ὑπερβαίνομεν, ὅταν πλεῖον ἡμῖν τὸ δυσχερὲς ἐκ τούτων ἕπηται· καὶ πολλὰς ἀλγηδόνας ἡδονῶν κρείττους νομίζομεν, ἐπειδὰν μείζων ἡμῖν ἡδονὴ παρακολουθῇ πολὺν χρόνον ὑπομείνασι τὰς ἀλγηδόνας.", "st": "10.129"}, {"sp": "N", "t": "πᾶσα οὖν ἡδονὴ διὰ τὸ φύσιν ἔχειν οἰκείαν ἀγαθόν, οὐ πᾶσα μέντοι 〈γ’〉 αἱρετή· καθά περ καὶ ἀλγηδὼν πᾶσα κακόν, οὐ πᾶσα δὲ ἀεὶ φευκτὴ πεφυκυῖα. τῇ μέντοι συμμετρήσει καὶ συμφερόντων καὶ ἀσυμφόρων βλέψει ταῦτα πάντα κρίνειν καθήκει· χρώμεθα γὰρ τῷ μὲν ἀγαθῷ κατά τινας χρόνους ὡς κακῷ, τῷ δὲ κακῷ τἄμπαλιν ὡς ἀγαθῷ. καὶ τὴν αὐτάρκειαν δὲ ἀγαθὸν μέγα νομίζομεν, οὐχ ἵνα πάντως τοῖς ὀλίγοις χρώμεθα, ἀλλ’ ὅπως ἐὰν μὴ ἔχωμεν τὰ πολλά, τοῖς ὀλίγοις ἀρκώμεθα, πεπεισμένοι γνησίως ὅτι ἥδιστα πολυτελείας ἀπολαύουσιν οἱ ἥκιστα ταύτης δεόμενοι, καὶ ὅτι τὸ μὲν φυσικὸν πᾶν εὐπόριστόν ἐστι, τὸ δὲ κενὸν δυσπόριστον. οἱ γὰρ λιτοὶ χυλοὶ ἴσην πολυτελεῖ διαίτῃ τὴν ἡδονὴν ἐπιφέρουσιν, ὅταν ἅπαξ τὸ ἀλγοῦν κατ’ ἔνδειαν ἐξαιρεθῇ· καὶ μᾶζα καὶ ὕδωρ τὴν ἀκροτάτην ἀποδίδωσιν ἡδονήν, ἐπειδὰν ἐνδέων τις αὐτὰ προσενέγκηται. τὸ συνεθίζειν οὖν ἐν ταῖς ἁπλαῖς καὶ οὐ πολυτελέσι διαίταις καὶ ὑγιείας ἐστὶ συμπληρωτικὸν καὶ πρὸς τὰς ἀναγκαίας τοῦ βίου χρήσεις ἄοκνον ποιεῖ τὸν ἄνθρωπον καὶ τοῖς πολυτελέσιν ἐκ διαλειμμάτων προσερχομένους κρεῖττον ἡμᾶς διατίθησι καὶ πρὸς τὴν τύχην ἀφόβους παρασκευάζει. “Ὅταν οὖν λέγωμεν ἡδονὴν τέλος ὑπάρχειν, οὐ τὰς τῶν ἀσώτων ἡδονὰς καὶ τὰς ἐν ἀπολαύσει κειμένας λέγομεν, ὥς τινες ἀγνοοῦντες καὶ οὐχ ὁμολογοῦντες ἢ κακῶς ἐκδεχόμενοι νομίζουσιν, ἀλλὰ τὸ μήτε ἀλγεῖν κατὰ σῶμα μήτε ταράττεσθαι κατὰ ψυχήν. οὐ γὰρ πότοι καὶ κῶμοι συνείροντες οὐδ’ ἀπολαύσεις παίδων καὶ γυναικῶν οὐδ’ ἰχθύων καὶ τῶν ἄλλων, ὅσα φέρει πολυτελὴς τράπεζα, τὸν ἡδὶν γεννᾷ βίον, ἀλλὰ νήφων λογισμὸς καὶ τὰς αἰτίας ἐξερευνῶν πάσης αἱρέσεως καὶ φυγῆς καὶ τὰς δόξας ἐξελαύνων ἐξ ὧν πλεῖστος τὰς ψυχὰς καταλαμβάνει θόρυβος.", "st": "10.130"}, {"sp": "N", "t": "τούτων δὲ πάντων ἀρχὴ καὶ τὸ μέγιστον ἀγαθὸν φρόνησις· διὸ καὶ φιλοσοφίας τιμιώτερον ὑπάρχει φρόνησις, ἐξ ἧς αἱ λοιπαὶ πᾶσαι πεφύκασιν ἀρεταί, διδάσκουσα ὡς οὐκ ἔστιν ἡδέως ζῆν ἄνευ τοῦ φρονίμως καὶ καλῶς καὶ δικαίως, οὐδὲ φρονίμως καὶ καλῶς καὶ δικαίως ἄνευ τοῦ ἡδέως· συμπεφύκασι γὰρ αἱ ἀρεταὶ τῷ ζῆν ἡδέως, καὶ τὸ ζῆν ἡδέως τούτων ἐστὶν ἀχώριστον. “Ἐπεὶ τίνα νομίζεις εἶναι κρείττονα τοῦ καὶ περὶ θεῶν ὅσια δοξάζοντος καὶ περὶ θανάτου διὰ παντὸς ἀφόβως ἔχοντος καὶ τὸ τῆς φύσεως ἐπιλελογισμένου τέλος, καὶ τὸ μὲν τῶν ἀγαθῶν πέρας ὡς ἔστιν εὐσυμπλήρωτόν τε καὶ εὐπόριστον διαλαμβάνοντος, τὸ δὲ τῶν κακῶν ὡς ἢ χρόνους ἢ πόνους ἔχει βραχεῖς, τὴν δὲ ὑπό τινων δεσπότιν εἰσαγομένην πάντων διαγελῶντος 〈εἱμαρμένην καὶ μᾶλλον ἃ μὲν κατ’ ἀνάγκην γίγνεσθαι λέγοντος〉, ἃ δὲ ἀπὸ τύχης, ἃ δὲ παρ’ ἡμᾶς διὰ τὸ τὴν μὲν ἀνάγκην ἀνυπεύθυνον εἶναι, τὴν δὲ τύχην ἄστατον ὁρᾶν, τὸ δὲ παρ’ ἡμᾶς ἀδέσποτον, ᾧ καὶ τὸ μεμπτὸν καὶ τὸ ἐναντίον παρακολουθεῖν πέφυκεν (ἐπεὶ κρεῖττον ἦν τῷ περὶ θεῶν μύθῳ κατακολουθεῖν ἢ τῇ τῶν φυσικῶν εἱμαρμένῃ δουλεύειν·", "st": "10.133"}, {"sp": "N", "t": "ὁ μὲν γὰρ ἐλπίδα παραιτήσεως ὑπογράφει θεῶν διὰ τιμῆς, ἡ δὲ ἀπαραίτητον ἔχει τὴν ἀνάγκην), τὴν δὲ τύχην οὔτε θεόν, ὡς οἱ πολλοὶ νομίζουσιν, ὑπολαμβάνοντος (οὐθὲν γὰρ ἀτάκτως θεῷ πράττεται) οὔτε ἀβέβαιον αἰτίαν (〈οὐκ〉 οἴεται μὲν γὰρ ἀγαθὸν ἢ κακὸν ἐκ ταύτης πρὸς τὸ μακαρίως ζῆν ἀνθρώποις δίδοσθαι, ἀρχὰς μέντοι μεγάλων ἀγαθῶν ἢ κακῶν ὑπὸ ταύτης χορηγεῖσθαι), κρεῖττον εἶναι νομίζοντος εὐλογίστως ἀτυχεῖν ἢ ἀλογίστως εὐτυχεῖν· βέλτιον γὰρ ἐν ταῖς πράξεσι τὸ καλῶς κριθὲν μὴ ὀρθωθῆναι διὰ ταύτην.", "st": "10.135"}, {"sp": "N", "t": "“Ταῦτα οὖν καὶ τὰ τούτοις συγγενῆ μελέτα πρὸς σεαυτὸν ἡμέρας καὶ νυκτὸς πρός τε τὸν ὅμοιον σεαυτῷ, καὶ οὐδέποτε οὔθ’ ὕπαρ οὔτ’ ὄναρ διαταραχθήσῃ, ζήσεις δὲ ὡς θεὸς ἐν ἀνθρώποις. οὐθὲν γὰρ ἔοικε θνητῷ ζῴῳ ζῶν ἄνθρωπος ἐν ἀθανάτοις ἀγαθοῖς.", "st": "10.135b"}, {"sp": "N", "t": "Μαντικὴν δ’ ἅπασαν ἐν ἄλλοις ἀναιρεῖ, ὡς καὶ ἐν τῇ μικρᾷ ἐπιτομῇ. καί φησι· μαντικὴ οὖσα ἀνύπαρκτος, εἰ δὲ καὶ ὑπαρκτή, οὐδὲν πρὸς ἡμᾶς ἡγητέα γινόμενα.", "st": "10.135c"}, {"sp": "N", "t": "Τοσαῦτα καὶ περὶ τῶν βιωτικῶν· καὶ ἐπὶ πλείω διείλεκται ἀλλαχόθι.", "st": "10.135d"}, {"sp": "N", "t": "Διαφέρεται δὲ πρὸς τοὺς Κυρηναϊκοὺς περὶ τῆς ἡδονῆς· οἱ μὲν γὰρ τὴν καταστηματικὴν οὐκ ἐγκρίνουσι, μόνην δὲ τὴν ἐν κινήσει· ὁ δὲ ἀμφοτέραν * * ψυχῆς καὶ σώματος, ὥς φησιν ἐν τῷ Περὶ αἱρέσεως καὶ φυγῆς καὶ ἐν τῷ Περὶ τέλους καὶ ἐν τῷ πρώτῳ Περὶ βίων καὶ ἐν τῇ πρὸς τοὺς ἐν Μυτιλήνῃ φιλοσόφους ἐπιστολῇ. ὁμοίως δὲ καὶ Διογένης ἐν τῇ ἑπτακαιδεκάτῃ τῶν Ἐπιλέκτων καὶ Μητρόδωρος ἐν τῷ Τιμοκράτει λέγουσιν οὕτω· νοουμένης δὲ ἡδονῆς τῆς τε κατὰ κίνησιν καὶ τῆς καταστηματικῆς. ὁ δ’ Ἐπίκουρος ἐν τῷ Περὶ αἱρέσεων οὕτω λέγει· ἡ μὲν γὰρ ἀταραξία καὶ ἀπονία καταστηματικαί εἰσιν ἡδοναί· ἡ δὲ χαρὰ καὶ ἡ εὐφροσύνη κατὰ κίνησιν ἐνεργείᾳ βλέπονται.", "st": "10.136"}, {"sp": "N", "t": "Ἔτι πρὸς τοὺς Κυρηναϊκούς· οἱ μὲν γὰρ χείρους τὰς σωματικὰς ἀλγηδόνας τῶν ψυχικῶν, κολάζεσθαι γοῦν τοὺς ἁμαρτάνοντας σώματι· ὁ δὲ τὰς ψυχικάς. τὴν γοῦν σάρκα τὸ παρὸν μόνον χειμάζειν, τὴν δὲ ψυχὴν καὶ τὸ παρελθὸν καὶ τὸ παρὸν καὶ τὸ μέλλον. οὕτως οὖν καὶ μείζονας ἡδονὰς εἶναι τὰς τῆς ψυχῆς. ἀποδείξει δὲ χρῆται τοῦ τέλος εἶναι τὴν ἡδονὴν τῷ τὰ ζῷα ἅμα τῷ γεννηθῆναι τῇ μὲν εὐαρεστεῖσθαι, τῷ δὲ πόνῳ προσκρούειν φυσικῶς καὶ χωρὶς λόγου. αὐτοπαθῶς οὖν φεύγομεν τὴν ἀλγηδόνα· ἵνα καὶ ὁ Ἡρακλῆς καταβιβρωσκόμενος ὑπὸ τοῦ χιτῶνος βοᾷ<br>δάκνων ἰύζων· ἀμφὶ δ’ ἔστενον πέτραι Λοκρῶν τ’ ὄρειοι πρῶνες Εὐβοίας τ’ ἄκραι.", "st": "10.137"}, {"sp": "N", "t": "Διὰ δὲ τὴν ἡδονὴν καὶ τὰς ἀρετὰς αἱρεῖσθαι, οὐ δι’ αὑτάς, ὥσπερ τὴν ἰατρικὴν διὰ τὴν ὑγίειαν, καθά φησι καὶ Διογένης ἐν τῇ εἰκοστῇ τῶν Ἐπιλέκτων, ὃς καὶ διαγωγὴν λέγει τὴν ἀγωγήν. ὁ δ’ Ἐπίκουρος καὶ ἀχώριστόν φησι τῆς ἡδονῆς τὴν ἀρετὴν μόνην· τὰ δ’ ἄλλα χωρίζεσθαι, οἷον βρωτά.", "st": "10.138"}, {"sp": "N", "t": "Καὶ φέρε οὖν δὴ νῦν τὸν κολοφῶνα, ὡς ἂν εἴποι τις, ἐπιθῶμεν τοῦ παντὸς συγγράμματος καὶ τοῦ βίου τοῦ φιλοσόφου, τὰς Κυρίας αὐτοῦ δόξας παραθέμενοι καὶ ταύταις τὸ πᾶν σύγγραμμα κατακλείσαντες, τέλει χρησάμενοι τῇ τῆς εὐδαιμονίας ἀρχῇ.", "st": "10.138b"}, {"sp": "N", "t": "[I.] Τὸ μακάριον καὶ ἄφθαρτον οὔτε αὐτὸ πράγματα ἔχει οὔτε ἄλλῳ παρέχει, ὥστε οὔτε ὀργαῖς οὔτε χάρισι συνέχεται· ἐν ἀσθενεῖ γὰρ πᾶν τὸ τοιοῦτον.", "st": "10.139"}, {"sp": "N", "t": "[ἐν ἄλλοις δέ φησι τοὺς θεοὺς λόγῳ θεωρητούς, οὓς μὲν κατ’ ἀριθμὸν ὑφεστῶτας, οὓς δὲ καθ’ ὁμοείδειαν ἐκ τῆς συνεχοῦς ἐπιρρύσεως τῶν ὁμοίων εἰδώλων ἐπὶ τὸ αὐτὸ ἀποτετελεσμένωι ἀνθρωποειδῶς.] [II.] Ὁ θάνατος οὐδὲν πρὸς ἡμᾶς·", "st": "10.139b"}, {"sp": "N", "t": "τὸ γὰρ διαλυθὲν ἀναισθητεῖ· τὸ δ’ ἀναισθητοῦν οὐδὲν πρὸς ἡμᾶς.", "st": "10.139c"}, {"sp": "N", "t": "[III.] Ὅρος τοῦ μεγέθους τῶν ἡδονῶν ἡ παντὸς τοῦ ἀλγοῦντος ὑπεξαίρεσις. ὅπου δ’ ἂν τὸ ἡδόμενον ἐνῇ, καθ’ ὃν ἂν χρόνον ᾖ, οὐκ ἔστι τὸ ἀλγοῦν ἢ τὸ λυπούμενον ἢ τὸ συναμφότερον.", "st": "10.139d"}, {"sp": "N", "t": "[IV.] Οὐ χρονίζει τὸ ἀλγοῦν συνεχῶς ἐν τῇ σαρκί, ἀλλὰ τὸ μὲν ἄκρον τὸν ἐλάχιστον χρόνον πάρεστι, τὸ δὲ μόνον ὑπερτεῖνον τὸ ἡδόμενον κατὰ σάρκα οὐ πολλὰς ἡμέρας συμμένει. αἱ δὲ πολυχρόνιοι τῶν ἀρρωστιῶν πλεονάζον ἔχουσι τὸ ἡδόμενον ἐν τῇ σαρκὶ ἤ περ τὸ ἀλγοῦν.", "st": "10.140"}, {"sp": "N", "t": "[V.] Οὐκ ἔστιν ἡδέως ζῆν ἄνευ τοῦ φρονίμως καὶ καλῶς καὶ δικαίως, 〈οὐδὲ φρονίμως καὶ καλῶς καὶ δικαίως〉 ἄνευ τοῦ ἡδέως. ὅτῳ δὲ τοῦτο μὴ ὑπάρχει ἐξ οὗ ζῆν φρονίμως, καὶ καλῶς καὶ δικαίως ὑπάρχει, οὐκ ἔστι τοῦτον ἡδέως ζῆν.", "st": "10.140b"}, {"sp": "N", "t": "[VI.] Ἕνεκα τοῦ θαρρεῖν ἐξ ἀνθρώπων, ἦν κατὰ φύσιν [ἀρχῆς καὶ βασιλείας] ἀγαθόν, ἐξ ὧν ἄν ποτε τοῦθ’ οἷός τ’ ᾖ παρασκευάζεσθαι. [VII.] Ἔνδοξοι καὶ περίβλεπτοί τινες ἐβουλήθησαν γενέσθαι, τὴν ἐξ ἀνθρώπων ἀσφάλειαν οὕτω νομίζοντες περιποιήσεσθαι. ὥστ’ εἰ μὲν ἀσφαλὴς ὁ τῶν τοιούτων βίος, ἀπέλαβον τὸ τῆς φύσεως ἀγαθόν· εἰ δὲ μὴ ἀσφαλής, οὐκ ἔχουσιν οὗ ἕνεκα ἐξ ἀρχῆς κατὰ τὸ τῆς φύσεως οἰκεῖον ὠρέχθησαν.", "st": "10.141"}, {"sp": "N", "t": "[VIII.] Οὐδεμία ἡδονὴ καθ’ ἑαυτὸ κακόν· ἀλλὰ τὰ τινῶν ἡδονῶν ποιητικὰ πολλαπλασίους ἐπιφέρει τὰς ὀχλήσεις τῶν ἡδονῶν.", "st": "10.141b"}, {"sp": "N", "t": "[IX.] Εἰ κατεπυκνοῦτο πᾶσα ἡδονή, καὶ χρόνῳ καὶ περὶ ὅλον τὸ ἄθροισμα ὑπῆρχεν ἢ τὰ κυριώτατα μέρη τῆς φύσεως, οὐκ ἄν ποτε διέφερον ἀλλήλων αἱ ἡδοναί.", "st": "10.142"}, {"sp": "N", "t": "[X.] Εἰ τὰ ποιητικὰ τῶν περὶ τοὺς ἀσώτους ἡδονῶν ἔλυε τοὺς φόβους τῆς διανοίας τούς τε περὶ μετεώρων καὶ θανάτου καὶ ἀλγηδόνων, ἔτι τε τὸ πέρας τῶν ἐπιθυμιῶν ἐδίδασκεν, οὐκ ἄν ποτε εἴχομεν ὅ τι ἐμεμψάμεθα αὐτοῖς, πανταχόθεν εἰσπληρουμένοις τῶν ἡδονῶν καὶ οὐδαμόθεν οὔτε τὸ ἀλγοῦν οὔτε τὸ λυπούμενον ἔχουσιν, ὅ περ ἐστὶ τὸ κακόν.", "st": "10.142b"}, {"sp": "N", "t": "[XI.] Εἰ μηθὲν ἡμᾶς αἱ τῶν μετεώρων ὑποψίαι ἠνώχλουν καὶ αἱ περὶ θανάτου, μή ποτε πρὸς ἡμᾶς ᾖ τι, ἔτι τε τὸ μὴ κατανοεῖν τοὺς ὅρους τῶν ἀλγηδόνων καὶ τῶν ἐπιθυμιῶν, οὐκ ἂν προσεδεόμεθα φυσιολογίας.", "st": "10.142c"}, {"sp": "N", "t": "[XII.] Οὐκ ἦν τὸ φοβούμενον λύειν ὑπὲρ τῶν κυριωτάτων μὴ κατειδότα τίς ἡ τοῦ σύμπαντος φύσις, ἀλλ’ ὑποπτευόμενόν τι τῶν κατὰ τοὺς μύθους· ὥστε οὐκ ἦν ἄνευ φυσιολογίας ἀκεραίους τὰς ἡδονὰς ἀπολαμβάνειν.", "st": "10.143"}, {"sp": "N", "t": "[XIII.] Οὐθὲν ὄφελος ἦν τὴν κατ’ ἀνθρώπους ἀσφάλειαν κατασκευάζεσθαι τῶν ἄνωθεν ὑπόπτων καθεστώτων καὶ τῶν ὑπὸ γῆς καὶ ἁπλῶς τῶν ἐν τῷ ἀπείρῳ.", "st": "10.143b"}, {"sp": "N", "t": "[XIV.] Τῆς ἀσφαλείας τῆς ἐξ ἀνθρώπων γενομένης μέχρι τινὸς δυνάμει τε ἐξερειστικὴ καὶ εὐπορίᾳ εἰλικρινεστάτη γίνεται ἡ ἐκ τῆς ἡσυχίας καὶ ἐκχωρήσεως τῶν πολλῶν ἀσφάλεια.", "st": "10.143c"}, {"sp": "N", "t": "[XV.] Ὁ τῆς φύσεως πλοῦτος καὶ ὥρισται καὶ εὐπόριστός ἐστιν· ὁ δὲ τῶν κενῶν δοξῶν εἰς ἄπειρον ἐκπίπτει.", "st": "10.144"}, {"sp": "N", "t": "[XVI.] Βραχέα σοφῷ τύχη παρεμπίπτει, τὰ δὲ μέγιστα καὶ κυριώτατα ὁ λογισμὸς διῴκηκε καὶ κατὰ τὸν συνεχῆ χρόνον τοῦ βίου διοικεῖ καὶ διοικήσει.", "st": "10.144b"}, {"sp": "N", "t": "[XVII.] Ὁ δίκαιος ἀταρακτότατος, ὁ δ’ ἄδικος πλείστης ταραχῆς γέμων.", "st": "10.144c"}, {"sp": "N", "t": "[XVIII.] Οὐκ ἐπαύξεται ἐν τῇ σαρκὶ ἡ ἡδονή, ἐπειδὰν ἅπαξ τὸ κατ’ ἔνδειαν ἀλγοῦν ἐξαιρεθῇ, ἀλλὰ μόνον ποικίλλεται.", "st": "10.144d"}, {"sp": "N", "t": "τῆς δὲ διανοίας τὸ πέρας τὸ κατὰ τὴν ἡδονὴν ἀπεγέννησεν ἥ τε τούτων αὐτῶν ἐκλόγησις καὶ τῶν ὁμογενῶν τούτοις, ὅσα τοὺς μεγίστους φόβους παρεσκεύαζε τῇ διανοίᾳ.", "st": "10.144e"}, {"sp": "N", "t": "[XIX.] Ὁ ἄπειρος χρόνος ἴσην ἔχει τὴν ἡδονὴν καὶ ὁ πεπερασμένος, ἐάν τις αὐτῆς τὰ πέρατα καταμετρήσῃ τῷ λογισμῷ.", "st": "10.145"}, {"sp": "N", "t": "[XX.] Ἡ μὲν σὰρξ ἀπέλαβε τὰ πέρατα τῆς ἡδονῆς ἄπειρα, καὶ ἄπειρος αὐτὴν χρόνος παρεσκεύασεν.", "st": "10.145b"}, {"sp": "N", "t": "ἡ δὲ διάνοια τοῦ τῆς σαρκὸς τέλους καὶ πέρατος λαβοῦσα τὸν ἐπιλογισμὸν καὶ τοὺς ὑπὲρ τοῦ αἰῶνος φόβους ἐκλύσασα τὸν παντελῆ βίον παρεσκεύασεν, καὶ οὐθὲν ἔτι τοῦ ἀπείρου χρόνου προσεδεήθη· 〈οὐ〉 μὴν ἀλλ’ οὔτε ἔφυγε τὴν ἡδονήν, οὐθ’ ἡνίκα τὴν ἐξαγωγὴν ἐκ τοῦ ζῆν τὰ πράγματα παρεσκεύαζεν, ὡς ἐλλείπουσά τι τοῦ ἀρίστου βίου κατέστρεφεν.", "st": "10.145c"}, {"sp": "N", "t": "[XXI.] Ὁ τὰ πέρατα τοῦ βίου κατειδὼς οἶδεν, ὡς εὐπόριστόν ἐστι τὸ 〈τὸ〉 ἀλγοῦν κατ’ ἔνδειαν ἐξαιροῦν καὶ τὸ τὸν ὅλον βίον παντελῆ καθιστάν· ὥστ’ οὐδὲν προσδεῖται πραγμάτων ἀγῶνας κεκτημένων.", "st": "10.146"}, {"sp": "N", "t": "[XXII.] Τὸ ὑφεστηκὸς δεῖ τέλος ἐπιλογίζεσθαι καὶ πᾶσαν τὴν ἐνάργειαν, ἐφ’ ἣν τὰ δοξαζόμενα ἀνάγομεν· εἰ δὲ μή, πάντα ἀκρισίας καὶ ταραχῆς ἔσται μεστά.", "st": "10.146b"}, {"sp": "N", "t": "[XXIII.] Εἰ μάχῃ πάσαις ταῖς αἰσθήσεσιν, οὐχ ἕξεις οὐδ’ ἃς ἂν φῇς αὐτῶν διεψεῦσθαι πρὸς τί ποιούμενος τὴν ἀναγωγὴν κρίνῃς.", "st": "10.146c"}, {"sp": "N", "t": "[XXIV.] Εἴ τιν’ ἐκβαλεῖς ἁπλῶς αἴσθησιν καὶ μὴ διαιρήσεις τὸ δοξαζόμενον κατὰ τὸ προσμένον καὶ τὸ παρὸν ἤδη κατὰ τὴν αἴσθησιν καὶ τὰ πάθη καὶ πᾶσαν φανταστικὴν ἐπιβολὴν τῆς διανοίας, συνταράξεις καὶ τὰς λοιπὰς αἰσθήσεις τῇ ματαίῳ δόξῃ, ὥστε τὸ κριτήριον ἅπαν ἐκβαλεῖς. εἰ δὲ βεβαιώσεις καὶ τὸ προσμένον ἅπαν ἐν ταῖς δοξαστικαῖς ἐννοίαις καὶ τὸ μὴ τὴν ἐπιμαρτύρησιν, οὐκ ἐκλείψεις τὸ διεψευσμένον· ὡς τετηρηκὼς ἔσῃ πᾶσαν ἀμφισβήτησιν κατὰ πᾶσαν κρίσιν τοῦ ὀρθῶς ἢ μὴ ὀρθῶς.", "st": "10.147"}, {"sp": "N", "t": "[XXV.] Εἰ μὴ παρὰ πάντα καιρὸν ἐπανοίσεις ἕκαστον τῶν πραττομένων ἐπὶ τὸ τέλος τῆς φύσεως, ἀλλὰ προκαταστρέψεις εἴ τε φυγὴν εἴ τε δίωξιν ποιούμενος εἰς ἄλλο τι, οὐκ ἔσονταί σοι τοῖς λόγοις αἱ πράξεις ἀκόλουθοι. [XXVI.] Τῶν ἐπιθυμιῶν ὅσαι μὴ ἐπ’ ἀλγοῦν ἐπανάγουσιν ἐὰν μὴ συμπληρωθῶσιν, οὐκ εἰσὶν ἀναγκαῖαι ἀλλ’ εὐδιάχυτον τὴν ὄρεξιν ἔχουσιν, ὅταν δυσπόριστοι ἢ βλάβης ἀπεργαστικαὶ δόξωσιν εἶναι.", "st": "10.148"}, {"sp": "N", "t": "[XXVII.] Ὧν ἡ σοφία παρασκευάζεται εἰς τὴν τοῦ ὅλου βίου μακαριότητα, πολὺ μέγιστόν ἐστιν ἡ τῆς φιλίας κτῆσις.", "st": "10.148b"}, {"sp": "N", "t": "[XXVIII.] Ἡ αὐτὴ γνώμη θαρρεῖν τε ἐποίησεν ὑπὲρ τοῦ μηθὲν αἰώνιον εἶναι δεινὸν μηδὲ πολυχρόνιον, καὶ τὴν ἐν αὐτοῖς τοῖς ὡρισμένοις ἀσφάλειαν φιλίαις μάλιστα κατεῖδε συντελουμένην.", "st": "10.148c"}, {"sp": "N", "t": "[XXIX.] Τῶν ἐπιθυμιῶν αἱ μέν εἰσι φυσικαὶ 〈καὶ ἀναγκαῖαι· αἱ δὲ φυσικαὶ〉 καὶ οὐκ ἀναγκαῖαι· αἱ δὲ οὔτε φυσικαὶ οὔτ’ ἀναγκαῖαι ἀλλὰ παρὰ κενὴν δόξαν γινόμεναι.", "st": "10.149"}, {"sp": "N", "t": "[φυσικὰς καὶ ἀναγκαίας ἡγεῖται ὁ Ἐπίκουρος τὰς ἀλγηδόνος ἀπολυούσας, ὡς ποτὸν ἐπὶ δίψους·", "st": "10.149b"}, {"sp": "N", "t": "φυσικὰς δὲ οὐκ ἀναγκαίας δὲ τὰς ποικιλλούσας μόνον τὴν ἡδονήν, μὴ ὑπεξαιρουμένας δὲ τὸ ἄλγημα, ὡς πολυτελῆ σιτία·", "st": "10.149c"}, {"sp": "N", "t": "οὔτε δὲ φυσικὰς οὔτ’ ἀναγκαίας, ὡς στεφάνους καὶ ἀνδριάντων ἀναθέσεις.] [XXX.] Ἐν αἷς τῶν φυσικῶν ἐπιθυμιῶν, μὴ ἐπ’ ἀλγοῦν δὲ ἐπαναγουσῶν ἐὰν μὴ συντελεσθῶσιν, ὑπάρχει ἡ σπουδὴ σύντονος, παρὰ κενὴν δόξαν αὗται γίνονται καὶ οὐ παρὰ τὴν ἑαυτῶν φύσιν οὐ διαχέονται ἀλλὰ παρὰ τὴν τοῦ ἀνθρώπου κενοδοξίαν.", "st": "10.149d"}, {"sp": "N", "t": "[XXXI.] Τὸ τῆς φύσεως δίκαιόν ἐστι σύμβολον τοῦ συμφέροντος εἰς τὸ μὴ βλάπτειν ἀλλήλους μηδὲ βλάπτεσθαι.", "st": "10.150"}, {"sp": "N", "t": "[XXXII.] Ὅσα τῶν ζῴων μὴ ἠδύνατο συνθήκας ποιεῖσθαι τὰς ὑπὲρ τοῦ μὴ βλάπτειν ἄλλα μηδὲ βλάπτεσθαι, πρὸς ταῦτα οὐθὲν ἦν δίκαιον οὐδὲ ἄδικον. ὡσαύτως δὲ καὶ τῶν ἐθνῶν ὅσα μὴ ἠδύνατο ἢ μὴ ἐβούλετο τὰς συνθήκας ποιεῖσθαι τὰς ὑπὲρ τοῦ μὴ βλάπτειν μηδὲ βλάπτεσθαι.", "st": "10.150b"}, {"sp": "N", "t": "[XXXIII.] Οὐκ ἦν τι καθ’ ἑαυτὸ δικαιοσύνη, ἀλλ’ ἐν ταῖς μετ’ ἀλλήλων συστροφαῖς καθ’ ὁπηλίκους δή ποτε ἀεὶ τόπους συνθήκη τις ὑπὲρ τοῦ μὴ βλάπτειν μηδὲ βλάπτεσθαι.", "st": "10.150c"}, {"sp": "N", "t": "[XXXIV.] Ἡ ἀδικία οὐ καθ’ ἑαυτὴν κακόν, ἀλλ’ ἐν τῷ κατὰ τὴν ὑποψίαν φόβῳ, εἰ μὴ λήσει τοὺς ὑπὲρ τῶν τοιούτων ἐφεστηκότας κολαστάς.", "st": "10.151"}, {"sp": "N", "t": "[XXXV.] Οὐκ ἔστι τὸν λάθρᾳ τι κινοῦντα ὧν συνέθεντο πρὸς ἀλλήλους εἰς τὸ μὴ βλάπτειν μηδὲ βλάπτεσθαι, πιστεύειν ὅτι λήσει, κἂν μυριάκις ἐπὶ τοῦ παρόντος λανθάνῃ. μέχρι γὰρ καταστροφῆς ἄδηλον εἰ καὶ λήσει.", "st": "10.151b"}, {"sp": "N", "t": "[XXXVI.] Κατὰ μὲν 〈τὸ〉 κοινὸν πᾶσι τὸ δίκαιον τὸ αὐτό, συμφέρον γάρ τι ἦν ἐν τῇ πρὸς ἀλλήλους κοινωνίᾳ· κατὰ δὲ τὸ ἴδιον χώρας καὶ ὅσων δή ποτε αἰτιῶν οὐ πᾶσι συνέπεται τὸ αὐτὸ δίκαιον εἶναι.", "st": "10.151c"}, {"sp": "N", "t": "[XXXVII.] Τὸ μὲν ἐπιμαρτυρούμενον ὅτι συμφέρει ἐν ταῖς χρείαις τῆς πρὸς ἀλλήλους κοινωνίας τῶν νομισθέντων εἶναι δικαίων, ἔχει τὸν τοῦ δικαίου χαρακτῆρα, ἐάν τε τὸ αὐτὸ πᾶσι γένηται ἐάν τε μὴ τὸ αὐτό.", "st": "10.152"}, {"sp": "N", "t": "ἐάν δὲ νόμον θῆταί τις, μὴ ἀποβαίνῃ δὲ κατὰ τὸ συμφέρον τῆς πρὸς ἀλλήλους κοινωνίας, οὐκέτι τοῦτο τὴν τοῦ δικαίου φύσιν ἔχει. κἂν μεταπίπτῃ τὸ κατὰ τὸ δίκαιον συμφέρον, χρόνον δέ τινα εἰς τὴν πρόληψιν ἐναρμόττῃ, οὐδὲν ἧττον ἐκεῖνον τὸν χρόνον ἦν δίκαιον τοῖς μὴ φωναῖς κεναῖς ἑαυτοὺς συνταράττουσιν, ἀλλ’ ἁπλῶς εἰς τὰ πράγματα βλέπουσιν.", "st": "10.152b"}, {"sp": "N", "t": "[XXXVIII.] Ἔνθα μὴ καινῶν γενομένων τῶν περιεστώτων πραγμάτων ἀνεφάνη μὴ ἁρμόττοντα εἰς τὴν πρόληψιν τὰ νομισθέντα δίκαια ἐπ’ αὐτῶν τῶν ἔργων, οὐκ ἦν ταῦτα δίκαια. ἔνθα δὲ καινῶν γενομένων τῶν πραγμάτων οὐκ ἔτι συνέφερε τὰ αὐτὰ δίκαια κείμενα, ἐνταῦθα δὲ τότε μὲν ἦν δίκαια, ὅτε συνέφερεν εἰς τὴν πρὸς ἀλλήλους κοινωνίαν τῶν συμπολιτευομένων· ὕστερον δ’ οὐκ ἦν ἔτι δίκαια, ὅτε μὴ συνέφερεν.", "st": "10.153"}, {"sp": "N", "t": "[XXXIX.] Ὁ τὸ μὴ θαρροῦν ἀπὸ τῶν ἔξωθεν ἄριστα συστησάμενος οὗτος τὰ μὲν δυνατὰ ὁμόφυλα κατεσκευάσατο· τὰ δὲ μὴ δυνατὰ οὐκ ἀλλόφυλά γε· ὅσα δὲ μηδὲ τοῦτο δυνατὸς ἦν, ἀνεπίμεικτος ἐγένετο, καὶ ἐξωρίσαθ’ ὅσα τούτων λυσιτελῆ πράττειν.", "st": "10.154"}, {"sp": "N", "t": "[XL.] Ὅσοι τὴν δύναμιν ἔσχον τοῦ τὸ θαρρεῖν μάλιστα ἐκ τῶν ὁμορούντων παρασκευάσασθαι, οὕτω καὶ ἐβίωσαν μετ’ ἀλλήλων ἥδιστα τὸ βεβαιότατον πίστωμα ἔχοντες, καὶ πληρεστάτην οἰκειότητα ἀπολαβόντες οὐκ ὠδύραντο ὡς πρὸς ἔλεον τὴν τοῦ τελευτήσαντος προκαταστροφήν.", "st": "10.154b"}], []);})();
